INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.25, 3.03, '9780006545910', '0006545912', 470, 82.38, 4.44, '1994-01-01', 'Cooking in Spain brings the flavor of Spain to your kitchen. Some of the world''s most interesting preparations for seafood, meat and vegetables are here. Spanish/English glossary of more than 500 culinary terms, a handy conversion guide, an easy-to-use index to recipes and ingredients, all of it illustrated in color photographs.', 'The Sierras of the South', 3.18, 9.72, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.98, 5.84, '0007250835', '9780007250837', 690, 95.95, 1.5, '1956-11-19', 'The final book in one of the greatest epic adventures of all time: The Sword of Truth, from bestselling fantasy author Terry Goodkind.', 'Confessor', 4.72, 1.89, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.15, 7.0, '9780008272999', '0008272999', 354, 38.44, 3.89, '2020-04-02', '''Gripping, stylish, convincing'' Sunday Times They won''t all live to tell the tale...', 'I Confess', 3.64, 7.33, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.07, 6.63, '9780008285197', '0008285195', 448, 53.61, 1.5, '2018-10-22', 'The return of the famous shared-world superhero books created and edited by George R. R. Martin, author of A Song of Ice and Fire For decades, George R.R. Martin - bestselling author of A Song of Ice and Fire - has collaborated with an ever-shifting ensemble of science fiction and fantasy icons to create the amazing Wild Cards universe. In the aftermath of World War II, the Earth''s population was devastated by a terrifying alien virus. Those who survived were changed for ever. Some, known as Jokers, were cursed with bizarre mental and physical deformities; others, granted superhuman abilities, are known as Aces. Wild Cards tells the stories of this world.', 'Texas Hold''em', 3.23, 8.73, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.05, 3.66, '9780140092400', '0140092404', 224, 58.79, 2.24, '1975-11-01', 'A fascinating well-told tale of heroism and adventure, told by a master of the craft. Harper s', 'Cooper''s Creek', 2.18, 8.9, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.92, 6.28, '9780140296204', '0140296204', 411, 62.73, 2.09, '1954-02-14', 'Frustrated by his experiences on an expedition led by Captain Robert Scott, explorer Ernest Shackleton, in 1907, launched his own attempt to reach the South Pole. At the mercy of a hostile continent it was to become the most extreme test of endurance imaginable. This is his thrilling account of that expedition.', 'In the Heart of the Antarctic', 6.04, 4.17, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.47, 9.44, '0141025387', '9780141025384', 91, 24.88, 3.67, '2001-12-13', '''Great Journeys'' allows readers to travel both around the planet and back through the centuries and also back into ideas and worlds frightening, ruthless and cruel in different ways from our own. It describes great civilisations, walls of ice, violent jungles, deserts and mountains and multitudes of birds and flowers new to science. This title is a classic in 19th century exploration of Arabian culture.', 'To the Holy Shrines', 4.89, 1.57, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.77, 1.54, '0141025441', '9780141025445', 87, 56.06, 1.38, '1979-04-04', 'Inspired by Penguinas innovative Great Ideas series, our new Great Journeys series presents the most incredible tours, voyages, treks, expeditions, and travels ever writtenafrom Isabella Birdas exaltation in the dangers of grizzlies, rattlesnakes, and cowboys in the Rocky Mountains to Marco Poloas mystified reports of a giant bird that eats elephants during his voyage along the coasts of India. Each beautifully packaged volume offers a way to see the world anew, to rediscover great civilizations and legends, vast deserts andunspoiled mountain ranges, unusual flora and strange new creatures, and much more.', 'Sold as a Slave', 6.4, 8.44, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.41, 9.2, '9780141025506', '0141025506', 0, 12.77, 4.37, '2016-02-14', 'Overwhelmed by what he felt was the worthlessness of his great success as a writer, Chekhov (1860-1904) decided to leave everything behind him and go to the far reaches of Siberia - to the terrible Russian penal colony on Sakhalin Island. This book mixes his witty, charming letters back to friends on his long journey with his grim account of the reality of life in one of the worst places on earth. Great Journeys allows readers to travel both around the planet and back through the centuries - but also back into ideas and worlds frightening, ruthless and cruel in different ways from our own. Few reading experiences can begin to match that of engaging with writers who saw astounding things- Great civilisations, walls of ice, violent and implacable jungles, deserts and mountains, multitudes of birds and flowers new to science. Reading these books is to see the world afresh, to rediscover a time when many cultures were quite strange to each other, where legends and stories were treated as facts and in which so much was still to be discovered.', 'A Journey to the End of the Russian Empire', 8.61, 5.17, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.68, 4.97, '9780195838794', '0195838793', 236, 32.46, 2.73, '1955-03-22', 'In 1898 Cather Borland married George Macartney and, as a bride of 21, journeyed with him to one of the least accessible places on earth - Kashgar in Turkestan, on the remote borders of India, Russia and China.George Macartney represented Britain at Kashgar from 1890 to 1918. Officially he was responsible for looking after the interests of the small British Indian community there, but unofficially he kept a watch on the activities of the Russians. For at that time Kashgar was Britain''s most advancedposition in the Great Game, the long and shadowy struggle with the Tsarist Russia for political and economic supremacy in Asia.Lady Macartney spent seventeen years in Kashgar and extended her hospitality to many famous travellers, among them Sir Aurel Stein, Albert von Le Coq and Dr G.E.Morrison. This book, first published in 1931, is a charming account of her life there and of the sometimes exotic customs of Turkestan.This edition is now reprinted with the addition of an Introduction by Peter Hopkirk, the author of three books on the Central Asian travellers. "Foreign Devils on the Silk Road", "Trespassers on the Roof of the World", and "Setting the East Ablaze".', 'An English Lady in Chinese Turkestan', 8.19, 6.48, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.38, 5.09, '9780312638320', '0312638329', 0, 30.54, 3.25, '2010-07-06', 'Kate Hopkins knew there had to be more to whiskey than using it as a mixer. She had an unquenchable thirst to learn more about "the drink" and set out on an ambitious itinerary researching its history. Combining comprehensive research with informal narrative, Hopkins entertains and educates the readers on whiskey''s place in the history of the world. She visited historians and pub owners, went to distilleries owned by corporations who sell thousands of gallons per day, and artisans who sell thousands of gallons per year, and interviewed the aficionados and the common drinkers, because one of the best aspects of whiskey is not just its taste, but the stories about the drink that are told around the bar. As an added bonus, she discusses the fine art of distilling, the proper ways to drink whiskey, and provides tasting notes on different brands, all in the hope of discovering the best shot of the liquor.', '99 Drams of Whiskey', 6.03, 5.27, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.71, 5.08, '9780316730549', '0316730548', 376, 59.64, 3.2, '1966-05-07', 'The first message sent to Tom Thorne''s mobile phone was just a picture - the blurred image of a man''s face, but Thorne had seen enough dead bodies in his time to know that the man was no longer alive. But who was he? Who sent the photograph? And why? While the technical experts attempt to trace the sender, Thorne searches the daily police bulletins for a reported death that matches the photograph. Then another picture arrives. Another dead man ... It is the identities of the murdered men which give Thorne his first clue, a link to a dangerous killer he''d put away years before and who is still in prison. With a chilling talent for manipulation, this man has led another inmate to plot revenge on everyone he blames for his current incarceration, and for the murder of his family while he was inside. Newly released, this convict has no fear of the police, no feelings for those he is compelled to murder. Now Tom Thorne must face one of the toughest challenges of his career, knowing that there is no killer more dangerous than one who has nothing left to lose.', 'Death Message', 3.59, 9.09, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.35, 1.7, '9780330434683', '0330434683', 452, 13.49, 3.0, '1960-04-18', 'In his new book, Mishra brings literary authority and political insight to bear on travels that are at once epic and personal as he sees the pressures of Western-style modernity, prosperity, and globalization on a rapidly changing region.', 'Temptations of the West', 4.48, 9.05, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.13, 4.48, '9780340899496', '0340899492', 502, 4.42, 1.68, '1969-01-08', '''Once upon a time, there was a boy who lost his mother ...''As twelve-year-old David takes refuge from his grief in the myths and fairytales so beloved of his dead mother, he finds the real world and the fantasy world begin to blend. That is when bad things start to happen. That is when the Crooked Man comes. And David is violently propelled into a land populated by heroes, wolves and monsters, his quest to find the legendary Book of Lost Things.', 'The Book of Lost Things', 1.79, 2.3, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.49, 1.23, '9780517695111', '0517695111', 672, 78.72, 3.23, '2003-10-16', '', 'Edward Rowe Snow Disaster at Sea', 2.13, 7.54, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.82, 1.11, '9780525949602', '0525949607', 332, 11.67, 3.5, '1980-04-15', 'A new collection of tongue-in-cheek tributes to people whose own lack of judgment led to their demise includes a homeowner who filled his house with natural gas to kill termites, a motorcycle rider who steered with his feet, and a welder who incorporated a grenade into a chain. 300,000 first printing.', 'The Darwin Awards 4', 1.09, 4.17, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.11, 4.18, '0552773964', '9780552773966', 596, 14.65, 4.19, '1946-02-05', 'Examines how England''s peculiar class system was established by some snobby French nobles whose posh descendents still have wine cellars and second homes in the Dordogne. This title explores the complex socio-economic reasons why Britain''s kings were the first in Europe to be brought to heel. It is a journey through Britain'' bizarre history.', 'An Utterly Impartial History of Britain', 4.83, 2.42, 11, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.78, 8.43, '9780552996013', '0552996017', 283, 64.51, 3.62, '1939-09-12', 'In the 1920s Gordon West and his wife toured the little-known island of Majorca, observing the rich pageantry of a people whose customs, gentle manners and generous hospitality made the island a unique and fascinating place. This is West''s account of those experiences.', 'Jogging Round Majorca', 1.5, 6.16, 12, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.23, 7.85, '0553588559', '9780553588552', 322, 24.47, 5.0, '2005-10-25', 'The enchantment of the holidays meets the pure storytelling genius of New York Times bestselling author Luanne Rice, as she presents readers with a special gift for the season and a Christmas classic in the making… On a quaint, snowy Chelsea street, librarian Catherine Tierney and a widowed Christmas tree seller from Nova Scotia will rediscover the magic of the season where they least expect it: in a chance encounter that leads to a holiday surprise of love and hope powerful enough to last a lifetime.', 'Silver Bells', 7.27, 9.83, 13, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.34, 5.26, '9780578197180', '0578197189', 420, 54.88, 1.5, '2017-08-23', 'When 12-year-old John Quinn discovers he possesses strange powers, he learns his mother is an alien, part of a band of refugees, marooned on earth twenty years earlier. Ostracized by this alien community for being a "half-breed" and hunted by the CIA, John embarks on a harrowing space adventure to rescue his mother from a pair of brutish, alien bounty hunters.', 'Johnny Quantum', 7.09, 4.79, 14, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.25, 9.24, '9780578418377', '0578418371', 176, 61.39, 2.13, '2018-12-03', '1920''s Vampires, who previously killed to feed, now thrill to feed. The revolution is led by four-hundred-year-old vampire, Rick Hiatt, and his newly turned ward, Matt Brenner. This is not the first time Rick has encountered the brutal treachery of the Moreau family of vampires, but he and Matt seek to make it the last.', 'Appetite for Blood', 8.5, 9.35, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.71, 9.67, '0586085912', '9780586085912', 178, 49.26, 4.61, '1972-03-27', 'The Burroughs'' book which, with ''The Soft Machine'' and ''Nova Express'', completes the classic ''Cut-Up Trilogy''.', 'The Ticket that Exploded', 1.68, 6.48, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.17, 2.93, '0586203222', '9780586203224', 642, 14.22, 4.55, '1974-02-07', 'Fantasy-roman.', 'The King''s Buccaneer', 9.52, 9.66, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.91, 4.52, '0615591086', '9780615591087', 268, 57.28, 4.34, '2022-11-22', 'The history of implementing ERP systems has shown that leaving the fate of your Enterprise Resource Planning project in the hands of software consultants and vendors may only create a false sense of security. While the help of consultants is usually required, they are not all-knowing, have a limited ability to control the keys to project success, and are often the beneficiaries of cost overruns. When it comes to software vendors, their sales people will be long gone when it comes time to go-live with the new system. This book presents comprehensive strategies and techniques that enable organizations to take charge of their Enterprise Resource Planning projects to drive success. It is a guide to making informed decisions during each project phase. The author describes how to become less dependent on outside consultants, mitigate project risks, and significantly reduce implementation costs. Just as important are strategies and methods for the project team and stakeholders to identify business improvement opportunities within your organization and redesign processes to achieve the project benefits. The book also contains many tips to create internal project ownership, select ERP software, manage service providers, transfer software knowledge, develop the right implementation strategies, establish a realistic schedule and budget, and properly test the new system. It also addresses the various system deployment options, emerging technology trends, and the implications from a software selection, implementation and on-going support standpoint. The information is applicable to new implementations and system upgrades. This edition updated: November 2023 For those who prefer audiobooks, this version is also available on Google Play. Click "Switch To Audiobook" on this ebook homepage. Reviews "You owe it to your company and yourself to read this book. If you do so, you will sharply increase your odds for success and spend a lot less money. Steve has done the ERP industry a big service." - Thomas F. Wallace, early ERP pioneer, author, and Distinguished Fellow at The Ohio State University Center for Operational Excellence. "There really aren''t many "must-read" ERP books in the 30 year (or so) history of ERP, but you can add this book to the must-read list. The book fits nicely into what I call the Center of Excellence movement - the push by ERP customers to gain more value out of their ERP investments and endure less headaches. The book is a combination of hard-won advice, cautionary tales, and a bit of a manifesto for not placing blind trust in third party consultancies." - Jon Reed, SAP/ERP Market Analyst. "I love this book." - R. Ray Wang. CEO and Principal Analyst at Constellation Research, a founding partner of the Altimeter Group and thought leader on enterprise digital transformation. "If the Project Management Institute (PMI) had a certification program in ERP Management, this would be the only textbook needed." - Andy Klee, President, Klee Associates, ERPtips.com (SAP), and JDEtips.com (Oracle Enterprise One).', 'Control Your ERP Destiny', 7.52, 5.25, 15, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.33, 1.85, '9780646510354', '0646510355', 636, 16.61, 4.33, '1953-05-13', '"Six journeys beyond the borders of the real"--Cover.', 'X6', 6.75, 8.23, 16, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.0, 4.2, '9780648220329', '064822032X', 404, 42.51, 3.65, '2017-03-28', 'The city survivors join Sundown''s Commando on the edge of the desert. Sergeant Nulla, and his group find the trek to sanctuary is not as safe as they''d hoped. The teenagers, forced to defend their friends against a brutal assault, show maturity beyond their years. Confronted with annihilation they react with a ferocious savagery of their own.', 'Sundown Apocalypse 3', 8.56, 7.31, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.07, 7.63, '9780648220343', '0648220346', 270, 73.99, 4.83, '2018-01-28', 'The back-story of the special operatives from Pine Gap. Thus began the Apocalypse of the book of Revelations. While holidaying at the beautiful Western Australian seaside city of Geraldton, US Ranger, Staff Sergeant Ben ''Obi-Wan'' Kennedy, leads a group of special ops, anti-terrorist police, AFP and female friends to escape back to Pine Gap.', 'Sundown Apocalypse 5', 6.24, 2.86, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.09, 3.55, '9780648228202', '0648228207', 216, 21.91, 4.24, '2018-02-14', 'A devastatingly realistic vision of a post-climate change world in which governments have collapsed and corporations rule with an iron fist. Two brave young women team up to fight back and search for the truth about the world they live in.', 'Survival', 3.81, 1.87, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.25, 8.98, '9780648240808', '0648240800', 382, 15.08, 1.59, '2018-02-05', 'House paid off, money in the bank, and son fully independent, Cindy Moussi had worked hard and accomplished fast. However, by 43, she was burnt out and exhausted from trying to prove herself. She yearned for the slow life. So she made a decision. It was time for a gap year! A fun year free of external demands. A year to inquire about life¿s deeper meaning and `what¿s next?¿. Cindy moved from the fast pace of Sydney back to her small home on ten-acres in the country, ready for a slow and simple existence of yoga and permaculture, with time to walk the Camino de Santiago. It was also time for her spiritual awakening!But there was one problem: Cindy¿s `superwoman¿ was in charge of slowing down, and she had no idea what the experience would evoke. It would be a time of profound joy and loss, followed by the agonising grip of anxiety, overwhelming dread, and unrelenting terror that became her permanent companion. It would also be a time of learning to listen to her own deeper intuition, and having the courage to trust and act upon its profound insights.Cindy weaves in her personal story of growing up in war-torn Lebanon as well as tracing her family history to times of starvation and massacres. This was the beginning of her journey to inquiring, and eventually understanding, the question of `how could this happen to me?¿This is not a book of answers. It is a book about the courage to open up about life¿s painful events that can lead to anxiety and conquering the shame that accompanies it. This is a book with no ending, but rather, a new, and more gentle, beginning.', 'Beyond Superwoman', 5.68, 5.59, 17, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.62, 6.8, '9780648299592', '0648299597', 188, 69.72, 3.22, '2018-04-20', 'Ever wondered if you could climb a mountain? Maybe one of the Seven Summits? What if you are a middle-aged, unfit, inexperienced business woman with a sedentary job? This is the story of one such woman who decided to leave her office job in Sydney and go climb Mt Kilimanjaro in Africa. She tells the tale with wry humour, undaunted - well, only a little daunted - by the difficulties of spending nine days and eight nights on the slopes of the mountain, dealing with no running water, hours of uphill slog, high altitude - and what do you do about the toilet thing, anyway? The African mountain is a very dangerous place and several people die up there each year. But this is the story of how and why anyone in their right mind would try to touch the snows of Kilimanjaro.', 'Mt Kilimanjaro & Me', 6.53, 4.47, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.38, 1.79, '9780692096062', '069209606X', 340, 50.85, 3.55, '2018-03-30', 'Ciara gets the shock of a lifetime when she discovers the Zodiacs are real beings. She must learn to trust them to find Taurus''s true birthstone and stop him from taking over humanity. But Taurus isn''t the only threat. An ancient order of mages looms in the shadows. They also want the birthstones, but for a very different reason.', 'The Tenth House', 8.3, 9.18, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.33, 1.13, '9780692157091', '0692157093', 194, 96.02, 3.66, '2018-08-17', 'Three years after the war between hell and earth a new adeventure blossums as Cya Sya Do and his friends travel through new areas on the hunt for Nova Volious who was kidnapped. Along the way the crew meets other warriors who join Cya Sya Do on his journey. The quest has only started when an old evil awakes from his entranal slumber.', 'Armageddon', 1.39, 3.87, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.28, 4.93, '9780692394465', '069239446X', 162, 93.11, 4.69, '2015-03-05', 'The journey to hearing, accepting and walking in the call to ministry as told by a family of ministers, Rev. Dr. James Edwards, wife Rev. Delores Edwards, and daughter, Rev. Donita Edwards.', 'Then There Were Three', 6.35, 4.4, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.46, 6.22, '9780692515716', '0692515712', 168, 96.91, 4.95, '2015-08-24', 'While spending hours waiting for model castings, Melissa Stetten secretly took pictures of other models on their phones, amassing over 100 photographs from New York, London, Manchester, and Los Angeles. Captions of what Melissa predicted the model was texting at that moment were added to each photo. 166 pages Full Color 8x10', 'Models on Phones', 4.07, 6.16, 18, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.75, 7.31, '9780714860770', '0714860778', 0, 48.28, 4.94, '2011-05-04', 'An author and illustrator describes how he and his wife moved from New York City to an isolated peninsula on Nova Scotia.', 'Far Out Isn''t Far Enough', 2.77, 2.67, 19, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.42, 2.91, '9780718154349', '0718154347', 253, 24.32, 4.63, '1996-01-08', 'Explorer Bruce Parry is embarking on yet another epic journey: down the Amazon - the world''s greatest river, its largest forest, the most bio-diverse habitat on the planet and home to some of the last uncontacted tribes left on Earth. It''s one hell of a trip, as Parry travels over 6,000 kms by foot, light aircraft and boat to meet and live with tribesmen, coca growers, loggers and illegal miners. Written in diary form, Amazon gives a rare insight into the ways of life that have existed since the dawn of time and are about to disappear forever.', 'Amazon', 9.16, 6.76, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.76, 5.48, '9780753813584', '0753813580', 390, 8.66, 2.4, '1973-05-06', 'One man goes in search of the lost cities of the Amazon in the Inca heartland. The lost cities of South America have always exercised a powerful hold on the popular imagination. The ruins of the Incas and other pre-Colombian civilisations are scattered over thousands of miles of still largely uncharted territory, particularly in the Eastern Andes, where the mountains fall away towards the Amazon. Twenty-five years ago, Hugh Thomson set off into the cloud-forest on foot to find a ruin that had been carelessly lost again after its initial discovery. Into his history of the Inca Empire he weaves the story of his adventures as he travelled to the most remote Inca cities. It is also the story of the great explorers in whose footsteps he followed, such as Hiram Bingham and Gene Savoy.', 'The White Rock', 8.73, 3.61, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.55, 7.08, '9780759650589', '0759650586', 384, 42.32, 1.04, '1975-02-10', 'One thing is for sure Kay''s life is heading nowhere, fast. On the verge of an emotional breakdown, she needs to make a change as soon as she can. Nick, the man who sends her heart fluttering with the mere mention of his name has broken her heart, yet won''t let her go. She meets Brian, a stable young paramedic who offers her a fresh look at love. Will she leave the mistakes of the past behind? Or will the passion she feels for Nick be too strong to resist? How can her love be redeemed?', 'The Gay Book of Saints', 5.59, 1.6, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.33, 5.15, '9780762722471', '0762722479', 0, 85.91, 4.93, '2005-11-26', 'This guide features sixty trails across the Green Mountain State.', 'Vermont', 8.21, 2.9, 20, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.29, 6.5, '9780762726967', '0762726962', 0, 62.82, 4.45, '1970-09-26', 'A handy pocket-size guide to mountain biking around Lake Tahoe and Truckee. Detailed ride descriptions make it easy to find the trailheads and follow the routes, helping mountain bikers stay on track with accurate distances keyed to easy-to-read maps and ratings for physical and technical difficulty.', 'Lake Tahoe', 4.77, 3.93, 21, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.62, 5.61, '9780762743810', '0762743816', 0, 48.02, 3.68, '1993-03-11', 'A guide to the offbeat people, places, and events that make West Virginia even stranger than readers might think!', 'West Virginia Curiosities', 7.08, 8.97, 22, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.13, 2.47, '9780762754083', '0762754087', 0, 1.03, 3.06, '1980-01-03', 'Geared towards parents with children between the ages of two and twelve, Fun with the Family Upstate New York features interesting facts and sidebars as well as practical tips about traveling with your little ones.', 'Fun with the Family', 2.91, 8.2, 23, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.31, 5.86, '9780762757213', '0762757213', 0, 17.82, 2.79, '1986-10-20', 'Geared towards parents with children between the ages of two and twelve, Fun with the Family Oregon features interesting facts and sidebars as well as practical tips about traveling with your little ones.', 'Fun with the Family Oregon', 7.37, 7.21, 24, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.18, 1.07, '9780762759453', '0762759453', 0, 29.64, 3.79, '2010-05-18', '"Whether you''re a visitor or a local looking for something different, let this first edition of Upstate New York Off the Beaten Path show you the Empire State you never knew existed."--Back cover', 'Upstate New York', 8.89, 4.52, 25, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.43, 1.19, '9780762759880', '0762759887', 0, 29.27, 1.28, '2010-11-09', 'Your round-trip ticket to the wildest, wackiest, most outrageous people, places, and things the Nutmeg State has to offer!', 'Connecticut Curiosities', 3.53, 4.36, 22, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.48, 7.77, '9780762759958', '076275995X', 0, 96.29, 3.18, '2011-04-12', 'The definitive collection of North Carolina''s odd, wacky, and most offbeat people, places, and things, for North Carolina residents and anyone else who enjoys local humor and trivia with a twist.', 'North Carolina Curiosities, 4th', 4.52, 8.42, 26, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.39, 7.58, '9780762760572', '0762760575', 0, 67.25, 2.85, '1972-08-05', 'Best Easy Day Hikes Berkshires includes concise descriptions of the best short hikes in the area, with detailed maps of the routes. The 20 hikes in this guide are generally short, easy to follow, and guaranteed to please.', 'Berkshires - Best Easy Day Hikes', 3.13, 2.07, 20, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.61, 7.96, '9780762761333', '0762761334', 0, 64.66, 1.93, '2000-03-17', 'Hikes varying from half-hour strolls to full-day adventures, this guidebook is for everyone, including families.', 'Best Easy Day Hikes Cape Cod and the Islands', 1.97, 1.1, 20, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.99, 5.29, '9780762764488', '0762764481', 0, 46.77, 2.37, '2020-09-27', 'The definitive collection of New Hampshire''s odd, wacky, and most offbeat people, places, and things, for New Hampshire residents and anyone else who enjoys local humor and trivia with a twist.', 'New Hampshire Curiosities', 9.78, 8.79, 22, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.01, 2.33, '9780762764808', '0762764805', 0, 81.35, 3.7, '2019-02-21', 'New Jersey Off the Beaten Path features the things travelers and locals want to see and experience--if only they knew about them. From the best in local dining to quirky cultural tidbits to hidden attractions, unique finds, and unusual locales, New Jersey Off the Beaten Path takes the reader down the road less traveled and reveals a side of New Jersey that other guidebooks just don''t offer. In addition to the text being fully revised and updated, the 9th edition features a new cover treatment and new series branding.', 'New Jersey', 5.2, 3.93, 23, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.26, 3.83, '9780762773077', '0762773073', 0, 84.81, 2.72, '1985-11-16', 'Rediscover the simple pleasures of a day trip with Day Trips from San Antonio. This guide is packed with hundreds of exciting things for locals and vacationers to do, see, and discover within a two-hour drive of the San Antonio metro area.', 'Day Trips from San Antonio', 9.77, 9.11, 27, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.3, 2.62, '9780762777563', '0762777567', 0, 21.35, 2.99, '1954-03-16', 'An intrepid African safari guide sets out to discover all he can about the wildlife of the South American continent in a hilarious book about walking pumas (can be dangerous), chasing jaguars (can be elusive) and finding love (can be tricky).', 'How to Walk a Puma', 8.51, 5.78, 26, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.25, 5.35, '9780762782505', '0762782501', 246, 85.44, 4.95, '2019-10-15', 'No other campground guidebook focuses solely on the Michigan quite like Kevin Revolinski''s. Michigan offers a surprising array of quiet, out-of-the-way parks replete with lakes, rivers, rugged hills, and even rocky cliffs. Camping Michigan opens the door to these places. It includes: Ø Up-to-date trail information and route descriptions Ø Accurate directions to popular as well as less-traveled trails Ø Difficulty ratings for each hike Ø Historical highlights Ø Detailed trail maps Ø Zero-impact camping, and wilderness safety tips and techniques', 'Camping Michigan', 6.83, 7.63, 20, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.91, 3.27, '9780762796717', '0762796715', 0, 5.46, 4.15, '2014-08-05', 'Rediscover the simple pleasures of a day trip with Day Trips from Washington, D.C. This guide is packed with hundreds of exciting things for locals and vacationers to do, see, and discover all within a 2-hour drive. With full trip-planning information, Day Trips from Washington, D.C. helps makes the most of a brief getaway.', 'From Washington, D. C.', 5.87, 7.32, 27, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.94, 1.61, '0765326450', '9780765326454', 368, 76.94, 3.46, '2013-02-19', 'An anthology of original horror tales featuring "evil genius" archetype characters intent on ruling the world features contributions by Diana Gabaldon, Daniel Wilson, and Austin Grossman.', 'The Mad Scientist''s Guide to World Domination', 4.18, 7.08, 28, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.92, 3.11, '9780765327789', '0765327783', 0, 21.81, 2.78, '2014-07-08', 'In Executioner''s Heart--the fourth Newbury & Hobbes steampunk mystery from George Mann--the detectives are up against the most frightening villainess England has yet seen. It''s normal for Charles Bainbridge, Chief Inspector of Scotland Yard, to be called to the scene of a crime, but this is the third murder in quick succession where the victim''s chest has been cracked open and their heart torn out. Bainbridge suspects there''s a symbolic reason for the stolen hearts, so he sends for supernatural specialist Sir Maurice Newbury and his determined assistant, Miss Veronica Hobbes. Unfortunately, neither of them are in much shape to take the case. Veronica has been hunting for some way to alleviate the mysterious forces that have been hounding her family of late, and Newbury has been retained by a private client: Edward, Prince of Wales, who''s concerned that his mother, the Queen of England, is losing her grip on the nation. However, the two detectives pull together long enough to determine that the killings may be the work of a mercenary known as the Executioner. French, uncannily beautiful, her flesh covered in tattoos and inlaid with precious metals, the Executioner is famed throughout Europe, with legends going back for hundreds of years. Something is keeping her in a form of living stasis, but her heart is damaged, leaving her an emotionless shell, inexplicably driven to collect her victims'' hearts as trophies. Who is the Executioner targeting, and who hired her? Why has Veronica stopped trusting Bainbridge? What does the Prince of Wales really want? These are just some of the mysteries that Newbury and Hobbes will confront on the way to unearthing the secret of the Executioner''s Heart. Newbury & Hobbes Investigation #1 The Affinity Bridge #2 The Osiris Ritual #3 The Immortality Engine #4 The Executioner''s Heart #5 The Revenant Express', 'The Executioner''s Heart', 6.91, 6.18, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.29, 1.27, '9780765331014', '0765331012', 0, 88.39, 2.67, '2014-06-10', 'For decades, the spacefaring species of Known Space have battled over the largest artifact—and grandest prize—in the galaxy: the all-but-limitless resources and technology of the Ringworld. But without warning the Ringworld has vanished, leaving behind three rival war fleets. Something must justify the blood and treasure that have been spent. If the fallen civilization of the Ringworld can no longer be despoiled of its secrets, the Puppeteers will be forced to surrender theirs. Everyone knows that the Puppeteers are cowards. But the crises converging upon the trillion Puppeteers of the Fleet of Worlds go far beyond even the onrushing armadas: Adventurer Louis Wu and the exiled Puppeteer known only as Hindmost, marooned together for more than a decade, escaped from the Ringworld before it disappeared. And throughout those years, as he studied Ringworld technology, Hindmost has plotted to reclaim his power ... Ol''t''ro, the Gw''oth ensemble mind—and the Fleet of World''s unsuspected puppet master for a century—is deviously brilliant. And, increasingly unbalanced ... Proteus, the artificial intelligence on which—in desperation—the Puppeteers rely to manage their defenses, is outgrowing its programming. And the supposed constraints on its initiative ... Sigmund Ausfaller, paranoid and disgraced hero of the lost human colony of New Terra, knows that something threatens his adopted home world. And that it must be stopped ... Achilles, the megalomaniac Puppeteer, twice banished—and twice rehabilitated—sees the Fleet of World''s existential crisis as a new opportunity to reclaim supreme power. Whatever the risks ... One way or another, the fabled race of Puppeteers may have come to the end of their days in Fate of Worlds, the final installment to Larry Niven and Edward M. Lerner''s Fleet of Worlds series.', 'Fate of Worlds', 3.64, 2.89, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.94, 4.22, '9780765332554', '0765332558', 0, 18.28, 2.72, '2013-07-23', 'Sarah Jane Beauhall thinks she''s getting her life in order. The blacksmith turned dragon slayer has it all figured out—little things like dealing with the political intrigue of dragons who secretly run our world and learning to wield the magic that she has been given by none other than Odin, who has been fighting the dragons for millennia. And then there is the matter of coming to terms with who she is...and how to build a life with her partner, Katie. All these things are forced into the background, however, when a magic-wielding serial killer starts prowling the Pacific Northwest. All of his victims have ties to Sarah. Sarah will have to unravel the web she finds closing around her as a powerful necromancer and a crazed blood cult known as the Dragon Liberation Front work to tear apart everything she holds dear. Forged in Fire is the third title in J.A. Pitts''s urban fantasy series', 'Forged in Fire', 2.04, 8.5, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.79, 8.66, '9780765334596', '0765334593', 0, 27.15, 2.43, '2014-08-26', 'An all-star tribute to Gene Wolfe, featuring the work of Neil Gaiman, David Brin, Nancy Kress, and others Perhaps no living author of imaginative fiction has earned the awards, accolades, respect, and literary reputation of Gene Wolfe. His prose has been called subtle and brilliant, inspiring not just lovers of fantasy and science fiction, but readers of every stripe, transcending genre and defying preconceptions. In this volume, a select group of Wolfe''s fellow authors pay tribute to the award-winning creator of The Book of the New Sun, The Fifth Head of Cerberus, Soldier of the Mist, The Wizard Knight and many others, with entirely new stories written specifically to honor the writer hailed by The Washington Post as "one of America''s finest." Shadows of the New Sun features contributions by Neil Gaiman, David Brin, David Drake, Nancy Kress, and many others, plus two new short stories by Gene Wolfe himself.', 'Shadows of the New Sun', 1.46, 9.91, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.45, 3.94, '9780765336859', '0765336855', 0, 92.92, 2.47, '2014-03-18', 'Theater, magic, art, and politics all blend in Elsewhens, the second installment of the amazing high-fantasy series, Glass Thorns, from the imagination of Melanie Rawn. Touchstone, the magical theater troupe, continues to build audiences. But Cayden is increasingly troubled by his "elsewhens," the uncontrolled moments when he is plunged into visions of the possible futures. He fears that his Fae gift will forever taint his friendships; his friends fear that his increasing distance will destroy him. But worldly success follows them-an apparent loss in the Trials leads to Touchstone being selected to travel to the Continent with a Royal Embassy to collect Prince Ashgar''s new bride. They are the first theater artists to appear outside Albeyn for at least seventy years-for magic is suspect and forbidden elsewhere, and the Kingdom''s easy race mixing and magic use horrifies the people they are to travel among. The Glass Thorns Series #1 Touchstone #2 Elsewhens #3 Thornlost #4 Window Wall #5 Playing to the Gods (forthcoming)', 'Elsewhens', 4.04, 5.76, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.74, 1.4, '9780765337276', '0765337274', 0, 24.37, 3.91, '2015-03-17', 'Canada’s Aurora Award for Best Young Adult Novel 2015 When seventeen-year-old Toby McGonigal finds himself lost in space, separated from his family, he expects his next drift into cold sleep to be his last. After all, the planet he''s orbiting is frozen and sunless, and the cities are dead. But when Toby wakes again, he''s surprised to discover a thriving planet, a strange and prosperous galaxy, and something stranger still—that he''s been asleep for 14,000 years. Welcome to the Lockstep Empire, where civilization is kept alive by careful hibernation. Here cold sleeps can last decades and waking moments mere weeks. Its citizens survive for millennia, traveling asleep on long voyages between worlds. Not only is Lockstep the new center of the galaxy, but Toby is shocked to learn that the Empire is still ruled by its founding family: his own. Toby''s brother Peter has become a terrible tyrant. Suspicious of the return of his long-lost brother, whose rightful inheritance also controls the lockstep hibernation cycles, Peter sees Toby as a threat to his regime. Now, with the help of a lockstep girl named Corva, Toby must survive the forces of this new Empire, outwit his siblings, and save human civilization. Karl Schroeder''s Lockstep is a grand innovation in hard Science Fiction space opera.', 'Lockstep', 7.2, 1.55, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.85, 9.34, '9780765337795', '0765337797', 0, 12.66, 3.47, '2014-04-29', 'After vowing never to return, Kara Wade is back in New York City. She''s come to claim the body of her twin sister Kelly, and to find out how she died. No secret as to the cause of death—a nearly nude, twelve-story plunge from a room in the Plaza Hotel—but Kara is determined to learn what led to that plunge. Enlisting the help of an old lover, now an NYPD detective, Kara delves into her sister''s life. Startling and bizarre facts begin to surface. Instead of answers, Kara finds more questions. Who was the stranger Kelly became during the months prior to her death? What was behind the perverse, decadent lifestyle she came to embrace so passionately? Kelly''s psychiatrist hints at a terrible secret in her past. But Kara shares that past with her twin. Is the sinister influence that drove Kelly into her bizarre double life about to overtake Kara as well? Sibs is F. Paul Wilson''s most daring, most erotic, most deeply terrifying novel.', 'Sibs', 8.28, 7.24, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.27, 6.41, '9780765375018', '076537501X', 0, 7.45, 2.36, '2003-05-18', 'Most readers recognize L. E. Modesitt, Jr., as the author of a favorite fantasy series, be it The Magic of Recluce or The Spellsong Cycle. It''s always a special treat when he turns his hand again to science fiction and Archform: Beauty is no exception. Four centuries in the future, the world is rich--nanomachines watch the health of the wealthy and manufacture food and gadgets for everybody--but no Utopia, as we see in the lives of five very different people. A singing teacher suffers for her music and fights bureaucracy and apathy. A news researcher delivers the essential background details but can''t help looking deeper and wondering about the real story behind the grim incidents that make the headlines. A police investigator, assigned to study trends, begins to see a truly sinister pattern behind a series of seemingly unrelated crimes and deaths. A politician aids his constituents, fights the good fight, and tries to get reelected without compromising his principles. A ruthless businessman strives to make his family powerful, wealthy, and independent. Theirs is a society where technology takes care of everyone''s basic needs but leaves most people struggling to extract a meaningful life from a world crowded with wonders but empty of commitment and human connection. Alternating the voices and experiences of these five characters in a tour de force of imaginative creation, Modesitt overlaps, combines, and builds their disparate stories into a brilliant tale of future crime and investigation, esthetic challenge and personal triumph. In the same way that he has built fantasy landscapes of surpassing fascination, Modesitt creates a believable future, one imbued with a deep understanding of the way politics works and how people act and react when their sense of themselves, of justice and truth, is exploited by others for power and control. When there''s nothing left to need or want, will beauty live on in people''s lives or disappear forever? L. E. Modesitt, Jr. asks difficult questions, sets himself unlikely challenges, and once again delivers an absorbing tale that enlightens, entertains, and uplifts all at once. "Modesitt has outdone himself...This brilliant novel is as thought-provoking as it is entertaining."--Publishers Weekly (starred review) Other Series by L.E. Modesitt, Jr. The Saga of Recluce The Imager Portfolio The Corean Chronicles The Spellsong Cycle The Ghost Books The Ecolitan Matter The Forever Hero Timegod''s World Other Books The Green Progression Hammer of Darkness The Parafaith War Adiamante Gravity Dreams The Octagonal Raven Archform: Beauty The Ethos Effect Flash The Eternity Artifact The Elysium Commission Viewpoints Critical Haze Empress of Eternity The One-Eyed Man Solar Express', 'Archform: Beauty', 8.27, 5.27, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.99, 4.56, '9780765375803', '076537580X', 0, 24.77, 1.4, '2015-01-06', 'The year is 10,515 AD. The Hyades Armada, traveling at near lightspeed, will reach Earth in just four centuries to assess humanity''s value as slaves. For the last 8,000 years, two opposing factions have labored to meet the alien threat in very different ways. One of them is Ximen del Azarchel, immortal leader of the mutineers from the starship Hermetic and self-appointed Master of the World, who has allowed his followers to tamper continuously with the evolutionary destiny of Man, creating one bizarre race after another in an apparent search for a species the Hyades will find worthy of conquest. The other is Menelaus Montrose, the posthuman Judge of Ages, whose cryonic Tombs beneath the surface of Earth have preserved survivors from each epoch created by the Hermeticists. Montrose intends to thwart the alien invaders any way he can, and to remain alive long enough to be reunited with his bride Rania, who is on a seventy-millennia journey to confront the Hyades'' masters, tens of thousands of light-years away. Now, with the countdown to the Hyades'' arrival nearing its end, del Azarchel and Montrose square off for what is to be their final showdown for the fate of Earth, a battle of gunfire and cliometric calculus; powered armor and posthuman intelligence. The Judge of Ages is the wildly inventive third volume in a series exploring future history and human evolution from John C. Wright.', 'The Judge of Ages', 8.9, 9.37, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.79, 7.66, '9780765376688', '0765376687', 0, 42.09, 2.69, '2015-09-08', 'Mason Stark has a problem with minding his own business. This worked to his advantage when he helped bring peace between humans and the alien Tremist. He''s now considered an intergalactic hero, but that hasn''t made school any easier. With his new reputation, any bully with something to prove wants to fight him. With the new peace treaty on shaky ground, Mason is called upon to infiltrate the Tremist school for soldiers. Mason''s bound to find trouble, especially now that he has the power to channel electricity through his Tremist gloves, but when his new classmates begin to disappear under mysterious circumstances, trouble might find him first. The Tremist are working on a secret project, but what Mason discovers goes beyond that, to an ancient, powerful enemy. With that very enemy threatening to invade, Mason must call on his friends, both human and Tremist, to fight. They call him a hero, and now that''s what he must be—even if it requires the ultimate sacrifice. In this stellar follow-up to The Planet Thieves, Dan Krokos imbues The Black Stars with all the tension and action that made his first middle-grade novel such a gripping tale.', 'The Black Stars', 4.71, 3.64, 30, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.64, 6.02, '9780765377821', '0765377829', 0, 75.59, 4.55, '2014-10-14', 'Action, adventure, romance, and thrills--everything readers love from USA Today bestselling authors C.T. Adams and Cathy Clamp who are also Cat Adams, creator of the Blood Singer series--are all on display in Touch of Evil, the first volume in the Thrall series! The alien vampires known as the Thrall classify most humans as Prey, save for a few who survive the bite of the parasite. People like Kate Reilly, whose latent psychic powers were activated by the vampire''s venom when she was attacked a few years ago. Kate is Not Prey, and safe. Or is she? The Thrall Queen intends to make Kate her successor, despite Kate''s hatred of the vampires. All is not bleak in Kate''s world. Her downstairs neighbor, Tom, is a hunky firefighter who arouses her senses...including the ones that tell her he''s not human. Tom''s a werewolf—and his pack knows how to protect Kate from the Thrall Queen. The problem? The last time Kate trusted a man she loved, he betrayed her to the Thrall and nearly got her killed. Action, adventure, romance, and thrills—everything readers want from the USA Today bestselling authors who are also Cat Adams, creator of the Blood Singer series—are all on display in Touch of Evil.', 'Touch of Evil', 8.1, 2.11, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.98, 6.82, '9780765380210', '0765380218', 608, 52.64, 2.35, '2009-03-01', 'When streetwise Molly Templar witnesses a brutal murder, her first instinct is to run back to the poorhouse where she grew up. But there she finds her fellow orphans butchered, and she realizes she had been the real target, in this adventure set in a fantastical universe.', 'Court of the Air', 9.38, 3.3, 31, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.81, 9.83, '9780765380272', '0765380277', 0, 65.87, 3.87, '2015-11-03', 'C. T. Adams and Cathy Clamp burst onto the urban fantasy scene with the Sazi series of mass market originals beginning with Hunter''s Moon, which Tor is pleased to offer for the first time in trade paperback. Mafia hitman Tony Giodone has never failed to kill-not even after a target tore his throat out. Since then, he''s had blackouts three days a month...but he''s always managed to complete his jobs. Until a woman named Sue hires him to kill her-suicide by assassin-and Tony can''t. Every instinct in him is screaming that this woman is fated to be his. Discoveries come thick and fast after that: Tony''s "lost" days are vanishing because he''s a werewolf. Hundreds of shifters-wolves, cats, bears, and more-live hidden throughout the world. And now that he''s found them, Tony''s in big trouble.', 'Hunter''s Moon', 9.42, 4.43, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.75, 8.83, '9780765382627', '0765382628', 478, 86.47, 1.25, '2009-09-01', 'The heart of this star-spanning story is the chilling tale of mankind''s unending battle against black-hearted, shape-shifting, blood-thirsty, alien vampires - and of one man''s battle in particular: Harry Keogh the Necroscope! Harry is the man who can talk to the dead, the man for whom every grave willingly gives up its secrets. In the original Necroscope trilogy Harry discovers that his powers are even greater than he thought - he can also travel effortlessly through time and space. Thus Harry Keogh becomes the one man able to attempt to eradicate the vampire evil at its source. Harry''s enemies are many - the vampires and their gruesome thralls and genetically altered servants, the Russian ESPionage service, and others. He''s even been killed once already, forced out of his body and into that of Alec Kyle, head of Britain''s E-Branch. Luckily he has a few allies - E-Branch, an organization of psychically gifted spies...and the teeming dead, for whom Harry is a ray of light in an otherwise dark existence. There are millions of dead people who would do anything for Harry Keogh.', 'Vamphyri! (Special)', 2.77, 8.39, 32, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.43, 9.94, '9780765387912', '0765387913', 0, 61.29, 1.77, '2016-03-08', 'Katya deals in Authenticities and Captures, trading on nostalgia for a past long gone. Her clients are rich and they demand items and experiences with only the finest verifiable provenance. Other people’s lives have value, after all. But when her A.I. suddenly stops whispering in her ear she finds herself cut off from the grid and loses communication with the rest of the world. The man who stepped out of the trees while hunting deer cut her off from the cloud, took her A.I. and made her his unwilling guest. There are no Authenticities or Captures to prove Katya’s story of what happened in the forest. You’ll just have to believe her.', 'Forest of Memory', 9.96, 1.82, 33, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.71, 6.25, '9780765388506', '0765388502', 0, 23.98, 3.85, '2016-07-19', 'First in Melissa F. Olson''s gritty urban fantasy series, Nightshades: A Paranormal Thriller is a "fast-paced, action-filled clash between federal agents and vampires" (Christopher Farnsworth, author of The President''s Vampire). Alex McKenna is the new Special Agent in Charge of the Chicago office of the Bureau of Paranormal Investigations—the division tasked with investigating crimes involving shades. Or vampires, as they’re more widely known. Children have been going missing, and agents are routinely being slaughtered. It’s up to McKenna, and some unlikely allies, to get to the bottom of the problem, and find the kids before it’s too late.', 'Nightshades', 6.3, 6.42, 33, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.08, 1.24, '9780765388513', '0765388510', 0, 8.3, 3.93, '2005-04-01', 'Elegy for a Lost Star sets the stage for a major turning point in the Symphony of Ages series. The dragon Anwyn--who has lain for three years in deathlike sleep in a grave of rock and black coal is freed by the cataclysm that concluded REQUIEM FOR THE SUN. sisoriented and confused, she remembers only two things-the person who trapped her in dragon form and locked her in the grave-Rhapsody-and an all-encompassing desire to wreak vengeance. Meanwhile, Achmed, the Firbolg king, resumes rebuilding the his shattered home, while a guild of merciless assassins set about taking revenge on him for the killing of their leader. A horribly deformed but magical being finds its way through a carnival of freaks to the palace of an evil despot, who sees in it the potential to be the instrument by which his plans of conquest and brutal domination of a continent will be realized. With the rise of new leaders, good and evil, the long-awaited birth of the Child of Time, the dark plans of assassins and rulers, a confrontation that shakes the relationship of the Three, and a battle to the death between two dragons of unimaginable elemental power, the seeds of chaos are planted for a war that will, by its end, consume half of the world.', 'Elegy for a Lost Star', 9.9, 4.96, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.54, 5.56, '9780765389756', '0765389754', 0, 3.06, 3.93, '2016-07-26', 'City of Wolves is a gaslamp fantasy noir from debut author Willow Palecek. Alexander Drake, Investigator for Hire, doesn’t like working for the Nobility, and doesn’t prefer to take jobs from strange men who accost him in alleyways. A combination of hired muscle and ready silver have a way of changing a man’s mind. A lord has been killed, his body found covered in bite marks. Even worse, the late lord’s will is missing, and not everyone wants Drake to find it. Solving the case might plunge Drake into deeper danger.', 'City of Wolves', 7.79, 7.28, 33, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.93, 4.84, '9780765390240', '0765390248', 0, 33.37, 3.52, '2016-06-14', 'If war is hell, there is no word to describe what Private Jones has been through. Forced into a conflict with an unknowable enemy, he awakes to find himself in a strange land, and is soon joined by young woman, Morana, who tends to his wounds and tells him of the battles played out in this impossible place. She tells him of an Iron Beast that will end the Great War, and even as he vows to help her find it, enemy combatants seek them, intent on their utter annihilation. Return of Souls is the second volume of the trilogy Andy Remic began with A Song for No Man''s Land.', 'Return of Souls', 1.2, 1.39, 33, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.09, 6.61, '9780765390684', '076539068X', 384, 77.61, 4.45, '2004-10-01', 'Using the lore and the folk-magic of the men and women who settled North America, Orson Scott Card has created an alternate world where magic works, and where that magic has colored the entire history of the colonies. Charms and beseechings, hexes and potions, all have a place in the lives of the people of this world. Dowsers find water, the second sight warns of dangers to come, and a torch can read a person''s future---or their heart. In this world where "knacks" abound, Alvin, the seventh son of a seventh son, is a very special man indeed. He''s a Maker; he has the knack of understanding how things are put together, how to create them, repair them, keep them whole, or tear them down. He can heal hearts as well as bones, he build a house, he can calm the waters or blow up a storm. And he can teach his knack to others, to the measure of their own talent. Alvin has been trying to avert the terrible war that his wife, Peggy, a torch of extraordinary power, has seen down the life-lines of every American. Now she has sent him down the Mizzippy to the city of New Orleans, or Nueva Barcelona as they call it under Spanish occupation. Alvin doesn''t know exactly why he''s there, but when he and his brother-in-law, Arthur Stuart, find lodgings with a family of abolitionists who know Peggy, he suspects he''ll find out soon. But Nueva Barcelona is about to experience a plague, and Alvin''s efforts to protect his friends by keeping them healthy will create more danger than he could ever have suspected. And in saving the poor people of the city, Alvin will be put to the greatest test of his life---a test that will draw on all his power. For the time has come for him to turn to his old friend Tenskwa-Tawa, the Red Prophet who controls the lands to the west of the Mizzippy. Now Alvin must take the first steps on the road to the Crystal City that was shown to him in a vision so long ago. The Tales of Alvin Maker series Seventh Son Red Prophet Prentice Alvin Alvin Journeyman Heartfire The Crystal City', 'The Crystal City', 7.27, 2.67, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.1, 7.56, '9780765392268', '0765392267', 416, 69.34, 3.32, '2006-05-30', 'Repairman Jack is back! An anonymous mercenary, with no last name and no social security number, Jack has thrilled a veritable army of readers ever since his bestselling debut in The Tomb. Jack can fix any problem, supernatural or otherwise, for a price. Now, in his latest gripping adventure, he takes on two cases at once. The first involves a nun being blackmailed by someone who has photos of her she doesn''t want made public. What''s in those photos, she won''t say, but with her meager savings just about exhausted, she hires Jack to help her. The second seems straightforward enough, as an elderly woman hires Jack to find her missing son. But to locate his quarry, Jack must infiltrate the inner reaches of the Dormentalist Church, a secretive, globe-spanning cult whose members include some of the biggest and most powerful names in entertainment, sports, and politics. Ruthless in its pursuit of critics and enemies, the Church hides a sinister agenda known only to its ruling elite. But Jack can be ruthless, too, going to darker lengths than ever before as he crisscrosses the two fix-it jobs to settle the deadliest of scores!', 'Crisscross', 5.56, 1.7, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.39, 9.4, '9780765392336', '076539233X', 354, 80.19, 1.07, '2013-06-01', 'The explosive sequel to "The Human Disguise," "The Double Human "is an-action packed police thriller set in post-apocalyptic Florida. Tom Wilner is a cop. At least what passes for a cop in this shattered world. Plague and nuclear war have left most of the United States uninhabitable. Many have fled to safer zones, forcing what''s left of the government to wall off cities in an attempt to control mass migration. The city of Miami is just one of these contained prison states. But it''s the outskirts of this forsaken realm that Tom Wilner calls home. Amid this chaos, Wilner stumbles into the path of a wild and brutal adversary. Forced to go undercover in the most frightfully ravaged corners of the Miami Quarantine Zone, Wilner uncovers something he hasn''t seen in decades...a serial killer. But this killer''s path is not like any other; he has been active for nearly fifty years without any repercussions. People call him "the Vampire." Indeed, this serial killer is not human...and neither are his victims.', 'Double Human', 3.29, 7.87, 31, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.04, 2.07, '9780765393647', '0765393646', 608, 3.67, 4.76, '2005-12-27', 'DARKWITCH RISING is the third title in Sara Douglass''s compelling Troy Game series, a riveting historical fantasy series of love and revenge set against the very fabric of time itself. Britian. An ancient land. Most think they know its history. But few suspect and fewer still know the truth. For back in the mists of time came Brutus, last of the Trojan kings, who was armed with the knowledge of how to construct a magical Labyrinth that could rival the might of the gods. He was drawn to this place by the alluring sorceress Genvissa and together they almost succeeded in creating the Labyrinth. But in the end they were thwarted by Brutus''s wife Cornelia, who understood the danger to the land. Her actions however trapped them all into a endless cycle of death and rebirth until the magic of the Labyrinth is completed. Ages pass. Time and again the players have come close to victory but each time there is a new wrinkle to stay the fulfillment of power. The Now that these soul travelers arrive is a most unique one. The English are at war, not with a foreign power but amongst themselves; a mighty Civil War that threatens to destroy a nation. A great pestilence is upon the land and the newly restored Charles II sits upon the throne trying to hold chaos at bay...and he is one of the major players in this drama. And he is not alone.', 'Darkwitch Rising', 8.74, 7.87, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.85, 8.8, '9780765395467', '0765395460', 336, 93.49, 3.58, '2011-11-01', '"Repairman Jack is one of my favorite characters--I''m full of happy anticipation every time I hold a new RJ novel in my hands." --Charlaine Harris, creator of True Blood The End of the World is at hand! Munir Habib''s life has become a nightmare. His tormentor has warned Munir not to report the kidnapping of his family, or else they will pay a terrible price. A friend realizes something is terribly wrong and tells Munir he doesn''t have to go to the cops. There''s a guy who fixes situations like this-Repairman Jack. Jack is backed into helping Munir despite his ongoing involvement in the cosmic shadow war between the Ally and the Otherness. Or perhaps because of it. He''s chafing at being forced into the defensive role of protecting the Lady, the physical embodiment of the consciousness of the planet Earth. Meanwhile, the Septimus Order and the Kickers are seemingly working in concert on a plot to extinguish the Lady and open the way for the Otherness to take over our reality. To top it all off, Dawn Pickering finally goes into labor and delivers a baby she only glimpses as it''s whisked away, and is terrified by what she sees. Later she''s told the baby died, but she doesn''t believe it. Neither does Weezy. Neither does Jack. All these interlocking plots mean doom for humanity. But Jack never gives up or gives in.', 'Fatal Error', 2.38, 8.45, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.16, 9.46, '9780765395481', '0765395487', 336, 18.2, 4.6, '2005-11-01', 'Vampires have always lived in Eastern Europe. But with the fall of the Soviet Union, they began to spread across the continent, then the world, turning whole populations into vampires--or human cattle. Having overrun India, the far East, and the great cities of North and South America, the forces of Night are now spreading into the countryside to consolidate their conquest. In a town on the New Jersey shore, the vampires have just arrived, along with their human henchmen, the cowboys, who round up human cattle for the overlords in return for the promise of eternal life---later. For the vampires wish only a few of their own kind to rule, and feed. The rest of humanity are to be helpless herds, the source of the blood of life. Falsely accused of abuse, Father Dan is drunk in a basement waiting for the end. His superior has betrayed the local Catholic congregation and become a vampire. Sister Carolyn has become a formidable killer of cowboys and vampires. Dan''s niece, escaped from the conquest of New York, has made her way south to find him. Brought together by Rabbi Zev Wolpin, who is shaken by the vampires'' fear of the cross and holy water, they plan their resistance. Against all odds, they discover that there just might be a way for humanity to really fight back. But first they will have to kill the vampire king of New York.', 'Midnight Mass', 6.16, 9.25, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.23, 9.17, '9780765395511', '0765395517', 384, 7.2, 3.01, '2003-06-16', 'Visionary space industrialist Dan Randolph is dead-but his protégé, pilot Pancho Barnes, now sits on the board of his conglomerate. She has her work cut out for her. For Randolph''s rival, Martin Humphries, still wants to control Astro and still wants to drive independent asteroid miners like Lars Fuchs out of business. Humphries wants revenge against Pancho-and, most of all, he wants his old flame, Amanda, who has become Lars Fuchs''s wife. Brimming with memorable characters and human conflict, rugged high-tech prospectors and boardroom betrayals, The Rock Rats continues the tale of our near-future struggle over the incalculable wealth of the Asteroid Belt, the richest source of raw mineral wealth known to humankind. Before it ends, many will die-and many will achieve more than they ever dreamed was possible.', 'The Rock Rats', 7.49, 2.48, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.25, 8.13, '9780773512221', '0773512225', 288, 1.52, 1.9, '2008-04-01', 'To the Arctic by Canoe records the experiences of a remarkable young adventurer, Robert Hood, during the first overland Arctic expedition led by Sir John Franklin. Franklin''s expedition was the first to travel the northern coast of North America''s Arctic; in two birch-bark canoes the party surveyed no less than 675 miles of Arctic coastline.', 'To the Arctic by Canoe 1819-1821', 2.64, 4.73, 34, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.52, 7.75, '9780786926831', '078692683X', 0, 44.86, 1.43, '2001-09-01', 'Drizzt Do''Urden, the dark elf, confronts the underground civilization of the evil Drow elves, travels through an endless labyrinth, and battles to survive on the surface world.', 'The Dark Elf Trilogy', 8.06, 6.43, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.65, 9.1, '9780807855799', '0807855790', 484, 17.68, 3.86, '2004-08-01', 'Inspired and informed by the latest research in African American, military, and social history, the fourteen original essays in this book tell the stories of the African American soldiers who fought for the Union cause. Collectively, these essays probe', 'Black Soldiers in Blue', 7.02, 5.95, 35, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.28, 4.3, '9780809237845', '0809237849', 120, 57.05, 2.51, '1959-10-10', 'For every woman who''s had a too-close encounter with a member of the Testosterone Tribe, here is a witty and wicked collection of the best quips, quotes, curses, and jokes about men ever to grace the lips of the female of the species. Hilarious proof that if we can''t live without them, we can at least get a laught out of living with them.', 'Men and Other Reptiles', 7.4, 8.66, 36, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.99, 3.74, '9780810821941', '081082194X', 566, 38.06, 4.98, '2007-11-04', '', 'Index to Fairy Tales, Myths and Legends', 9.86, 7.87, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.24, 8.97, '9780810827509', '0810827506', 0, 28.1, 3.85, '2015-01-25', '', 'Index to Fairy Tales, Myths, and Legends. Supplement', 5.63, 1.75, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.28, 2.25, '9780811808231', '0811808238', 208, 64.46, 2.33, '1995-04-01', '', 'Istanbul', 2.22, 9.3, 37, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.91, 2.96, '0857668404', '9780857668400', 0, 81.42, 4.99, '2020-03-23', 'The third book in Jeff Noon''s widely acclaimed ''Nyquest Mysteries'' find our protagonist caught up in a new mystery that delves into nightmares, Saints and the answer to his father''s disappearance In the winter of 1959, private eye John Nyquist arrives in the village of Hoxley-on-the-Hale with only a package of cryptic photographs, and the frail hope of finding an answer to a question he''s been asking since his childhood. But the villagers offer little help, as each day brings a twisted new rule in the name of a different Saint that they, and Nyquist, must follow. And there are whispers of the return of the Tolly Man, an avatar of chaos in a terrible mask... As Nyquist struggles to distinguish friend from foe, and the Tolly Man draws nearer, he must race to finally settle the one mystery he has never been able to solve: the disappearance of his father. From the singular imagination of Jeff Noon comes this dark tale of folk horror in the Philip K. Dick Award-nominated John Nyquist series. File Under: Horror Fantasy [ Everyday Saints | Not the Ravens | Fatherland | Written in Blood ]', 'Creeping Jenny', 3.3, 3.94, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.52, 9.49, '088415002X', '9780884150022', 241, 7.34, 4.84, '1961-10-23', 'This book is a unique guide to tell you when, where, and how to catch more than 35 varieties of sport fishes.', 'Fish Florida Saltwater', 4.66, 5.23, 39, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.15, 2.18, '9780892723850', '0892723858', 0, 45.72, 3.79, '1937-01-08', 'Tim Sample''s humor is as much a Down East institution as the famous little restaurant that inspired the title story of his book.', 'Saturday Night at Moody''s Diner', 2.64, 9.03, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.02, 1.14, '9780892724703', '0892724706', 0, 37.64, 3.45, '1965-08-13', 'Summering on a Maine island, thirteen-year-old Ab joins her friend Bean in investigating the odd noises in her boarding house and solving the mystery of a missing treasure and stolen paintings.', 'The Secret of the Missing Grave', 6.49, 6.59, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.42, 3.21, '9780892726240', '0892726245', 0, 84.73, 1.4, '1957-08-07', 'Virginia Thorndike, Maine''s own version of Studs Terkel, traveled to all the Maine coast islands that still maintain a year-round population and persuaded the islanders to talk openly about their lives. The result is a compulsively readable, unvarnished, and appealing portrait, much of it in the islanders? own words. The 15 islands not accessible by bridge that still have year-round populations are: Isle au Haut, Islesboro, the Cranberry Isles (near Mt. Desert Island), Eagle Island, Long Island (Frenchboro), Long Island (Casco Bay), Matinicus, Monhegan, North Haven, Swans Island, Vinalhaven, Peaks, Chebeague, Great Diamond, and Cliff.', 'Islanders', 3.45, 7.8, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.15, 7.27, '9780892726493', '0892726490', 0, 74.28, 1.05, '1962-12-12', 'The author of the successful Maine Sporting Camps collects here classic and favorite recipes from the proprietors of 47 of Maine''s most popular traditional backwoods retreats. The folks who cook at these camps know that tasty, satisfying food is an important part of their clients'' backwoods experience, and they have perfected many recipes to fill the bill. Organized by season, the recipes also include quotes from the owners.', 'The Maine Sporting Camp Cookbook', 8.94, 2.96, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.14, 10.0, '9780892726691', '0892726695', 0, 37.93, 4.73, '2022-07-18', 'For more than ten years, Elizabeth Peavey has been traveling around the state of Maine, and writing about her wide-ranging experiences and discoveries in Down East magazine. This book collects her very best columns and essays. In a light and entertaining style laced with lots of entertaining humor, she weaves a wide-ranging tapestry that will give readers a vivid and fresh view of the state.', 'Maine & Me', 4.04, 1.53, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.66, 6.52, '9780892727889', '0892727888', 0, 42.51, 4.21, '1957-06-23', 'How did a mountain get the name Moose''s Bosom? Why is another called Picked Chicken Hill? Was Smart Mountain named for a local Einstein? And what''s afoot on Toenail Ridge? Mountain trekker Steve Pinkham provides the informative and sometimes surprising answers in Mountains of Maine: Intriguing Stories Behind Their Names. Arranged alphabetically within regions are capsule histories highlighting natural features, origins of place names, intriguing facts, and local legends. Sidebars tell about selected trails, historical figures, and other topics of interest. This ambitious and endlessly fascinating book touches on significant peaks and hills throughout the state of Maine. Book jacket.', 'Mountains of Maine', 1.88, 6.09, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.85, 4.37, '9780934641579', '0934641579', 0, 22.54, 1.67, '1960-08-20', 'Revised and updated, this guide covers the myriad of bouldering problems from Santa Barbara to San Diego.', 'Southern California Bouldering', 2.05, 8.88, 20, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.07, 5.12, '9780956136107', '0956136109', 160, 8.88, 1.38, '1947-02-26', 'Join us by the fireside of a legendary guesthouse in the Outer Hebrides of Scotland, where fly fishermen gather each evening to tell stories of their exploits. Tales from The Angler''s Retreat reveals a world of amiable obsession, as people from many backgrounds - united by fishing, companionship and the unusual beauty of the island of South Uist - take turns to tell their stories. Some tales may be tall. Many involve mishaps. Some are hilarious, others wistful. Together they offer unexpected insight into fishing, Scottish islands and how men behave when practising their passion.', 'Tales from The Angler''s Retreat', 5.23, 1.6, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.93, 7.09, '9780957192027', '0957192029', 244, 12.84, 3.25, '1969-05-12', 'Named one of the twelve best travel books of 2009 by Worldhum, Chucking It All exposes the gritty reality behind all those twee bestsellers which extol the joys of sunny rural idylls. With its remorseless true-life account of downshifting to a remote Scottish island, Chucking It All uncovers the frightening realities of relocating to "a magical island lost in the mists of time" as you follow the warts-and-all adventures of urban misanthrope, Max Scratchmann, as he valiantly tries to forge a new life in the windswept Orkney islands, and grumbles his way through unending winters with eighteen-hour nights, nocturnal visits from drunken farmers and booty calls from desperate divorcees. From struggling to fit in as a temporary postman in a wilderness where houses don''t display numbers or names, to attending drunken country ceilidhs with the island singles'' club, or finding himself up to the neck in local politics while performing in the village pantomime, Chucking It All is an urbanite''s nightmare and one of the most hilarious books that you will read this year. Irreverent, sarcastic and bitingly caustic, Chucking It All still manages to be a grudgingly affectionate portrait of rural life through the eyes of a cynical outsider, and is one of the truest accounts of "living the dream" ever published. "Does for downshifting what Lewinsky did for Clinton - only much funnier..."', 'Chucking It All', 1.02, 8.82, 40, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.3, 3.99, '9780957338753', '0957338759', 0, 99.51, 2.14, '2017-06-12', 'Michael is missing. I am his legacy. Reluctantly, Michaelson re-enters the murky world of London''s elite vampires. Spanning several years, The London Vampire recounts his darkest encounters, makes new alliances and walks the painful path of redemption. Memoirs culminate in the fight against human traffickers - a darker conspiracy ever imagined.', 'Nuptial Flight', 8.93, 7.67, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.28, 3.58, '9780966443066', '0966443063', 286, 52.63, 3.27, '2018-04-10', 'Menacing aliens, a diverted asteroid, the imminent end of the world: these are the sensational elements that Gray Apocalypse fuses together in this tale of heroic action. Can anyone stop the destruction of the human race and the alien takeover of the world? How the threat is dealt with is what this unique and highly entertaining novel is all about.', 'Gray Apocalypse', 8.85, 2.53, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.1, 3.68, '9780979934483', '0979934486', 38, 10.53, 2.15, '2018-03-02', 'This book allows its readers to see past the opinions of others and themselves, and look at the facts of God''s Word.', 'Getting Past the Facts', 4.35, 1.8, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.13, 7.0, '9780985731045', '0985731044', 264, 51.95, 2.88, '2016-11-30', 'In the final entry to the Ashen Twilight book trilogy, an immortal enemy has been revealed with ties to one of the most important figures in the Ashen Twilight House. Ariya is plunged into darkness and Jace''s love is tested when a final strike nearly cripples the houses. The last stand to defeat their enemies will leave many fallen heroes on the battlefield and will shake the Houses to their very core. The battle for the survival of all mortals and immortals ends here', 'Inheritance of Ashes', 4.87, 4.99, 41, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.37, 5.86, '9780986301599', '0986301590', 258, 54.94, 2.73, '2016-09-01', 'A guide for today and beyond, this book chronicles the possibility of a renaissance in religion and transforms our understanding through its inviting message. Gods and the names for God have changed in every era, yet one dynamic remains constant-the Light.', 'The Light', 4.61, 6.62, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.71, 2.85, '9780988178373', '0988178370', 244, 9.78, 4.46, '2015-11-27', 'Time Travel. Blessing or curse? One man thinks he has it all figured out but what began as a simple test has turned into a nightmare. With his equipment failing all around him, only Red and James can save him. Can they reach him in time? Book 2 of the Red Warp series.', 'Time Rock', 1.41, 2.97, 42, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.42, 4.02, '9780988643529', '0988643529', 444, 8.33, 4.82, '2016-12-20', 'Alien Hitman is a prequel to the Euclidian series, which follows the exploits of Adar, an alien from the Ossuary System, which consisted of a race of warriors. He lived to fight and to kill. For that reason the Euclidian hired him as a guard and assassin. Adar was sent to Earth to find a group of treacherous aliens who killed a group of people then escaped from lockup to hide on Earth. Adar is a reluctant hero who is hoping to one day find love. To pass time while he learned of the aliens? whereabouts and feed his thirst for blood, Adar decided to join the mob where he chopped his way through bad guys. Along the way he found some lives to save.', 'The Euclidian', 9.02, 7.18, 43, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.62, 8.21, '9780989828468', '0989828468', 366, 79.75, 2.77, '2015-02-03', 'BOOK THREE OF THE GREAT WAY: What was once the Peradaini Empire is now a wasted landscape of burned, empty cities and abandoned farmlands. The Blessing, now more numerous than ever, continues to spread across the continent, driving refugees to the dubious safety of the city walls. Unharvested crops mean that few strongholds have enough provisions to last the winter, although most know the grunts will take them before starvation will.But hope survives. A piece of stolen magic just might halt the spread of The Blessing if Tejohn and Cazia can find a scholar with the skill to recreate the spell. If such a person still lives.Unfortunately, they are nearly out of time. The few remaining human enclaves are isolated and under siege. Worse, The Blessing has spread to other sentient creatures. If Cazia and Tejohn are going to strike back at their monstrous enemy, they can not delay.And there''s another, deeper question left unaddressed: where did The Blessing come from, and why have they invaded Kal-Maddum?The Way Into Darkness is the final book in The Great Way, wrapping up the story begun in The Way Into Chaos and continued in The Way Into Magic.', 'The Way Into Darkness', 4.2, 4.35, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.27, 7.29, '9780990588429', '0990588424', 480, 42.23, 2.37, '2016-08-29', 'From near thirty winters past, through the Battle for the Dragon Clan and beyond, a convergence is rushing toward the mysterious Keep of St Swiftyn''s. With the Fates hounding their every move, can Darque rebuild the Brotherhood, find the True King, and prevent the death of life? Against incredible odds, does she have time?', 'Death of Life', 3.98, 8.93, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.54, 5.29, '9780994335524', '0994335520', 468, 31.21, 1.57, '2017-12-30', 'Aliens. They always attack when you least expect it. Although if we knew our history we would''ve expected these ones. But the truth about human history has been long forgotten, dismissed as mere myth and legend.Not that Kim McLean really cares about the details. All she knows is that one minute she was wondering what a medieval hot dog might have been filled with, and the next she was beating aliens over the head with a mace. Now it''s up to her alone to end this war. Well, just her, and a crew that have come to her across the gulf of years and may just be as much trouble as the enemy.Her journey will take her to the far ends of the galaxy and to universes that humans haven''t visited for 50 thousand years to fight an enemy that nobody in the galaxy can defeat.', 'Songs of Space and Time', 4.01, 4.72, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.84, 1.27, '9780994335531', '0994335539', 528, 95.69, 3.65, '1999-03-17', 'Kim has found an ancient starship on the world of Nexis and, against all odds, has made it into space. But if she thought that was hard, all she has to do now is find some more crew, deal with the US Airforce and end a 50,000-year old war against an enemy she doesn''t understand. And she has to do all of that, just so she can fight the battle that really matters. But with the multeese not giving her a chance to think, Kim doesn''t know if all the ships in the galaxy will help.', 'All the Wars of Heaven', 5.75, 8.31, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.17, 2.62, '9780994742735', '0994742738', 290, 9.93, 2.12, '2016-03-01', 'Captain Jonathan Dallas, commodore of Battle Unit 72, investigates the disappearance of a military research vessel on the fringes of known space. When the unit is ambushed by a threat that endangers not only the fleet but also all of humanity itself, Jonathan must somehow find the resources to fight back. Cut off from Central Command and faced with impossible odds, can Jonathan overcome his demons to save humanity and, more importantly, can he save himself? Flagship: where captains are made. Or broken.', 'Flagship', 4.25, 6.26, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.58, 9.43, '9780994758408', '0994758405', 260, 54.27, 1.38, '2015-06-23', 'Imagine how your life could be if travel was inexpensive of free. Forget winning the lottery, forget waiting until next year... Whether you''re a five star traveler, a backpacker, or anywhere in between, you can travel now at a fraction of the going rate. Unlike subject specific travel literature that tells you where to go and what to do, this practical book shows you how to: - Beat the best online fare - every time - Turn a one-way flight into a ''half-way-around the world'' ticket - Bypass checked bag and roaming fees - Stockpile travel rewards points without buying anything - Beat Priceline by understanding how it works - Fund your travels - Avoid EXTREME travel scams that can empty your wallet - Find coupons for up to 40% off in most major cities - Disaster proof your vacation You also get: - How to travel 5 times more on the same budget using lean principles. - Hundreds of niche travel resources for families, business travelers, couples, students and solo travelers. - The 7 factors that play a hand in any travel deal, and how to use them to your advantage. - Actual tools and templates Russell uses to travel 5 times more for the local cost of living. - A step-by-step system that shows you how to multiply your savings. You don''t need to quit your job, sell your home or leave your life. Stop Dreaming ... Start Traveling has everything you need to globetrot - without the bill. "This book is the ultimate Get Out of Town FREE card. it is chock full of tips, tricks, steals and deals. Russell quiets any doubts about being able to travel more often, to better destinations, on less money without skimping on luxury. Pack your bags, you''re in for a whole new adventure!" - DANETTE KUBANDA, Emmy-Winning TV Producer, 2011/2012 "Woman of the Year" - National Association of Professional Women "This is more than a travel book. It''s a life training book that defies the clichE ''You get what you pay for.'' It will change your travel destiny." - ARTHUR VON WIESENBERGER, Host, Around the World Travel TV "Inexpensive travel doesn''t need to be no frills. Russell has done the research and brings together the tips and resources to maximize your travel dollar while doing it in style!" - SIMON DONATO, PhD, Star of Boundless TV, founder of Adventure Science "Russell makes it easy for you to save time and money by pulling great travel tips and resources together." - PATRICK SOJKA, Founder of rewards Canada and Frequent Flier Bonus Points "I wish I had read this years ago. Russ covers every angle from planning and budgeting to short-cuts, cost-saving advice and overall safety. It''s a required reading for anyone looking to get more from sir travel dollar. Don''t plan another trip until you read this book!" - ROD MORGAN, President, Sigma Plus Solutions Inc., Lean Six Sigma Quality Consulting "This book has the greatest ways to save money while traveling from A-Z and I gladly recommend it." - TRAVEL COACH CHRIS, President, Lifetime Leisure Experiences', 'Stop Dreaming Start Traveling', 8.7, 4.13, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.85, 4.6, '9780995383906', '0995383901', 222, 84.92, 1.69, '2016-10-09', 'Time Travel, daring adventure and romance await sixteen-year-old exchange student Ingrid Calloway during her visit to France. When Ingrid joins a war-game re-enactment with local teenagers Luc and Marianne Durand, all hell breaks loose! Gunfire, tanks and explosions become real, as the trio are transported back in time to the perilous trenches of the First World War. It''s not a game any more. As Ingrid struggles to adapt to a dangerous world vastly different to her comfortable 21st century lifestyle, she finds herself attracted to headstrong Luc. But while Ingrid desperately wants to return home, Luc wants to stay put in this quaint pocket of yesteryear. However, these 1916 streets of Paris aren''t how observant Ingrid remembers them from her school lessons. Someone is rewriting history. As events spiral out of control, the teenagers must band together and confront their worst fears, if they''re to get back to their own time alive.', '1916-ISH', 6.03, 2.39, 18, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.43, 3.3, '9780996307888', '0996307885', 226, 46.2, 4.01, '2016-01-26', '. The work is a lighthearted and surprisingly informative read, featuring on-the-ground stories from scores of participants in Colorado''s historic transformation into a cannabis-friendly state. The book doubles as a reference guide, listing Colorado dispensaries, marijuana stocks and more."Legalizing pot in Colorado changed everything. Cultures were transformed, entrepreneurs descended on the state, and people couldn''t stop talking about it," says author Johnny Welsh. Johnny Welsh''s unique perspective stems from his career as a professional bartender in the heart of Colorado''s famous ski country. His big, engaging personality encourages friends and strangers alike to share what they have seen and heard about the state''s new cannabis culture.', 'Weedgalized in Colorado', 3.41, 1.67, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.5, 9.62, '9780996706056', '0996706054', 434, 55.71, 2.79, '2016-04-18', 'A Cyberpunk Thriller To Keep You on the Edge of Your Seat! Liquid Cool is the action-packed (and funny), debut cyberpunk detective series. How Much is One Life Worth? In the sci-fi/cyberpunk detective series, author Austin Dragon shows why you never want to meet a cyborg in a dark alley. Liquid Cool is a cross between Blade Runner and the Maltese Falcon. There is plenty of gritty action, suspense, thrills, and even a few laughs. It''s cyberpunk reimagined--an ever-rainy world of colossal skyscrapers, hover-cars, flashy neon streets, and futuristic mechanization. Metropolis isn''t a bad place, but it isn''t a good one either. Uber-governments and mega-corporations fight for control of the fifty-million-plus super-city, but so does crime. We meet Cruz, our private eye (and unlikely hero), in this super-city with a million victims and perpetrators. Watch out for tech-tricksters, analog hustlers, and digital gangsters--psychos, samurais, and cyborgs aplenty. Visitors have a way of becoming permanent attractions. Welcome to the high-tech, low-life world of Liquid Cool.', 'Liquid Cool (Liquid Cool Book 1)', 1.75, 9.98, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.86, 8.13, '9780997013276', '0997013273', 0, 63.83, 1.79, '2016-10-23', 'You would think that being the daughter of Santa would be a dream come true, but you would be wrong. Wynter Clause is miserable. She wants to get away, so, hiding her true identity, she goes to the one place where she knows no one will look for her. Will Wynter be found out? Accepted? Will Wynter ever step up to the duties that she left behind?', 'The Clause Rebellion', 4.45, 9.15, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.45, 9.37, '9780997392197', '0997392193', 468, 57.95, 3.41, '2016-11-23', 'What does it mean to be human? What if the price of saving humanity is giving up your own? The year is 2322, and we stand upon the precipice of extinction. The invading Metigen armada has decimated the eastern third of settled space in a matter of days, leaving tens of millions dead. Determined to save the heart of human civilization, Earth and Seneca at last put aside their differences to face the threat together. But even this may not be enough to stop the fleet of colossal dreadnoughts inhabited by advanced AIs. Alex Solovy and Caleb Marano hold the key to defeating the invaders, for they know the secrets the aliens wage war to protect. Now they face a deadly gauntlet of relentless alien hunters and assassins sent to kill them before they can unleash a potent new weapon. They will risk everything in a bid to save their families, their loved ones, the entire human race--even if it means they can''t save each other. The lines blur between man and machine, ally and enemy, and soldier and civilian. In a final stand against an ancient, powerful foe intent on eradicating it from the universe, humanity comes face to face with its destiny. When faced with its greatest challenge, will humanity rise to triumph or fall to ruin? Aurora Rising is an epic tale of galaxy-spanning adventure, of the thrill of discovery and the unquenchable desire to reach ever farther into the unknown. It''s a tale of humanity at its best and worst, of love and loss, of fear and heroism. It''s the story of a woman who sought the stars and found more than anyone imagined possible.', 'Transcendence', 3.03, 2.46, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.56, 1.59, '9780997578645', '0997578645', 256, 5.31, 4.87, '2018-11-16', 'A hardened detective and his idealistic, young deputy investigate the attempted murder of a child and uncover a secret with earth-shattering implications.', 'Shattered Nine', 9.34, 8.82, 44, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.19, 5.15, '9780997680829', '0997680822', 80, 29.09, 1.86, '2018-02-03', 'Visually astonishing, and insightful, Chronicles of Entanglement, debuts artist/author''s Rodrigo de Toledo unique blend of illustrated fiction, graphic novel and artist''s book. An intimate tale of search for beauty and identity in a foreign land. The book''s whimsical illustrations and writing reveal a poetic landscape, and a personal mythology.', 'Chronicles of Entanglement', 5.29, 5.74, 45, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.84, 1.48, '9780997779516', '0997779519', 306, 21.8, 3.76, '2017-07-04', 'A collection of quirky tales, NAKED JOY pulls back the curtain on the life of a small-town girl turned worldly woman. From Idaho roots to Manhattan capers to EXPAT living, the author shares her offbeat observations - from Tater Tots to Japanese toilets. More than a memoir, this book is a trip - around the world and back.', 'Naked Joy', 5.5, 4.37, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.33, 1.76, '9780998288833', '0998288837', 366, 8.7, 1.21, '2017-04-25', 'What if Sir Arthur Conan Doyle was right all along, and Harry Houdini really DID do his illusions, not through sleight of hand, but via noncorporeal means? More, what if he could do this because...he wasn''t human? Ari Ho''d''ni, Glu''g''ik son of the Special Steward of the Royal House of Va''du''sha''ā, better known to modern humans as an alien Gray from the ninth planet of Zeta Reticuli A, fled his homeworld with the rest of his family during a time of impending global civil war. With them, they brought a unique device which, in its absence, ultimately caused the failure of the uprisings and the collapse of the imperial regime. Consequently Va''du''sha''ā has been at peace for more than a century. What is the F''al, and why has a rebel faction sent a special agent to Earth to retrieve it? It falls to the premier team in the Pan-Galactic Law Enforcement and Immigration Administration, Division One -- the Alpha One team, known to their friends as Agents Echo and Omega -- to find out...or die trying.', 'A Small Medium at Large', 6.43, 9.59, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.34, 5.16, '9780998294216', '0998294217', 86, 27.44, 2.49, '2017-03-01', 'The rain streaming down the window pane entices her to join it in its run. Why does it have such pull on her soul? Does the rain truly have the answers of her past? Who is the young female dancing in the rain? Why can''t she wake from this nightmare, back to the life she knows is hidden somewhere at edges of this horrible world?', 'Window Pane', 8.86, 1.97, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.81, 7.39, '9780998661513', '0998661511', 294, 30.41, 5.0, '2017-04-20', 'Whether your taste runs to crocodiles, ancient relics or flying saucers, you''re sure to find entertainment and illumination in this collection of 21 true travel stories. Join in on the author''s adventures as she:* Makes a pilgrimage to see a 2,200-year-old tooth.* Considers the fate of a three-legged elephant.* Learns the chilling secrets of the Jamaica Inn pirates.* Participates in a shamanic ayahuasca ritual.* Discovers the secrets of alien spaceship propulsion.* And more ...', 'Your Crocodile Has Arrived', 9.39, 9.89, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.24, 2.73, '9780998861722', '0998861723', 0, 95.53, 1.38, '1978-04-04', '“,Doug, I been practicin’, law for fifty years. And I learned a long time ago, there ain’,t no such word as ‘,attorney’, or ‘,lawyer’,. It’,s ‘,asshole attorney’, or ‘,fuckin’, lawyer.’, ", Author Douglas Wood first heard that advice from a southern lawyer nearly forty years ago. It was his inspiration to write Asshole Attorney, a book of observations and reflections over his lifetime and legal career. A self-proclaimed “,Army Brat”,, Doug moved to eight different homes throughout his childhood. His last move from Hawaii to Rutherford, NJ was a tough one, especially when faced with years of cold, snowy winters in lieu of sandy beaches and warm sunsets., His madcap journey included college in Rhode Island, three law degrees, working with out-of-control rock stars, dealing with international crises in the dark alleys of Eastern Europe, and a partnership in one of the world'',s leading law firms. Readers will be charmed by Wood’,s candor and humor and will laugh aloud at his sharp, witty commentary as he navigates the pathways of his life and the jungles of his profession_,', 'Asshole Attorney', 9.12, 9.05, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.57, 6.42, '9780998952222', '0998952222', 418, 95.92, 2.5, '2018-02-20', 'Lured by the need for control over her life and the need for respect as a woman, Barbara Troye leaves her principles behind when she enters college. Living in a different world she soon becomes disgusted, and angry at her life. She finds herself on a path not of her own making but of the dragon. She has left her belief and trust in a personal God behind to seek her own desires. Can she be rescued before she falls victim to the lies of a demon?', 'A Gathering of Dragons', 7.61, 5.33, 46, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.35, 1.95, '9780999185209', '0999185209', 236, 87.16, 2.03, '1967-07-19', 'In the wake of September 11th, New York native John Dennehy turned to pacifist idealism and activism. But the bombs fell over Iraq anyway. When the nation reelected George Bush, Dennehy left the country. At twenty-two-years-old he impulsively moved to Ecuador hoping to experience their revolutionary social movements up close.Two years later, after falling in love with a local girl and witnessing student activists overthrow the Ecuadorian Government¿the revolution turned nationalist and began targeting U.S. interests and citizens in Ecuador. Dennehy was arrested and deported¿but he had found something worth fighting for. Two days later he snuck back in from Colombia with the help of corrupt police and drug smugglers. Over the next year, he lived in Ecuador illegally and crossed four more times. He earned an education in borders, even as the life he fought so hard to save unraveled more with each illegal crossing.', 'Illegal', 5.99, 8.64, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.18, 3.64, '9780999190616', '099919061X', 408, 33.37, 4.73, '1942-01-06', 'In the near future, a device called the Univiz that can seamlessly switch between augmented and virtual reality has revolutionized how people interact with the world and each other. It''s inventor, Oreste Pax, is now the head of the largest company in the world, but he is facing a shareholder revolt. Pax¿s only hope for keeping control of his company lies with a new project he hopes will do for human cognition what the Univiz did for personal computing.However, unbeknownst to Pax, a brilliant sociopath called the Mechanic has unleashed a world-wide computer virus that is well on its way to tearing apart the fragile bonds holding human society together. Pax will soon be torn away from his concerns over his company¿s future by a mysterious society attempting to fight the virus with a quantum computer they call the Infinet. Pax will have to make a decision that will affect the future of the human race, and the choice of what to do is his, and his alone.', 'The Infinet', 2.17, 5.57, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.85, 3.55, '9780999238578', '0999238574', 424, 17.91, 4.33, '2018-03-29', 'Madison Fox is determined to reform Jamie, her half-evil pooka, but the bond linking her to Jamie works both ways. Already, it has manipulated her into bending the rules. If she continues down this path, she could doom her soul. If she hopes to survive, she must make an impossible choice: save herself and her region or save Jamie.', 'A Fistful of Frost', 7.41, 5.15, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.6, 5.16, '9780999446409', '0999446401', 192, 16.41, 1.43, '2017-10-24', 'What this country needs right now to get us out of this political nightmare is you! We need your collective energy and creativity and heart in the fight right now. Wake, Rise, Resist is your guide to this fight. These 128 actions will show you how to get involved in the work for social justice, racial equality, refugees, and more.', 'Wake, Rise, Resist', 6.69, 2.74, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.41, 9.93, '9780999516225', '0999516221', 397, 4.48, 2.36, '1956-04-11', 'The Chenille Ultimatum is the third book in the Chenille series. It takes place on the exotic planet Schtatik, home to quarreling clans, and in San Francisco, where Susan''s great-grandmother Agnes met aliens from that planet when she was a child.', 'The Chenille Ultimatum', 3.79, 7.71, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.35, 7.18, '1101985429', '9781101985427', 641, 2.1, 3.8, '2019-12-31', 'An unfathomable loss or an unthinkable crime? Tami Hoag keeps you guessing in this harrowing New York Times bestselling thriller. When Detective Nick Fourcade enters the home of Genevieve Gauthier outside the sleepy town of Bayou Breaux, Louisiana, the bloody crime scene that awaits him is both the most brutal and the most confusing he''s ever seen. Genevieve''s seven-year-old son, KJ, has been murdered by an alleged intruder, yet Genevieve is alive and well. Meanwhile, Nick''s wife, Detective Annie Broussard, sits with the grieving Genevieve. A mother herself, Annie understands the devastation this woman is going through, but as a detective she''s troubled: Who would murder a child and leave the only witness behind? When KJ''s sometimes babysitter, twelve-year-old Nora Florette, is reported missing the very next day, the town fears a maniac is preying on their children. With pressure mounting from a tough, no-nonsense new sheriff, the media, and the parents of Bayou Breaux, Nick and Annie dig deep into the dual mysteries. Is someone from Genevieve''s past or present responsible for the death of her son? Is Nora a victim, or something worse? Then everything changes when Genevieve’s past as a convicted criminal comes to light. Could she have killed her own child to free herself from the burden of motherhood, or is the loss of her beloved boy pushing her to the edge of insanity? Could she have something to do with the disappearance of Nora, or is the troubled teen the key to the murder? How far will Nick and Annie have to go to uncover the dark truth of the boy?', 'The Boy', 7.69, 6.31, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.62, 8.66, '9781250014016', '1250014018', 0, 59.2, 1.29, '2012-10-02', 'A middle class, Midwestern family in search of meaning uproot themselves and move to their ancestral village in Croatia "We can look at this in two ways," Jim wrote, always the pragmatist. "We can panic and scrap the whole idea. Or we can take this as a sign. They''re saying the economy is going to get worse before it gets better. Maybe this is the kick in the pants we needed to do something completely different. There will always be an excuse not to go..." And that, friends, is how a typically sane middle-aged mother decided to drag her family back to a forlorn mountain village in the backwoods of Croatia. So begins the author Jennifer Wilson''s journey in Running Away to Home. Jen, her architect husband, Jim, and their two children had been living the typical soccer- and ballet-practice life in the most Middle American of places: Des Moines, Iowa. They overindulged themselves and their kids, and as a family they were losing one another in the rush of work, school, and activities. One day, Jen and her husband looked at each other–both holding their Starbucks coffee as they headed out to their SUV in the mall parking lot, while the kids complained about the inferiority of the toys they just got–and asked themselves: "Is this the American dream? Because if it is, it sort of sucks." Jim and Jen had always dreamed of taking a family sabbatical in another country, so when they lost half their savings in the stock-market crash, it seemed like just a crazy enough time to do it. High on wanderlust, they left the troubled landscape of contemporary America for the Croatian mountain village of Mrkopalj, the land of Jennifer''s ancestors. It was a village that seemed hermetically sealed for the last one hundred years, with a population of eight hundred (mostly drunken) residents and a herd of sheep milling around the post office. For several months they lived like locals, from milking the neighbor''s cows to eating roasted pig on a spit to desperately seeking the village recipe for bootleg liquor. As the Wilson-Hoff family struggled to stay sane (and warm), what they found was much deeper and bigger than themselves.', 'Running Away to Home', 1.24, 2.91, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.69, 5.84, '9781250033352', '1250033357', 0, 91.88, 2.49, '2013-06-25', 'A fresh, exhilarating take on one of the world''s most popular topics—Paris, the City of Light!—by an acclaimed novelist Rosecrans Baldwin A self-described Francophile since the age of nine, Rosecrans Baldwin had always dreamed of living in France. So when an offer presented itself to work at a Parisian ad agency, he couldn''t turn it down—even though he had no experience in advertising, and even though he hardly spoke French. But the Paris that Rosecrans and his wife, Rachel, arrived in wasn''t the romantic city he remembered, and over the next eighteen months, his dogged American optimism was put to the test: at work (where he wrote booklets on breastfeeding), at home (in the hub of a massive construction project), and at every confusing dinner party in between. A hilarious and refreshingly honest look at one of our most beloved cities, Paris, I Love You but You''re Bringing Me Down is the story of a young man whose preconceptions are usurped by the oddities of a vigorous, nervy metropolis—which is just what he needs to fall in love with Paris a second time.', 'Paris, I Love You but You''re Bringing Me Down', 4.73, 4.24, 47, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.62, 9.02, '9781250050311', '1250050316', 0, 75.69, 3.39, '2014-08-12', 'WINNER OF THE NATIONAL OUTDOOR BOOK AWARD FOR NATURAL HISTORY LITERATURE A FINALIST FOR THE WILLIAM SAROYAN INTERNATIONAL PRIZE FOR WRITING A SEATTLE TIMES BEST BOOK OF THE YEAR When biologists Aaron Hirsh and Veronica Volny lead twelve college students to a remote fishing village on the Sea of Cortez, they encounter a bay of dazzling beauty and richness. But as the group begins its investigations—conducting ecological and evolutionary studies of the area and its natural inhabitants; listening to the stories of local villagers; and examining the journals of conquistadors and explorers—they realize that the sea is but a ghost of what it once was. And yet there is redemption in their difficult realization: as they find their places in a profoundly altered environment, they also recognize their roles in the path ahead, and ultimately come to see themselves in a new light. By turns epic and intimate, Telling Our Way to the Sea is a profound meditation on our changing relationships with nature—and with one another.', 'Telling Our Way to the Sea', 3.86, 6.81, 47, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.94, 5.1, '9781250054647', '1250054648', 0, 92.73, 1.25, '2015-01-06', 'Welcome to Downtrodden Abbey, where a battle for the deed to the property is waged between legitimate aristocrats and literal pretenders to the throne. The Crawfish family—Marry, Supple, Enid, Lady Flora, and Lord Roderick—are content wiling their days away with naughty charades and twenty-two course dinners until the sinking of the Gigantic takes down the next in line to inherit Downtrodden. Soon, cousin Isabich and her son, Atchew, the rightful heir to the Abbey, arrive to claim what''s theirs. Downstairs, the servants are running amok, as crippled weakling Brace is aggressively courted by teen hottie Nana, and lady''s maid "Potatoes" O''Grotten and her flamboyant sidekick, Tomaine, cause trouble at every turn. The ensuing, insufferably overwrought melodrama takes the reader upstairs and downstairs, into parlours and drawing rooms, boudoirs and bathrooms, and across every class—from the classiest to the classless—in the social pecking order of Edwardian England. Uproariously funny, with a wicked sense of humor that Downton Abbey diehards will enjoy, Gillian Fetlocks skewers your favorite characters with panache in this winning parody', 'Downtrodden Abbey', 3.98, 3.52, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.36, 3.96, '1250077990', '9781250077998', 129, 39.4, 1.97, '2016-03-08', 'Is your eyesight failing, are you not very good at driving yourself, or are you simply blind drunk? These are just a few of the reasons why it would make perfect sense to teach your dog to be your new chauffeur. Here, for the first time, is a complete guide: how to get your dog acquainted with the controls, which breeds are the safest drivers, frequently asked questions; and how to get your dog successfully through their tests. Never again need you wait for a taxi, or make that long highway drive unassisted. If you are a dog owner and a car owner, then How to Teach Your Dog to Drive will be the most useful book you buy this year, or even this decade . . .', 'How to Teach Your Dog to Drive', 4.62, 2.76, 28, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.84, 2.94, '9781250122926', '1250122929', 288, 18.35, 1.41, '1996-10-03', 'A riveting, modern-day gothic tale about a woman who succumbs and then must save herself from a dark lover "That night was the first time I tasted champagne French he told me, and as I loved all things French I was enchanted. I barely remember what we said only that I did most of the talking: about leaving the South, my dreams of becoming a writer, my thoughts of Harlem . . . and of you. He said very little, only this: "The moment I saw you I knew you would be mine forever. And even death, even that, could not part us."" Jocelyn''s life feels empty, devoid of passion and purpose. After she finds a journal written by her "doomed" great-grandmother, Caprice, she is spellbound by her story: the escape from a loveless marriage, her seduction by a nameless lover who is both "demon and savior." Then, as if stepping out of a dream, Jocelyn meets Asa, her mysterious next door neighbor. Asa is charming, handsome, and daring and, as if by magic, she is drawn into his hedonistic lifestyle. Yet there is something unsettling about Asa. Luna is suspicious of this man, and although Jocelyn is dismissive of Luna and amused by her friend''s warnings, she can''t completely ignore them. She begins to wonder if things with Asa aren''t quite what they seem."', 'When the Night Whispers', 8.74, 6.86, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.49, 1.02, '9781250123275', '1250123275', 544, 81.14, 2.56, '2008-07-29', '', 'The Race', 9.98, 4.71, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.92, 4.45, '9781250293657', '1250293650', 736, 44.16, 1.98, '2020-01-28', 'Endgames is the stunning final volume in L. E. Modesitt, Jr''s, New York Times bestselling epic fantasy series the Imager Portfolio, and the third book in the story arc that began with Madness in Solidar through Treachery''s Tools and Assassin''s Price. Solidar is in chaos. Charyn, the young and untested ruler of Solidar, has survived assassination, and he struggles to gain control of a realm in the grip of social upheaval, war, and rioting. Solidar cannot be allowed to slide into social and political turmoil that will leave the High Holders with their ancient power and privilege, and the common people with nothing. But the stakes are even higher than he realizes. The Imager Portfolio #1 Imager / #2 Imager’s Challenge / #3 Imager’s Intrigue / #4 Scholar / #5 Princeps / #6 Imager’s Battalion / #7 Antiagon Fire / #8 Rex Regis / #9 Madness in Solidar / #10 Treachery’s Tools / #11 Assassin’s Price / #12 Endgames Other series by L. E. Modesitt, Jr. The Saga of Recluce The Corean Chronicles The Spellsong Cycle The Ghost Books The Ecolitan Matter', 'Endgames', 7.25, 7.64, 29, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.76, 1.97, '9781364316129', '1364316129', 288, 41.76, 1.33, '2016-02-23', 'Together, a plant ecologist father and his adult, millennial son hike Tennessee''s Cumberland Trail. They share their observations and various fun facts along the way about themselves, each other, history, backpacking, day hiking, salamanders who seemingly rise from the dead, ferns, buckeyes, waterfalls, rock formations, possibly mind-reading exhibitionist leeches, the cuteness of toads, hickory "miscarriages," coyotes, the Scopes "Monkey" Trial, the similarity between rattlesnakes and rebellious teenagers, the tenderness of vultures and wild hogs as parents and much more. Join them for a walk you won''t forget. Two dollars of the book price goes to the non-profit Cumberland Trails Conference which is helping to build the trail.', 'Wildly Strolling Along', 2.7, 5.12, 18, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.26, 4.71, '9781364435783', '1364435780', 174, 82.78, 3.3, '2016-01-26', 'Our annual guide to the extraordinary outdoors of the Pacific Northwest. The Summit Book 2016 serves as our mile marker. Our annual celebration of the one of the greatest places on this planet.The Outdoor Society strives to help define and explain outdoor culture in the Pacific Northwest through our experiences in and around the wilderness areas we call home. We love this place and we know you do too. We know that for nearly everyone that lives here, there is no greater place on earth and nowhere else we would rather be. This is the land of mountains, glaciers, rivers and salmon. This is the location of rainforests and ice caves, volcanoes and canyons. The Pacific Northwest is where we work, live and most importantly, play. We want to help with that, and we want you to come along on this journey.', 'The Summit Book 2016', 2.17, 8.05, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.4, 3.1, '9781366338433', '136633843X', 234, 94.17, 3.9, '2018-04-24', '"First zombies and now this? Jesse was freaking sucking Stacey''s neck for blood. It was disgusting and kinda hot, but more disgusting. Anyways, I lost a lot of respect for Jesse then, not because he was a vampire, but because he could have done a lot better than Stacey Thompson." Rosetta Stone is a 17-year-old girl struggling with the awkwardness of teen angst, her bald stepdad and stuck-up cheerleaders. When the zombie outbreak comes to her high school, she''s forced to leave everything behind to find her dad in Montana. On her journey across the nation, Rosetta must discover who is trustworthy and who is deadly in this post-Z world and that includes her vampire crush, Jesse Sweeney. Relationship status update: it''s complicated! In a world full of monsters, will Rosetta become one? Or will she fight to keep her humanity and discover what she''s really made of?', 'Surviving the Zombie Apocalypse While Dating a Vampire', 5.04, 5.62, 18, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.35, 1.53, '9781366439239', '1366439236', 0, 53.35, 1.13, '2017-01-22', 'This is a book for those who have finally accepted the insanity of our human situation. That means anyone who understands that our finest insights often appear in moments of complete surrender, such as when we laugh. It is then that we allow cracks to form in the brittle shell of certainty that hides the light of reality. The Philosopher''s Stoned makes no claim to offer answers for any spiritual seekers among you. What it does offer is an out-of-kilter view of the world that may offend some and delight others. Above all, it strives to lay waste to our lazy assumptions about life. In doing so, it targets universal themes that should resonate with anyone''s experience.', 'The Philosopher''s Stoned', 4.7, 8.39, 18, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.92, 7.45, '9781367910294', '1367910293', 444, 47.09, 1.92, '2016-04-07', 'A directionless produce stocker. A foul-mouthed bicycle messenger. A reclusive businesswoman. A homeless musician. A flippant heir. The alien Drifters chose these unwilling strangers to play in their gladiatorial game. Before an audience beyond human comprehension, Earth''s new superheroes must put on a good show or doom their planet to destruction. But being super isn''t like the comic books said. The monsters don''t go down easy, the public isn''t always on your side, and your own team members can be as cruel as any villain. Despite it all, the heroes must play their roles and unravel a mystery that could alter Earth''s place in the stars forever.', 'Necessaries', 9.99, 5.56, 18, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.61, 7.67, '9781367910300', '1367910307', 444, 16.2, 1.48, '2016-04-07', 'A directionless produce stocker. A foul-mouthed bicycle messenger. A reclusive businesswoman. A homeless musician. A flippant heir. The alien Drifters chose these unwilling strangers to play in their gladiatorial game. Before an audience beyond human comprehension, Earth''s new superheroes must put on a good show or doom their planet to destruction. But being super isn''t like the comic books said. The monsters don''t go down easy, the public isn''t always on your side, and your own team members can be as cruel as any villain. Despite it all, the heroes must play their roles and unravel a mystery that could alter Earth''s place in the stars forever.', 'Necessaries', 1.86, 9.2, 18, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.45, 7.47, '9781388630386', '1388630389', 400, 53.9, 3.98, '2018-04-12', 'This is not a tale of redemption. It is not a path to inspire dreams. It is the rise of Lakrius. The man of many names. The deceiver of time. The king of fortune lost. * * * Working as a blacksmith for noblemen willing to kill to protect their secrets, Avvyr knows his days are numbered. Unless he walks a path more dangerous than death itself. As he unearths the truth behind their power--something far grimmer than he ever could have imagined--Avvyr realizes there is a way to put an end to the nobles'' brutal reign. But while his intentions are pure, his actions thin the divide between life and darkness, threatening to entrap him in the very cage he wanted the world to escape.​', 'Forged in Flames', 8.42, 5.99, 18, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.33, 9.03, '9781389054112', '138905411X', 342, 51.0, 1.17, '2018-01-03', 'When journalist Catherine Cobb arrives in the East Texas town of Elena, she quickly finds herself fighting for her life. Something is spreading through the population, turning ordinary civilians into murderers capable of committing the most heinous crimes. As the body count continues to rise, Catherine walks into one nightmare after another, uncovering a secret plot involving a group of neo-Nazis, top-level federal government, and the strange world of the occult - with global implications. Before long, Catherine finds herself trapped in a terrifying world that she doesn''t understand. And might not escape from.', 'Tongues', 7.55, 5.18, 18, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.52, 3.14, '9781389232312', '138923231X', 120, 76.42, 4.71, '2018-01-18', 'This immersive adventure gamebook is designed to be played by candlelight with 3-16 players. Includes free downloads of 6 hours os soundscapes, PDF version, printable props and 25 masks. The four interactive tales will take you into a world of Wizards and witches like no other experience.', 'Storymaster''s Tales School of Wizards & Witches Dark Fairy Tale: A Parlour Gamebook 3-16 Players', 4.69, 9.56, 18, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.27, 3.01, '9781389297250', '138929725X', 60, 55.66, 1.53, '2017-11-26', 'The pharaoh who ruled Egypt was a tyrant who oppressed the descendants of Prophet Jacob (pbuh), known as the children of Israel (Bani Israel). He used every means to demean and disgrace them. They were kept in bondage and forced to work for him for small wages or nothing. Under this system the people obeyed and worshipped the pharaoh, and the ruling class carried out his orders, thereby authorizing his tyranny and crazy whims. The pharaoh wanted the people to obey him only, and to believe in the gods of his invention. Thus, successive dynasties came to Egypt and assumed that they were gods or their representative or spokesmen. Years passed, and a despotic king, who was adored by the Egyptians, ruled Egypt. His king saw the children of Israel multiplying and prospering. He heard them talking about a vague vision that one of Israel'' s sons would dethrone the pharaoh of Egypt. Perhaps this vision was only a daydream that persisted within the hearts of the persecuted minority, or perhaps it was a prophecy from their books. Another tradition states that it was Pharaoh himself who had the vision. Ibn ''Abbas narrated: "Pharaoh saw in his vision a fire, which came from Jerusalem and burned the houses of the Egyptians, and all Copts, and did not do harm to the children of Israel. When he woke up, he was horrified. He then gathered his priests and magicians and asked them about this vision. They said: "This means a boy will be born of them and the Egyptian people will perish at his hands.'' That is why Pharaoh commanded that all male children of the children of Israel be killed." Either way, this vision reached the ears of the Pharaoh. He then issued a decree to slay any male child that would be born to the children of Israel.', 'Exodus Tales of Prophet Moses (Musa) & Prophet Haron (Aaron)', 1.95, 8.06, 18, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.75, 8.51, '9781389396441', '1389396444', 444, 50.76, 3.76, '2017-11-08', 'At the edge of the galaxy, shadows gather. The true dark, not merely the absence of light. At the vanguard of its advance, the youngest of a near-immortal race is flung into the fulcrum of cosmic history. In order to solve the mystery of the shadows, he must first unravel the riddle of his species'' existence, a secret which has been well hidden for over 20,000 years. What he finds will change everything. From the author of Rewired comes an adventure into deep space, both without and within.', 'Threnody', 6.72, 3.06, 18, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.41, 6.6, '9781389663550', '1389663558', 334, 60.91, 3.58, '2017-10-02', 'Elizabeth is angry and she needs someone to blame. As storm clouds build on her way home from work Elizabeth finds herself as charged as the night sky. The three men who follow her down the dark alley bear the brunt of a supernatural blast as Elizabeth''s rage harnesses the elements in a way she never expected. Elizabeth is devastated by the forces she has unleashed and begins to ask difficult questions about the path her life is taking. The answers she finds lead to more questions, but also to new friendships, adventure and finding the strength to fulfil her true potential. Elizabeth has to look deep within herself for long forgotten memories and a lifetime of hidden magic as she discovers the strength to face her demons.', 'Witch Way ... for Me?', 3.5, 4.28, 18, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.55, 1.05, '9781409196808', '1409196801', 304, 67.75, 3.86, '2020-02-20', '''Plunge a syringe filled with adrenaline into the heart of Twelve Angry Men and you''ve got The Holdout: the first legal thriller in thirty years - ever since Presumed Innocent and A Time to Kill electrified readers the world over - to rank alongside those two modern classics.'' AJ Finn''The most gripping and satisfying thriller I''ve read in more than a decade'' Sophie Hannah''Quite the tour de force! Twelve Angry Men meets Chinatown and creates something of its own'' Sarah Pinborough''This is a tense, emotionally charged, scary-good, stand-out read that hooked me until the last page'' Caroline KepnesOne juror changed the verdict. What if she was wrong?''Ten years ago we made a decision together...''Fifteen-year-old Jessica Silver, heiress to a billion-dollar fortune, vanishes on her way home from school. Her teacher, Bobby Nock, is the prime suspect. It''s an open and shut case for the prosecution, and a quick conviction seems all but guaranteed. Until Maya Seale, a young woman on the jury, persuades the rest of the jurors to vote not guilty: a controversial decision that will change all of their lives forever.Ten years later, one of the jurors is found dead, and Maya is the prime suspect.The real killer could be any of the other ten jurors. Is Maya being forced to pay the price for her decision all those years ago?', 'Holdout', 1.58, 1.67, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.65, 8.03, '9781420932492', '1420932497', 0, 70.23, 2.69, '1968-09-22', 'Diamond, a young boy living in nineteenth-century London, has many adventures as he travels with the beautiful Lady North Wind and comes to know the many facets of her protective and violent temper.', 'At the Back of the North Wind', 7.9, 7.57, 48, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.08, 6.97, '9781434457622', '1434457621', 484, 81.56, 1.28, '1944-09-14', 'Like Stephen King''s ''Salem''s Lot, the town of Ewerton, Wisconsin is a bad place -- a VERY bad place! Whatever malignant spirit governs this little burg lost in the middle of bloody nowhere, it doesn''t much like the people who live there. No one ever TRULY leaves Ewerton--not really! As Ardath Mayhar says, "The horror Morlan evokes is not so much occult as uniquely human--the worst of human traits are her stock in trade."', 'Dark Journey', 1.17, 3.92, 49, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.71, 9.5, '1443734918', '9781443734912', 292, 26.33, 4.46, '2008-11-01', '''It is personal to every reader, it will become for every one a reflection of himself. I fancy that here, as always where work is fine and true, the author has created something not as he would but as he must, and here an interpreter of a world more wonderful than he himself knows.'' Hugh Walpole', 'Thunder on the Left', 6.21, 8.19, 50, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.03, 4.61, '9781463329525', '1463329520', 0, 80.39, 1.29, '1981-09-21', 'Have you ever been sick of everything? Have you ever felt a deep void that you can''t fill with anything? Have you noticed that your nature guides you to act one way, but if you dare to follow it, you will be severely judged? Have you felt that you don''t fit in completely; that there is something that you maybe still have to find and that it would make sense of everything? Have you experienced fear? Have you felt guilt? Would you like to stop feeling them forever? Are you tired of crying, of suffering and enduring pain, and even so there are still cynics who tell you that this is the road to eternal happiness? And if all the answers were always with you? And if you were always right? And if your unlimited potential was always there, and now it''s ready to burst forth and show the world that the truth was always with you and not with everyone else? Angel Whitewolf, the dark enlightened one, has awakened, and he is here to show you, if you wish, that the greatest power imaginable belongs to you... and to use it, you have only to reclaim it through being yourself. It''s only fair that things finally be done your way...', 'Angel Whitewolf', 6.59, 9.0, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.86, 5.59, '1463329547', '9781463329549', 242, 48.01, 2.6, '2003-04-20', 'Have you ever been sick of everything? Have you ever felt a deep void that you can''t fill with anything? Have you noticed that your nature guides you to act one way, but if you dare to follow it, you will be severely judged? Have you felt that you don''t fit in completely; that there is something that you maybe still have to find and that it would make sense of everything? Have you experienced fear? Have you felt guilt? Would you like to stop feeling them forever? Are you tired of crying, of suffering and enduring pain, and even so there are still cynics who tell you that this is the road to eternal happiness? And if all the answers were always with you? And if you were always right? And if your unlimited potential was always there, and now it''s ready to burst forth and show the world that the truth was always with you and not with everyone else? Angel Whitewolf, the dark enlightened one, has awakened, and he is here to show you, if you wish, that the greatest power imaginable belongs to you... and to use it, you have only to reclaim it through being yourself. It''s only fair that things finally be done your way...', 'Angel Whitewolf', 2.02, 7.8, 51, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.5, 7.78, '9781466609457', '1466609451', 0, 7.63, 4.48, '1966-09-20', '"This book provides relevant theoretical frameworks and the latest empirical research finding to improve understanding of geospatial discovery methodologies and technologies, as well as techniques to design and deploy geospatial resources in Information Infrastructures"--Provided by publisher.', 'Discovery of Geospatial Resources', 6.68, 5.08, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.21, 6.18, '9781466618275', '1466618272', 0, 72.63, 2.53, '1999-10-02', 'Ubiquitous Positioning and Mobile Location-Based Services in Smart Phones explores new research in smart phones with an emphasis on positioning solutions in smart phones, smart phone-based navigation applications, mobile geographical information systems, and related standards. Contributors Ming Zu & Kefei Zhang from RMIT.', 'Ubiquitous Positioning and Mobile Location-based Services in Smart Phones', 9.04, 1.01, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.54, 5.68, '9781466619517', '1466619511', 0, 52.14, 1.98, '1996-04-06', '"This book exemplifies the usage of geographic information science and technology (GIS&T) to explore and resolve geographical issues from various application domains within the social and/or physical sciences"--Provided by publisher.', 'Emerging Methods and Multidisciplinary Applications in Geospatial Research', 7.95, 9.99, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.14, 9.06, '9781471157493', '1471157490', 336, 64.63, 4.53, '2019-01-24', 'As addictive as Lee Child and as explosive as Michael Connelly - THE WANTED is the new thriller from Robert Crais, and a NEW YORK TIMES BESTSELLER ''I can''t wait for the next Robert Crais!'' Bill Clinton Seventeen-year-old Tyson is a normal teenaged boy - he''s socially awkward, obsessed with video games, and always hungry. But his mother is worried that her sweet, nerdy son has started to change... and she''s just found a $40,000 Rolex watch under his bed. Suddenly very frightened that Tyson has gotten involved in something illegal, his mother gets in touch with a private investigator named Elvis Cole and asks him to do some digging. Cole uncovers a connection between Tyson and eighteen unsolved burglaries in LA''s ritziest neighbourhood. Tyson spooks and runs. And then people start dying... Robert Crais'' books have been published in a staggering 62 countries and are bestsellers around the world. He began his career writing for classic crime and police shows like Hill Street Blues, Cagney & Lacey, Miami Vice and LA Law. He is a Grand Master of the Mystery Writers of America. * * * PRAISE for THE WANTED * * * ''Cleverly plotted, stylishly written... another rewarding page-turner by one of the most reliable storytellers in modern crime fiction'' Washington Post ''Los Angeles ace Crais extends his streak of sharp, enjoyable thrillers'' Kirkus ''Gripping... The Wanted is a relentless thriller... I found myself engrossed by two terrible -- but remarkably compelling -- villains... a welcome literary gift from a master of the craft'' HuffPost ''Taut... expertly crafted'' Publishers Weekly ''An absolute must read'' Mystery Tribune * * * PRAISE for ROBERT CRAIS * * * ''In Crais, a new star has appeared on the priovate eye scene - a dazzling first novel'' -Tony Hillerman on The Monkey''s Raincoat ''Far and away the most satisfying private eye novel in years. Grab this one - it''s a winner!'' -Lawrence Block on The Monkey''s Raincoat ''Taken is intense and fast-paced and reads like a big-budget Hollywood blockbuster!'' -CNN ''A tale of one man''s bare-knuckled search for redemption. Like the best L.A. noir writers, Crais nudges the mystery genre into higher gear, tackling grand themes in exceedingly personal ways through flawed heroes and hard-to-spot villains'' - LA Times Book Review on The Two Minute Rule', 'The Wanted', 2.3, 4.71, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.07, 9.75, '9781474609593', '1474609597', 0, 16.03, 2.36, '2020-03-31', 'A TIMES CRIME BOOK OF THE MONTH ONE OF M. W. CRAVEN''S BOOKS OF 2019 A ruthless killer is spreading panic in a quiet village in the Italian Alps. Police Inspector Teresa Battaglia is the only one who can stop them. But how can you catch a monster when you''re slowly losing your mind? PREPARE TO FALL IN LOVE WITH TERESA BATTAGLIA, A POLICE INSPECTOR LIKE NO OTHER: ''Superintendent Teresa Battaglia, a criminal profile expert, is in her sixties, overweight, lonely, diabetic, full of the ailments of ageing - and delightful. It''s rare that a character like Teresa Battaglia enters crime fiction for the first time, and with such gripping impact'' Marcel Berlins, The Times (Crime Book of the Month) ''Teresa Battaglia is set to give tyneside''s Vera a run for her money'' Lancashire Post ''Teresa Battaglia is one of the most interesting detectives to emerge in recent years'' M. W. Craven, author of The Puppet Show ''I was rooting for Teresa Battaglia from the start'' Sarah Ward, author of In Bitter Chill ''I totally fell for the tough-but-vulnerable Teresa Battaglia'' Roz Watkins, author of The Devil''s Dice ''A brilliant protagonist, an eerie setting and a community hiding dark secrets'' Dead Good (Debut crime novels to watch out for in 2019)', 'The Man in the Woods', 6.83, 7.01, 52, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.32, 4.1, '9781474610469', '1474610463', 0, 57.98, 1.65, '2020-06-16', '''A WILD RIDE'' Ian Rankin ''TOUGH AND UNCOMPROMISING: YOU''LL BE GLAD YOU READ IT'' Lee Child ''HILARIOUS, GRIPPING, POETIC. I LOVED IT'' Adrian McKinty, author of The Chain ''GRIPPING FROM BEGINNING TO END'' Independent ''INTOXICATING AND CHILLING'' Observer ''PACY AND EXCITING'' Daily Telegraph ''VIVID AND LYRICAL'' Guardian Nobody asked us to look. Every day, every since, I still wish we hadn''t. Jaded reporter Andrew and his photographer boyfriend, Carlos, are sick of sifting the dregs of Mexico''s drug war: from cartel massacres to corrupt politicians, they think they''ve seen it all. But when they find a body even the police are too scared to look at, what started out as just another assignment becomes the sort of story all reporters dream of... ...until Carlos pushes for answers too fast, and winds up murdered, leaving Andrew grief-stricken and flailing for answers, justice, and revenge. MORE PRAISE FOR CALL HIM MINE: ''One thing novelists can do more effectively than journalists, perhaps, is to remind us that every killing in Mexico ought to seem as shocking an aberration as a murder in the St Mary Mead vicarage. This is one of the achievements of this debut novel by Tim MacGabhann, an Irish journalist and Mexico resident... This is not an epic catalogue of depravity in the manner of Don Winslow''s Cartel trilogy; instead, it uses just two murders as a focal point for Mexico''s grief and rage... The novel is written lyrically, with an offbeat humour, which helps defamiliarise a situation to which Western readers have become inured, and communicate its horrors afresh'' Telegraph ''This exciting and accomplished novel is a major achievement, as MacGabhann displays the grace of Greene, the pace of Hammett, the imagination of Bolano and the darkness of Elroy. An exciting new voice in Irish writing'' Irish Examiner ''Call Him Mine soars in two regards. First MacGabhann paints an extraordinarily vivid picture of Mexico, in all its seething, sweltering madness and beauty. The last time I read a book which placed the reader so firmly and intensely into the heart of a place, it was the ''Fate'' and ''Santa Teresa'' sections of Roberto Bolano''s great 2666'' Irish Independent', 'Call Him Mine', 6.11, 5.55, 52, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.49, 9.84, '1475934203', '9781475934205', 244, 92.97, 2.8, '2000-07-18', 'In Working My Way through Retirement, author Lola Albion finds that retirement has many surprises and totally unexpected opportunities in store for her. She shares her unique trek in a series of e-mails written to family and friends from locations throughout the world over a period of nearly eight years. Her travels spanned far and wide, with her messages relayed from places as diverse as Doomadgee, an Aboriginal community in remote Australia; Labrador on the Atlantic edge of Canada; Montenegro in the Balkans; Tanna in the Pacific; Qatar in the Middle East; Italy; Jordan; and Cambodia. Albion shares her extraordinary experiences with a great deal of humour, gentleness, and wise insight into the human condition. She also considers themes of change, ageing, the universality of human hopes and dreams, and the wonder of the world and its people throughout.', 'Working My Way Through Retirement', 7.45, 6.31, 53, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.14, 8.79, '9781479448814', '1479448818', 216, 7.22, 4.92, '2018-11-22', 'With the Empire poised on the edge of war, Sten spearheads the Eternal Emperor''s crackdown on the pirates and traitorous profiteers who are arming his enemies with vital war supplies. A trap is baited to lure the villains into a truel - a three-way duel. Only one thing stands in Sten''s way: Venatora, the beautiful pirate queen he''s grown to love. When it comes down to it, can he overcome loyalty and duty and pull the trigger?', 'Sten and the Pirate Queen', 1.51, 9.38, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.79, 8.48, '9781480859517', '1480859516', 386, 13.66, 1.36, '2018-08-17', 'From 1987 to 1990, author Dr. Richard Moss traveled extensively through Asia while working as a cancer surgeon in four different countries including Thailand, Nepal, India, and Bangladesh. His work was voluntary, however the "payoff" was in the rich, fascinating, and, often bizarre experiences he had both as a surgeon and wanderer. Based on this three-year excursion, A Surgeon''s Odyssey delves into the true-to-life adventures, struggles, and quandaries of a young surgeon from humble beginnings who found himself in a strange and tragic but beautiful world, striving to save those suffering from horrifying disease under hellish circumstances. In this memoir, Moss shares his story that includes insights into life, other cultures and religions, and the tragedy of intolerable disease amidst destitution and scarcity. A Surgeon''s Odyssey tells of a young man''s decision to forgo comfort and financial security for the adventure of a lifetime, pitting himself against the specter of overwhelming suffering and illness. It narrates the unique journey of a cancer surgeon who, against conventional wisdom, embarked on a pilgrimage of healing and experienced surgical triumphs and setbacks amidst some of the most beguiling and fascinating cultures in the world. "A Surgeon''s Odyssey" by Richard Moss MD wins the Independent Press Award for 2019 for best book in the category of Travel.', 'A Surgeon''s Odyssey', 9.46, 4.43, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.75, 4.88, '9781489714619', '1489714618', 272, 15.92, 4.49, '2018-02-24', 'THIS TIME is a clear-and-to-the-point story that grasps the readers attention immediately. Unapologetically, Manuel Manny Gutirrez leaves no doubt that the newcomer flamme passionne has come to right unacceptable wrongs. Jack Delgado, author of The Trail to Golgotha (2009) and Crooked (2007). Jacks website is at http: //www.gate.net/ joachim/ The opening chapter of THIS TIME recalls the tragic, yet forgotten, catastrophes that afflicted humankind at the end of 2000 as we awaited Y2K. The chapter takes the audience around the world where many people die inexplicably-at the same time- mostly in fire-related incidents. I fully expect to read the entire book because this first chapter has me hooked! Fernando Fernn Hernndez is the author of 4 books; the last two are The Cubans: Our Legacy in the United States and his most recent one, The Cubans: Our Footprints Across America, both available at Amazon.com. A retired educator, he resides in Miami, Florida. THIS TIME offers a unique perspective on the past by rewriting the history of the present and recasting the most well-known of all stories in a different light. Highly imaginative, engaging, and intriguing, this book is full of unexpected twists that will keep the reader guessing what might happen next, and also what might happen if history were to repeat itself. CARLOS EIRE, author of Waiting for Snow in Havana (winner of the 2003 National Book Award for Non-fiction) Professor of Religious studies at Yale University. Christmas Day, December 25, 2000a mysterious series of unexpected and unexplainable deaths happens across the globe during the birth of the only child of a rebellious young couple. Two clues only group the hundreds of cases together, but these clues are seen only by the sharpest and hardest-working investigators and journalists. The child, a unique individual, is going to turn the world upside down. Although his power and actions are reminiscent of the best known rebel in history, his novel approach will delight his followers and make deadly enemies of his opponents. Will he succeed in his personal quest?', 'This Time: A 21st-Century Look at an Ancient Mystery That Changed the World', 8.63, 2.47, 54, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.93, 1.01, '9781490769899', '1490769897', 158, 48.0, 2.68, '2016-05-31', 'The perverse machinations of a mad scientist. The forbidden secret of the girl''s family that could very well drive her beloved away. The old uncle''s mission to end the dire stress to his family. The bizarre actions and rituals of hideous aliens. All of these will have a play in the lives of our young couple as they struggle to survive these. Will the lad''s hidden innate heritage save them or will this end up destroying the young couple in the end?', 'An Orbiting Dilemma', 9.62, 9.6, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.15, 9.96, '9781493012947', '1493012940', 0, 20.89, 4.04, '2015-04-16', 'The Battle of Fredericksburg, waged in December 1862, was the Civil War''s only major urban battle and a key victory for the Confederates under Robert E. Lee. Historical Tours Fredericksburg is a unique guide that takes you on an exploration of the battlefield, bringing you face-to-face as never before with the people and events that shaped this epic event. Included are a timeline of events and descriptions of key personalities who conceived, planned, and designed the area as well as information about where to stay, where to eat, and what to see nearby. Visit the historic Chatham Manor, an old Southern plantation converted into a wartime field hospital. Pay your respects at the Richard Kirkland Memorial in Marye''s Heights. Climb Lee''s Hill, where Confederate general Robert E. Lee watched the Union attack his troops. Book jacket.', 'Fredericksburg', 8.28, 2.87, 55, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.1, 6.23, '9781493013159', '1493013157', 0, 12.58, 1.39, '1971-11-12', '''Hiking Georgia: Atlanta'' offers 30 trails of varying difficulty in and around greater Atlanta. Complete with up-to-date trail information and maps, GPS coordinates for trailheads, and photos throughout, this book is perfect for people of all ages and skill levels.', 'Georgia - Atlanta', 8.17, 9.53, 21, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.85, 2.12, '9781493018413', '1493018418', 0, 66.9, 4.52, '2001-09-17', 'Rediscover the simple pleasures of a day trip with Day Trips The Carolinas. This guide is packed with hundreds of exciting things for locals and vacationers to do, see, and discover within a two-hour drive to and from many top destinations in North Carolina and South Carolina. With full trip-planning information, Day Trips The Carolinas helps makes the most of a brief getaway.', 'Carolinas', 9.83, 2.42, 56, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.96, 3.67, '9781493022397', '1493022393', 0, 63.42, 4.22, '1993-04-02', '"Pack up the car and enjoy gorgeous drives through some of the most spectacular scenery in Massachusetts. This pocket-size highway companion maps out short trips for exploring scenic byways and back roads with a fresh perspective."--', 'Scenic Driving Massachusetts', 9.95, 9.63, 57, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.82, 1.73, '9781493022410', '1493022415', 0, 12.67, 1.92, '1947-08-25', 'Pack up the car and enjoy gorgeous drives through some of the most spectacular scenery Vermont has to offer. This pocket-size guide is an indispensable highway companion that maps out short trips for exploring scenic byways and back roads. Whether you embark on an adventure that winds along mountainsides or cuts through open fields, the road trips in Scenic Driving Vermont transform your passenger seat into a front row seat to experience natural beauty at its finest.', 'Scenic Driving Vermont', 7.59, 5.7, 57, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.25, 2.59, '9781493025428', '1493025422', 240, 42.96, 1.81, '2013-02-11', 'This guide details 40 of the very best paddles throughout the Ozarks. Spanning Oklahoma, Illinois, Arkansas, and Missouri, the guide provides routes for every type of paddler.', 'Paddling the Ozarks', 6.96, 7.71, 20, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.32, 5.81, '9781493025893', '1493025899', 0, 54.51, 1.76, '2024-03-06', 'Whether you''re a visitor or a local looking for something different, Georgia Off the Beaten Path shows you the Peach State with new perspectives on timeless destinations and introduces you to those you never knew existed--from the best in local dining to quirky cultural tidbit...', 'Georgia Off the Beaten Path', 4.77, 6.75, 25, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.51, 2.32, '9781493026890', '1493026895', 0, 84.07, 4.44, '1947-11-24', 'Texas history buffs and travelers have an eerie need for this book, which offers an unusual twist to seeing the "sights" in the Lone Star state. Organized by region--Gulf Coast, Rio Grande Valley, South Texas, Central Texas, North Texas, and West Texas--this book is the complete guide for both hardcore ghost hunters and more earthly tourists seeking to add some spirited fun to their travels. Complete practical information on non-haunted accommodations, attractions, and restaurants are also included, making this the only guide your Texan spirit will need. Scott Williams, who lives in Corpus Christi, is a journalist and the author also of The Insiders'' Guide to Corpus Christi.', 'Haunted Texas', 4.4, 3.23, 58, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.68, 5.58, '9781493031207', '1493031201', 208, 28.48, 1.03, '2017-12-13', 'Tired of the same old tourist traps? Whether you''re a visitor or a local looking for something different, let Minnesota Off the Beaten Path show you the North Star State you never knew existed. Ski, hike, or just relax at the Eagle Bluff Environmental Learning Center; visit a three-billion-year-old rock in Yellow Medicine County; or fill up at the world''s only Frank Lloyd Wright-designed service station in Carlton County. So if you''ve "been there, done that" one too many times, get off the main road and venture Off the Beaten Path.', 'Minnesota Off the Beaten Path®', 6.69, 1.98, 59, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.01, 1.67, '9781504315241', '1504315243', 200, 59.05, 3.55, '2018-10-18', 'Have you ever wondered what goes on behind the scenes in the North Pole around Christmastime? Does Santa get distracted? Do toy machines break down? Does someone else out there want to destroy Christmas? Well, I''ve wondered about all these things and imagined what could happen, so come and share the adventures with me.', 'My Christmas Tales', 6.8, 7.3, 60, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.58, 9.36, '9781513618159', '1513618156', 194, 89.31, 2.49, '2006-10-27', 'The dark side of Xtina Marie''s poetry delves into intense emotions: heartache, loss, hurt, pain, rage, and a dangerous consuming love which can drive one insane. Dark Musings is not a collection! The author returned to the centuries old practice of Narrative Poetry-the telling of a story through poetry. If you believe you are brave enough to explore the savage emotions of the human heart; Dark Musings will test your mettle', 'Dark Musings', 1.44, 9.38, 61, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.33, 5.13, '9781515420217', '1515420213', 236, 27.31, 2.59, '2018-04-03', '', 'A Modern Utopia', 4.26, 4.8, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.43, 4.02, '9781515420835', '1515420833', 590, 23.19, 2.99, '2018-04-03', 'Fritz Leiber was a giant in the genre field. He won five Hugo Awards, three Nebula Awards, three world Fantasy Awards, and one Stoker Award and was a Science Fiction Writers of America Grand Master. His influence on science fiction, fantasy, and horror cannot be overstated. Over 250,00 words of fiction', 'Fritz Leiber Super Pack #1', 2.65, 6.69, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.1, 6.86, '9781515420859', '151542085X', 514, 60.35, 4.78, '2018-04-03', 'Over five hundred pages of fiction by Ray Cummings, Murray Leinster, Otis Adelbert Kline and, Edgar Rice Burroughs', 'Argosy All-Story Weekly Super Pack', 2.02, 1.06, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.39, 7.44, '9781515420934', '1515420930', 284, 45.58, 1.49, '2018-04-03', 'Fantastic Universe started publishing in 1953 and continued until March 1960. It was one of the better magazines to launch during the boom in science fiction magazines publishing. It published many important stories by some of the fields best known writers.', 'Fantastic Stories Presents the Fantastic Universe Super Pack #2', 1.25, 1.46, 7, NOW(), NOW());
