INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.98, 5.28, '9781515421191', '1515421198', 44, 41.49, 4.84, '2018-04-03', 'Granthan''s mission was the most vital of the war. It would mean instant victory-but for whom? Earth didn''t trust his information. They were sure that he had been brain washed by the enemy. He had to convince them that he could be trusted before they killed him. But could he?', 'End as a Hero', 7.16, 1.54, 2, NOW(), NOW());
