INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.42, 3.3, '9781515424451', '1515424456', 100, 92.7, 2.91, '2018-04-03', '"On an expedition to Antarctica, Professor William Dyer and his colleagues discover the remains of ancient half-vegetable, half-animal lifeforms. The extremely early date in the geological strata is surprising because of the highly-evolved features found in these previously unknown life-forms. Through a series of dark revelations, violent episodes, and misunderstandings, the group learns of Earth''s secret history and legacy." --Amazon.com.', 'At the Mountains of Madness', 7.33, 9.36, 1, NOW(), NOW());
