INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.25, 5.81, '9781522526940', '1522526943', 0, 10.67, 2.02, '1993-05-02', '"This book focuses on the findings that indicate that improved policy-making is needed, leading to enhanced transparency and more dynamism in assisted reproduction-related research. The book focuses on the country of Greece and its ability to capitalize on its natural advantages in this special kind of tourism as well"--', 'Legal and Economic Considerations Surrounding Reproductive Tourism', 6.31, 8.89, 64, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.87, 7.61, '9781522527961', '1522527966', 0, 82.71, 1.76, '2017-11-11', '"This book adds to the knowledge in the field of religious tourism by providing readers with information on the international perspectives as well as the most current religious tourism practices used in both developed and developing countries. It also raises the level of awareness on the main studies carried out in the field of religious tourism"--', 'Global Perspectives on Religious Tourism and Pilgrimage', 8.47, 2.18, 63, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.47, 2.19, '9781532050046', '1532050046', 208, 78.92, 4.21, '2018-05-31', 'The world has forever changed. Nuclear war has destroyed all governments, left the land barren, and pushed man near extinction. One of the only foods man can eat is the cattleworm, a new species that drags its body along the earth like a snail, but the cattleworm are slowly disappearing. Eighteen-year-old Sean Anders realizes his village is running out of food. After he and three others are chosen to embark on a mission that could save the people of Nova from starvation, they travel across a barren land made even more dangerous by unpredictable weather, bandits, and a new species that has replaced man at the top of the food chain. As Sean learns what it takes to be a man in a world that belongs to the fittest, he soon discovers how far mankind''s cruelty extends when there are no rules to follow or laws to govern. Now only time will tell if he can survive long enough to save his people or whether he will be just another victim of a harsh new world.', 'Saving Nova', 7.15, 5.18, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.51, 8.05, '9781532603136', '1532603134', 0, 9.49, 3.56, '2016-11-18', 'What is it about that word? Aroostook. ""The County,"" they call it in Maine. She sat in the Ohio kitchen with books spread out, having just read a word. She said the word aloud. Someone little called. A door slammed. She stood automatically, walked a step, reached up and got out peanut butter. There was cold milk in the refrigerator, and bread speckled with cracked wheat on the counter. The word Aroostook was thickening against the roof of her mouth. It''s been years, but that''s how she remembers it, living now in Maine. She''d like to go there. But, driving the Town Road in the western mountains today, her spouse asks, ""Why Aroostook? Why is it so important to you?"" Her answer was purely explanatory: about that Ohio kitchen twelve years behind. About the endless prehistoric primal forest in some corner of that distant northern state. About its transformation into a sea of pine stumps; each five, six, or seven feet in diameter. And of how potatoes now grew in their stead. Aroostook today is an aisle of civilization bordering a rolling plain of farms, edging, in turn, a great industrial north woods filled with thin trees. And she had been listening to its story. Aroostook, she said, is the mystique of exploring Aroostook. That''s why they visited the eastern uplands of Maine. S. Dorman tells you of their experience in this book. ""Loving small things well trains our hearts to love larger things. Dorman''s memoirs about her life in Maine are models of how to love small places. Her attentiveness to the life of a single small place on earth is an example for anyone who wishes to be mature, to be capable of loving others well, and to be of service to their own local places."" --Jake Meador, Editor-in-chief, Mere Orthodoxy S. Dorman is the memoirist of Maine Metaphor, a series in spiritual and metaphoric experience. She is also the author of Maine fiction, including The God''s Cycle and Gott''im''s Monster 1808. She writes speculative and science fiction, and is the sub-creator of Fantastic Travelogue: Mark Twain and C.S. Lewis Talk Things over in The Hereafter. Her pastimes are bicycling and snowshoeing with her spouse in the mountains of Western Maine."', 'Visiting the Eastern Uplands', 9.32, 3.0, 65, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.86, 2.43, '1532604009', '9781532604003', 163, 57.02, 1.41, '2017-07-14', 'These days it seems like heroes fight each other more often than they fight villains. The hero-vs-hero trope so common in comic books and in superhero movies these days can provide us with a means of thinking about the deeply polarized state of modern politics and public opinion about civic life, morality, and even God. There is a real divide in our public life that nobody seems to be able to cross. It''s easy to complain that people should be more willing to meet each other half-way, that politicians should be more willing to compromise in order to get things done, but there are plenty of important issues on which compromise really isn''t possible. We see this problem dramatized in comics like Marvel''s Civil War and Avengers vs X-Men; in DC''s Kingdom Come and The Dark Knight Returns; and in film media like Daredevil, Batman v Superman, and Captain America: Civil War. The consequences of the conflicts that arise in these stories can serve as warnings about our current political environment. They''re safe places in which we can see the logic of our political dysfunction carried to frightening (but perhaps inevitable?) conclusions.', 'Titans', 9.76, 3.55, 66, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.57, 5.16, '9781541910119', '1541910117', 64, 31.16, 3.81, '2017-01-01', 'Can you guess what''s on the page? This is going to be an interesting activity book that will keep your child at the edge of his/her seat! Not only will it boost the essential life skills of patience, determination and self-confidence, it will also improve the logic and analytic skills of the young. The activity book can be completed individually or as a group. Grab a copy now!', 'Guessing Game for Kids - Activity Book for Kids (What Am I? Animal Edition) | Work, Play & Learn Series Grade 1 Up', 9.94, 9.81, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.76, 4.29, '9781541911277', '154191127X', 64, 94.45, 1.92, '2017-05-15', 'Educate your child about geography today and he/she would have a reason to explore the world in the future. In this book, we''re going on a virtual tour to Central America and he Caribbean. So prepare to leave your home and experience the sights of sounds of foreign places. Geography creates a better picture of this diverse world. Grab a copy toda', 'The Big Book of Central America and the Caribbean - Geography Facts Book Children''s Geography & Culture Books', 3.88, 6.14, 67, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.71, 3.29, '9781541913257', '1541913256', 64, 22.44, 1.16, '2017-03-15', 'You probably know some of the truths behind the establishment of Rome as a country. This time, let''s take a look at the mythical stories behind the creation of Rome. You will notice that the main characters of such stories are always Romulus and Remus. How did these twins create Rome? And what do you think happened to them? Read this book to find out!', 'Romulus and Remus', 5.53, 2.53, 67, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.68, 6.46, '9781541914421', '1541914422', 64, 24.07, 3.87, '2017-09-15', 'Have you ever wondered why Greek myths are known worldwide? Well, they have the perfect ingredients of magic, power and culture. They''re fictional but they strongly reflect the cultures and traditions of Greece. In this book, we''re going to discuss The Big Three: Zeus, Poseidon and Hades. Who are they? What power do they have and what realms do they reign over?', 'The Big Three', 5.11, 4.12, 67, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.58, 5.24, '9781541915114', '1541915119', 64, 72.72, 2.62, '1969-08-21', 'Have you heard about the adventures of Odysseus? They''re make believe alright but they''re rich in lessons of freedom, love and bravery. The adventures of Odysseus come with a bit of magic from the gods and goddesses. Reading the story will make you realize the beauty of the Greek beliefs and cultures. So read and be amazed. Start today!', 'The Adventures of Odysseus - Mythology Stories for Kids | Children''s Folk Tales & Myths', 9.84, 3.43, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.99, 5.64, '9781541915336', '154191533X', 64, 29.97, 1.64, '1965-04-25', 'Like other myths, ancient Chinese mythology includes stories of love, creation, gods and goddesses, mortal champions and demi-gods. Some of these stories could have resulted from actual events that happened when scientific truths were still scarce. But all of the stories contribute to the symbols used in classical and modern Chinese literature. Enjoy reading!', 'The Three Demigods, The Five Emperors and The Chinese Dragon - Mythology 4th Grade | Children''s Folk Tales & Myths', 9.63, 3.15, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.31, 2.84, '9781541916166', '1541916166', 64, 1.89, 4.35, '1963-06-16', 'Greek mythology often spoke of monsters. These could either be good or bad, depending on the story. But like all other characters, the monsters of Greek mythology hold meanings. Meet some of the most popular monsters, what they do and how they shape myths. You will be learning a lot from this book. Grab a copy today!', 'The Marriage of Aphrodite and Hephaestus - Mythology and Folklore | Children''s Greek & Roman Books', 6.49, 9.72, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.85, 4.59, '9781541916203', '1541916204', 64, 42.24, 2.53, '1991-08-03', 'Let''s get to know Athena in this Greek mythology book for kids. Knowing gods and goddess, and what they stand for, will help you to better understand ancient Greek culture. You will also get a firm grasp on the values, traditions and beliefs that the Greeks hold dear. What''s your favorite story about Athena?', 'Athena', 4.8, 1.87, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.22, 9.76, '9781541916241', '1541916247', 64, 57.76, 1.93, '1984-05-16', 'The story of Demeter and Persephone was all about a mom''s undying love for her daughter. This story also creates a "reason" for the change of seasons. Of course, in the ancient times, such a reason was acceptable due to the lack of scientific truths. Myths are powerful stories created out of the need to explain certain phenomena. Have a happy rea', 'Demeter''s Search for Persephone - Mythology 4th Grade | Children''s Greek & Roman Books', 6.26, 5.67, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.72, 7.82, '1556227809', '9781556227806', 353, 9.2, 1.15, '1942-06-24', 'Based on a 1912 publication about Texans who fought for the South in the Civil War, Texas Boys in Gray presents a collection of fascinating remembrances of those who were there. Sometimes humorous and sometimes heartbreaking, the experiences of these men are documented as a tribute to Texas war veterans. Texas Boys in Gray captures, in their own words, the patriotism, the fear, the confusion, the bravery, the terrible wounds, the desperate hunger, the camaraderie, the horrible prison conditions, and the joyful reunions that were all part of that historical time.', 'Cartoon History of Texas', 9.91, 8.99, 39, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.84, 6.52, '1556228880', '9781556228889', 248, 83.13, 2.82, '2001-12-27', 'In Texas "Yankee" is a loose term covering a lot of ground. If you''re not a Texan or a southerner, you''re a Yankee and therefore, to many Texans, suspect. There are many rites of passage to being a Yankee in Texas: the first time you spot a pickup with a gun rack; the first time you realize that a week is a long time to go without Mexican food; the first time you recognize a change in seasons; your first thunderstorm; your first honky-tonk. Culture Shock in Texas can be intense and is exacerbate by local rules of propriety that tell us to keep out mouths shut. But here in this book we are going to talk all about it with good old Yankee outspokenness. We''ll clear the air, share experiences, orient newcomers, and have some good laughs.', 'The Yankee Chick''s Survival Guide to Texas', 6.4, 7.27, 39, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.61, 6.73, '1556228953', '9781556228957', 242, 12.64, 3.68, '2003-09-26', 'Connect the past with the present in this book and appreciate the state''s rich heritage by visiting the landmarks and campsites used by the Indians of Texas.', 'Texas Indian Trails', 6.46, 6.1, 39, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.17, 8.15, '9781565125575', '1565125576', 0, 14.78, 2.83, '2007-03-02', 'Bill Alexander had no idea that his simple dream of having a vegetable garden and small orchard in his backyard would lead him into life-and-death battles with groundhogs, webworms, weeds, and weather; midnight expeditions in the dead of winter to dig up fresh thyme; and skirmishes with neighbors who feed the vermin (i.e., deer). Not to mention the vacations that had to be planned around the harvest, the near electrocution of the tree man, the limitations of his own middle-aged body, and the pity of his wife and kids. When Alexander runs (just for fun!) a costbenefit analysis, adding up everything from the live animal trap to the Velcro tomato wraps and then amortizing it over the life of his garden, it comes as quite a shock to learn that it cost him a staggering $64 to grow each one of his beloved Brandywine tomatoes. But as any gardener will tell you, you can''t put a price on the unparalleled pleasures of providing fresh food for your family.', 'The $64 Tomato', 5.04, 1.43, 68, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.06, 4.58, '9781574093551', '157409355X', 0, 36.9, 4.47, '2010-06-20', '"An entertaining guidebook for sailing the usually benign but changeable Caribbean Sea--you must learn to sail with the grain of wind, weather, current, and climate"--', 'Caribbean Passagemaking', 2.34, 8.88, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.26, 9.03, '9781577312376', '1577312376', 424, 31.48, 1.6, '2005-11-06', 'Baksheesh & Brahman illustrates Campbell''s working method and grants an illuminating look at the thoughts and experiences of an incredible mind, as well as a revealing portrait of the roiling Indian subcontinent of fifty years ago."--BOOK JACKET.', 'Baksheesh & Brahman', 3.67, 7.79, 69, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.11, 1.27, '1589791819', '9781589791817', 242, 96.57, 2.88, '2005-03-14', 'This new edition of a popular travel guide provides a detailed accurate and modern approach to touring these national treasures.', 'Civil War Battlefields', 6.14, 1.43, 39, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.57, 4.08, '9781589791916', '1589791916', 242, 48.9, 4.12, '2010-07-04', 'In his thirty years with the National Park Service, Jim Burnett has seen it all: boatramp mishaps that have sent cars into the water; skunks in the outhouse and bears at the dumpser; visitors looking for the bridge over the Grand Canyon.', 'Hey Ranger!', 1.94, 9.17, 39, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.55, 6.22, '9781592281060', '1592281060', 0, 12.2, 3.13, '1985-02-02', 'Stewart retraces the pilgrimage across the old empire of Genghis Khan, from Istanbul to Mongolia. Winner of the Thomas Cook Travel Book Award.', 'In the Empire of Genghis Khan', 1.9, 8.06, 26, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.9, 4.95, '9781592283347', '1592283349', 0, 83.88, 2.87, '1977-11-08', 'From a jungle survival school in Panama to a week at a professional wrestler''s training camp, White leaves readers mesmerized by the potential of undiscovered places and the promise of endless adventure in unfamiliar territory.', 'Last Flight Out', 2.99, 4.48, 70, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.59, 2.69, '9781599541228', '159954122X', 0, 24.98, 4.32, '1950-11-26', 'Poetry. Women''s Studies. In WHAT MY FATHER TAUGHT ME, Maria Giura writes richly and candidly about growing up Italian-American Catholic from her earliest days as the daughter of immigrant parents and a workaholic father to her coming of age and onward into adulthood where she works at reconciling the sensual and spiritual. Her poems are a celebration in the face of love and loss. They are at once intimate and universal, serious and light, and are grounded in the Brooklyn, New York that she cherished and called home: from her parents'' pastry shoppe, to the view from the Belt Parkway, to the family living room "where [she] learned to pull out the microphone, even though it was always broken, and sing."', 'What My Father Taught Me', 2.94, 1.51, 71, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.56, 5.89, '9781604504569', '1604504560', 330, 38.67, 4.09, '2014-09-01', 'An interplanetary probe in the twenty-first century lands on Titan and discovers an alien civilization established there long ago.', 'Code of the Lifemaker', 8.57, 6.49, 72, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.48, 3.83, '9781604506839', '1604506830', 136, 12.53, 4.4, '1960-02-16', '', 'The Coming Race', 1.96, 1.85, 73, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.78, 2.2, '9781604507294', '1604507292', 118, 84.6, 1.78, '2009-09-01', 'Idle Thoughts of an Idle Fellow, is a collection of humorous essays by Jerome K. Jerome. It was the author''s second published book and it helped establish him as a leading English humorist.', 'Idle Thoughts of an Idle Fellow', 3.33, 7.1, 73, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.88, 1.3, '9781604507720', '1604507721', 156, 66.08, 1.23, '2024-12-17', 'Publisher: London:: Printed, and are to be Sold by Benj. Bragg at the Blue Ball in Ave-mary-lane Publication date: 1705 Subjects: Interplanetary voyages Notes: This is an OCR reprint. There may be numerous typos or missing text. There are no illustrations or indexes. When you buy the General Books edition of this book you get free trial access to Million-Books.com where you can select from more than a million books for free. You can also preview the book there.', 'The Consolidator', 8.16, 1.66, 73, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.18, 1.75, '9781604509861', '1604509864', 248, 5.79, 1.87, '1968-12-10', 'Large print edition, with easy-to-read text, of Defoe''s classic work.', 'The Consolidator (Large Print Edition)', 4.01, 1.09, 73, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.33, 6.38, '1605202835', '9781605202839', 790, 5.87, 1.11, '2008-01-01', 'American psychologist and philosopher WILLIAM JAMES (1842 1910), brother of novelist Henry James, was a groundbreaking researcher at Harvard University, author of such works as Principles of Psychology (1890) and The Varieties of Religious Experience: A Study in Human Nature (1902), and one of the most influential academics of the 19th century. His collected letters edited by his son, also named HENRY JAMES (1879-1947) here afford us an intimate look into the great thinker s mind: he was a man of delightfully wide-ranging interests and ambitions, and a correspondent of great animation and wit. Originally published in 1920 in two volumes but here presented in one, the letters run the course of James s adult life, and were written to everyone from family to professional colleagues and others, including such luminaries as Hugo M nsterberg, George Santayana, H. G. Wells, John Jay Chapman, Henri Bergson, and John Dewey. Offering provocative insight into James s temperament, biases, instincts, and unique perspectives, this is essential reading for anyone hoping to truly understand his work.', 'The Letters of William James', 7.8, 4.58, 74, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.76, 7.08, '9781605668185', '1605668184', 334, 31.38, 1.12, '1941-12-05', '"This book presents innovative research being conducted into Travel Recommender Systems, travel related on-line communities, and their user interface design"--Provided by publisher.', 'Tourism Informatics', 3.45, 6.88, 75, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.59, 4.39, '9781608932825', '1608932826', 0, 52.69, 4.9, '1961-07-14', 'This is a completely revised and expanded edition of the best-selling, comprehensive guide covering not only reasons to move to Maine but also what newcomers will find once they get here. The book answers questions about what Maine is really like as a place to live, providing a broad range of information about schools, housing, cultural life, taxes, work and employment opportunities, and even the weather.', 'Moving to Maine', 3.02, 9.86, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.57, 4.24, '9781609441050', '1609441052', 82, 1.73, 3.64, '2016-03-15', '"Queen of the Martian Catacombs" marks the debut of one of Leigh Brackett''s most iconic characters: Eric John Stark: orphan child raised on Mercury, who becomes a mercenary, fighting injustices across the solar system. Eric John Stark is hunted by Earth police in the Martian desert. Simon Ashton is with them and makes a deal with Stark to act as his agent in preventing a holy war. An unscrupulous ruler of a Martian Low-Canal city is partnering with a barbarian chief, Kynon, to plunder half the planet. Specialist mercenaries and criminals are coming from all over the solar system to join up. When Stark reaches the city of Valkis, he witnesses a ritual that reveals deception at the highest levels. The journey to the ancient ruins of Sinharat is beset with treachery and sandstorms, leading to a final confrontation with the secret masters of Mars. This version of ''Queen of the Martian Catacombs, '' by Leigh Brackett, was originally published in Planet Stories, 1949, later expanded into ''The Secret of Sinharat''.', 'Queen of the Martian Catacombs', 2.83, 7.03, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.75, 5.64, '9781611945003', '1611945003', 300, 42.89, 1.87, '2014-06-06', '"Previously published by ROC, an imprint of New American Library, a division of Penguin Group (USA) in 2007."', 'The Cipher', 6.11, 7.34, 76, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.08, 7.42, '9781611945461', '1611945461', 280, 43.59, 4.64, '2014-10-07', '"Previously published by ROC, an imprint of New American Library, a division of Penguin Group (USA) in 2000."', 'The Black Ship', 4.07, 4.52, 76, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.07, 5.41, '9781612270142', '161227014X', 224, 67.4, 2.14, '2011-05-01', 'In Albert Bleunard''s Ever Smaller (1893), the first modern novel on the theme of the "Shrinking Man," a group of scientists are shrunken down, first to insect-size, to explore an ordinary garden, which becomes as perilous to them as an alien world; then, to microbe-size inside a drop of water and, finally, into a rose bush. The book also includes The Reluctant Spiritualist, an 1889 novella about a mysterious and seemingly blank canvas which when photographed reveal the face of a man. "Ever Smaller is a significant landmark in the history of scientific romance. Not only does it go where no writer had gone before, in extending its thought-experiments beyond those of Jean-Henri Fabre and S. Henry Berthoud, it does so boldly." Brian Stableford.', 'Ever Smaller', 4.73, 5.58, 77, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.17, 3.28, '9781612270586', '1612270581', 252, 54.44, 1.85, '1977-12-19', '"The World in 2000 Years" (1878) describes a future in which the primary objective of economic policy is the prevention of the accumulation of money into the hands of relatively few individuals. While making money remains an objective, it is subsidiary to the determination to steer it in the right direction and redistribute it in such a way as to give every member of society the opportunity to earn a living free of hardship and strife.', 'The Word in 2000 Years', 7.31, 7.32, 77, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.84, 8.31, '9781612968001', '1612968007', 256, 37.52, 2.29, '2017-01-05', 'Father Jim has a gambling problem, a girlfriend, and his brother Gabe just killed his bookie. Detective Mark Porfino investigates while mob boss Mario Gallante arrives to figure out why his protEgE was found floating in the harbor. Mark and Mario form an unholy alliance, with fast food, drinking, Girl Scout cookies, a dead man with a morbid sense of humor, and a wedding with a miracle, contributing to the search for the killer. Jim must weigh family loyalty and protection of his lover against the vows he''s made to himself and his church. Will Gabe confess and relieve Jim of his burden? Or will they both be dragged further into the abyss until their secret is revealed?', 'The Long Harbor Testament', 4.89, 4.51, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.62, 1.1, '1613161360', '9781613161364', 0, 17.86, 3.89, '2019-07-23', 'A Golden Age mystery set in the Golden Age of science fiction Legendary science fiction author Fowler Faulkes may be dead, but his creation, the iconic Dr. Derringer, lives on in popular culture. Or, at least, the character would live on if not for Faulkes’s predatory and greedy heir Hilary, who, during his time as the inflexible guardian of the estate, has created countless enemies in the relatively small community of writers of the genre. So when he is stabbed nearly to death in a room with only one door, which nobody was seen entering or exiting, Foulkes suspects a writer. Fearing that the assailant will return, he asks for police protection, and when more potentially-fatal encounters follow, it becomes clear to Detective Terry Marshall and his assistant, the inquisitive nun, Sister Ursula, that death awaits Mr. Foulkes around every corner. Now, they’ll have to work overtime to thwart the would-be murderer—a task that requires a deep dive into the strange, idiosyncratic world of science fiction in its early days. With characters based heavily on Anthony Boucher’s friends at the Manana Literary Society, including Robert Heinlein, L. Ron Hubbard, and Jack Parsons, Rocket to the Morgue is both a classic locked room mystery and an enduring portrait of a real-life writing community. Reprinted for the first time in over thirty years, the book is a must-read for fans of mysteries and science fiction alike.', 'Rocket to the Morgue', 4.54, 7.2, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.93, 7.75, '9781614277422', '1614277427', 210, 66.21, 4.66, '2014-12-02', '2014 Reprint of Original 1912 Edition. Exact facsimile of the original edition, not reproduced with Optical Recognition Software. "Laughter" is a collection of three essays by French philosopher Henri Bergson, first published in 1900. In a short introduction, Bergson announces that he will try to define the comic, but he does not want to give a rigid definition of the word; he wants to deal with the comic as part of human life. His ambition is also to have a better knowledge of society, of the functioning of human imagination and of collective imagination, but also of art and life. Bergson begins to note three facts on the comic: 1] the comic is strictly a human phenomenon. A landscape cannot be a source of laughter, and when humans make fun of animals, it is often because they recognize some human behavior in them. Man is not only a being that can laugh, but also a being that is a source of laughter. 2] laughter requires an indifference, a detachment from sensibility and emotion: 3] it is more difficult to laugh when one is fully aware of the seriousness of a situation. It is difficult to laugh alone, it is easier to laugh collectively. One who is excluded from a group of people does not laugh with them, there is often a complicity in laughter. Thus the comic is not a mere pleasure of the intellect, it is a human and social activity, it has a social meaning.', 'Laughter', 2.56, 5.26, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.28, 8.57, '9781614277682', '1614277680', 358, 3.5, 4.74, '2015-01-27', '2015 Reprint of Original 1955 Edition. Exact facsimile of the original edition, not reproduced with Optical Recognition Software. Abridged by Edward Garnett. Long famous among scholars and students of Arab history and culture, readers of travel and adventure books, and lovers of English literature, Charles M. Doughty''s "Travels in Arabia Deserta" is in its original form a formidable work of over 1,400 pages, a daunting length for many readers. This excellent abridgment, less than a quarter of that length, is ideally suited to a wide audience of general readers. Written after the author had spent two years wandering among the Bedouin nomads, the remarkable book describes Doughty''s attempt to reach Mecca, his endurance of extraordinary hardships, and his first-hand observations of Arab life and culture in the 1870s. The work is as revered for the exceptional power and beauty of its prose as it is for its panoramic view of a fascinating and mysterious land. Originally published as "Passages from Arabia Deserta" by Horace Liveright, Inc., New York, 1931.', 'Travels in Arabia Deserta', 2.61, 5.46, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.84, 7.15, '9781614753452', '1614753458', 174, 15.68, 3.6, '2015-10-14', 'Extinction is not permanent. Not anymore. Multi-millionaire researcher Alex Pierce has developed cutting-edge genetic techniques to extract viable DNA from preserved samples of breathtaking species that humans have erased from the Earth. From passenger pigeons and Tasmanian tigers, to Pleistocene dire wolves and sabretooths...even the humble dodo. The cornerstone of Alex''s dream is to resurrect the woolly mammoth. Majestic and massive, these creatures no longer roam the world, driven to extinction by ancient hunters. At his isolated Pleistocene Ranch in the wilds of Montana, Alex has actually bred the very first mammoth to walk the Earth in 10,000 years. But there are those who believe what is extinct should remain extinct, and that any tampering goes against the laws of nature. And their fervor may be far stronger than Alex''s dreams. Mammoth Dawn is the original acclaimed novella written by New York Times bestseller and Hugo and Nebula Award nominee Kevin J. Anderson and multiple Hugo and Nebula winner Gregory Benford; this volume also includes their detailed chapter-by-chapter treatment of the full novel the two authors originally envisioned, as well as a non-fiction overview of current scientific attempts to clone mammoths-a reality that may be much closer than you think.', 'Mammoth Dawn', 8.46, 7.43, 78, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.02, 6.77, '9781614754466', '1614754462', 288, 70.35, 4.36, '2016-11-21', 't''s the most unusual medical unit in the galaxy - and it makes house calls. A fully equipped starship lab, Taylor''s Ark is run by Dr. Shona Taylor, a specialist in environmental medicine. She has a menagerie of very special assistants, including an Abyssinian cat, a dog, rabbits, mice, and an alien ottle named Chirwl. Now, this highly trained crew faces the ultimate medical mystery. On Chirwl''s home world, humans and ottles alike are aging at an alarming rate. And if Dr. Taylor doesn''t find a fast cure, the entire colony will die ... of old age.', 'Medicine Show', 9.74, 7.25, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.3, 4.75, '9781615001330', '1615001336', 114, 80.44, 4.03, '2016-10-07', 'After a horrific investigation, Mike Taylor wanted to give up everything in the paranormal world. He lost his friends and his love. Kevin, the last member of VGH, brings Mike back to investigate a swamp. Jonathan Johnson, a lawyer, hires the two of them to help Mrs. Davis to save her land from the bank, and the unknown. Will this help Mike realize that he was born to be a ghost hunter, or will he himself fade away?', 'Investigation of Davis Swamp', 9.15, 8.21, 79, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.97, 6.16, '9781615083817', '1615083812', 166, 56.79, 2.06, '1986-04-08', 'THE CAMPBELL AWARD WINNING NOVEL. The reluctant revolutionary! Charles Cantrell thought he had enough headaches as project manager of a crew building a habitat on the asteroid, Rosinante. Then some dunderheaded politician back on Earth shipped several thousand perfectly innocent political prisoners to Rosinante to escape embarrassment. Suddenly, Charles found the habitat transformed from an engineering project to a colony - and he was in charge! Every one of the new arrivals had an axe to grind, and Charles seemed to be the whetstone they liked to grind their blades on. Then Earth decided it wanted several of the prisoners back, and Charles refused to surrender them. Now Earth''s space navy is on its way to seize control of the asteroid. To preserve his own freedom, and that of everyone now on Rosinante, Charles is forced to turn revolutionary. But how can one small group stranded on a tiny worldlet billions of miles from anywhere possibly resist the military might of Terra? "Big engineering, and the right people in the right place, trump political turmoil, economic collapse, and sinister political agendas. Add Independence, big science [and] tons of ill-gotten booty ... will make you believe that normal people with a dream can win out in the end! A feel-good story for our times." -Bear Peters. "Gilliland''s quirky mix of eccentric characters, cynical power politics, and old-style engineering-in-space-hard-sf works ... fun to read. " -Dani Zweig''s Reviews. First book in The Rosinante Trilogy. Alexis A. Gilliland is a science fiction and fantasy writer, as well as a fan cartoonist highly regarded for an acerbic wit. Gilliland won the John W. Campbell Award for Best New Writer for The Revolution from Rosinante in 1982, and has won four Hugo Awards for Best Fan Artist. His other books include The End of the Empire and the Wizenbeak Trilogy.', 'The Revolution from Rosinante', 5.58, 2.15, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.32, 8.58, '1616200510', '9781616200510', 318, 55.56, 3.03, '2011-04-01', 'The Alaskan landscape—so vast, dramatic, and unbelievable—may be the reason the people in Haines, Alaska (population 2,400), so often discuss the meaning of life. Heather Lende thinks it helps make life mean more. Since her bestselling first book, If You Lived Here, I''d Know Your Name, a near-fatal bicycle accident has given Lende a few more reasons to consider matters both spiritual and temporal. Her idea of spirituality is rooted in community, and here she explores faith and forgiveness, loss and devotion—as well as raising totem poles, canning salmon, and other distinctly Alaskan adventures. Lende''s irrepressible spirit, her wry humor, and her commitment to living a life on the edge of the world resonate on every page. Like her own mother''s last wish—take good care of the garden and dogs—Lende''s writing, so honest and unadorned, deepens our understanding of what links all humanity.', 'Take Good Care of the Garden and the Dogs', 5.86, 6.45, 68, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.41, 3.18, '162089002X', '9781620890028', 270, 49.67, 1.91, '1949-02-28', 'Introduces the first person to visit Oz from an altogether different world, Princess Planetty of Anuther Planet and Thun her Thundercolt. This book contains the original, twenty-five page, fully illustrated, short story Gludwig and the Red Hair, written by Adam Nicolai and illustrated by Ardian Hoda.', 'The Silver Princess in Oz', 1.11, 1.16, 80, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.12, 8.39, '9781626463158', '1626463158', 310, 13.41, 2.06, '2013-03-01', 'Five women are on a quest to survive a present that comes on the heels of a past that killed them all. Members of a sacred sisterhood, they are hunted for their gifts, and magical essence. Once again, their existence is threatened. This time by highly skilled seekers. To survive, they must uncover secrets hidden in their past. And put their trust in a bond that not even death can break.', 'The Purple Rose', 1.84, 7.97, 81, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.14, 2.73, '9781627556316', '1627556311', 84, 75.5, 4.49, '2014-08-14', 'As a schoolboy in Virginia, George Washington took his first steps toward greatness by hand copying a list of 110 "Rules of Civility & Decent Behavior in Company and Conversation." Based on a 16th-century set of precepts compiled for young gentlemen by Jesuit instructors, the Rules of Civility were one of the earliest and most powerful forces to shape America''s first president. Most of the Rules are concerned with details of etiquette, offering pointers on such issues as how to dress, walk, eat in public and address one''s superiors. But these maxims are much more than "mere" etiquette; they address moral issues, but indirectly. They seek to form the inner man (or boy) by shaping the outer. This edition of the Rules, which Moncure D. Conway compiled a century and a half after Washington wrote them, are taken from his original papers. Conway''s research results in a collection that includes not only 110 maxims, but their histories and origins as well. His detailed introduction also offers a view into how these Rules made their way into young Washington''s life. He also explains the import of this volume, writing "I am no worshipper of Washington. But in the hand of that man of strong brain and powerful passions once lay the destiny of the New World, in a sense, human destiny. But for his possession of the humility and self-discipline underlying his Rules of Civility, the ambitious politicians of the United States might to-day be popularly held to a much lower standard." More than a century ago, Conway also expressed the desire that "the time is not far distant when in every school right rules of civility will be taught as a main part of the curriculum." We can still hope.', 'George Washington''s Rules of Civility', 5.63, 3.18, 82, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.4, 2.25, '9781630760830', '1630760838', 0, 54.1, 3.24, '1939-01-10', 'To the Nines will introduce you to a whole new golfing experience by sharing the stories of nineteen nine-hole layouts across the country. This book will send you on a mission to discover the roots of the game and seek out your own unheralded courses. This new edition includes recent renovations and rebunkering of several of these classic "nines."', 'To the Nines', 8.03, 4.51, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.11, 2.71, '9781631870811', '1631870815', 44, 90.51, 3.34, '1953-06-02', 'Practical ideas on how to save money while taking a trip with your family.', 'Best Family Vacations on a Budget How to Find Great Budget Vacation Packages', 3.43, 7.17, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.53, 6.92, '9781635299502', '1635299500', 126, 86.89, 1.86, '1949-10-28', 'MIB meets AGENTS OF SHIELD. Mr. Fisk is the best at what he does, but nobody knows it. He''s a covert agent in the S.U.B.S.T.I.T.U.T.E. department of the Board of Education. He''s called in to deal with mad scientists, temporal rifts, aliens and any other supernatural occurrences that might threaten a school - all without public knowledge, to prevent widespread panic. Mr. Fisk thought he''d seen it all, until now. Suddenly, he finds himself (armed only with his briefcase and a new protege by his side) facing the greatest challenge of his career. After all, weird has no lesson plan! Collects issues 0-3 of the comic book series.', 'FISK The S.U.B.S.T.I.T.U.T.E. - Volume One', 7.98, 9.97, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.96, 4.9, '9781640449077', '1640449078', 206, 21.23, 4.3, '2018-02-15', 'An African-American teenager''s alienation is taken to the extreme in this utterly surreal and dark work of Weird Fiction. BloodLight is a dark metaphysical fantasy--psychological, philosophical, bizarre, and intense. Due to its language and themes, this book is intended for mature readers. This book is a prequel to the Eve of Light series.', 'BloodLight', 1.62, 1.42, 83, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.87, 1.09, '9781640805705', '1640805702', 0, 80.97, 2.48, '1949-05-16', 'When an act of cruelty drives Billy Joe from Mississippi and his car breaks down in snowy Pennsylvania, Carlos is there to help. They want a future together, but their families have other ideas... and Billy''s will stop at nothing to get what they want.', 'Running to You', 7.21, 9.98, 84, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.84, 4.8, '9781641140256', '1641140259', 356, 77.94, 4.85, '2018-03-29', 'Satiana is a twelve-year-old girl living in Orchid Village where Kamori, the sorceress, raised her after finding her stranded in the forest as a baby. Satiana is learning to be an enchantress but is having trouble controlling her powers. But then, she discovers her moon and star powers during her training with Lumiere. She has won the tournament, but during her victory party, she is confronted by a white-skinned demon named Sheiko, who calls her Moon Child. Satiana then sets out on a journey to find her long-lost real parents, meeting new friends along the way--such as Tokomo the fairy--confronting other five demons, learning about Moon People, and trying to stop an evil threat, the Lord of Darkness.', 'Satiana''s Magical Adventure', 8.11, 9.65, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.04, 3.57, '9781642261196', '164226119X', 134, 98.4, 3.66, '2018-04-10', 'The International Journal Of Media, Culture and Literature, published biannually by the School of Foeign Languages at Istanbul Aydın University, Istanbul, Turkey, is an international scholarly journal in English devoted in its entirety to media, culture and literature. The International Journal Of Media, Culture and Literature is committed to the principles of objective scholarship and critical analysis. Submissions and solicited articles are evaluated by international peer referees through a blind review process. As a biannual academic journal, JMCL publishes articles on English language and linguistics, on English and American literature and culture from the Middle Ages to the present, on the new English literatures, as well as on general and comparative literary studies, including aspects of cultural and literary theory. JMCL also aims to create a critical, discursive space for the promotion and exploration of media, culture and their relations with literature.', 'ISTANBUL AYDIN UNIVERSITY INTERNATIONAL JOURNAL OF MEDIA, CULTURE AND LITERATURE', 8.12, 8.69, 85, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.17, 7.0, '9781642550337', '1642550337', 396, 36.8, 3.46, '2018-04-22', 'Today''s top Horror and SF authors pay tribute to C.H.U.D. in this anthology of original fiction. C.H.U.D. is a genre defying, cult classic film featuring monsters living in the sewers below New York. The stories in this anthology expand the world created by the film and add depth to the C.H.U.D. universe like never before. From stories of apocalyptic horror and all out monster action, to tales of underground parties interrupted by uninvited guests and evening strolls that end in death, this anthology will leave you both smiling and breathless. Relive the fear as these original stories take you beyond the movie to events that occurred before, during, and after the scenes we remember so well. Includes C.H.U.D. related stories by Jonathan Maberry, Tim Waggoner, JG Faherty, Mort Castle, Michael H. Hanson, Martin Powell, Ben Fisher, Jason White, Chad Lutzke, Ross Baxter, Philip C Perron, David Bernstein, Nick Cato, Alex Laybourne, Christopher Fulbright, Angeline Hawkes, David Robbins, Robert Waters, Greg Mitchell, Ryan C. Thomas, and Eugene Johnson. With an introduction by David Drake. Compiled by Eric S. Brown. C.H.U.D. Lives! also features in-depth interviews with Andrew Bonime (producer) and Parnell Hall (screenwriter), as well as never before seen behind-the-scenes photos from the classic 80s horror film. Lineup: Introduction by David Drake Interview with the late Andrew Bonime "Dog Walker" by Robert E Waters "The Dwellers" by Nick Cato "The City Will Eat You Alive" by Ryan C. Thomas "Date Night" by David Robbins "Strange Gods" by Christopher Fulbright and Angeline Hawkes "Lost and Found" by Greg Mitchell "They Are C.H.U.D" by Alex Laybourne "C.H.A.D." by Michael H. Hanson "Samsa''s Party" by Ben Fisher "The Way to a Man''s Heart" by Tim Waggoner "Dweller Messiah" by Jason White "That''s Entertainment!" by Mort Castle "Toxic Disposal" by David Bernstein "Monstrous Me" by Martin Powell "Step Ate" by Chad Lutzke "Zero Hour" by JG Faherty "The Deuce" by Philip C. Perron "All at Sea" by Ross Baxter "You Will Never Leave Harlan Alive" by Jonathan Maberry and Eugene Johnson Interview with Parnell Hall (screenwriter) by Eric S Brown This book is dedicated in loving memory to Andrew Bonime, the producer of the C.H.U.D. film. Proudly represented by Crystal Lake Publishing--Tales from the Darkest Depths.', 'C.H.U.D. Lives!', 2.95, 7.79, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.61, 8.08, '9781643507682', '1643507680', 106, 10.01, 2.27, '2018-11-11', 'Today''s retail climate is fierce. There has never been such a competitive retail front that is forcing companies to try nearly anything to survive. This is why leadership plays such a pivotal role. The Humor and Art of Retail Leadership brings us a compelling lesson as to why there is indeed a difference between management and leadership. Also taking a deep dive into personal development, self-reflection, and homage to all the retail workers and leaders who have survived the clopen. From learning about ourselves and how we engage our teams to learning to fail properly, even how to take a vacation correctly, these are all tools to the retail leaders'' belt. This book offers a comical approach to getting ourselves in the right mind-set to be effective in a retail climate that changes on the dime. In all, The Humor and Art of Retail Leadership offers learnings to the newly promoted to the seasoned veteran on why personal development is key to being a great leader. 1', 'Leading in Retail', 2.25, 5.83, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.28, 4.57, '9781681278322', '1681278324', 50, 51.36, 3.38, '2015-04-12', 'Homesteading is all the rage and this handy journal will help you keep all your projects in one place. Bees are the very life force of pollination, the beginning of all new life. It''s appropriate then that it would grace the cover of this useful journal. Keep track of your livestock and plant varieties along with your own thoughts in this book.', 'Bee Keepers Journal', 9.87, 6.56, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.2, 8.04, '9781681452432', '168145243X', 50, 68.2, 1.3, '2015-04-25', 'Music is considered one of the most useful therapies known to man. It is used in many cultures across the world and the effect is almost always as powerful. A music journal helps you document and share your personal musical experience. You don''t have to be a musician to keep a journal, anyone who loves music and is keen to tracking responses to different genres can.', 'Music Journal', 1.03, 4.47, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.44, 3.56, '9781681456966', '1681456966', 106, 49.06, 4.95, '2015-05-02', 'If you''re travelling on a budget, it is imperative that you keep track of your travel expenses. This journal helps you prepare for your vacation by looking for the right lodgings and mode of transportation. When you right everything down, it becomes easy to review all the rates and come up with the best decision possible.', 'Travel Expense Journal', 3.81, 4.07, 86, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.66, 6.67, '9781681456973', '1681456974', 106, 14.62, 2.75, '2015-05-02', 'Document how much you spent on your accommodation, transportation and everything else in between. It''s easier to travel in style if you''re not spending too much. Keeping a log will also help others save when traveling to places you''ve already been to. Best of all, you get to boast that you traveled the world on a shoestring budget.', 'Travel Expense Log', 8.34, 8.73, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.0, 9.94, '9781681456980', '1681456982', 106, 95.33, 3.52, '2015-05-02', 'Organize your travel expenses in this handy organizer. Here, you can write and compare different accommodation and transportation options. When you write everything down, review becomes easier to do. Next, you will be able to determine what''s digging a hole in your pocket and what you can do to cut the costs the next time you travel.', 'Travel Expense Organizer', 2.1, 3.32, 86, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.28, 2.93, '9781681851204', '1681851202', 70, 36.08, 4.2, '2017-02-15', 'Alice is stuck on earth and there''s no way back to heaven. She finds herself floating back to her college campus and when her friend Milly doesn''t seem to care that she''s dead, she begins to lose her sanity. When a resident ghost at the college warns her about the path of revenge she is taking, it becomes startlingly obvious that Alice may already be too far gone. But when a familiar face shows up from heaven, Alice starts to realize just how far she has fallen. The question is, though, is it already too late for her? Has she already fallen too far to be saved?', 'Heaven Falls - No Turning Back (Book 3) Supernatural Romance', 5.8, 8.5, 87, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.45, 2.98, '9781683057697', '1683057694', 68, 36.35, 2.23, '2017-02-15', 'Seren knows that her choices are limited. Lucia has her right where she wants her and escaping her evil clutches isn''t going to be an easy feat. That''s what she has to do, though: she has to find a way of getting away from Lucia, before Lucia has a chance to torture the darkness out of Seren. With only hours to spare before Seren''s birthday hits and the darkness reaches its full power, the risks are high and the chances of failure are even higher. Will Seren be able to fight her way through the lures of the darkness or will she become the monster she has always been destined to be?', 'Stardark - How Things Must Always Be (Book 3) Fallen Stars Series', 9.05, 4.61, 87, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.72, 3.62, '9781683268260', '1683268261', 0, 25.68, 1.95, '2017-02-15', 'How do you build your wealth? First, you should become a mindful spender. There''s only one way to one, and that''s by keeping track of your income and expenses. Write both information side-by-side for easy comparison. You can use this effective bill organizer book for that purpose. Second, determine the expenses that need to be reduced. And third, start saving!', 'Organizing Finances to Build Wealth! Bill Paying Organizer Book.', 2.62, 6.72, 88, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.48, 1.08, '9781684115358', '1684115353', 420, 43.18, 4.13, '2018-04-02', 'The black experience in America--starting from its origins in western Africa up to 1961--is examined in this seminal study from a prominent African American figure. The entire historical timeline of African Americans is addressed, from the Colonial period through the civil rights upheavals of the late 1950s to 1961, the time of publication. "Before the Mayflower" grew out of a series of articles Bennett published in Ebony magazine regarding "the trials and triumphs of a group of Americans whose roots in the American soil are deeper than the roots of the Puritans who arrived on the celebrated Mayflower a year after a ''Dutch man of war'' deposited twenty Negroes at Jamestown." Bennett''s history is infused with a desire to set the record straight about black contributions to the Americas and about the powerful Africans of antiquity. While not a fresh history, it provides a solid synthesis of current historical research and a lively writing style that makes it accessible and engaging reading. After discussing the contributions of Africans to the ancient world, "Before the Mayflower" tells the history of "the other Americans," how they came to America, and what happened to them when they got here. The book is comprehensive and detailed, providing little-known and often overlooked facts about the lives of black folks through slavery, Reconstruction, America''s wars, the Great Depression, and the civil rights movement. The book includes a useful time line and some fascinating archival images.', 'Before the Mayflower: A History of the Negro in America, 1619-1962', 3.84, 6.39, 89, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.24, 5.7, '9781732022805', '1732022801', 34, 42.62, 2.75, '2018-04-03', 'In this contemporary folktale, the two-spirit s/hero Ochumaré the Rainbow Serpent comes to the defense of Water against the Black Snake. Inspired by the real events of 2016 at the Standing Rock protest of the Dakota Access Pipeline, scholar of U.S. myth and culture, Dr. Kat Williams, imagines the unseen forces at play in these historic events.', 'Ochumaré Takes On the Black Snake', 8.6, 7.46, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.12, 4.54, '9781732051164', '173205116X', 250, 61.49, 2.67, '2018-04-24', 'In 1899, Peter Gray, a young orphaned wolf is coming of age in the urban alleys of New York City. Peter''s mischievous, happy-go-lucky attitude gets him in trouble between running from bullies and annoying the local baker. Peter realizes something is missing in his life. Will he accept the circumstances or run from the truth of wanting a family?', 'The Adventures of Peter Gray', 1.54, 6.53, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.25, 2.85, '9781740276719', '174027671X', 71, 89.75, 1.47, '2004-01-24', 'A philosophical, often off the main tourist beat travel book based on the author Lyn Drummond''s seven years'' travel experiences working mainly in central and eastern Europe. The book''s title is based on a Jung philosophy that seven years of our lives represent a particular cycle and she has just completed such a cycle. The seven years began when she left Sydney in 2002 to work in Chuuk in the Federated States of Micronesia as a volunteer for an aid agency. The journey continues in 2003 to Hungary and a three year contract at the Australian embassy in Budapest, and later as a teacher and journalist in other parts of the region, such as Montenegro, Croatia, Slovenia and Albania. It is not a travel book in the sense that it lists places and contact details, but an exploration of a region she previously had no particular interest in, a renewed discovery of her European heritage, a strong relationship with a city (Budapest) she has no traditional or family connection to and a contemplation of the strong feelings she once had for Australia. The book also examines elements of exile, and anonymity in foreign countries which can create a rather contented bubble of living, sometimes immune from more deeper emotions - including in the context of her long friendship with the late Australian writer Randolph Stow, who settled in her home town in England and whose books dwelt on these themes.', 'Where To Go For a Seven-year Cycle', 3.4, 1.78, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.83, 6.22, '9781741791440', '1741791448', 127, 61.4, 4.69, '1988-10-16', 'Written by Amelia Thomas, this book is a wake-up call to raise awareness about the number of non-work days you actually have a year. This fun and interactive book encourages you to assess what you''re doing with your free time, and offers suggestions to help you make the most of it.', '132 Seize the Days', 1.73, 1.11, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.3, 3.22, '9781770531161', '1770531165', 200, 31.55, 1.69, '2016-03-18', 'A humorous, philosophical, and very weird collection of short stories. Eliezer ben-Avraham, wizard, Kabbalist, and kvetch, makes his rounds demonstrate how important it is to be generous with your gifts, even to the craziest goyim.', 'Making the Rounds', 5.29, 5.13, 90, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.44, 8.75, '9781770531246', '1770531246', 336, 22.59, 1.2, '2016-08-05', 'When aliens finally make first contact, they abduct Estlin Hume from his home and take him across the globe to act as translator - too bad he has no idea what they''re saying. A hilarious sci-fi romp perfect for fans of The Hitchhiker''s Guide to the Galaxy!', 'The Rosetta Man', 9.69, 8.15, 90, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.56, 6.58, '9781770531345', '1770531343', 236, 97.49, 2.99, '2018-03-06', 'Kate Foster accepts a job at a remote research facility in the Arctic. Her scientific expedition becomes one of survival when something begins hunting them.', 'White Death', 8.39, 6.93, 90, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.07, 2.8, '9781773704012', '177370401X', 134, 75.11, 3.35, '2018-02-13', 'This is a collection of creative low protein recipes with excellent photographs of the dishes for those who must maintain a protein-restricted diet for treatment of PKU or similar inherited diseases of protein metabolism. This book was created by a low protein cooking specialist and a professional home economist with hopes to make reader''s lives a bit easier and to share personal culinary experience and expertise. Low protein diets may feel restrictive and full of limitations but with the right ingredients and some basic cooking skills, it is possible to have low protein fine dining at home. Time is valuable so most of the recipes are quick and hassle free. Learning to cook from scratch is the best way to gain full control of the diet and eat healthy and low protein food.', 'Maria''s Low Protein Cook Book', 1.63, 1.77, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.24, 9.15, '9781773704029', '1773704028', 134, 44.33, 2.03, '2018-02-13', 'This is a collection of creative low protein recipes with excellent photographs of the dishes for those who must maintain a protein-restricted diet for treatment of PKU or similar inherited diseases of protein metabolism. This book was created by a low protein cooking specialist and a professional home economist with hopes to make reader''s lives a bit easier and to share personal culinary experience and expertise. Low protein diets may feel restrictive and full of limitations but with the right ingredients and some basic cooking skills, it is possible to have low protein fine dining at home. Time is valuable so most of the recipes are quick and hassle free. Learning to cook from scratch is the best way to gain full control of the diet and eat healthy and low protein food.', 'Maria''s Low Protein Cook Book', 4.19, 5.35, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.01, 6.5, '9781773840413', '177384041X', 162, 14.36, 3.74, '2018-02-26', 'An erotic, paranormal adventure featuring a Hybrid and the two men who fall for her.', 'Hybrid Misfit', 6.21, 6.12, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.05, 3.55, '9781775169345', '1775169340', 370, 15.51, 1.68, '2017-12-21', 'Fighter. Survivor. Outcast. The werewolf Anastasia, illegitimate daughter of Erzsebet Bathory, is able to meet her notorious mother at last. She discovers a pack of werewolves living in the forests around Csejthe and joins their ranks, forgetting her human life and her daughter. Katrine and the Danse Macabre are set to travel to Moscow in pursuit of a mysterious creature rumored to be terrorizing the area. The group receives a chilly reception from the local vampires, who are suspicious of their associate Nikoli Osomov. Katrine also meets a member of the shadowy Order of the Dragon, who casts doubts on the motives of her cousin Gabor. Meanwhile, the blood drinker Klara Von Dores has been sold into slavery as punishment for her crimes against the Danse Macabre. Never one to submit to the will of others, she slaughters her new master and frees her fellow servants. But her behaviour won''t go unnoticed for long, and her new friend Olivia fears she may have been better off a slave.', 'Ikon', 3.7, 7.54, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.2, 8.77, '9781780924014', '1780924011', 0, 50.59, 4.4, '1946-12-05', 'London, 1920: Boston-bred Enoch Hale, working as a reporter for the Central News Syndicate, arrives on the scene shortly after a music hall escape artist is found hanging from the ceiling in his dressing room. What at first appears to be a suicide turns out to be murder -- the first of several.... What''s the connecting factor ... [o]r, isn''t there one? ...Covering the Hangman Murders brings him into contact with a diverse cast of witnesses ... Winston Churchill, WIlliam Butler Yeats, George Bernard Shaw, Alfred Hitchcock, and Ezra Pound. Hale ... even makes a pilgrimage to the Sussex Downs to get an opinion on the case from the great detective Sherlock Holmes. -- Cover, page 4.', 'The Amateur Executioner', 5.86, 1.0, 91, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.14, 7.34, '9781781086490', '1781086494', 0, 65.46, 1.15, '2019-07-09', 'Nigerian God-Punk – a powerful and atmospheric urban fantasy set in Lagos. Since the Orisha War that rained thousands of deities down on the streets of Lagos, David Mogo, demigod, scours Eko''s dank underbelly for a living wage as a freelance Godhunter. Despite pulling his biggest feat yet by capturing a high god for a renowned Eko wizard, David knows his job''s bad luck. He''s proved right when the wizard conjures a legion of Taboos-feral godling-child hybrids-to seize Lagos for himself. To fix his mistake and keep Lagos standing, David teams up with his foster wizard, the high god''s twin sister and a speech-impaired Muslim teenage girl to defeat the wizard.', 'David Mogo Godhunter', 8.44, 2.66, 92, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.03, 2.79, '9781782011736', '1782011730', 164, 43.83, 1.78, '1971-09-12', 'Lewis Carroll, di s'' vr nom Charles Lutwidge Dodgson, a v''nu au monde Daresbury (Cheshire) li 27 di janvier 1832, t il a moru l'' 14 d minme mw s 1898, Guilford. Il steut m sse di mat matiques Christ Church College Oxford. I s''a int r ss ossi al fotograf ye. Li 4 di jul t 1862, i f t one pormin de dins one b rque su l'' Tamise avou l s trw s f yes dau dw yin Henry Liddell d Christ College, dith (8 ans), Lorina (13 ans) t Alice (tot jusse 10 ans '' djo -l ), t co on so on, li r v rind Robinson Duckworth qui tint l s rames. L s so s l d''mand t d lz raconter one istw re t il mantche li fauve d''one pitite Alice qui toume dins l'' t r ye d''on lapin. Alice li va soy po qu''i m te tot a d''ssu pap . Li scr je va bin s r ajouter totes s tes d''af res s'' conte. I l''ofrit Alice po s'' Noy 1864 t l''an ye d''apr s, Alice''s Adventures in Wonderland st publiy avou d s d ssins da John Tenniel. Ci l ve-l a st r''m tu dins one masse di langues. Li walon a tot '' qu''i faut ossi po raconter les pask yes d''Alice. I-gn-a co d s djins qui t z t qui l'' walon, c'' st d folkl re, qui c'' -st-on lingadje tot jusse bon po conter d s prautes. I n'' sav t nin qu''on scr t walon dispe y 1600 pau pr s. I n'' sav t nin qu''au 20yinme si ke, d s grands scr je s ont f t d'' nosse lit rature one grande lit rature. Dji vou ossi bouter al tch r te avou m'' traducsion d''on grand roman.', 'Lès paskéyes d''Alice è payis dès mèrvèyes', 1.35, 1.07, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.37, 3.77, '1782223835', '9781782223832', 204, 40.64, 2.9, '2015-04-15', 'Rose is plunged into a world of magic and monsters and must learn to master magic, or be consumed by it. At the same time, she learns that she may have to work with the Elf Eloo and the Werewolf Kye – creatures that she believed evil – to save her sister Robin from dark magic users. Will she succeed or be transformed by the magic … into what?', 'The Awakening of Magic', 5.26, 3.81, 93, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.04, 9.2, '1782225129', '9781782225126', 262, 36.38, 3.82, '2017-03-24', 'It is 2110. In an advanced technological world of holograms transmitted by mobile phones, food made by a Maxi Maker, drone trays, clones and automata concierges, Quadrant is the world government. But the world is not at ease and relationships are put under strain. James Walters is a sales manager for an international conglomerate, based in the UK. One day he encounters Adriana – “The Empress Adriana” – from the Galactic Command Force... oh, and ruler of planet Earth and all planets circling the sun. Can the Galactic Command Force, with help from some inspiring sources, thwart planetary conflict?', 'Galactic Mission', 1.07, 5.19, 93, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.58, 2.69, '1782225323', '9781782225324', 206, 85.12, 1.97, '2017-08-18', 'Meet Grump, the traveler’s guardian angel. Having flown the Atlantic over 300 times and stayed at over 40 of London’s variously priced hotels, who better to give cost-conscious advice to first-time London visitors? With a sharp eye for trouble, Grump is unafraid to expose all those potentially embarrassing ‘ooops’ moments that can trip the unwary. He even helps you beat jet lag! Finally the affable Mr. Grump pilots you out onto on the streets of London with a spring in your step and a smile on your face. Grump’s Guide To London is a treasure trove of helpful insights about the unique British culture found on ‘Planet London’. Heeding Grump’s advice will make planning and packing fun, the journey stress-free, and the arrival formalities a breeze. Bonus Tips On…… Beating Jet Lag What-to-wear tips for comfort in Britain’s changeable weather What the Queen thinks ‘Britishness’ explained – including their Empire and their table manners What Have The Brits Ever Done For Me? Plenty! (they gave you Fifty Shades of Gray, Harry Potter, Adele and Grand Theft Auto) Advice On Dealing With London’s Terror Threats A language primer explaining all those puzzling words and phrases the Brits use.', 'Grump''s Guide to London', 8.47, 1.66, 93, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.86, 5.28, '9781787460782', '1787460789', 432, 54.11, 1.33, '2020-01-23', '', 'Come Back for Me', 5.92, 1.64, 94, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.39, 2.63, '1841958891', '9781841958897', 289, 74.69, 2.2, '1980-12-10', 'A postmodern, radical retelling of the myth of Theseus and the Minotaur', 'The Helmet of Horror', 7.76, 5.41, 95, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.22, 5.34, '9781843410034', '1843410036', 394, 64.62, 3.83, '2001-09-01', 'One of the true epics of adventure. With his travelling companion, Eva Maillart, and motivated largely by curiosity, Fleming set out across war-torn China, to journey through Sinkiang, China''s most westerly province. When they began their journey in February 1935, it was eight years since any traveller had crossed this inhospitable area, and those who had had the courage to venture there seldom left alive. Beautifully written and superbly observed, this is not simply a portrayal of a mysterious and beautiful part of the world, but also a marvellous insight into the last days of the Great Game, when Britain and Russia still faced each other across a Central Asia in a state of anarchy. It is a magnificent travelogue by one of the last and greatest adventurers of Empire.', 'News from Tartary', 4.88, 6.3, 96, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.07, 5.8, '9781844080168', '1844080161', 0, 1.56, 3.67, '1985-10-08', 'Montaigne was alarmed to discover that by staying still, his mind ''bolted off like a runaway horse '' Diski, failing to keep still, finds much the same problem and produces here a record of her ramblings both mental and physical.', 'On Trying to Keep Still', 8.57, 5.71, 97, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.69, 6.05, '1846644771', '9781846644771', 396, 75.03, 3.52, '2020-08-18', 'Originally published in 1921. Contents include: How William of Palermo was carried off by the Werwolf - The Disenchantment of the Werwolf - The Slaying of Hallgerda''s Husbands - The Death of Gunnar - Njal''s Burning - The Lady of Solace - Una and the Lion - How the Red Cross Knight slew the Dragon - Amys and Amyle - The Tale of the Cid - The Knight of the Sorrowful Countenance - The Adventure of the Two Armies who turned out to be Flocks of Sheep - The Adventure of the Bobbing Lights - The Helmet of Mambrino - How Don Quixote was Enchanted while guarding the Castle - Don Quixote''s Home-coming - The Meeting of Huon and Oberon, King of the Fairies - How Oberon saved Huon - Havelok and Goldborough - Cupid and Psyche - Sir Bevis the Strong - Ogier the Dane - How the Ass became a Man again - Guy of Warwick - How Bradamante conquered the Wizard - The Ring of Bradamante - The Fulfilling of the Prophecy - The Knight of the Sun - How the Knight of the Sun rescued his Father. Author: Andrew Lang Language: English Keywords: Literature (Novel) / Fairy Stories / High Adventure Many of the earliest books, particularly those dating back to the 1900s and before, are now extremely scarce and increasingly expensive. Obscure Press are republishing these classic works in affordable, high quality, modern editions, using the original text and artwork.', 'The Red Romance Book - Tales of Knights, Dragons & High Adventure', 4.77, 7.15, 98, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.24, 5.3, '1846645220', '9781846645228', 396, 54.91, 3.04, '2009-02-26', 'Originally published in 1879. Author: Richard F. Burton Language: English Keywords: History Many of the earliest books, particularly those dating back to the 1900s and before, are now extremely scarce and increasingly expensive. Obscure Press are republishing these classic works in affordable, high quality, modern editions, using the original text and artwork.', 'The Land of Midian (North-Western Arabia) Volume I', 7.24, 1.56, 98, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.23, 3.38, '9781846648281', '1846648289', 484, 3.14, 1.46, '1999-03-05', 'CHARACTERS FROM THE HISTORIES amp MEMOIRS OF THE SEVENTEENTH CENTURY By DAVID NICHOL SMITH With an Essay on THE CHARACTER and Historical Notes CONTENTS ESSAY ON THE CHARACTER I. The Beginnings II. The Literary Models III. Clarendon IV. Other Character Writers CHARACTERS JAMES I THE DUKE OF BUCKINGHAM SIR THOMAS COVENTRY. SIR RICHARD WESTON. THE EARL OFVUDEL THE EARL OF PEMBROKE SIR FRANCIS BACON. BEN JONSON. HENRY HASTINGS. CHARLES I THE EARL OF STRAFFORD THE EARL OF STRAFFORD THE EARL OF NORTHAMPTON THE EARL OF CARNARVON LORD FALKLAND LORD FALKLAND SIDNEY GODOLPHIN. WILLIAM LAUD. WILLIAM JUXON. THE MARQUIS OF HERTFORD THE MARQUIS OF NEWCASTLE THE LORD EKCY THE LORD CAPEL ROYALIST GENERALS: PATRICK RUTHVEN, EARL OF BRENTFORD PRINCE RUPERT GEORGE, LORD GORING HENRY WILMOT, EARL OF ROCHESTER. JOHN HAMPDEN. JOHN PYM. OLIVER CROMWELL. OLIVER CROMWELL SIR THOMAS FAIRFAX. SIR HENRY VANE COLONEL JOHN HUTCHINSON. THE EARL OF ESSEX THE EARL OF SALISBURY THE EARL OF WARWICK THE EARL OF MANCHESTER THE LORD SAY JOHN SELDEN. JOHN EARLE. JOHN HALES. WILLIAM CHILLINGWORTH. EDMUND WALLER. THOMAS HOBBES. THOMAS FULLER. JOHN MILTON. ABRAHAM COWLEY. CHARLES II. CHARLES II. THE EARL OF CLARENDON THE EARL OF LAUDERDALE THE EARL OF LAUDERDALE THE EARL OF SHAFTESBURY THE EARL OF SHAFTESBURY THE DUKE OF BUCKINGHAM s, THE DUKE OF BUCKINGHAM THE MARQUIS OF HALIFAX SIR EDMUND SAUNDERS. Two GROUPS OF DIVINES NOTES INDEX. "THE CHARACTER THE seventeenth century is rich in short studies or characters of its great men. Its rulers and statesmen, its soldiers and politicians, its lawyers and divines, all who played a prominent part in the public life, have with few notable exceptions been described for us by their con temporaries. There are earlier characters in English literature but as a definite and established form of literary composition the character dates from the seven teenth century. Even Sir Robert Nauntons Fragmenta Regalia, or Observations on the late Queen Elizabeth her Times and Favourites, a series of studies of the great men of Elizabeths court, and the first book of its kind, is an old mans recollection of his early life, and belongs to the Stuart period in everything but its theme. Nor at any later period is there the same wealth of material for such a collection as is given in this volume. The eighteenth century devoted itself rather to biogrlphy. When the facts of a mans life, his works, and his opinions claimed detailed treatment, the fashion of the short character had passed. Yet the seventeenth century did not know its richness. None of its best characters were then printed. The writers themselves could not have suspected how many others were similarly engaged, so far were they from belonging to a school. The characters in Clarendons History of the Rebellion were too intimate and searching The Character. to be published at once, and they remained in manu script till about thirty years after his death. In the interval Burnet was drawing the characters in his History of His Own Time.', 'John Marshall in India Notes and Observ', 3.82, 1.44, 99, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.71, 7.09, '9781848250291', '1848250290', 0, 82.21, 3.83, '2010-08-24', 'Dave Walker, a thirty-something cartoonist, web editor and former church and community youth worker has become the UK''S leading cartoon commentator on the state of the Church (local and national). His Guide to the Church cartoons appear weekly in the Church Times, and on the paper''s daily blog, and many more can be found on Dave''s website, www.cartoonchurch.com This is his third collection of cartoons. His first cartoon collection reprinted within three months and is now in its third printing. His second collection is in its second printing. His many fans will love this third volume with its Tweeting bishops, its sociological study of the average Lent group, its handy guide to weighing up the respective merits of going to a church service vs. an Alpha course, and a great deal more.', 'The Exciting World of Churchgoing', 3.33, 5.62, 100, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.52, 9.12, '9781863958646', '1863958649', 0, 83.57, 4.4, '2016-07-08', 'That''s what this book is about -- the summer in which Dave finished school and waited ten weeks to find out whether he''d make it into uni or have to get that trade his dad kept banging on about. The Summer of ''82 is a hilarious and heartfelt journey of a boy becoming a man in suburban Australia.', 'The Summer of ''82', 6.2, 7.1, 101, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.13, 5.22, '9781864500622', '186450062X', 0, 55.31, 4.39, '2019-05-15', 'Travel writing may seem like the perfect job, but in this collection Lonely Planet authors reveal what it can be like on the road when things go wrong. Worldwide misfortunes include facing a rampaging elephant in Sri Lanka and infestation by insects in the Amazon. Budding travel writers and armchair travellers alike will enjoy this behind-the-scenes look at the creation of Lonely Planet guidebooks.', 'Lonely Planet Unpacked', 5.26, 8.81, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.77, 5.16, '9781874267690', '1874267693', 0, 29.03, 3.39, '1993-03-01', 'Deserts - vast, empty places where time appears to stand still. The very word conjures images of endless seas of sand, blistering heat and a virtual absence of life. However, deserts encompass a large variety of landscapes and life beyond our stereotypes. As well as magnificent Saharan dunes under blazing sun, the desert concept encompasses the intensely cold winters of the Gobi, the snow- covered expanse of Antarctica and the rock- strewn drylands of Pakistan. Deserts are environments in perpetual flux and home to peoples as diverse as their surroundings, peoples who grapple with a broad spectrum of cultural, political and environmental issues as they wrest livelihoods from marginal lands. The cultures, environments and histories of deserts, while fundamentally entangled, are rarely studied as part of a network. To bring different disciplines together, the 1st Oxford Interdisciplinary Deserts Conference in March 2010 brought together a wide range of researchers from backgrounds as varied as physics, history, archaeology anthropology, geology and geography. This volume draws on the diversity of papers presented to give an overview of current research in deserts and drylands. Readers are invited to explore the wide range of desert environments and peoples and the ever-evolving challenges they face.', 'Changing Deserts', 4.41, 6.57, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.58, 6.66, '9781906288907', '1906288909', 200, 99.78, 1.34, '2013-02-01', 'At Britex Fabrics, Francesca Wilson''s economic investigation and John McLeish''s murder inquiry are getting inextricably confused - with an American senator, a pop star and the Bach Choir, as well as each other.', 'Death''s Bright Angel', 6.87, 5.32, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.34, 5.13, '9781909735125', '1909735124', 122, 90.32, 3.88, '1996-04-19', 'Charlotte Stetson Gilman was known as a crusading feminist intellectual, concerned especially with gender inequality within marriage. Most married women of her time had little chance of participating in any creative or professional career - an enforced domestic slavery that was, for Gilman, not only patently unjust, but made neither partner happy or content. In ''Herland'', Gilman weaves these themes into an adventure story of three young men, schooled in the then-current view of women as weak and timid creatures. They discover Herland, an all-female society of rationality, equality and compassion composed solely of strong, athletic women, where even reproduction requires no male input! Gilman uses this utopian fantasy with skill and humour, gradually bringing the three male adventurers from an initial arrogant confidence in their own culture, to a realization that life in Herland is infinitely preferable to the war-torn, poverty-stricken male-dominated nations they have left. And that the supposed inferiority of the weaker sex is, in fact, nothing more than a product of cultural indoctrination.', 'Herland', 7.64, 6.6, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.22, 8.56, '9781910773604', '1910773603', 260, 9.63, 1.34, '2018-04-16', 'The Travel Scam Survival Guide offers practical advice on avoiding the scams and hoaxes that can ruin any trip. From no-menu, rigged betting, and scenic taxi tour scams to rental damage, baksheesh, and credit card deceits - this book details scam hotspots, how the scams play out and what you can do to prevent them.', 'The Travel Scam Survival Guide [2018 Edition]', 7.31, 2.49, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.11, 1.95, '9781911486176', '1911486179', 302, 44.91, 1.36, '2017-07-21', 'Japan has long fascinated with its unique culture and elaborate folklore. This anthology collects fantasy stories inspired by the culture and literary traditions of Japan. From steadfast samurai and contemplative monks, to transforming animals, horrifying spirits and everyday objects come to life, these tales transport you to the magical world of the Sunrise Lands. - An itinerant monk and his animal companion follow an evil wind to a desolate village. - An onmyoeji astrologer investigates the murder of a man who held secrets of the Imperial family. -The god''s gift of good luck is accompanied by an invisible cat. -The daughter of a fallen samurai is drawn back into her violent past to defend a village from attacking ronin. -A little girl is caught between a mischievous fox and a talking fish. 18 stories of magical Japan, by: Mike Adamson, Stewart C Baker, Laura VanArendonk Baugh, Jaap Boekestein, Evan Dicken, Alice Dryden, Harry Elliot, Steven Grassie, Alison Akiko McBain, Marta Murvosh, Kirstie Olley, Richard Parks, Frances Pauli, TS Rhodes, Douglas Smith, Lyn Thorne-Adler, Josh Wagner, Will Weisser.', 'Tales of the Sunrise Lands', 9.94, 6.76, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.15, 4.53, '9781912045525', '1912045524', 104, 7.23, 2.62, '2018-05-07', 'More Not the Parables of Jesus contains another 40 satirical takes on the original parables to snap us out of our over-familiarity and to open our eyes to the truth of the Gospel. Often fun, sometimes poignant, and occasionally painful; these parables reveal our cultural biases, hidden assumptions, and the lies we believe.', 'More Not the Parables of Jesus', 9.88, 3.41, 102, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.7, 6.77, '9781912105335', '1912105330', 88, 10.52, 2.23, '2019-01-24', 'Three short stories inspired by Dante''s Inferno, linked by a book of human skin passed down through generations. A mutilated corpse covered in occult symbols, a dark altar hidden in the icy Far North, and the desperate attempt to rescue a sister before her Blessing ... Large Print Edition', 'A Thousand Fiendish Angels: Large Print Short Stories Inspired by Dante''s Inferno', 3.87, 4.97, 103, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.38, 4.29, '9781925491241', '1925491242', 372, 61.92, 3.95, '2018-04-14', 'The old eddas speak of dreki--fabled creatures that haunt the depths of Iceland''s volcanoes and steal away fair maidens. Haakon wants none of such myths. For years he''s searched for the beast that stole his wife, desperate to slay the golden dreki and rescue his precious Árja. He has sacrificed everything to find her--including his honor--but now Haakon knows the truth. His entire marriage was a lie. The woman he knew as his wife was no victim, but the dreki herself. And when he finally tracks down the deceitful princess, there will be a reckoning of passion and glory.... She came to him on a storm... Long ago, Árdís gave her heart to a mortal man, despite knowing it could only end in tragedy. When her clan summoned her home, she had no choice but to leave--or see her husband pitted against her vicious cousin, Sirius. When Sirius insists upon a betrothal that will help him gain the dreki throne, she is forced to flee--straight into the arms of the now-ruthless dragon hunter she once called husband. But can Haakon ever forgive her deceit? And can she save him from a spurned dreki prince who would see them both dead?', 'Storm of Desire', 2.26, 6.76, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.21, 2.17, '9781925589214', '1925589218', 270, 38.55, 4.66, '2020-11-11', 'An astonishing memoir about the power of a daily creative practice', 'Write Way Home', 2.82, 1.11, 104, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.63, 8.02, '9781925799989', '1925799980', 354, 30.37, 3.49, '2018-03-05', 'Evil should never be necessary. Except when it is. Caitlin wakes in hospital, her damaged body telling a brutal story of torture, kidnap and rape that she will never forget. Burning for retribution, she''ll stop at nothing to get her life back. Can she trust Nathan, the mysterious man who saved her life - or will his past destroy them both?', 'Necessary Evil of Nathan Miller', 9.69, 8.84, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.68, 8.49, '9781926801087', '1926801083', 0, 97.27, 1.48, '2024-05-27', 'The seventeen stories selected for this compilation range from the fantastic to the outright bizarre, exposing the dark dreams and obsessions that turned an awkward boy from providence into the master of supernatural horror. Often known as The Macabre Cycle, Lovecraft''s earliest works of short fiction established the concepts and framework for the celebrated Cthulhu Mythos and earned him a position of authority in the Weird Fiction genre.--Back cover.', 'Dagon and Other Tales of the Macabre Cycle', 9.52, 7.84, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.23, 7.56, '9781927844182', '1927844185', 278, 92.59, 3.92, '2017-10-31', 'Marking forty years of the Phantacea Mythos in print, "Hidden Headgames" presents three intertwined novellas featuring characters who appeared in ''The Thrice-Cursed Godly Glories'' and ''Launch 1980'' fantasy trilogies. It leads up to and into "Wilderwitch''s Babies," which in turn marks the inception of the Phantacea Phase Two storylines.', 'Hidden Headgames', 8.01, 9.54, 105, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.04, 1.31, '9781937997694', '1937997693', 342, 98.37, 1.85, '2016-09-01', 'There was once a thriving black community on remote Ibo Key. But Revelation''s residents all vanished one night long ago. An odd little man tells researcher Lucy Fowler the island is cursed. Everyone on it will soon die. To escape, Lucy must face her own connection to a long-ago massacre . . . a crime so monstrous it invites an evil old as time.', 'Devil''s Key', 6.78, 6.85, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.08, 3.01, '9781938499333', '1938499336', 0, 64.82, 2.81, '2013-11-07', '"Bury Me with My Pearls is a real-life, roller-coaster ride of laughter, tears, and stomach-churning truths written by a professional speaker, humorist, and singer, who as Miss South Carolina, represented her state in the Miss America Pageant. Incorporating the analogy of pearls, this laugh-out-loud book bravely addresses difficult issues many in her audiences encounter within changing roles, self-actualization, and families."--Back cover', 'Bury Me with My Pearls', 9.02, 3.23, 106, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.5, 1.74, '9781940161723', '194016172X', 0, 66.36, 1.2, '1972-10-12', 'A decade ago, if you''d walked into a bookstore looking for a zombie novel, you would have found only two: Brian Keene''s The Rising and Joe McKinney''s Dead City. Long recognized as one of the driving voices that launched the world''s fascination with the living dead, Joe McKinney''s Dead World novels have emerged as seminal works in the Horror genre. Now, collected for the first time in Dead World Resurrection, are all of Joe McKinney''s zombie short stories. Here you''ll not only find tales that provide invaluable links between the various Dead World novels, such as "Ethical Solution," "Dating in Dead World," and the award-winning story "Survivors," but also nightmare glimpses into other post-apocalyptic worlds told in the inimitable Joe McKinney fashion. From the bleak political satire of "State of the Union" to the historical vignettes of "Starvation Army" and "Paradise of the Living Dead," this collection features the full range of McKinney''s horrific mastery of the living dead. The zombie has grown up since Joe McKinney first penned Dead City, yet he has continued to stand out among the throng of voices telling tales of the undead. Dead World Resurrection shows why. -- Amazon', 'Dead World Resurrection', 8.26, 2.24, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.08, 2.46, '9781940675268', '194067526X', 318, 89.74, 1.58, '2016-09-13', 'Some cravings can''t be denied.Werewolf Laina Flynn wants to break from the patriarchal expectations of the Fireborn pack. A successful veterinarian and entrepreneur, she doesn''t have time to be bossed around by her alpha brother let alone act as a proper werewolf princess. But when there''s a murder at her shifting grounds, she''ll do anything to protect her pack, even if that means posing as a waitress at Hunt Club, a gentleman''s club that flies in the face of her feminist ideals. She plans to do her royal duty and put the whole thing behind her. But when her inner wolf marks the club''s owner, Kyle "The King" Kingsley, as her vice, he becomes a hunger she can''t ignore. One that could threaten her life, her family, and her pack.', 'Vice', 3.87, 5.6, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.71, 3.53, '9781942712916', '194271291X', 0, 57.88, 3.15, '2019-02-16', 'Two works bound tãete-bãeche each with its own title page and pagination.', 'Dark of Night - Flesh and Fire', 8.59, 3.77, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.68, 4.77, '9781942990383', '1942990383', 324, 12.03, 3.06, '2016-10-03', 'Gathered here is a cross-section of stories from the first decade of the award-winning Defending The Future series.', 'The Best of Defending the Future', 1.17, 8.45, 107, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.42, 2.87, '9781943442003', '1943442002', 324, 64.73, 1.99, '2015-06-02', 'Until an arrow wound and a prairie blizzard drive him to the doorstep of the girls whose family he once destroyed, Leith Torren had never questioned his orders or his loyalty to King Respen.', 'Dare (The Blades of Acktar #1)', 6.29, 8.36, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.77, 1.17, '9781943526260', '1943526265', 0, 76.44, 1.08, '2016-09-01', 'In "One Plane Ticket from Normal," Pam Morton describes her family''s move from their fulfilling, understood Midwestern life to a white-knuckled, faith-leaping journey into the Middle East. Through humorous and hope-filled stories, Pam gives the readers snapshots of daily life in a mysterious part of the world.', 'One Plane Ticket from Normal', 3.65, 7.9, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.92, 4.33, '9781943924219', '194392421X', 336, 19.73, 3.3, '2016-10-11', 'The balance of dark and light is again threatened in Ersetu. The land of Aurderia is at the center of the struggle between the forces aligned with the dark, and the rest of the world. Shuran, a young man grown from elemental magic powers beyond his comprehension, faces his sister who is consumed by darkness. With his growing powers, Shuran travels the realms gathering allies and building his Zidu''Si, a collective of the races of man who serve the Shin''Ar. As the Shin''Ar, Shuran has been thrust into the position as "Watcher of the Lands", an ancient title that goes back to the Telukukal, the first people of Ersetu.', 'River of Souls', 3.78, 8.22, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.6, 2.29, '9781944322311', '1944322310', 118, 45.55, 2.33, '2018-11-11', 'Mysterious deaths in London baffle authorities, but for two men the reason is quite clear: they have seen something unspeakably terrible and lost their lives for it. For Clark it goes back to events from years ago; events he had strangely forgotten. The Great God Pan was written in the style of Bram Stoker''s Dracula and first published in the Victorian year, 1894. The monster: the elusive pagan god figure, Pan, who none dare to look upon lest they die of horror.', 'The Great God Pan', 7.71, 1.53, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.59, 3.52, '9781944370015', '1944370013', 0, 33.2, 2.81, '1954-12-28', 'As travel writers we need to continually strive to create engaging content, and this book shows you how to use freewriting to elevate your travel writing from one-dimensional to attention-grabbing.', 'Freewriting for Travel Writers', 6.4, 4.59, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.69, 9.03, '9781945373558', '1945373555', 0, 43.54, 3.11, '1990-12-21', 'A murdered movie star reaches out to an unlikely fan. An orchard is bewitched with poison apples and would-be princesses. A pair of outcasts fail a questionnaire that measures who in their neighborhood will vanish next. Two sisters keep a grotesque secret hidden in a Victorian bathtub. A dearly departed best friend carries a grudge from beyond the grave. In her debut collection, Gwendolyn Kiste delves into the gathering darkness where beauty embraces the monstrous, and where even the most tranquil worlds are not to be trusted. From fairy tale kingdoms and desolate carnivals, to wedding ceremonies and summer camps that aren''t as joyful as they seem, these fourteen tales of horror and dark fantasy explore death, rebirth, and illusion all through the eyes of those on the outside--the forgotten, the forsaken, the Other, none of whom will stay in the dark any longer.', 'And Her Smile Will Untether the Universe', 1.92, 7.4, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.06, 1.68, '9781945373596', '1945373598', 0, 17.28, 2.17, '1980-08-21', 'Originally published in German as Bleed: Ausgeblutet by Voodoo Press, 2016.', 'Bleed', 1.07, 3.85, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.46, 1.26, '9781945373664', '1945373660', 0, 80.25, 3.59, '1940-09-22', 'Ever since her mother abandoned her, five-year-old Sophie has had to depend on her uncle Mitch for everything. But he''s struggling. Restarting a life interrupted by time in prison is hard enough without having to balance work and single parenthood. Mitch is determined to make it work though, striving to keep their family together despite the obstacles in their way, because no matter how difficult things get, they are good for each other. And life for the two of them seems to be looking up. But when Sophie dies tragically, it all comes crashing down. Mitch descends into a crippling grief, coming to understand how little his freedom means without her to share it with. And though released from the sudden responsibility thrust upon him, all he wants is his niece back, safe and alive.', 'Come to Dust', 1.88, 7.83, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.96, 9.81, '9781945397820', '1945397829', 314, 17.45, 1.58, '2018-04-10', 'After receiving an ominous message about forthcoming demons and doom, Falmagon Sej is sent to retrieve a magical staff to protect the Anshedar. But he has unknowingly fallen in love with the sister of his enemy, and the price for betraying love may be too high for him to stomach. Falmagon''s footpath to becoming the Highborn Longwalker is riddled with sorrow, promising an undying hate for himself, unless he can somehow find salvation under the grace of the Lightbringer.', 'The Highborn Longwalker', 9.45, 8.94, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.35, 3.06, '9781945502804', '1945502800', 194, 56.97, 3.46, '2017-09-05', 'Who Decides What is Human... The Corporations, Clones or Chimera? When Finder is hired to locate charismatic, green-haired Miraluna Rose, it seems like an easy job. Crack into corporate databases, brew up some biologics to enhance his thinking, and get the job done with the help of the Parrot, a bird/dog chimera with the finest traits of both species. The search takes Finder and the Parrot to the sun-broiled streets of Laxangeles, the canals of Seattle and the weirdly mutated vegetation of the Area. It turns out that it''s not a simple missing-person case after all. Finder discovers that ReMe, a corporation providing medical cloning services, is illegally breeding human/animal chimeras. ReMe is selling these exotically beautiful female creatures, branded as ArcoTypes, as playthings to the wealthy and ruthless. Miraluna Rose is its finest creation, but she has other ideas. She''s holed up at Refuge, a haven for ArcoTypes, where she''s planning a future of freedom for her sisters. To help the ArcoTypes fight ReMe, Finder and the Parrot will need the help of a couple of sympathetic AIs, the CEO of the world''s largest advertising company and a posse of highly modded, celebrity-crazed media kids. This exciting adventure is a must read for anyone concerned about where our world and humanity is possibly headed...', 'Chimera Catalyst', 8.5, 1.67, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.9, 2.67, '9781945502842', '1945502843', 192, 40.17, 2.4, '2017-11-30', 'For Zeke Adams, identity theft isn''t just wrecking his life. It could cost him his life.', 'Pariah', 6.14, 9.93, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.93, 7.64, '9781946006639', '1946006637', 0, 45.92, 1.6, '2017-04-13', 'Lady Emalyn has kept a treasure hidden in the cushion of a green velvet chair...a treasure no other living soul has seen, not even her beloved husband or devoted housekeeper. When a series of tragedies forces Emalyn to relinquish the treasure she held so dear she learns the value of the true treasures in her life.', 'Emalyn''s Treasure', 5.45, 1.72, 108, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.21, 4.03, '9781946187093', '1946187097', 0, 60.89, 4.25, '2016-10-18', 'Join Hyden Hawk Skyler, and some great new friends, on an adventurous quest, over land and sea, to find the Silver Skull of Zorellin. Fight with Mikahl, Ironspike, and fierce King Jarrek as they try to free the enslaved people of Wildermont from King Ra''Gren and his Dakaneese Overlords. Patrol the skies with Shaella, and her new black dragon, Vrot. With her father''s spell books, and the Priests of Kraw, she decides to aid King Ra''Gren, while scheming to free her lover, Gerard, from the hellish Nethers. Demonic love, valiant battles, and foolhardy heroics await readers in this hefty continuation of the epic Wardstone Trilogy that was written in a Texas prison cell by author M. R. Mathias', 'Kings, Queens, Heroes, and Fools', 1.57, 6.08, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.47, 1.67, '9781946202451', '1946202452', 290, 16.22, 1.82, '2017-10-31', 'The Meadows is home to the guardians, a race of beings similar to the deities in ancient mythology. They watch over the Earth from their serene lands, keeping everything in check. For millennia, it has been peaceful. However, in the beginning, there was a great war. A war with Chaos, a war that is still remembered in the legends of the guardians and shape shifters. Months have passed since Isis'', a shape shifter/guardian hybrid and member of the prophesied Four, narrow escape from the Obsidian Manor. The Four still haven''t found answers about the mysterious Coop and their search for the Key has yielded nothing but more questions. When an old alliance is reforged, the Four are thrown into another mystery. Who are the strange shape shifters known only as the "glowing-eyes" and what is their connection to the odd symbol and vanishing bodies?', 'Through Storm and Night', 3.76, 6.82, 109, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.94, 8.91, '9781946552594', '1946552593', 212, 84.83, 3.03, '2018-03-13', 'Scout Shannon wants nothing more than to leave her home world and its petty squabbling factions behind. Galactic central with all of its excitement and opportunities awaits her. She makes it as far as her own planet''s orbit before the snares of bureaucracy close around her, trapping her on a space station populated by her people''s oldest foe. Then her rescuer, her only friend in the galaxy, disappears, abducted by a group of strangers the moment he steps off his ship. Alone in a strange place, surrounded by the old enemies she knows and new enemies just making themselves known, Scout faces a challenge like none before. But with her dogs at her side, Scout stands prepared for anything. "Among Treacherous Stars" the third book in "The Travels of Scout Shannon" series, a young adult science fiction novel for fans of plucky heroines, girl spies conspiring in political intrigues, and loyal dog sidekicks.', 'Among Treacherous Stars', 4.73, 6.35, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.15, 1.67, '9781946926371', '194692637X', 314, 53.58, 1.97, '1962-03-05', '"Cross Larry the Cable Guy with The Dresden Files, and you have Bubba the Monster Hunter" "Reminds me a bit of Ash from Army of Darkness" "Hartness spins another tale of redneck mayhem full of his usual sarcastic humor." Scattered, Smothered and Chunked collects the entire first "season" of Bubba the Monster Hunter, from his first graveyard-splattering adventure in Voodoo Children to the stunning cliffhanger at the end of Final Countdown! Fans of the rollicking redneck monster hunter will find plenty of value in this massive collection of monsters, strippers, beer and bullets! This collection includes ten Bubba shorts, a Bubba prequel novella, and a bonus Black Knight Chronicles short story!', 'Scattered, Smothered, & Chunked', 4.73, 2.34, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.6, 8.37, '9781946994073', '1946994073', 284, 16.95, 3.1, '1950-11-24', 'From USA Today bestselling author Shay Roberts comes the first book of Emma''s Saga, a stunning vampire novel set in the groundbreaking Heartblaze world. Tired of old school vampires? Vampire Soul is the perfect remedy. Prepare yourself for a truly innovative, richly detailed, adrenaline-fueled adventure!', 'Vampire Soul', 5.25, 7.04, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.69, 8.9, '9781946994080', '1946994081', 272, 16.65, 1.67, '1994-09-15', 'From USA Today bestselling author Shay Roberts comes the second book of Emma''s Saga, a riveting vampire novel set in the acclaimed Heartblaze world. After you''ve read Book One of this electrifying saga, you''ll want to begin Book Two immediately! Don''t miss this thrilling journey through a beautifully elaborate paranormal landscape.', 'Vampire Rising', 7.32, 4.79, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.05, 1.76, '9781946994097', '194699409X', 285, 30.85, 1.52, '2017-08-18', 'A vampire experience unlike any other.From USA Today bestselling author Shay Roberts comes the third book of Emma¿s Saga, a gripping vampire novel set in the celebrated Heartblaze world.Dive into this sensational story and join Emma as she faces her ruthless nemesis in a showdown for the ages.¿My name is Emma. A witch named Rowan stole my dagger, a Fae artifact that will destroy the world if I can¿t get it back. But how can I recover it if I don¿t have a body? The bitch stole that too.¿"When I started reading I couldn''t put it down." ¿ Ana ¿¿¿¿¿"Full of twists and turns, nearly all of which took me by surprise." ¿ Oscar ¿¿¿¿¿"I am in love with this story, these characters, this author!" ¿ Olpster ¿¿¿¿¿AUTHOR Q&AHow would you describe this series?The books are fast-paced paranormal/urban fantasy thrillers with both action and romance. When I began writing this series, I set out to create something for readers who enjoy a thought-provoking book. Heartblaze books are told from the point of view of multiple characters and take place in the present-day as well as the past. These books are not for people looking for light and fluffy reading, nor for readers completely unfamiliar with the genre.Is this series appropriate for all ages?No. The series is written for adults, young adults, and mature teens.What types of creatures are in the novel?Quite a number: vampires, werewolves, werebears, ghosts, witches, and fae. All of them are portrayed in new ways. For example, the werewolves are shifters who channel animal spirits from the distant past. The fae have their own unique language that plays a role in some of the books. It¿s a functional language that I spent a year developing!', 'Vampire Eternal', 9.12, 5.89, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.41, 6.43, '9781946994103', '1946994103', 320, 18.77, 3.21, '1939-06-10', 'From USA Today bestselling author Shay Roberts comes the first book of Ash''s Saga, a gritty werewolf novel set in the remarkable Heartblaze world. Fair warning, these aren''t your mother''s shifters. If you''re feeling brave, pounce on this book and sink your teeth into a frenzied werewolf epic!', 'Werewolf Unchained', 2.83, 5.18, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.75, 4.64, '9781946994110', '1946994111', 272, 32.99, 3.97, '1957-08-25', 'The ultimate wolf shifter adventure! From USA Today bestselling author Shay Roberts comes the second book of Ash''s Saga, a rousing werewolf novel set in the breathtaking Heartblaze world. Cool characters, intense drama, and stunning landscapes. Everything you need for a howling paranormal adventure! "My name is Ash. I''ve thrown myself into the Viking past on a crazy quest to save my wolf, but what I discover there is beyond crazy." "This is a heroine for readers who are tired of passive girls surrounded by paper-thin plots." - Kattomic Book Blog ★★★★ "It''s just an awesome book. And it comes with a bonus that will twist your mind." - Wendy Thorpe ★★★★★ "Twisty, turning, heartblazing wild!" - Jane Firebaugh ★★★★★ READING ORDER There are three separate trilogies set in the Heartblaze world. You can start with any of them, but if you want to read all three sets, the recommended order is: Tyler''s Saga Emma''s Saga Ash''s Saga AUTHOR Q&A How would you describe this series? The books are fast-paced paranormal/urban fantasy thrillers with both action and romance. When I began writing this series, I set out to create something for readers who enjoy a thought-provoking book. Heartblaze books are told from the point of view of multiple characters and take place in the present-day as well as the past. These books are not for people looking for light and fluffy reading, nor for readers completely unfamiliar with the genre. Is this series appropriate for all ages? No. The series is written for adults, young adults, and mature teens. What types of creatures are in the novel? Quite a number: vampires, werewolves, werebears, ghosts, witches, and fae. All of them are portrayed in new ways. For example, the werewolves are shifters who channel animal spirits from the distant past. The fae have their own unique language that plays a role in some of the books. It''s a functional language that I spent a year developing!', 'Werewolf Unbroken', 6.13, 7.5, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.72, 5.77, '9781946994158', '1946994154', 198, 66.32, 2.9, '2018-02-02', 'From USA Today bestselling author Shay Roberts comes the second book of Tyler''s Saga, a fiery dragon novel set in the popular Heartblaze world. Tyler joins the Time Academy, where he meets his fated mate, Rose. Together, they take a forbidden journey into the past to face a time-traveling supervillain.', 'Dragon War', 1.87, 1.81, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.3, 2.53, '9781947462038', '1947462032', 402, 50.12, 3.62, '2013-04-23', 'Peri Jean Mace thinks seeing ghosts is a curse, but her murdered trailer trash cousin doesn''t care. She wants Peri Jean to expose her killer. Everyone in her one-stoplight East Texas town has something to hide. And one of them will kill to hide the truth. In over her head, Peri Jean has to face her curse or end up the next victim.', 'Forever Road', 7.65, 3.91, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.8, 1.95, '9781947462182', '1947462180', 360, 89.67, 1.95, '2018-02-20', 'Peri Jean Mace will do anything for her loved ones. Even make a bargain with a monster. But now it''s time to pay up. Hidden in Devil''s Rest, Texas, is an ancient book written by the worshipers of a forgotten god. Peri Jean must find this book to pay off her debt. The kick in the pants? Do it in seventy-two hours, or become a dark being''s baby mama. Peri Jean heads to the eerie little town, only to uncover the sordid history of a cult and two decades-old bloodbaths. A ghost with a case of the deep-down crazies may hold all the answers. But she''d rather turn Peri Jean into worm chow than talk. Minutes and seconds ticking away, Peri Jean searches for another clue to the book''s whereabouts. Can she find the truth before her time runs out? Wrong Turn is #10 in the Peri Jean Mace Ghost Thrillers series. If you like your urban fantasy with a strong side of goosebumps and a heroine who feels like someone you''ve known all your life, you''ll love Wrong Turn.', 'Wrong Turn', 7.31, 7.18, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.0, 5.52, '9781947708037', '1947708031', 144, 36.63, 3.05, '1938-01-24', 'Dayle Grande Herstik does not live in the past but looks back on it and remembers what it was like "in those days," growing up in crowded neighborhoods and cities of concrete. In stark contrast stood the country house--a place of respite from frenetic times and noise, and lack of trees--in a magical environment replete with aromas of pine and balsam, water without chlorine, and activities like berry picking, hammock swinging, and rowing in a big wooden boat. As Herstik''s essays welcome us into the summertime sanctuary enjoyed by generations of her family, nature''s lessons unfold before our eyes and help us all lead a balanced life.', 'A Country House with Soul', 2.65, 9.0, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.86, 8.38, '9781947844254', '1947844253', 492, 82.74, 3.16, '2018-01-10', '"Household Tales" was published in 1812 by the brothers Grimm and has been entertaining the masses ever since. Popular tales like Cinderella and Hansel and Gretel and others had their beginning in the Grimm brothers'' collection of fairy tales. This 1884 translation is your best opportunity to re-live the magic of the Brothers'' Grimm''s book!', 'Grimms'' Household Fairy Tales', 2.66, 9.05, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.52, 1.36, '9781947855038', '1947855034', 144, 78.09, 4.35, '2018-02-14', 'The evil witches are back with their brain-dead monster zombies, ready to feast on all the little brains at Sandy Furlow Middle School. When the Club Zombie Hunters least expect it, Ms. Eisenstein and Hailey surprise attack Johnny and take him to a dark, eerie place where brain-eating, eyeball-splashing, depraved monster zombies live and breathe.', 'Monster Zombies Are Coming for Johnny', 2.93, 8.42, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.63, 2.74, '1948260271', '9781948260275', 328, 21.83, 4.75, '2018-04-04', 'The cutting edge of human brain research is exploring how to download our own individual memory for digital storage and later shared access. In the near future, the brilliant neuro-scientist Steven Marshall collaborates with his devious post-doc student to discover access to “Genetic Memory” residing in us all. Identify your own fleeting ability to access your own inherited memory as déjà vu, mystical or religious visions, certain types of creative thought, vivid repeating dreams, infatuation with the past and genealogy, artistic inspiration, child prodigies, or even the monster within. This science fiction novel, “The Genetic Memory of the Cazadores,” elaborates upon the plausible science of translating the locked codes of genetic memory to re-create a compelling story of human experience. Join a typical middle-aged man, Robert Walker, as he undertakes his dangerous journey of the mind and uncovers a past available to us all – hidden deep in the abyss of human history. You are invited to discover your own ancestral ‘genetic memory’!', 'Genetic Memory of the Cazadores', 1.78, 8.88, 110, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.45, 9.48, '1948260875', '9781948260879', 168, 29.04, 2.1, '2013-05-04', 'As pastor of a small country church, husband to the Gracious Mistress of the Parsonage, father to three, grandfather to nine, and great-grandfather to one, I take great delight in finding the funny side of any situation. My wife doesn’t always delight in my sense of humor, however. (I think she doesn’t understand it, but I won’t say that aloud.) Then again, we have enjoyed more than forty-five years of wedded bliss, so she has obviously found a way to abide my idea of comedy. “For a long time I was under the impression that my wife was giving me compliments. It takes a husband a long time to understand his wife, and by the time he understands her, she has morphed into the next level of womanhood. The man who thinks he knows his wife needs a psychiatrist, preferably a woman psychiatrist.”', 'A Merry Heart Doeth Good', 7.06, 8.77, 110, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.28, 6.11, '9781948312097', '1948312093', 258, 26.9, 3.76, '2018-03-09', 'RWK Clark''s bestselling novel, venture into the mind of this obsessed insane killer, a chilling and unforgettable masterpiece of suspense. Little do they know a horrible murderer has escaped from prison just as the small town is about to get hit with a record blizzard. But the trusting innocence of these small-town people will prove to be their undoing, for they cannot conceive the likes of the stranger they are helping on that snowy night. No need to worry about the weirdo. He''s just passing through. rwkclark.com', 'Passing Through', 3.46, 1.1, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.82, 5.89, '9781948312219', '1948312212', 312, 13.77, 2.01, '2018-03-21', 'Sarah turns to witchcraft to console her grieving heart, and soon she discovers that the craft is all too real. But Sarah doesn''t know that there are two sides to every coin, and in her innocence, she misses the signs that something very sinister is going on behind the scenes. Mommy told me something. Every kid should know. It''s all about the devil. And I''ve learned to hate him so. Sarah is 15 with a kind heart and genuinely sweet disposition, and manages with a natural ease to be the "perfect child" that all other parents secretly compare their own children to. Sarah is definitely a product of her upbringing, as being raised in a loving home whose members all have their lives centered on worshiping the Lord and church life as a whole. Sarah, as a result, has lived an idyllic, picturesque life, free of pain, loss, and grief. As though feeling shock waves from the toppling of the Devil''s domino set, Sarah soon has her life slammed upside down. The kickoff to her personal Death March thru the Valley of the Shadow of Death starts with the passing of her beloved grandmother. Confronted with the sad reality of Death for the very first time in her life, Sarah responds poorly. Unfortunately with each event, Sarah finds her thoughts turning dour, dim, and darker at all times, with there being but one specific target for her pain: God. Mad at the Lord for a perceived indifference to her plight, Sarah soon finds solace in something that she heard about in Sunday School, but only in the worst possible terms: witchcraft. Despite her anger at her faith, Sarah couldn''t help but agree that everything her Sunday School teachers told her about witchcraft was entirely true- it''s dangerous, it''s dark, and it is a thing of pure evil. Sarah begins to use her new found power via witchcraft to help to start healing her broken heart, in addition to learning that her new faith has the power to give her any and all that she craves in life. However, caught up in the glitz and mysticism of her new power, Sarah forgot a key lesson from her church days: The greatest trick the Devil ever played was convincing you he didn''t exist. www.rwkclark.com', 'Lucifer''s Angel', 6.23, 3.88, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.72, 2.78, '9781948312226', '1948312220', 312, 78.63, 1.07, '2018-03-21', 'Sarah turns to witchcraft to console her grieving heart, and soon she discovers that the craft is all too real. But Sarah doesn''t know that there are two sides to every coin, and in her innocence, she misses the signs that something very sinister is going on behind the scenes. Mommy told me something. Every kid should know. It''s all about the devil. And I''ve learned to hate him so. Sarah is 15 with a kind heart and genuinely sweet disposition, and manages with a natural ease to be the "perfect child" that all other parents secretly compare their own children to. Sarah is definitely a product of her upbringing, as being raised in a loving home whose members all have their lives centered on worshiping the Lord and church life as a whole. Sarah, as a result, has lived an idyllic, picturesque life, free of pain, loss, and grief. As though feeling shock waves from the toppling of the Devil''s domino set, Sarah soon has her life slammed upside down. The kickoff to her personal Death March thru the Valley of the Shadow of Death starts with the passing of her beloved grandmother. Confronted with the sad reality of Death for the very first time in her life, Sarah responds poorly. Unfortunately with each event, Sarah finds her thoughts turning dour, dim, and darker at all times, with there being but one specific target for her pain: God. Mad at the Lord for a perceived indifference to her plight, Sarah soon finds solace in something that she heard about in Sunday School, but only in the worst possible terms: witchcraft. Despite her anger at her faith, Sarah couldn''t help but agree that everything her Sunday School teachers told her about witchcraft was entirely true- it''s dangerous, it''s dark, and it is a thing of pure evil. Sarah begins to use her new found power via witchcraft to help to start healing her broken heart, in addition to learning that her new faith has the power to give her any and all that she craves in life. However, caught up in the glitz and mysticism of her new power, Sarah forgot a key lesson from her church days: The greatest trick the Devil ever played was convincing you he didn''t exist. www.rwkclark.com', 'Lucifer''s Angel', 1.96, 8.5, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.52, 1.87, '9781949977028', '1949977021', 260, 75.54, 1.1, '2018-11-28', 'When a local heiress goes missing, Danielle discovers it''s not always possible to distinguish the living from the dead. To complicate matters, it seems Danielle is not the only one who communicates with spirits. Her new guest claims to hear Walt. But, something''s not quite right with Marlow House''s newest medium. Danielle must move quickly before her best friend joins the spirit world.', 'The Ghost Who Wasn''t', 1.53, 9.42, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.16, 4.74, '9781949977035', '194997703X', 264, 87.93, 2.22, '2018-11-28', 'With his dying breath, Stoddard Gusarov names his killer: Danielle Boatman. Danielle had a score to settle with Stoddard Gusarov, but murder him? Never. Proving to the police she is innocent is the least of her problems. She has an angry spirit to contend with, the ghost of Stoddard Gusarov--and he''s out for revenge.', 'The Ghost Who Wanted Revenge', 3.2, 4.6, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.12, 2.77, '9781949977066', '1949977064', 266, 24.93, 4.58, '2018-11-28', 'A romantic weekend at Marlow House Bed and Breakfast turns deadly when Earthbound Spirits founder, Peter Morris, is murdered. Plenty of people had a reason to want the man dead-especially Danielle''s current guests. But it isn''t Morris'' ghost distracting Danielle on this deadly Valentine''s Day weekend, it''s her late husband Lucas. She has her hands full with suitors coming from all directions-both living and dead-while she tries to figure out if there''s a killer in Marlow House.', 'The Ghost of Valentine Past', 3.95, 2.48, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.32, 5.16, '9781949977158', '1949977153', 260, 42.17, 3.7, '2018-03-12', 'They say everyone has a double. Walt''s distant cousin, Clint Marlow, could be his twin. When the unscrupulous cousin arrives at Marlow House with his fiancée, he conceals his real reason for being there. But, unknown to Walt--and his cousin--the Universe has its own plans, and none of them will ever again be the same.', 'The Ghost and the Doppelganger', 3.29, 3.51, 111, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.9, 5.33, '9781949977189', '1949977188', 266, 60.52, 3.8, '2018-11-28', 'It''s hard to know who to trust when you''re worth billions. Christmas brings uninvited family members to Marlow House, vying for Chris Glandon''s favor. One of them may have already killed for it. In the midst of the mystery Lily is distracted with one question--what isn''t Danielle telling her?', 'The Ghost of Christmas Secrets', 7.78, 1.22, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.27, 4.62, '1950321029', '9781950321025', 85, 9.82, 4.96, '2019-03-21', 'Millions of people learn Italian but only a very small percentage of learners can actually speak it fluently. Why is that? People in general are quick to point out that some are naturally built more than others to learn Italian and other languages. This is not necessarily true, however, since we have all come to learn and speak our native language fluently. If you find yourself overwhelmed trying to memorize thousands of Italian grammar rules and vocabulary words or are struggling to speak Italian with native speakers, try this book! This is not a basic Italian for beginners textbook designed to teach Italian but a book that will teach you how to learn Italian the smart way and get you to fluency faster using highly effective language learning methods and techniques. There exists hundreds of Italian language coursebooks, Italian phrase books, and basic Italian for beginners textbooks, but without smart language learning techniques and strategies, you are likely to forget what you have studied and reviewed and especially during a conversation. There exists an easier and more fun way to build your overall Italian language ability. In How to Get Really Good at Italian, discover how you can easily conquer Italian language learning using highly effective methods and strategies used by polyglots (language learning experts). These methods and techniques can even be used to learn Italian grammar, phrases, and vocabulary from TV shows, videos, music, and video games. Learn Italian smarter and faster starting today!', 'How to Get Really Good at Italian', 4.39, 6.06, 112, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.31, 6.89, '9781984516404', '198451640X', 172, 72.47, 2.32, '2018-03-28', 'Some people express themselves through songs; some through hardcore porn. Some through high-caliber weapons with laser sighting. Martin Kennedy chose the keyboard. Martin has written everythingfrom commercials and screenplays to songs and dating profiles. He won Best Feature at the Oregon Film Festival for his first screenplay Death Bed, which he wrote and produced. He took on the task of reading the entire Bible in preparation for a documentary he was planning to film. However, once he consumed the information with the left side of his brain (obsessive-compulsive logic and reason), it compelled him to write this book with the right side of his brain (smart-ass humor slathered in sarcasm). Above all else, he champions options and choices. He is certain that his book, about your book, will give you just that.', 'He Said It, I Didn''T', 4.77, 9.42, 113, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.22, 5.6, '9781984538598', '1984538594', 214, 4.03, 2.32, '2018-07-06', 'We always suspected that we were not alone in the universe. The Charter is a collection of alien races that have ruled the galaxy for over a thousand years. For better or for worse, that Charter established contact with Earth and has woven us into their alliance. Nick Everroot is a new graduate from Charters Academy. Nick expected that he would be assigned to one of the proud fighting ships of the fleet. But you dont always get what you want, and Nick learns that is not always a bad thing. Nick finds that not everything in the galaxy is as obvious or as orderly as the Charter would have us believe. There are problems to be solved, battles to be fought, and lost things to be found. And if that were not enough, some of the mysteries remain hidden, even in plain sight.', 'Hidden in Plain Sight', 6.18, 9.32, 113, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.12, 8.04, '9781988035369', '1988035368', 312, 56.43, 1.73, '2018-03-15', 'Vengeance hunts them. Rebellion seeks them. Loyalty commands them. The shadows will fear them. Captain David Rice and Mage Maria Soprano have made their choice, signing up with the Martian Interstellar Security Agency and converting Red Falcon into a covert operations ship for the Protectorate. Their new duties drag them back into the very underworld they once strove to escape, intentionally provoking the Azure Legacy into a renewed conflict. They find unexpected allies with secret agents from Legatus''s rebellion against Mars as they seek to stop Mikhail Azure''s Blue Star Syndicate from being reborn. The Azure Legacy wants revenge. Legatus wants blood. David and Maria are bound by the overriding duty of all officers of the Mage-King''s Protectorate: Protect the innocent.', 'Mage-Provocateur', 1.8, 2.38, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.71, 7.55, '9781988035406', '1988035406', 358, 30.63, 3.22, '2018-12-10', 'A humanitarian mission into unfriendly stars A training cruise under the watch of a fortified fleet base The closing jaws of a trap years in the making', 'UnArcana Stars', 7.92, 4.44, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.62, 8.02, '9781988328768', '1988328764', 232, 34.92, 4.53, '2015-10-22', 'The six exciting and hilarious book in the Welcome to Hell series is here, with Adexios, Charon''s clumsy son taking the lead. With the wilds of Hell submerged by seawater, and monsters hungry for flesh, Adexios and his Amazon lady will have to fight stay alive - and not give in to their attraction.', 'Hell''s Geek', 1.63, 9.74, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.85, 7.82, '9781999523602', '1999523601', 306, 16.08, 3.53, '2018-12-26', 'Lochlan Ellyll learned the hard way; power attracts enemies. So does fighting shoulder to shoulder with a God. But that was a long time ago. MAGIC REQUIRED is an Urban Fantasy Novel that follows the demigod, Lochlan Ellyll, through his journey to redemption. Or so Lochlan thinks...', 'Magic Required', 8.21, 5.12, 114, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.05, 4.63, '9781999663612', '1999663616', 366, 54.35, 1.27, '2018-04-08', 'The Mother Of All Things is the outstanding debut psychological thriller from author Gabriel Blake. A fast-paced and thrilling read as we find ourselves immersed in the anguished and confused mind of Elaine Davis as she struggles with grief, mental health, reality, and a past she doesn''t remember.', 'The Mother Of All Things', 8.84, 2.85, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.01, 3.39, '9781999755300', '1999755308', 292, 26.51, 2.34, '2017-10-31', 'Every nine years, the Vessel War commences. A battle between nine supernatural beings-each infused with a unique magical power, each fighting for the ultimate prize: True Immortality. Anathame, one such Vessel, has the ability to channel demons. But her mind is turning against her, haunted by the echoes of a past she can''t remember...', 'Anathame Book One', 2.11, 5.5, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.72, 5.5, '9781999913779', '1999913779', 372, 94.5, 4.75, '2018-03-05', 'The second book in the popular Psychic Surveys series gets much darker! Ruby Davis, owner of the high street business, Psychic Surveys, must face the demons from her past if she is to ever have a future.', 'Psychic Surveys Book Two', 4.14, 4.11, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.74, 2.41, '9782070347469', '207034746X', 311, 97.55, 1.77, '2007-11-01', '', 'La guerre des mondes', 7.37, 6.99, 115, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.69, 8.61, '9782253087854', '2253087858', 568, 90.22, 2.89, '2009-01-14', 'Fin du IIIè siècle. Eilan, fille d''une grande prêteresse d''Avalon et d''un prince de Grande-Bretagne, traverse les brumes magiques qui conduisent vers l''autre monde : élevée sur l''île mystérieuse d''Avalon, elle est initiée aux mystères de la déesse... [4e de couverture]', 'La Prêtresse d''Avalon', 6.37, 6.93, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.25, 3.68, '9782253119715', '2253119717', 533, 67.42, 3.25, '2009-01-01', 'Galen Waylock est le dernier représentant d''une famille chargée de veiller depuis des siècles à ce que le Royaume des Rêves demeure séparé de notre réalité, sous peine d''une destruction totale de l''humanité. Mais le jeune homme a échoué dans sa mission. Son âme erre de l''autre côté du miroir, tandis qu''un puissant sorcier a pris possession de son corps resté sur Terre, où ses amis doivent affronter maints périls magiques. Car les Forces des Ténèbres ont lancé l''ultime bataille, et la Cité Noire d''Achéron, demeure du sinistre Astre du Matin, est remontée des profondeurs de l''océan pour annoncer l''Apocalypse. Un conte de fées contemporain plein de bruit et de fureur, situé quelque part entre la fantasy de Roger Zelazny et la dark fantasy de HP Lovecraft.', 'Guerriers de L Eternite T02 Brumes D Acheron', 6.65, 4.26, 116, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.95, 2.22, '9782253151364', '225315136X', 279, 44.95, 3.69, '2022-04-12', 'C''est exprès que Trisha s''est laissée distancer par sa mère et son frère, ce jour-là, au cours d''une excursion sur la piste des Appalaches. Lassée de leurs sempiternelles disputes depuis que Papa n''est plus là. Ce qu''elle n''imaginait pas, c''est que quelques minutes plus tard elle serait réellement perdue dans ces forêts marécageuses. Qu''elle affronterait le froid, la faim, la nuit, les bruits et les rumeurs de la nature. Et deux personnages terrifiants acharnés à sa perte : la Teigne et la Chose. Il lui reste son baladeur, sur lequel elle peut suivre les exploits de son idole, Tom Gordon, le joueur de base-ball. Le seul qui peut l''aider, la sauver. Après Sac d''os et La Tempête du siècle, le roi de l''épouvante offre à ses millions de fans une surprise. Un magnifique personnage de petite fille drôle, futée, énergique, capable de désespoir autant que de courage. Et puis une histoire très simple. Une terreur très simple.', 'La petite fille qui aimait Tom Gordon', 9.36, 3.83, 117, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.63, 2.24, '9782264030030', '2264030038', 308, 93.89, 2.12, '1967-10-06', 'Ceci est l''histoire d''un homme dont tout le monde semble avoir oublié l''existence et l''identité. La veille encore, il était Jason Taverner, producteur de télévision respecté, chanteur à ses heures et idole d''au moins trente millions de téléspectateurs. Mais lorsqu''il s''éveille dans une chambre sordide un matin, il semble être le seul être humain au monde à savoir qui était - qui avait été - Jason Taverner. Ses amis, ses collaborateurs, et même Heather, sa maîtresse et complice de toujours, affirment ne jamais l''avoir rencontré. Une situation embarrassante dans un monde où les campus sont assiégés depuis vingt ans et où le défaut de papiers d''identité suffit à vous envoyer au bagne. Mais c''est un Six. Ses gènes sont spéciaux. Il a des nerfs d''acier. Et si le monde entier a basculé dans la folie ou dans l''absurde, il va le remettre à l''endroit. Sous l''œil blasé du policier sentimental.', 'Coulez mes larmes, dit le policier', 1.0, 7.93, 118, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.71, 5.97, '9782265055346', '2265055344', 187, 10.92, 4.05, '1962-11-28', 'Kriminalroman, hvor Maigret, for at hjælpe en uheldig kollega, involveres i et opgør mellem amerikanske gangstere forfulgt af amerikanske myndigheder', 'Maigret, Lognon et les gangsters', 6.81, 5.14, 119, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.64, 7.29, '9782266111966', '2266111965', 409, 82.13, 3.5, '2001-10-11', 'Dément, incontrôlable, inimitable : Terry Pratchett est LA superstar des romans délirants. Il ne se passe pas de jours sur le Disque-Monde sans que de terrifiantes découvertes soient faites. Cette fois-ci, c''est Ankh Morpork, l''alchimiste, qui a percé le secret de la magie des images animées : une boîte, appelée caméra, dans laquelle on enferme six diablotins - deux qui regardent par le trou à l''avant de la boîte et peignent les images de ce qu''ils voient sur une membrane transparente, et quatre qui soufflent dessus pour sécher la peinture... Facile et simple, maintenant que c''est inventé, on va pouvoir enfin s''amuser... Aussitôt, une activité fébrile s''empare d''une petite colline déserte et tranquille au bord de l''océan : Olive Oued ! Mais à jouer ainsi avec réalité et illusion, ne risque-t-on pas de provoquer une catastrophe d''ampleur galactique ?', 'Les zinzins d''Olive Oued', 1.24, 9.16, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.3, 8.49, '9782266118019', '2266118013', 569, 45.79, 5.0, '2001-10-01', 'Frodon le Hobbit et ses Compagnons se sont engagés, au Grand Conseil d''Elrond, à détruire l''Anneau de Puissance dont Sauron de Mordor cherche à s''emparer pour asservir tous les peuples de la terre habitée : Elfes et Nains, Hommes et Hobbits. Dès les premières étapes de leur audacieuse entreprise, les Compagnons de Frodon vont affronter les forces du Seigneur des Ténèbres et bientôt ils devront se disperser pour survivre. Parviendront-ils à échapper aux Cavaliers de Rohan ? Trouveront-ils asile auprès de Ceux des Arbres, grâce à l''entremise de Sylvebarbe ? Qu''adviendra-t-il de Gandalf le Gris métamorphosé, au-delà de la mort, en Cavalier Blanc ? La trilogie de Tolkien, l''une des créations les plus riches et les plus neuves de notre temps, est aujourd''hui portée à l''écran par Peter Jackson.', 'Les deux tours', 7.2, 4.72, 120, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.59, 5.42, '9782266118286', '2266118285', 189, 81.17, 1.25, '1985-07-22', 'En l''an 2500, le professeur Antelle, son second Arthur Levain et le journaliste Ulysse Mérou sont en expédition vers l''étoile Bételgeuse, quand ils remarquent une planète étrangement similaire à la Terre qu''ils décident ainsi d''explorer. Une fois posés, ils découvrent des villes, des routes et des paysages en tout point semblables à ceux de notre planète, jusqu''à ce qu''ils rencontrent la belle Nova, nue, incapable de parler, ni même de sourire. Les hommes de sa tribu, qui accueillent Ulysse, sont également privés de parole et communiquent par des hululements. Plus surprenant encore, tous se font attaquer par des singes, vêtus en élégante tenue de chasse. Retenu prisonnier par des gorilles, Ulysse comprend rapidement que sur cette planète la hiérarchie animale a été inversée : les singes dominent les hommes, réduits à l''état purement animal. Alors, quand il révèle son intelligence aux singes Zira et Zaïus, il lui faudra apporter la preuve de son humanité à une espèce qui a perdu la trace de son origine.', 'La planète des singes', 8.44, 7.25, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.51, 2.66, '9782266170161', '2266170163', 184, 89.86, 3.23, '1992-02-21', 'Francesca Johnson, fermière de l''Iowa, était seule cette semaine-là, son mari et ses enfants s''étaient rendus en ville pour la foire agricole. Sa rencontre avec Robert Kirlcaid, écrivain-reporter qui photographiait les ponts du comté de Madison, eut lieu au cours de l''été 1965. Dès leur premier regard, ils surent qu''ils étaient faits l''un pour l''autre de toute éternité. Ils ne disposaient que de quelques jours pour se connaître, s''aimer et vivre une vie entière de passion silencieuse, avide et sans espoir.', 'Sur la route de Madison', 4.26, 5.88, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.71, 3.8, '9782845211025', '2845211023', 195, 93.05, 3.67, '1972-12-20', '', 'Métropoles', 8.14, 1.37, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.17, 5.83, '9782878300291', '2878300297', 96, 58.87, 1.5, '2000-12-23', '', 'Viaje Por Egipto', 7.86, 9.53, 121, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.94, 7.35, '9786071606990', '6071606993', 128, 93.67, 3.84, '1948-02-14', 'El poeta y filósofo Ramón Xirau ofrece en estas páginas sus impresiones y reflexiones surgidas de sus experiencias de viaje en Italia. la obra se divide en diversos capítulos dedicados cada uno a una ciudad italiana: Florencia, Siena, Amalfi, Capri, Anacapri, Venecia y Verona. Cada ciudad es motivo de descripciones y de referencias literarias y artísticas en general, a través de las cuales Xirau desarrolla temas de arquitectura, escultura, pintura, política y reflexiona sobre personajes como Maquiavelo, Miguel Ángel, Botticelli y Da Vinci.', 'Ciudades', 4.65, 2.49, 122, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.81, 3.22, '9788401022166', '8401022169', 896, 75.12, 3.05, '1975-12-18', 'El nuevo libro de George R. R. Martin narra la fascinante historia de  los Targaryen, la dinastía que reinó en Poniente trescientos años antes del inicio de«Canción de hielo y fuego», la saga que  inspiró la serie de HBO:Juego de tronos.Siglos antes de que tuvieran lugar los acontecimientos que se relatan en  «Canción de hielo y fuego», la casa Targaryen, la única dinastía de  señores dragón que sobrevivió a la Maldición de Valyria, se asentó en la isla de Rocadragón.Aquí tenemos el primero de los dos volúmenes en el que el autor deJuego de tronos nos cuenta, con todo lujo de detalles, la historia  de tan fascinante familia: empezando por Aegon I Targaryen, creador del  icónico Trono de Hierro, y seguido por el resto de las generaciones de  Targaryens que lucharon con fiereza por conservar el poder, y el trono,  hasta la llegada de la guerra civil que casi acaba con ellos.¿Qué pasó realmente durante la Danza de dragones? ¿Por qué era tan  peligroso acercarse a Valyria después de la Maldición? ¿Cómo era  Poniente cuando los dragones dominaban los cielos? Estas, y otras  muchas, son las preguntas a las que responde esta monumental crónica,  narrada por un culto maestre de la Ciudadela, que anticipa el ya conocido universo de George R.R. Martin.Fuego y Sangre brindará a los lectores la oportunidad de tener  otra visión de la fascinante historia de Poniente. Esta obra,  magníficamente ilustrada con 80 láminas inéditas de Doug Wheatley, se  convertirá, sin duda, en una lectura ineludible para todos los fans de la aclamada serie.La crítica ha dicho.«Fuego y Sangre es un libro brillante.»Sunday Times«Sin duda alguna podemos considerar a George R. R. Martin como el  principal creador de mundos de fantasía de su generación ... la riqueza  de detalles y las capas del universo que ha creado es extraordinaria, y abundan los sorprendentes giros narrativos.»Sunday Express«Una historia rica llena de matices, que hace aún más grande la  maravilla que es "Canción de hielo y fuego". Muy disfrutable, y al nivel del mejor Martin... absolutamente imprescindible.»Juan Gómez-Jurado,ABC«Fuego y Sangre ofrece un montón de emociones con el característico sello de la casa Martin.»Jacinto Antón,El País', 'Fuego y Sangre (Canción de hielo y fuego)', 5.56, 2.24, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.63, 7.83, '9788401022524', '8401022525', 938, 11.75, 4.78, '1945-02-04', 'Una maravillosa edición ilustrada y actualizada, para conmemorar el  10º aniversario de la publicación en español de la aclamadísima novela  que ha consagrado a Patrick Rothfuss como fenómeno editorial.Desde su publicación en español hace ya una década,El nombre del vientoha embelesado a millones de lectores de todo el mundo. Esta  edición conmemorativa y actualizada nos brinda la oportunidad de  profundizar en el universo inigualable de Patrick Rothfuss, con material  inédito que incluye: notas del autor, del editor y de la reconocida  escritora Jo Walton, veintiuna magníficas ilustraciones a página  completa de Dan Dos Santos, mapas de Nate Taylor y apéndices ilustrados  sobre la historia, las monedas y el calendario de los cuatro rincones de la civilización.«Viajé, amé, perdí, confié y me traicionaron.»En una posada en tierra de nadie, un hombre se dispone a relatar, por  primera vez, la auténtica historia de su vida. Una historia que  únicamente él conoce y que ha quedado diluida tras los rumores, las  conjeturas y los cuentos de taberna que le han convertido en un personaje legendario a quien todos daban ya por muerto: Kvothe... músico, mendigo, ladrón, estudiante, mago, héroe y asesino.Atípica, profunda y sincera,El nombre del viento  es una novela de aventuras, de historias dentro de otras historias, de  misterio, de amistad, de amor, de magia y de superación, escrita con la  mano de un poeta que ha deslumbrado -por su originalidad y la maestría con que está narrada- a todos los que la han leído.La crítica ha dicho.«Una celebración del gusto de contar historias.»El País«Insólita y preciosa. Puntuación: sobresaliente.»Qué Leer«Un libro para quien conoce el mágico poder de las palabras.»Ricard Ruiz Garzón,El Periódico de Catalunya«Vaya donde vaya Pat Rothfuss con la espléndida historia que comienza conEl nombre del viento, nos llevará de la mano como el buen  músico nos lleva por una canción.»Ursula K. Le Guin«Un libro asombroso.»Orson Scott Card«Este Rothfuss es condenadamente bueno.»George R. R. Martin«Patrick Rothfuss me ha recordado a Ursula K. Le Guin, George R.R.  Martin y J.R.R. Tolkien, pero en ningún momento he sentido que estuviera imitándolos. Sin dudaEl nombre del viento se convertirá en un  clásico.»The Times«Cuando empecéis a leer, preparaos para perder el mundo real de vista y sumergiros en una historia de magia, amor y aventura inmensamente original e hipnótica.»The Barnes&Noble Review«El nombre del viento es una de las mejores historias contadas  durante la última década. Guardadlo en la estantería al lado deEl señor de los anillos.»The A.V. Club«Tan absorbente en una segunda lectura como lo es en la primera, este es  el tipo de primera novela que la mayoría de los autores tan solo pueden  soñar con escribir. El universo de la literatura fantástica tiene una nueva estrella.»Publishers Weekly', 'El nombre del viento', 8.35, 1.44, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.19, 3.34, '9788401024061', '8401024064', 0, 19.8, 4.02, '1939-06-20', 'El nuevo libro de George R. R. Martin narra la fascinante historia de  los Targaryen, la dinastía que reinó en Poniente trescientos años antes del inicio de«Canción de hielo y fuego», la saga que  inspiró la serie de HBO:Juego de tronos.Siglos antes de que tuvieran lugar los acontecimientos que se relatan en  «Canción de hielo y fuego», la casa Targaryen, la única dinastía de  señores dragón que sobrevivió a la Maldición de Valyria, se asentó en la isla de Rocadragón.Aquí tenemos el primero de los dos volúmenes en el que el autor deJuego de tronos nos cuenta, con todo lujo de detalles, la historia  de tan fascinante familia: empezando por Aegon I Targaryen, creador del  icónico Trono de Hierro, y seguido por el resto de las generaciones de  Targaryens que lucharon con fiereza por conservar el poder, y el trono,  hasta la llegada de la guerra civil que casi acaba con ellos.¿Qué pasó realmente durante la Danza de dragones? ¿Por qué era tan  peligroso acercarse a Valyria después de la Maldición? ¿Cómo era  Poniente cuando los dragones dominaban los cielos? Estas, y otras  muchas, son las preguntas a las que responde esta monumental crónica,  narrada por un culto maestre de la Ciudadela, que anticipa el ya conocido universo de George R.R. Martin.Fuego y Sangre brindará a los lectores la oportunidad de tener  otra visión de la fascinante historia de Poniente. Esta obra,  magníficamente ilustrada con 80 láminas inéditas de Doug Wheatley, se  convertirá, sin duda, en una lectura ineludible para todos los fans de la aclamada serie.La crítica ha dicho.«Fuego y Sangre es un libro brillante.»Sunday Times«Sin duda alguna podemos considerar a George R. R. Martin como el  principal creador de mundos de fantasía de su generación ... la riqueza  de detalles y las capas del universo que ha creado es extraordinaria, y abundan los sorprendentes giros narrativos.»Sunday Express«Una historia rica llena de matices, que hace aún más grande la  maravilla que es "Canción de hielo y fuego". Muy disfrutable, y al nivel del mejor Martin... absolutamente imprescindible.»Juan Gómez-Jurado,ABC«Fuego y Sangre ofrece un montón de emociones con el característico sello de la casa Martin.»Jacinto Antón,El País', 'Fuego y sangre', 4.13, 3.81, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.34, 4.5, '8401024293', '9788401024290', 0, 23.07, 1.24, '2020-05-19', 'Un relato de deseos enterrados y traiciones indescriptibles. Una historia de amor que desafía los límites. Una novela mágica e inolvidable. Imagina que los libros no solo contienen historias. Imagina que puedes ocultar entre sus páginas tus mayores miedos, tu dolor más profundo, tus secretos más oscuros. A todo el mundo. Incluso a ti mismo. Para siempre. Emmett Farmer, después de un largo día de trabajo en el campo, recibe una misteriosa carta que le cita a incorporarse como aprendiz de encuadernador. Es una profesión que despierta miedo y superstición en su entorno. Sin embargo, como humilde campesino sin recursos, no le queda más remedio que abandonar la granja familiar. En la casa aislada donde vive su maestra, la anciana Seredith, Emmett aprenderá a elaborar libros que, más allá de tener unos acabados muy cuidados, son tomos mágicos que conservan los recuerdos de las personas y atesoran secretos del pasado. Quien quiere olvidarse de algún episodio del pasado, puede acudir al lugar donde los encuadernadores encierran estas vivencias en volúmenes que guardan en una cripta bajo el taller: una suerte de biblioteca del olvido en la que todo permanece a la espera. Pero un día Emmett descubre su nombre en uno de esos libros... ENGLISH DESCRIPTION NATIONAL BESTSELLER A NEW YORK TIMES BOOK REVIEW EDITORS'' CHOICE Proclaimed as “truly spellbinding,” a “great fable” that “functions as transporting romance” by the Guardian, the runaway #1 international bestseller "A rich, gothic entertainment that explores what books have trapped inside them and reminds us of the power of storytelling. Spellbinding.” — TRACY CHEVALIER Imagine you could erase grief. Imagine you could remove pain. Imagine you could hide the darkest, most horrifying secret. Forever. Young Emmett Farmer is working in the fields when a strange letter arrives summoning him away from his family. He is to begin an apprenticeship as a Bookbinder—a vocation that arouses fear, superstition, and prejudice amongst their small community, but one neither he nor his parents can afford to refuse. For as long as he can recall, Emmett has been drawn to books, even though they are strictly forbidden. Bookbinding is a sacred calling, Seredith informs her new apprentice, and he is a binder born. Under the old woman’s watchful eye, Emmett learns to hand-craft the elegant leather-bound volumes. Within each one they will capture something unique and extraordinary: a memory. If there’s something you want to forget, a binder can help. If there’s something you need to erase, they can assist. Within the pages of the books they create, secrets are concealed and the past is locked away. In a vault under his mentor’s workshop rows upon rows of books are meticulously stored. But while Seredith is an artisan, there are others of their kind, avaricious and amoral tradesman who use their talents for dark ends—and just as Emmett begins to settle into his new circumstances, he makes an astonishing discovery: one of the books has his name on it. Soon, everything he thought he understood about his life will be dramatically rewritten. An unforgettable novel of enchantment, mystery, memory, and forbidden love, The Binding is a beautiful homage to the allure and life-changing power of books—and a reminder to us all that knowledge can be its own kind of magic.', 'El encuadernador / The Binding', 5.0, 5.75, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.82, 9.89, '8401026164', '9788401026164', 0, 5.4, 2.89, '2022-06-21', 'Mavi Doñate, corresponsal de RTVE en Pekín, nos ofrece un libro imprescindible para entender la transformación del mundo global. «Bajo la mirada del dragón despierto es tan solo una de mis crónicas, contada en primera persona, sobre la cobertura periodística que jamás habría querido hacer, pero que, de seguro, ha sido y será la más importante de mi carrera». China está lejos. Es lo primero que aprende un periodista destinado en un extremo del mundo al que nunca hemos prestado demasiada atención. Cuando Mavi Doñate llegó a Pekín en el verano de 2015 con el vértigo anidado en el estómago, cumplió un sueño que la había acompañado desde niña: ser corresponsal. Lo que no podía imaginar entonces es que estaba a punto de protagonizar una de las etapas de mayor intensidad informativa de este primer tramo de siglo. Mavi Doñate posee un don innato, mezcla de intuición y sutileza, para contar historias. Su relato personal de los seis años que vivió en el gigante asiático, elaborado a partir de los recuerdos y las voces que quedaron fuera de la información diaria, nos ofrece un valioso retrato de la China actual. Estas páginas recorren los contrastes de un país en constante reinvención y nos llevan de la política internacional a la vida cotidiana; de la modernidad sin freno a las tradiciones más arraigadas; del bullicio en las calles por las celebraciones del Año Nuevo al silencio de los peores días de la pandemia, y nos recuerdan que, durante décadas, hemos vivido de espaldas a ese dragón milenario que esperaba su momento para despertar. ENGLISH DESCRIPTION Mavi Doñate, RTVE correspondent in Beijing, brings us an essential book to understand the transformation of the global world. “Under the Gaze of the Awakened Dragon is but one of my chronicles, told in first person, about the media coverage I would never have wanted to do, but that surely has been and will remain the most important in my career.” China is far away. It is the first thing a journalist learns when stationed in a corner of the world nobody pays much attention to. When Mavi Doñate arrived in Beijing in the summer of 2015 feeling the vertigo nesting in her stomach, she was fulfilling a dream she’d had since childhood: being a correspondent. What she couldn’t imagine then was that she was about to star in one of the most intense media times in the first half of this century. Mavi Doñate has an innate gift—half intuition, half subtlety—to tell stories. Her personal tale of the six years she lived in the Asian juggernaut, crafted after the memories and voices left out of the daily news, offers a valuable recount of China today. These pages explore the contrasts in a country constantly reinventing itself, taking us from international politics to everyday life, from unrestrained modernity to deep-rooted traditions, from the bustle of the streets in New Year’s Eve to the silence during the worst days of the pandemic, reminding us that, for decades, we have lived with our backs to this ancient dragon, biding its time to reawaken.', 'Bajo la mirada del dragón despierto / Under the Gaze of the Awakened Dragon', 8.29, 4.04, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.37, 3.76, '9788401336348', '8401336341', 398, 46.36, 4.55, '1941-12-09', 'Mundodisco, el lugar fantástico e imaginario que sirve de escenario a la saga de novelas homónimas, está en guerra. Todo empieza con la disputa por unos peces y sigue por la posesión de una isla que emerge de repente en medio del mar. A partir de esta situación surrealista, Pratchett incide con ironía en la inutilidad de las guerras, la xenofobia, el racismo y el sexismo. Esta hilarante obra satírica sobre el falso patriotismo y los conflictos armados actuales forma parte de una extensa saga que ha vendido millones de libros en todo el mundo. En el Reino Unido se sitúa inmediatamente después de la afamada J K Rowling, autora de Harry Potter.', '¡Voto a bríos!', 4.54, 3.62, 123, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.67, 2.99, '9788401336980', '8401336988', 0, 3.35, 1.6, '2009-01-16', 'Sin querer, William de Worde se hace editor del primer periódico del Mundodisco.', 'La verdad', 9.89, 7.37, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.92, 9.52, '9788401337208', '8401337208', 0, 52.69, 4.5, '1942-01-15', 'He robado princesas a reyes agónicos. Incendié la ciudad de Trebon. He pasado la noche con Felurian y he despertado vivo y cuerdo. Me expulsaron de la Universidad a una edad a la que a la mayoría todavía no los dejan entrar. He recorrido de noche caminos de los que otros no se atreven a hablar ni siquiera de día. He hablado con dioses, he amado a mujeres y escrito canciones que hacen llorar a los bardos. "Me llamo Kvothe. Quizás hayas oído hablar de mi."', 'El nombre del viento', 9.54, 1.63, 124, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.28, 5.5, '9788401352348', '8401352347', 880, 8.06, 4.52, '2011-11-29', 'Atípica, profunda y sincera,El nombre del viento  es una novela de aventuras, de historias dentro de otras historias, de misterio, de amistad, de amor, de magia y de superación.La novela que ha consagrado a Patrick Rothfuss como fenómeno editorial de los últimos años.En una posada en tierra de nadie, un hombre se dispone a relatar, por  primera vez, la auténtica historia de su vida. Una historia que  únicamente él conoce y que ha quedado diluida tras los rumores, las  conjeturas y los cuentos de taberna que le han convertido en un  personaje legendario a quien todos daban ya por muerto: Kvothe... músico, mendigo, ladrón, estudiante, mago, héroe y asesino.Ahora va a revelar la verdad sobre sí mismo. Y para ello debe empezar  por el principio: su infancia en una troupe de artistas itinerantes, los  años malviviendo como un ladronzuelo en las calles de una gran ciudad y  su llegada a una universidad donde esperaba encontrar todas las respuestas que había estado buscando.«Viajé, amé, perdí, confié y me traicionaron».«He robado princesas a reyes agónicos. Incendié la ciudad de Trebon.  He pasado la noche con Felurian y he despertado vivo y cuerdo. Me  expulsaron de la Universidad a una edad a la que a la mayoría todavía no  los dejan entrar. He recorrido de noche caminos de los que otros no se  atreven a hablar ni siquiera de día. He hablado con dioses, he amado a  mujeres y he escrito canciones que hacen llorar a los bardos.«Me llamo Kvothe. Quizá hayas oído hablar de mí».La crítica ha dicho.«Una estupenda y fuera de lo común novela de aventuras fantásticas».Justo Navarro,El País«Sin dudaEl nombre del viento se convertirá en un clásico».The Times«Un libro para quien conoce el mágico poder de las palabras».Ricard Ruiz Garzón,El Periódico de Catalunya«Una aventura insólita y preciosa. Puntuación: Sobresaliente».Manu González,Qué Leer«No sucede a menudo, peroEl nombre del viento de Patrick Rothfuss sí es tan bueno como dicen las reseñas».Locus«Llena de música, magia, amor y pérdida, el absorbente y vivo debut de Patrick Rothfuss nos ha deslumbrado».Amazon.com«A veces, con suerte y unas cuantas recomendaciones de buenos amigos, se  vuelve a descubrir otro paraíso en el que quedarse, un par de semanas, unos cuantos días. Y eso es justo lo que me ha pasado conEl nombre del viento».Toni Rodero,La Voz de Avilés', 'El nombre del viento (TD)', 7.91, 6.79, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.72, 4.42, '9788401491689', '8401491681', 303, 31.1, 4.61, '2024-11-21', '', 'Mutación', 4.82, 6.74, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.07, 9.4, '9788401496714', '8401496713', 497, 23.33, 4.44, '2022-11-23', 'Este libro extraordinario resume medio siglo de pensamiento acerca de los robots y la robótica. Desde el mismo Robbie hasta los relatos de Susan Calvin, la primera robopsicóloga, pasando por Stephen Byerley, el robot humanoide, y el equipo de detectives formado por un hombre y un robot, Lije Bayley y Daneel Olivaw, encontramos aquí los momentos clave en la historia de ficción de las relaciones entre el hombre y el robot', 'Visiones de robot', 1.29, 4.4, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.55, 1.06, '9788402420541', '8402420540', 160, 63.37, 1.28, '1966-07-25', 'Novela enormemente divertida, no exenta de humor negro, en la que el lector penetra en la tienda y en la vida de una familia dedicada a la venta de productos (sogas para ahorcarse, venenos de toda índole, armas, etc,) que cualquier suicida deber tener a mano para el momento en que decida abandonar este mundo. La familia se siente orgullosa de su trabajo y su reconocida eficacia profesional, hasta que en su seno nace una nueva criatura: un niño alegre al que entusiasma la risa.Es una novela muy divertida, ágil, bien escrita, con diálogos chispeantes.', 'La tienda de los suicidas', 7.8, 5.54, 125, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.66, 3.7, '9788408018117', '8408018116', 469, 74.32, 3.64, '2000-01-23', '', 'Caballo de Troya 4', 4.84, 3.78, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.19, 6.61, '9788408073215', '8408073214', 224, 44.48, 4.64, '2007-06-12', 'En julio de 1956, al volante de un Simca Marly, Dominique Lapierre (entonces joven periodista del Paris Match), Jean-Pierre Pedrazzini (fotógrafo) y sus dos mujeres dejan París y se dirigen a la Unión Soviética, un país prohibido a los occidentales, para realizar un reportaje que cincuenta años después sigue resultando fascinante.', 'Érase una vez la URSS', 2.92, 7.0, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.94, 5.77, '8408108042', '9788408108047', 736, 26.21, 3.04, '1946-08-09', 'Caballo de Troya 1: Jerusalén de J. J. Benítez: El autor pone al descubierto una documentación secreta -clasificada como top secret por el Pentágono- con nuevos y sorprendentes datos sobre la figura y la obra de Jesús de Nazaret. Las revelaciones que aporta son tan rigurosas como desconcertantes.', 'Jerusalén', 2.37, 7.95, 126, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.38, 7.2, '9788409333462', '8409333465', 0, 28.86, 2.93, '2000-01-02', 'Este libro ha sido diseñado específicamente para el Ciclo Formativo de Formación Profesional "Técnico Superior en Sonido para Audiovisuales y Espectáculos", aunque será también un manual imprescindible para cualquier usuario interesado en las disciplinas relacionadas con el audio, especialmente en ciertos aspectos de la rama de la electroacústica.Todos los capítulos se abordan presentando los contenidos teóricos necesarios desde un punto de vista eminentemente práctico, de forma que al profesor de la asignatura le resulte casi consecuente una inmediata presentación de ejemplos y ejercicios prácticos de laboratorio o una resolución de problemas y ejercicios sencillos en clase. Al final del libro profundizamos contenido con más de veinte ejercicios de autoevaluación, por capítulo, con su correspondiente solucionario.', 'Canallas', 9.31, 9.48, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.04, 8.86, '9788411121156', '8411121151', 0, 65.54, 4.17, '1942-10-03', 'Sigue el evento estelar más exitoso de la galaxia.La galaxia está de celebración. Los oscuros días que en torno al desastre hiperespacial han quedado atrás y la canciller Lina Soh avanza la última de sus GRANDES OBRAS. La Feria de la República será su gran logro, una celebración de paz, unión y esperanza en el fronterizo mundo de Valo.Pero un horror implacable asoma por el horizonte. Uno por uno, los planetas van cayendo a medida que el carnívoro DRENGIR devora toda vida a su paso. Mientras la maestra Jedi Avar Kriss lidera la batalla contra esta amenaza, las fuerzas Nihil se reúnen en secreto para la siguiente fase del diabólico plan de MARCHION RO.Sólo los nobles CABALLEROS JEDI se interponen en su camino, pero ni siquiera los protectores de la luz y la vida están preparados para enfrentarse a la oscuridad que les acecha…', 'Star Wars. The High Republic: Tormenta Creciente', 5.29, 7.48, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.7, 9.6, '9788412299229', '8412299221', 557, 39.55, 3.21, '1971-03-23', 'Derrocar a un rey es un trabajo sangriento. El mariscal de campo Tamas ha liderado el golpe de estado en Adro. La aristocracia decadente y corrupta ha terminado en la guillotina y el pueblo hambriento ahora tiene comida. Pero además ha provocado la guerra en las Nueve Naciones, ataques internos de los realistas y lucha encarnizada por el dinero y el poder entre quienes suponía eran sus aliados: la Iglesia, los trabajadores y los mercenarios. Tamas apenas soporta la presión y necesita a Adamat, un inspector de policía retirado, cuya lealtad está en juego, y a los Magos de la Pólvora que le quedan, entre ellos Taniel, su indómito y brillante hijo. Hay quienes presagian muerte y destrucción. Las leyendas están en boca del pueblo pero ningún hombre instruido cree en ese tipo de cosas... aunque sería mejor que lo hicieran. Los dioses también están implicados. __________ “McClellan combina perfectamente la intriga y la acción en una sociedad donde las nuevas fuerzas como los sindicatos, los soldados armados y los ‘Magos de la Pólvora’ chocan con la magia tradicional”. —Publishers Weekly. “Guerra, magia, espadas, mosquetes y dioses reencarnados. Fantasía épica, el debut de McClellan y la primera novela de una trilogía. ¡Excelente!” —The Book Bag.', 'Promesa de sangre', 4.57, 6.81, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.01, 3.0, '9788412319682', '8412319680', 464, 82.85, 2.85, '1962-02-10', 'Atenea, diosa griega de la sabiduría, ha dado vida a la República de Platón en una isla perdida del Mediterráneo. Allí reúne a filósofos de todas las épocas, niños que fueron esclavos y robots encargados del trabajo duro.En La Ciudad Justa, Simmea, una niña brillante, demostrará todo su potencial; Maia, una antigua dama victoriana, deberá encontrar su verdadero lugar y Apolo comprenderá por fin el valor de la vida humana.En esta ciudad de las ideas y el conocimiento todos se esforzarán por alcanzar la excelencia siguiendo al pie de la letra las palabras de Platón… Todo, menos Sócrates, que hará las preguntas que nadie quiere responder.', 'La ciudad justa', 9.67, 1.98, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.5, 8.37, '9788412323252', '8412323254', 199, 72.91, 3.18, '1988-10-10', 'Ven. Acércate. Este es un libro para todos los públicos lleno de amor y humor. Es un manual de emociones. Es una oda al amor y la unión perro-humano y, al mismo tiempo, es una puesta en valor de que lo importante de la vida es vivirla cada día. Como bien te recuerda y enseña el Camino de Santiago: lo importante de cualquier camino es el propio camino, no la meta.En el interior encontrarás una doble aventura: la del primer Camino De Santiago que hicieron Nala y Sara, y la del camino de su vida juntas, como pack vital. Son catorce capítulos, o siete capítulos dobles, donde se establece un paralelismo en las etapas de cada una de las dos aventuras: Nala narra las etapas del peregrinaje a Santiago, y Sara narra las etapas del camino de la vida de una persona con su perro.El contenido descriptivo, el divertido y el emocional vande la mano, pero se dejan su espacio y se retroalimentan, para hacer de este libro una caminata en positivo tanto del Camino como de la vida.', 'El Canino de Santiago', 6.24, 2.64, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.56, 5.35, '9788412382785', '8412382781', 0, 50.5, 1.29, '2005-05-23', '«Mi pueblo fue el primero en caminar por el mundo, compartiendo Muriath con los demonios, mucho antes de la existencia de zarefíes, kalastys y eldos. Y por supuesto, miles de ágaras antes de la aparición de los humanos».  Asthaluss y Muriath son dos mundos gemelos, y la raza humana los habita ambos. Asthaluss es la Tierra que conocemos, pero Muriath se encuentra más allá de cualquier realidad imaginable: es un lugar antaño poblado por dioses y demonios, cuyos habitantes poseen dones extraordinarios, y en el que los humanos conviven con otras razas, entre ellas los dáricos, los primeros seres en haber caminado sobre él.  El día de su cumpleaños, Alhanna es transportada de Asthaluss a Muriath, donde aparece ante Kishur, un dárico que querrá a protegerla a toda costa al sentir que los une una inexplicable conexión. Los dáricos no tardarán en descubrir que la joven es poseedora de un poder que ningún humano debería albergar y que despertará el deseo y el recelo de cuantos seres habitan Muriath.  La llegada de Alhanna pondrá en marcha un engranaje de sucesos más antiguo que el tiempo. En su viaje en busca de respuestas sobre su poder y su identidad, un ser que lleva dormido desde tiempos inmemoriales planeará como una sombra sobre Alhanna y los dáricos. Sus caminos irán avanzando para converger en un destino legendario, terrible e inevitable, pues aquél que mueve los hilos del mundo así lo ha dispuesto.', 'El dárico gris', 5.28, 6.86, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.56, 5.25, '9788412382792', '841238279X', 0, 49.54, 4.75, '1953-08-25', 'Después de haber dejado atrás una tóxica y retorcida relación con Martín, y tras años sin tener noticias de él, a Eric le sigue torturando el recuerdo de su tiempo juntos. Pero, el Día del Fin del Mundo, el azar decide cruzar sus caminos de nuevo. Cuando unas brutales y gigantescas criaturas con cuernos comienzan a aparecer de las profundidades de la Tierra y a aniquilar a mujeres, hombres y niños en todo el planeta, ambos deben dejar sus complicados sentimientos a un lado para volcarse en su supervivencia. En El fin del mundo como excusa para amarte, Rubén Bellés captura la crueldad humana mediante un elenco de personajes brutalmente complejos, y demuestra cómo lo que al final tiene el poder de acabar con la humanidad resulta ser la propia maldad del hombre.', 'El fin del mundo como excusa para amarte', 7.02, 6.05, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.53, 6.62, '9788412419948', '8412419944', 0, 23.15, 4.56, '1987-09-13', '', 'Cantos de sirena', 3.61, 2.24, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.6, 8.45, '9788412560152', '8412560159', 0, 14.68, 2.08, '2003-01-23', 'Primaveral es un lugar extraño, difuso, inabarcable. En él, un raro fenómeno meteorológico identificado con la nieve borra del recuerdo colectivo a aquellos a los que roza. Numerosos eventos caóticos se derivan de ello: el significado de las palabras se desvanece, las relaciones humanas se confunden, las estructuras políticas se ahogan en batallas inocuas, la ignorancia más arrogante se expande incontrolada, el sinsentido lo inunda todo. En medio de todo ello, Nemoroso Ezquerro, un joven librero desencantado y uno de los habitantes más desapercibidos de la ciudad, decide marcharse, ignorando que, apenas salga de Primaveral, recuperará de pronto todas las memorias que las nieves le habían arrebatado. Sus planes cambiarán e iniciará un extraño viaje sin rumbo que estará repleto de alucinaciones nostálgicas, revelaciones insólitas de su identidad y aventuras extraordinarias. Solamente a través de estas, comprenderá la verdad que se oculta tras los extraños fenómenos que castigan Primaveral.', 'La nemorosea', 8.43, 8.67, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.8, 3.34, '9788413042534', '8413042534', 370, 76.66, 3.69, '2024-04-02', 'Sittre es una jovencita humilde y tenaz. Luego de abandonar Gran Árbol, tras descubrir parte de su naturaleza Cambiante, ella deberá aprender a sobrevivir en un temeroso mundo de Humanos. En busca de su propósito, Sittre comprenderá que el espíritu animal', 'El Clan del Sable Gemelo ?Luz?', 3.29, 2.02, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.95, 8.37, '9788413044705', '8413044707', 200, 33.71, 1.24, '2021-10-16', '?Por qu? lo llaman el Pa?s de la Sonrisa? No tiene m?s que leer este libro para comprobarlo. Delgado-Iribarren nos ofrece su mayor libro de viajes hasta la fecha, con un recorrido fascinante por gran parte de la geograf?a de Tailandia. La trepidante megal?polis de Bangkok, el voluntariado con los elefantes de Ban Taklang, las ruinas hist?ricas de Ayutthaya y Sukhotai, el encanto de Chiang Mai, las sorpresas de la selva y de la frontera norte, las maravillosas y variadas playas del sur? Todo aparece retratado con amenidad, profundidad y humor en esta cr?nica donde abundan los personajes entra?ables y las an?cdotas divertidas. No se arrepentir? de vivir este viaje: 35 d?as en Tailandia. ?Empezamos?', '35 días en Tailandia', 5.8, 2.71, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.27, 9.69, '9788413044927', '8413044928', 110, 72.61, 4.7, '2014-07-25', 'En Diccionario en tono de humor el autor reinventa el significado de m?s de 1200 palabras existentes en la lengua espa?ola. Observa cada una de ellas desde la perspectiva que m?s llama su atenci?n, para terminar d?ndole una personal defnici?n que, en muchas ocasiones, al lector se le antoja ?adem?s de divertida? m?s l?gica que la oficial.', 'Diccionario en tono de humor', 5.53, 4.92, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.59, 3.07, '9788413045863', '841304586X', 108, 36.76, 1.62, '1994-01-25', 'El protagonista, Michel, despierta en una playa en un a?o que no era el suyo. A medida que pasan los d?as va viviendo una serie de sucesos desconocidos e inexplicables para ?l. Una historia llena de aventuras, de acci?n... Os adentrareis en una novela de ciencia ficci?n, en un planeta desconocido y en momentos duros y llenos de tensi?n que vive el propio protagonista con varios personajes que aparecer?n a lo largo de la historia. Llena de emociones y miles de preguntas que no encuentra respuesta alguna, a lo largo de los cap?tulos se van desarrollando todas las respuestas convenientes a dichas preguntas. ?Quer?is adentraros en el mundo de Michel y sus amigos? ?O prefer?s no saber por que estaba en un a?o en el que ?l no deber?a residir?', 'Marte y la llave secreta', 3.32, 4.34, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.14, 5.37, '9788413046259', '8413046254', 118, 20.75, 1.36, '1974-11-25', 'La historia es contada por Zayeminc Baud?, una estudiante que vive en Nueva York. Ella pelea por su sue?o de ser escritora y rebelarse contra sus padres empresarios con industrias tanto en Europa como en Nueva York. Zayeminc, inspirada por las historias de magia que su madre le contaba en su infancia, creci? con la idea de dar a conocer la historia de est? ni?a llamada Zaphirah del mundo de Lizandria y lo mucho que aprendi? de ella.  Zaphirah es una ni?a de diez a?os que viv?a en un pueblito de M?xico hasta que un d?a un hada peque?a del tama?o de una mariposa fue a la tierra por ella, confes?ndole su verdadero origen y que, adem?s, ten?a que regresar a su mundo llamado Lizandria por medio de un portal m?gico, porque las criaturas m?gicas que habitaban ah? corrian peligro por los malos sentimientos de una bruja oscura llamada Nela. Zaphirah se enter? de que su mam? era una princesa sehu de una ciudad llamada Alemo y estaba cautiva en un castillo y que ella era la ?nica que pod?a terminar con el hechizo. Con la ayuda de los cuatro elementos y otras criaturas viajaran hasta Ciudad Alemo para rescatar a su madre y as? lograr la paz, el amor y la esperanza en el mundo m?gico lleno de fantas?a de Lizandria.  Pero primero, la ni?a de diez a?os tiene que descubrir qui?n es ella en aquel mundo m?gico y cu?l es su misi?n.', 'EL MUNDO DE ZAPHIRAH I. ZAPHIRAH Y EL PORTAL MAGICO', 1.77, 2.66, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.33, 5.84, '9788413174280', '8413174287', 131, 13.53, 3.25, '2021-06-02', 'Cuando un cierto número de jubilados se reúne, nadie puede imaginar dónde pueden ir a parar ni cómo acabará su aventura. Aventura criticada por sus familias a las que cuidan, miman y de las que son guardianes de sus vástagos las veinticuatro horas del día, trescientos sesenta y cinco días del año, sin descanso, sin un solo minuto para estar solos y contarse sus avatares diarios.Cuando trabajaban era otra cosa. Llegada al hogar y, mientras la parienta ponía la mesa y ellos descansaban después de un día agotador en el sofá tomando unas «birritas», se iban relatando las anécdotas, a modo de terapia conyugal y en cariñosa armonía, de sus respectivas idas y venidas.Ellas, las de su quehacer diario, y ellos, las acaecidas en el trabajo.Hasta que un día deciden romper la monotonía, y aquí es donde da comienzo este relato de mis jubis.Con todo el cariño del mundo a esa generación que, por causa de la crisis, o no, se están haciendo cargo de los nietos y, en ocasiones, incluso de hijos y biznietos.A todos, generalizo hombres y mujeres, gracias por estar ahí, gracias por estar al pie del cañón, con las edades que algunos de vosotros tenéis ya, y que, sin embargo, no os faltan fuerzas para el devenir diario.Ya quisieran muchos jóvenes, en el futuro, bregar con la prole como hoy lo estáis haciendo vosotros. Gracias, abuelos; gracias, yayos.', 'El ocio de un jubilado', 7.79, 5.59, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.44, 7.66, '9788413416366', '8413416361', 429, 9.34, 3.21, '1956-02-07', 'Empieza la nueva etapa en el Universo Star Wars con esta novela.Mucho antes de la Primera Orden, antes del Imperio, incluso antes de La Amenaza Fantasma, existió la edad de oro. Dos siglos antes de la saga Skywalker.Vivimos una época dorada. Intrépidos exploradores hiperespaciales expanden los límites de la República hasta las estrellas más remotas, los mundos prosperan bajo el benévolo liderato del Senado y reina la paz en la galaxia, defendida por la sabiduría y fuerza de la célebre orden de usuarios de la Fuerza conocidos como Jedi. Con los Jedi en la cima de su poder, los ciudadanos libres de la galaxia confían en su habilidad para capear cualquier temporal. Pero incluso la luz más brillante proyecta alguna sombra y algunos temporales desafían cualquier preparación.Cuando una impactante catástrofe en el hiperespacio hace pedazos una nave, la lluvia de metralla que emerge del desastre amenaza a todo un sistema. Los Jedi acuden a toda velocidad cuando llega su petición de auxilio. Sin embargo, el alcance de la emergencia lleva a los Jedi hasta su límite. Cuando el cielo se abre y la destrucción llueve sobre la pacífica alianza que ellos mismos ayudaron a construir, los Jedi deben confiar en la Fuerza para superar un día en que un solo error puede costar miles de millones de vida. Pero, mientras los Jedi combaten valerosamente contra la calamidad, algo realmente letal florece más allá de los confines de la República. El desastre hiperespacial es mucho más siniestro de lo que los Jedi podían sospechar. Una amenaza se esconde en la oscuridad, lejos de la luminosidad de la época, y guarda un secreto capaz de infundir terror incluso en el corazón de un Jedi.', 'Luz de los Jedi', 4.73, 2.8, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.83, 6.06, '9788413621487', '8413621488', 259, 14.11, 3.16, '1974-06-14', 'Si sabes que es miércoles y la mañana empieza como si fuera un domingo, algo muy grave tiene que estar pasando en alguna parte. De esta forma tan inocua comienza una de las novelas más famosas de catástrofes.  Al día siguiente de que una lluvia de meteoritos caiga sobre Inglaterra, Bill Masen es uno de los pocos afortunados que conserva la vista. Londres está llena de hombres y mujeres que vagan en busca de ayuda y en algunos casos tratan de esclavizar a quienes todavía pueden ver. Pero en este mundo postapocalíptico tienen que sobrevivir a otra amenaza: los trífidos, unas plantas carnívoras de más de dos metros de alto, que pueden desplazarse y que poseen aguijones letales. ¿Tienen los seres humanos alguna posibilidad ante un enemigo así?', 'El día de los trífidos', 5.65, 2.21, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.93, 7.48, '9788415374848', '8415374844', 296, 29.52, 1.94, '1967-01-16', 'La travesía del Snark, un queche de 44 pies de eslora construido por Jack London y al que bautizó con el nombre de un animal imaginario en homenaje al poema de Lewis Carrol “la caza del Snark” fue un episodio de la vida del famoso escritor americano que levantó gran expectación en la opinión pública de distintos continentes. El joven Martin Johnson consiguió inesperadamente enrolarse con el empleo de cocinero. El Snark partió de la bahía de San Francisco el 23 de abril de 1907, y durante más de dos años navegó por los Mares del Sur. El viaje terminó prematuramente cuando Jack London fue ingresado en un hospital de Sidney para recobrarse de una enfermedad. Esta es la historia, llena de encanto y aventura, de aquel viaje.', 'Por los Mares del Sur con Jack London', 3.73, 1.48, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.48, 6.91, '9788415618683', '8415618689', 0, 71.56, 2.4, '1939-07-27', 'Tâitulo original: The thing on the doorstep.', 'La llamada de Cthulhu', 6.29, 7.99, 127, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.99, 7.51, '9788415618690', '8415618697', 0, 11.34, 3.26, '1970-02-01', 'Las narraciones extraordinarias de Edgar Allan Poe, el novelista norteamericano nacido en Boston el 19 de enero de 1809 y desaparecido en Baltimore el 7 de octubre de 1849, constituyen la parte más conocida de su obra. El cine y la televisión han explotado, no siempre con fortuna, lo que en Poe hay de misterioso y hasta terrorífico, dejando de lado la intensidad, el pulso y ese acento de campana gigantesca que suponen los valores primordiales de una obra concentrada y personalísima, en la cual lo humano se eleva por caminos pavorosos a tensiones muy superiores a su contenido melodramático. Como si la vida, con su fundamento de terrores y sombras, necesitase ser penetrada por un autor, preocupada por alumbrar inéditos caminos con sus descubrimientos.', 'Narraciones extraordinarias', 4.07, 3.76, 127, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.09, 4.38, '9788415618836', '8415618832', 0, 93.66, 1.28, '1980-08-17', '"Las de Bram Stoker y Jonathan Haker fueron vidas paralelas. Stoker era el secretario particular de Henry Irving, un reputado actor shakespeariano y propietario del Lyceum Theatre de Londres; Harker, el del enigmático conde Drácula, quien lo convocó a su castillo de Transilvania para negociar la adquisición de una mansión en Londres. No es casual que el personaje de Drácula se inspire en las facciones e idiosincrasia de Irving, ni que stoker hiciese una lectura pública en el Lyceum Theatre días antes de su edición. Drácula es la novela vampírica por antonomasia. En ella se concitan los grandes eje s temáticos del subgénero: la lucha entre el bien y el mal y la sexualidad del vampiro, con una estética victoriana y un despliegue estilístico abrumador. Todo ello la convierte en un clásico incontestable e imperecedero." --', 'Drácula', 6.5, 5.93, 127, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.17, 9.88, '9788415831914', '8415831919', 0, 23.35, 1.42, '2013-07-18', 'En un futuro no muy lejano, tras siglos de sobreexplotación, el río Colorado está secándose. La catástrofe obliga a miles de ciudadanos a emigrar a zonas más fértiles de Estados Unidos, pero los estados deciden construir barreras para impedir la marea de refugiados que se les viene encima. A medida que la sequía se extiende y se prolonga, el campo y las ciudades se convierten en páramos sin ley, presas de especuladores que empiezan a comerciar con la desesperación de los seres humanos. En medio de esta desalmada guerra por el agua, el mercenario Angel Velasquez está al servicio de un poderoso cártel que busca nuevos acuíferos. Siguiendo su cometido se cruza con la curtida periodista Lucy Monroe, quien conoce de primera mano el peligro de saber demasiado, y con la joven Maria, hija de un inmigrante mexicano que sueña con escaparse al norte, donde dicen que la tierra sigue poblada de lagos y aún cae agua del cielo. Con la ciudad de Phoenix viniéndose abajo, no queda más remedio que depender los unos de los otros para sobrevivir. Aun así, en un escenario donde el agua vale más que el oro, las alianzas resultan tan movedizas como la arena.', 'Cuchillo de agua', 1.33, 2.47, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.12, 5.46, '9788416517244', '841651724X', 0, 32.53, 2.48, '2020-01-30', '"Se avecina la era de la oscuridad. Cinco vidas se interponen en su camino. ¿Quién la detendrá? ¿Y quién la desatará?" --contraportada.', 'Y Vendra La Oscuridad', 2.53, 2.31, 128, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.38, 3.63, '9788416517374', '8416517371', 504, 42.94, 5.0, '2020-09-30', 'A young woman makes a Faustian bargain to live forever―and is cursed to be forgotten by everyone she meets. Addie LaRue, learns how far she will go to leave her mark on the world. But everything changes when, after nearly 300 years, Addie stumbles across a man in a hidden bookstore and he remembers her name.', 'La Vida Invisible de Addie Larue', 4.37, 2.06, 129, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.74, 1.96, '9788416517411', '841651741X', 352, 84.7, 2.56, '1940-12-21', 'Inaugurando una nueva trilogía, la autora superventas de "Un cuento oscuro" y "Un mundo helado" nos abre las puertas a una peligrosa escuela de magia donde cometer errores es sinónimo de una muerte segura. hasta que una chica empieza a reescribir las reglas del juego.  Entra en una escuela de magia diferente a cualquiera que hayas conocido antes. En ella no hay profesores ni vacaciones, las amistades son pura estrategia y las probabilidades de sobrevivir nunca son las mismas.  Cuando estás dentro, solo hay dos maneras de salir: o te gradúas o mueres. El Higgins está preparada como nadie para hacer frente a los muchos peligros de la escuela. Puede que no tenga aliados, pero posee una fuerza oscura lo suficientemente poderosa para elevar montañas y aniquilar a millones, por no mencionar que puede destruir fácilmente a los innumerables monstruos que merodean por ella. Solo que, accidentalmente, podría matar también al resto de estudiantes. Así que El está intentando con todas sus fuerzas no usarla. a menos que no tenga elección. Ingeniosa, mordaz y divertida, y también con un profundo sentido de la justicia, esta fascinante novela nos recuerda que hay cosas mucho más importantes que la mera supervivencia.', 'UNA EDUCACIN MORTAL/ A DEADLY EDUCATION.', 1.42, 4.59, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.8, 5.31, '9788416517596', '8416517592', 544, 39.78, 4.41, '2022-07-26', 'Magneto and Professor X. Superman and Lex Luthor. Victor Vale and Eli Ever. Sidney and Serena Clarke. Great associations. But Marcella Riggins doesn''t need anyone. Emerging from her brush with death, she finally gained the control she always sought and she will use her newfound power to bring the city of Merit to its knees. She will do whatever it takes. With the rise of Marcella, new feuds create opportunities, and the stage for Merit City will once again be set for one last, terrible reckoning.', 'Una Venganza Mortal', 2.75, 2.92, 130, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.81, 3.42, '9788416517602', '8416517606', 384, 76.21, 4.12, '2022-05-03', 'Victor and Eli began as college roommates, both brilliant, arrogant, lonely boys. In their senior year, a shared research interest in adrenaline, near-death experiences, and seemingly supernatural events reveals that under the right conditions, someone could develop extraordinary abilities.', 'Una Obsesion Perversa', 5.8, 5.95, 130, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.72, 4.6, '9788416517626', '8416517622', 384, 71.84, 3.51, '2022-05-03', 'Kate Harker and August Flynn are the heirs to a divided city--a city where the violence has begun to breed actual monsters. Kate wants to be as ruthless as her father, who lets the monsters roam free, charging for their protection. All August wants is to be human, as good-hearted as his own father.', 'Una Cancion Salvaje', 1.72, 2.37, 130, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.34, 7.93, '9788416517671', '8416517673', 384, 55.11, 2.4, '2022-04-26', 'The threat of graduation takes on significant weight as Naomi Novik''s groundbreaking trilogy, a New York Times bestseller, continues with the stunning sequel to A Deadly Education. Knowledge grants protection. That is the official motto of Scholomance. I suppose we could say that it is true... The problem is that it is very difficult to learn here, so the protection we have is rather scarce. Our esteemed school does its best to devour its students, but now that I am in senior year and have made a few allies, it has suddenly developed a most particular craving for me. Even if I manage to survive the endless waves of evil with grueling class projects, I have no idea how my allies and I are going to make it out of the grade room alive. Unless, of course, I accept my prophesied fate at once and succumb to dark magic and destruction. Of course, that way it would be out in no time. Entering the path of knowledge, without a doubt. But I''m not going to give up: neither to evil nor to destiny, much less to Scholomance. I will leave this horrible place with my friends even if it is the last thing I do... With keen vision and biting humor, Novik reminds us that sometimes just rewriting the rules is not enough: every now and then, they have to be ripped apart.', 'El Ultimo Graduado', 8.5, 2.89, 130, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.5, 9.29, '9788416517695', '841651769X', 416, 34.38, 3.8, '2022-04-26', 'Perfect for fans of A Court of Thorns and Roses and Uprooted, this stand-alone, fantasy romance about a human girl and her marriage to the Elf King is impossible to put down!... The elves come for two things: war and wives. In both cases, they come for death. Three-thousand years ago, humans were hunted by powerful races with wild magic until the treaty was formed. Now, for centuries, the elves have taken a young woman from Luella''s village to be their Human Queen. To be chosen is seen as a mark of death by the townsfolk. A mark nineteen-year-old Luella is grateful to have escaped as a girl. Instead, she''s dedicated her life to studying herbology and becoming the town''s only healer. That is, until the Elf King unexpectedly arrives... for her.', 'Un Trato Con El Rey de Los Elfos', 8.1, 7.31, 130, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.93, 7.97, '9788416517718', '8416517711', 432, 86.67, 4.48, '1980-04-26', 'If your life was based on a lie, would you risk it all to tell the truth?... At Montverre, an ancient and elite academy hidden high in the mountains, society''s best and brightest are trained for excellence in the grand jeu--the great game--an arcane and mysterious competition that combines music, art, math, poetry, and philosophy. Léo Martin once excelled at Montverre but lost his passion for scholarly pursuits after a violent tragedy. He turned to politics instead and became a rising star in the ruling party, until a small act of conscience cost him his career. Now he has been exiled back to Montverre, his fate uncertain. But this rarified world of learning Léo once loved is not the same place he remembers. Once the exclusive bastion of men, Montverre''s most prestigious post is now held by a woman: Claire Dryden, also known as the Magister Ludi, the head of the great game. At first, Léo feels an odd attraction to the magister--a mysterious, eerily familiar connection--though he''s sure they''ve never met before. As the legendary Midsummer Game approaches--the climax of the academy''s year--long-buried secrets rise to the surface and centuries-old traditions are shockingly overturned. A highly imaginative and intricately crafted literary epic, The Betrayals confirms Bridget Collins as one of the most inventive and exquisite new voices in speculative fiction.', 'La Traicion de Montverre', 9.79, 3.43, 130, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.95, 5.96, '9788416517817', '8416517819', 480, 26.81, 1.93, '2022-05-24', 'The Alexandrian Society, caretakers of lost knowledge from the greatest civilizations of antiquity, are the foremost secret society of magical academicians in the world. Those who earn a place among the Alexandrians will secure a life of wealth, power, and prestige beyond their wildest dreams. Only the six most uniquely talented magicians are selected to be considered for initiation each decade. Enter the latest round of six: Libby Rhodes and Nico de Varona, unwilling halves of an unfathomable whole, who exert uncanny control over every element of physicality. Reina Mori, a naturalist, who can intuit the language of life itself. Parisa Kamali, a telepath who can traverse the depths of the subconscious, navigating worlds inside the human mind. Callum Nova, an empath easily mistaken for a manipulative illusionist, who can influence the intimate workings of a person''s inner self. Finally, there is Tristan Caine, who can see through illusions to a new structure of reality--an ability so rare that neither he nor his peers can fully grasp its implications. When the candidates are recruited by the mysterious Atlas Blakely, they are told they will have one year to qualify for initiation, during which time they will be permitted preliminary access to the Society''s archives and judged based on their contributions to various subjects of impossibility: time and space, luck and thought, life and death. Five, they are told, will be initiated. One will be eliminated. The six potential initiates will fight to survive the next year of their lives, and if they can prove themselves to be the best among their rivals, most of them will be initiated. Most of them.', 'El Atlas de Los Seis', 1.32, 9.44, 130, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.58, 4.68, '9788416665129', '8416665125', 0, 48.7, 4.99, '1960-10-13', 'Los relatos de viaje reunidos en este volumen son fruto de ese placer que consiste en hacer de la mirada pretendidamente neutra del reportero un ojo caprichoso.', 'Larga distancia', 1.86, 9.48, 131, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.01, 5.12, '9788416783564', '841678356X', 212, 54.23, 4.43, '1978-09-25', '"Ladakh, región situada en la vertiente norte del Himalaya indio, posee un enorme atractivo para el viajero actual. A la belleza abrupta de sus inmensas montañas y valles se une la riqueza y originalidad de una cultura, la tibetana, conservada con una pureza difícil de hallar en el propio Tíbet central. La hospitalidad y simpatía de sus habitantes, todavía no contaminados por el turismo masivo, hacen del viaje una continua invitación al disfrute, al aprendizaje, a la reflexión.Marta Torres Santo Domingo nos lleva, con este libro, a una etapa más de su particular Ruta de la Seda. Con ella visitaremos Dharamsala y el sueño del exilio tibetano, cruzaremos la Gran Cordillera por el Rothang Pass con los moteros que hacen la «Manali-Leh Road» y nos dejaremos rodear por las cabras pashminas del altiplano tibetano. Llegaremos al valle del Indo, cuna del reino de Ladakh, y nos adentraremos en el misterio de sus monasterios budistas. Además, el valle de Nubra y sus dunas de arena dorada, los espectaculares mandalas de Alchi o el conflicto en Cachemira serán otros hitos del viaje.La autora va acompañada en su camino de monjes recitando mantras, moteros y camioneros, camellos bactrianos perdidos, nómadas pastoreando sus cabras, misioneros con una Biblia en las manos, viajeras extravagantes, artistas, militares, exploradores, espías y escritores que, juntos, constituyen un variado paisaje humano en un viaje que no acaba al cerrar las páginas del libro."', 'VIAJE A LADAKH, EL PEQUEÑO TÍBET', 1.47, 4.24, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.32, 4.11, '9788417001629', '841700162X', 168, 99.77, 3.76, '1975-02-22', 'A través de una serie de entradas --"Aprovechategui", "Beca", "Censura", "Carles Puigdemont", "Corrupción", "Máster", "Pablo Iglesias", "M. Rajoy", "Pedro Sánchez"-- y alguna que otra frase célebre --"Lo desconozco", "Usted se financia de Venezuela", "# y los españoles, muy españoles y mucho españoles"--, Protestona y Anacleto Panceto --ácidos y geniales analistas de Twitter-- describen de forma voraz, cómica, informativa e irónica las dinámicas de la política española. Y lo hacen con un lema que lamentablemente en estos tiempos resulta indiscutible: la política en España parece una broma, y este libro también.', 'Diccionario de la política española', 9.2, 3.44, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.39, 3.96, '9788417014223', '8417014225', 304, 3.68, 3.45, '2019-06-08', 'La idea para esta novela nació en junio de 2015, cuando tuve la oportunidad de viajar por primera vez a la península de Paraguaná. El trayecto desde el aeropuerto hasta las salinas de las Cumaraguas fue una de las experiencias más perturbadoras que he tenido. Rodábamos por un camino desértico que mostraba los horrores de la pobreza extrema: niños famélicos semidesnudos, cadáveres de animales, pueblos fantasma y carteles oxidados sobre los logros de la Revolución Bolivariana. Aquellas imágenes, que me recordaban claramente la saga distópica Mad Max, no me abandonarían jamás. Choro 2021 es un western posapocalíptico, un road trip por una Venezuela en ruinas, donde diferentes tribus luchan por sobrevivir a cualquier precio. La historia tiene una abundante dosis de fantasía como para interpretarla en clave de actualidad. Sin embargo, las macabras similitudes con la realidad venezolana dejarán a más de uno sin aliento. Sea como fuere, deseo para mi país un futuro radicalmente distinto al que imaginé en esta obra y que este 2021 sea como el 1984 de Orwell: una profecía incumplida.Carl Zitelmann', 'Choro 2021: Una distopía bolivariana', 2.95, 4.49, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.59, 9.52, '9788417125844', '8417125841', 187, 17.63, 2.58, '2002-12-05', 'El clásico distópico que nos alerta sobre el lado oscuro de la modernidad>>> Nueva traducción de Marcial Souto<<<<<>>Fahrenheit 451 retrata un futuro sombrío y turbador. Montag, el  protagonista, forma parte de una extraña brigada de bomberos cuya misión  no es sofocar incendios, sino provocarlos para quemar libros. Y es que  en su mundo está terminantemente prohibido leer, porque lo que se quiere  suprimir es el pensar. Una vez que Montag lo comprenda, tendrá que elegir entre la sumisión y la resistencia.«Trabajo para evitar un futuro sin educación.»Ray BradburyLa crítica ha dicho.«Inmersos como estamos en una nueva ola mediática y  tecnológica, es el  momento de releer este clásico que plantea cuestiones eternas: ¿quiénes somos y cómo queremos ser?»Margaret Atwood«Un libro poderoso. Duele, por demasiado posible, el tipo de sociedad futura que retrata.»Bertrand Russell«Bradbury es heredero de la vasta imaginación del maestro Poe.»Jorge Luis Borges«Incomparable. Un maestro en el delicado equilibrio entre ciencia y fantasía.»C. S. Lewis«La fuerza y la potencia de su original imaginación llenan de júbilo... Un talento mayor e insólito.»Christopher Isherwood«De entre todos los infiernos del conformismo,Fahrenheit 451 ofrece el retrato más convincente.»Kingsley Amis', 'Fahrenheit 451', 5.89, 1.4, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.01, 5.58, '9788417248826', '841724882X', 336, 87.76, 1.03, '1977-07-21', '«Originalidad, solidez y belleza, tres cualidades de la arquitectura literaria de Pedro Torrijos. El talento de un relator de historias fascinantes en las que querrásquedarte a vivir»,Raquel Martos«Nunca sé si Pedro Torrijos está loco o es un genio. Supongo que es una mezcla. Lo que si sé es que me encanta leer lo que escribe»,Juan TallónLo que hacemos los seres humanos es construir. Desde ese instante eléctrico en el que ponemos un pie en el suelo por primera vez pero luego resulta que debajo del pie hay una pieza de Lego que habíamos tirado antes desde la cuna, y entonces la cogemos y la encajamos con otra. Sí, construimos. Construimos una vida, construimos un amor, construimos familias, casas, carreteras, ciudades, aeropuertos y naves espaciales. Transformamos lugares en lugares nuevos. A veces son cambios mundanos. A veces son asombrosos. Y los hechos asombrosos se convierten en historias.Territorios improbables es un viaje por las historias que construyeron lugares tan extraordinarios que a menudo ni siquiera aparecen en las guías. Relatos pequeños y hazañas monumentales. Crónicas de éxitos, de fracasos, de playas vacías y de barcos voladores. Historias de ciudades encerradas en edificios y de edificios que viajaron en el tiempo. De cicatrices de hormigón y de castillos de cartón piedra. Historias de casas y familias. Historias de amor y de carreteras.Historias de vida.', 'Territorios improbables', 1.37, 8.2, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.01, 3.71, '8417347003', '9788417347000', 0, 11.65, 3.44, '2018-07-31', 'Juramentada es la aclamada continuación de El camino de los reyes y de Palabras radiantes , y tercera parte de la decalogía «El Archivo de las Tormentas», obra maestra de la fantasía épica que ha coronado la lista de best sellers de The New York Times y ha postulado a Sanderson como el autor de género que más lectores está ganando en todo el mundo. La humanidad se enfrenta a una nueva Desolación con el regreso de los Portadores del Vacío, un enemigo tan grande en número como en sed de venganza. La victoria fugaz de los ejércitos alezi de Dalinar Kholin ha tenido consecuencias: el enemigo parshendi ha convocado la violenta tormenta eterna, que arrasa el mundo y hace que los hasta ahora pacíficos parshmenios descubran con horror que llevan un milenio esclavizados por los humanos. Al mismo tiempo, en una desesperada huida para alertar a su familia de la amenaza, Kaladin se pregunta si la repentina ira de los parshmenios está justificada. Entretanto, en la torre de la ciudad de Urithiru, a salvo de la tormenta, Shallan Davar investiga las maravillas de la antigua fortaleza de los Caballeros Radiantes y desentierra oscuros secretos que acechan en las profundidades. Dalinar descubre entonces que su sagrada misión de unificar su tierra natal de Alezkar era corta de miras. A menos que todas las naciones sean capaces de unirse y dejar de lado el pasado sangriento de Dalinar, ni siquiera la restauración de los Caballeros Radiantes conseguirá impedir el fin de la civilización. ENGLISH DESCRIPTION The #1 New York Times bestselling sequel to Words of Radiance, from epic fantasy author Brandon Sanderson at the top of his game. In Oathbringer, the third volume of the New York Times bestselling Stormlight Archive, humanity faces a new Desolation with the return of the Voidbringers, a foe with numbers as great as their thirst for vengeance. Dalinar Kholin’s Alethi armies won a fleeting victory at a terrible cost: The enemy Parshendi summoned the violent Everstorm, which now sweeps the world with destruction, and in its passing awakens the once peaceful and subservient parshmen to the horror of their millennia-long enslavement by humans. While on a desperate flight to warn his family of the threat, Kaladin Stormblessed must come to grips with the fact that the newly kindled anger of the parshmen may be wholly justified. Nestled in the mountains high above the storms, in the tower city of Urithiru, Shallan Davar investigates the wonders of the ancient stronghold of the Knights Radiant and unearths dark secrets lurking in its depths. And Dalinar realizes that his holy mission to unite his homeland of Alethkar was too narrow in scope. Unless all the nations of Roshar can put aside Dalinar’s blood-soaked past and stand together―and unless Dalinar himself can confront that past―even the restoration of the Knights Radiant will not prevent the end of civilization.', 'Juramentada / Oathbringer', 9.54, 1.11, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.57, 6.23, '9788417347208', '8417347208', 600, 24.33, 2.16, '2003-12-09', 'La tercera parte de «The Expanse», la saga superventas deThe New York Timesen que se basa la exitosa serie de televisión homónima  producida por Syfy y emitida en Netflix.«Hacía tiempo que no leía unaspace opera tan buena.»George R.R. MartinDurante generaciones, el Sistema Solar (Marte, la Luna y el cinturón de  asteroides) ha conformado la gran frontera de la humanidad.  Hasta  ahora. El artefacto alienígena que realizaba su obra bajo las nubes de Venus ha aparecido en la órbita de Urano, donde ha construido una puerta enorme que se abre hacia un espacio sin estrellas.Jim Holden y la tripulación de la Rocinante forman parte de una gran  flotilla de naves militares y científicas que parten para examinar el artefacto. Pero, entre bambalinas, se empieza a desarrollar una trama intrincada que tiene como finalidad la destrucción de Holden. Mientras los emisarios de la especie humana intentan ponerse de acuerdo acerca de si la puerta constituye una oportunidad o una amenaza, ignoran que el mayor de los peligros se encuentra entre sus filas.La crítica ha dicho.«El equivalente, en clave de ciencia ficción, de Canción de Hielo y Fuego.»NPR Books«Magnífico... Una aventura para seguirla.»The Washington Post«Lo más parecido a una película taquillera de Hollywood en forma de libro.»io9.com', 'LA PUERTA DE ABADON', 7.84, 8.24, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.11, 4.67, '8417347224', '9788417347222', 0, 60.46, 1.02, '2019-01-22', 'Mareas de Medianoche es el quinto volumen de la saga «Malaz: El Libro de los Caídos», la decalogía originalmente publicada entre 1999 y 2011 que ha convertido al escritor canadiense Steven Erikson en una de las mayores voces de la fantasía épica contemporánea. Desde entonces, esta obra maestra de la imaginación está considerada una de las series más ambiciosas del género de los últimos años. Después de décadas de guerras intestinas, las tribus de los Tiste Edur al fin se han unido bajo el mando del Rey Warlock. Hay paz, pero el precio ha sido terrible: un pacto hecho con un poder oculto cuyos motivos son, en el mejor de los casos, sospechosos, y, en el peor, mortales. Al sur, el rapaz reino de Lether, impaciente por ver cumplido el papel que profetizaron para él largo tiempo atrás como imperio renacido, ha esclavizado a sus vecinos menos civilizados. Es decir, a todos salvo a los Tiste Edur. El destino ha decretado que también ellos han de caer. Y, sin embargo, la lucha inminente que librarán estos dos pueblos no es más que un pálido reflejo de un conflicto más primitivo. Se están reuniendo antiguas fuerzas y con ellas la herida todavía abierta de una vieja traición y un ansia de venganza... ENGLISH DESCRIPTION After decades of internecine warfare, the tribes of the Tiste Edur have at last united under the Warlock King of the Hiroth. There is peace--but it has been exacted at a terrible price: a pact made with a hidden power whose motives are at best suspect, at worst, deadly. To the south, the expansionist kingdom of Lether, eager to fulfill its long-prophesized enaissance as an Empire reborn, has enslved all its less-civilized neighbors with rapacious hunger. All, that is, save one--the Tiste Edur. And it must be only a matter of time before they too fall--either beneath the suffocating weight of gold, or by slaughter at the edge of a sword. Or so destiny has decreed. Yet as the two sides gather for a pivotal treaty neither truly wants, ancient forces are awakening. For the impending struggle between these two peoples is but a pale reflection of a far more profound, primal battle--a confrontation with the still-raw wound of an old betrayal and the craving for revenge at its seething heart.', 'Mareas de media noche / Midnight Tides', 4.94, 2.13, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.03, 9.73, '8417347275', '9788417347277', 0, 21.03, 1.66, '2019-03-19', 'La nueva novela de Brandon Sanderson. El mundo lleva siglos en guerra; la humanidad está atrapada en un planeta constantemente atacado por unos alienígenas decididos a destruirla. Los pilotos son los únicos héroes dispuestos a combatir al enemigo. Spensa es una joven que siempre ha soñado con convertirse en piloto y defender a la Tierra. Pero su destino se cruza con el de su padre, un piloto que fue asesinado tras abandonar a su equipo, anulando sus opciones de asistir a la escuela de vuelo. De pronto, el ataque alienígena ha hecho duplicar la flota aérea de los humanos, facilitando que Spensa ahora sí pueda volar al espacio... ENGLISH DESCRIPTION From Brandon Sanderson, the #1 New York Times bestselling author of the Reckoners series, Words of Radiance, and the internationally bestselling Mistborn series, comes the first book in an epic new series about a girl who dreams of becoming a pilot in a dangerous world at war for humanity''s future. Spensa''s world has been under attack for decades. Now pilots are the heroes of what''s left of the human race, and becoming one has always been Spensa''s dream. Since she was a little girl, she has imagined soaring skyward and proving her bravery. But her fate is intertwined with her father''s--a pilot himself who was killed years ago when he abruptly deserted his team, leaving Spensa''s chances of attending flight school at slim to none. No one will let Spensa forget what her father did, yet fate works in mysterious ways. Flight school might be a long shot, but she is determined to fly. And an accidental discovery in a long-forgotten cavern might just provide her with a way to claim the stars.', 'Escuadrón / Skyward', 1.93, 2.06, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.29, 2.11, '8417347291', '9788417347291', 0, 66.71, 1.7, '2020-01-21', 'El imperio final inicia la saga «Nacidos de la Bruma [Mistborn]», obra imprescindible del Cosmere, el universo destinado a dar forma a la serie más extensa y fascinante jamás escrita en el ámbito de la fantasía épica. Durante mil años han caído las cenizas y nada florece. Durante mil años los skaa han sido esclavizados y viven sumidos en un miedo inevitable. Durante mil años el Lord Legislador reina con un poder absoluto gracias al terror, a sus poderes y a su inmortalidad. Le ayudan «obligadores» e «inquisidores», junto a la poderosa magia de la alomancia. Pero los nobles a menudo han tenido trato sexual con jóvenes skaa y, aunque la ley lo prohíbe, algunos de sus bastardos han sobrevivido y heredado los poderes alománticos: son los «nacidos de la bruma» (mistborn). Ahora, Kelsier, el «superviviente», el único que ha logrado huir de los Pozos de Hathsin, ha encontrado a Vin, una pobre chica skaa con mucha suerte... Tal vez los dos, unidos a la rebelión que los skaa intentan desde hace mil años, logren cambiar el mundo y la atroz dominación del Lord Legislador. Desde 2006, y en solo diez años, Brandon Sanderson se ha consolidado como el gran renovador de la fantasía del siglo XXI y el autor del género más prolífico del mundo. Ha logrado ganarse a ocho millones de lectores, ser publicado en treinta países y convertirse en el heredero de todo un género. ENGLISH DESCRIPTION From #1 New York Times bestselling author Brandon Sanderson, the Mistborn series is a heist story of political intrigue and magical, martial-arts action. For a thousand years the ash fell and no flowers bloomed. For a thousand years the Skaa slaved in misery and lived in fear. For a thousand years the Lord Ruler, the "Sliver of Infinity," reigned with absolute power and ultimate terror, divinely invincible. Then, when hope was so long lost that not even its memory remained, a terribly scarred, heart-broken half-Skaa rediscovered it in the depths of the Lord Ruler''s most hellish prison. Kelsier "snapped" and found in himself the powers of a Mistborn. A brilliant thief and natural leader, he turned his talents to the ultimate caper, with the Lord Ruler himself as the mark. Kelsier recruited the underworld''s elite, the smartest and most trustworthy allomancers, each of whom shares one of his many powers, and all of whom relish a high-stakes challenge. Only then does he reveal his ultimate dream, not just the greatest heist in history, but the downfall of the divine despot. But even with the best criminal crew ever assembled, Kel''s plan looks more like the ultimate long shot, until luck brings a ragged girl named Vin into his life. Like him, she''s a half-Skaa orphan, but she''s lived a much harsher life. Vin has learned to expect betrayal from everyone she meets, and gotten it. She will have to learn to trust, if Kel is to help her master powers of which she never dreamed. This saga dares to ask a simple question: What if the hero of prophecy fails?', 'El imperio final / The Final Empire', 1.64, 5.0, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.03, 6.52, '9788417347628', '8417347623', 784, 4.63, 2.32, '1961-02-02', 'La mayor epopeya de todos los tiempos, en nueva edición con la traducción corregida en 2019.Contiene 12 ilustraciones a color del artista Sam Weber.Duneserá siempre considerada el gran triunfo de la imaginación  que convirtió a Frank Herbert en uno de los grandes visionarios de la  literatura universal. Hoy este gran clásico vuelve a estar de actualidad  porque pronto inspirará una película y una serie de televisión dirigidas por Denis Villeneuve, el director deArrival yBlade Runner 2049. Es hora, pues, de reivindicar un libro mítico con esta edición  para coleccionistas que reproduce las doce ilustraciones interiores,  firmadas por el prestigioso ilustrador Sam Weber, de la aclamada edición  estadounidense, conmemorativa del cincuenta aniversario deDune, de The Folio Society.La historia comienza a miles de años en el futuro, en un gran imperio  galáctico dividido en cuasi-feudos controlados por familias nobles. La  clave para el control del Imperio se encuentra en Arrakis, un planeta  desértico también conocido como Dune. El protagonista de la historia es  el joven Paul Atreides, heredero del ducado de la Casa de los Atreides.  Su padre, Leto Atreides, recibe de pronto la orden de trasladarse a Arrakis, y Paul deberá enfrentarse, por un lado, al emperador y, por otro, a sus antiguos enemigos, la Casa de los Harkonnen.Dune, admirable mezcla de aventura, misticismo y política, ganó el  primer Premio Nebula (1965), el Premio Hugo (1966) y cimentó una de las sagas más grandiosas de la ciencia ficción.La crítica ha dicho:«No conozco nada comparable, exceptoEl Señor de los Anillos.»Arthur C. Clarke', 'Dune', 7.94, 9.61, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.48, 6.75, '8417347747', '9788417347741', 0, 14.14, 3.42, '2020-07-21', 'La continuación de Escuadrón, la nueva saga épica de Brandon Sanderson. Este es el segundo libro de una serie épica sobre una chica que guarda un secreto en un peligroso mundo en guerra por el futuro de la humanidad. En él continúan las aventuras de Spensa Nightshade, la joven piloto que ha conseguido un puesto en el escuadrón de defensa de la humanidad contra los ataques alienígenas. En realidad, ella siempre quiso ser piloto: poder probar que es una heroína, como su padre. Y aunque llegó a lo más alto, los secretos que desenmascaró sobre su padre fueron aplastantes. Los rumores sobre su cobardía resultaron ciertos. Abandonó su vuelo durante la batalla contra los Krell. Peor aún# se volvió contra su equipo y los atacó. Sin embargo, Spensa está segura de que hay aún más por descubrir en esa historia. Y, si es necesario, viajará hasta el fin de la galaxia para salvar a la humanidad. ENGLISH DESCRIPTION The #1 New York Times bestseller! From the #1 New York Times bestselling author of the Reckoners series, Words of Radiance, the Mistborn trilogy, and the Stormlight Archive comes the second book in an epic series about a girl with a secret in a dangerous world at war for humanity''s future. All her life, Spensa has dreamed of becoming a pilot. Of proving she''s a hero like her father. She made it to the sky, but the truths she learned about her father were crushing. The rumors of his cowardice are true--he deserted his flight during battle against the Krell. Worse, though, he turned against his team and attacked them. Spensa is sure there''s more to the story. And she''s sure that whatever happened to her father in his starship could happen to her. When she made it outside the protective shell of her planet, she heard the stars--and it was terrifying. Everything Spensa has been taught about her world is a lie. But Spensa also discovered a few other things about herself--and she''ll travel to the end of the galaxy to save humankind if she needs to. "[A] nonstop, highflying opener." --Kirkus Reviews, Starred Review "With this action-packed trilogy opener, Sanderson offers up a resourceful, fearless heroine and a memorable cast."--Publishers Weekly, Starred Review "Sanderson delivers a cinematic adventure that explores the defining aspects of the individual versus the society. . . . Fans of Sanderson will not be disappointed." --SLJ "It is impossible to turn the pages fast enough." --Booklist "He''s simply a brilliant writer. Period." --Patrick Rothfuss, author of the New York Times bestseller The Name of the Wind, on Brandon Sanderson.', 'Estelar / Starsight', 8.96, 4.01, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.81, 8.07, '8417347933', '9788417347932', 0, 52.9, 2.45, '2021-02-23', 'La esperada continuación de Juramentada. Brandon Sanderson, en la cima de su carrera. Tras forjar una coalición de resistencia humana contra la invasión enemiga, Dalinar Kholin y sus Caballeros Radiantes llevan un año librando una guerra prolongada y brutal. Ningún bando ha logrado obtener ventaja. Mientras los nuevos descubrimientos tecnológicos cambian el trasfondo de la contienda, el enemigo prepara una operación audaz y peligrosa. La carrera armamentística resultante desafiará el mismo núcleo de los ideales Radiantes y quizá revele los secretos de la antiquísima torre en la que una vez residió toda su fuerza. ENGLISH DESCRIPTION The Stormlight Archive saga continues in Rhythm of War, the eagerly awaited sequel to Brandon Sanderson''s #1 New York Times bestselling Oathbringer, from an epic fantasy writer at the top of his game. After forming a coalition of human resistance against the enemy invasion, Dalinar Kholin and his Knights Radiant have spent a year fighting a protracted, brutal war. Neither side has gained an advantage, and the threat of a betrayal by Dalinar’s crafty ally Taravangian looms over every strategic move. Now, as new technological discoveries by Navani Kholin’s scholars begin to change the face of the war, the enemy prepares a bold and dangerous operation. The arms race that follows will challenge the very core of the Radiant ideals, and potentially reveal the secrets of the ancient tower that was once the heart of their strength. At the same time that Kaladin Stormblessed must come to grips with his changing role within the Knights Radiant, his Windrunners face their own problem: As more and more deadly enemy Fused awaken to wage war, no more honorspren are willing to bond with humans to increase the number of Radiants. Adolin and Shallan must lead the coalition’s envoy to the honorspren stronghold of Lasting Integrity and either convince the spren to join the cause against the evil god Odium, or personally face the storm of failure.', 'El ritmo de la guerra / Rhythm of War', 2.14, 3.55, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.9, 7.2, '9788417477684', '8417477683', 930, 55.21, 3.73, '2020-06-28', 'El autor norteamericano Edgar Allan Poe (1809-1849) ocupa un lugar relevante en el panteón de los escritores más admirados, imitados y estudiados de la literatura universal. Considerado por muchos como un precursor del cuento corto y de terror como género literario, Edgar Allan Poe escribió también poesía, ensayos y crítica literaria. Aunque indudablemente fascinado con lo macabro y con un especial talento para ello, Poe también exploró diversos temas y tonos en su obra, con relatos detectivescos (de los cuales también es considerado pionero), humorísticos, históricos y hasta crónicas periodísticas. Su obra ha inspirado innumerables homenajes e influenciado el estilo de autores como H. P. Lovecraft y Arthur Conan Doyle. Con una vida marcada por la tragedia Poe logró dejar una huella indeleble en la historia literaria de su país y del mundo, como un maestro de la naturaleza humana y de todos sus matices. El presente volumen contiene más de sesenta cuentos, reuniendo todos los relatos publicados durante su corta y accidentada vida.', 'Cuentos completos', 5.44, 4.0, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.6, 3.41, '9788417496135', '8417496130', 340, 62.61, 2.22, '2024-09-14', 'Hay en la Rusia oriental una carretera mítica, una especie de Ruta 66 donde la Historia del comunismo más sanguinario se cruza con el carácter extremo de la temperatura siberiana y su inherente despoblación. Los mapas la denominan Autopista M56. Los locales la conocen, simplemente, como Trassa (La Ruta). Sin embargo, su nombre más legendario es el de Carretera de los Huesos, porque bajo ese pavimento maltrecho por el que apenas circula nadie están enterrados, para darle firmeza al suelo, miles de los prisioneros del Gulag que la construyeron por orden de Stalin.El prestigioso reportero polaco Jacek Hugo-Bader, heredero de Ryszard Kapuscinski, ha recorrido en autoestop los 2.025 kilómetros de esta vía. El suyo no es solo un viaje al terrible pasado soviético que retrataron Varlam Shalámov o Aleksandr Solzhenitsyn. Es sobre todo un descenso al alma de las personas que hoy habitan este infierno helado. Hugo-Bader habla con los descendientes de los prisioneros. Escribe de estafadores y comerciantes de chatarra. De políticos corruptos y del crimen organizado. De intelectuales que sobreviven alimentándose de hongos y de espías y delatores. De chamanes y chequistas. De mineros que cavan fosas comunes mientras buscan oro, y de todos los adictos, convictos y héroes caídos que huyen de sus problemas y acaban en la región más fría y remota de Rusia, un mundo aparte donde la Historia es un fantasma que se niega a marcharse.', 'Diarios de Kolimá', 4.56, 6.75, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.67, 3.01, '9788417517793', '8417517790', 343, 89.38, 4.6, '1993-09-17', 'Reseña del editor: ¿Qué pasaría si un inocente juguete dinamitara nuestra noción de libre albedrío? ¿Y si fuera posible ponerse en contacto con versiones de nosotros mismos en otras líneas temporales? Si creáramos mascotas virtuales provistas de una inteligencia artificial que les permitiera aprender como si fueran niños humanos, ¿qué clase de compromiso ético deberíamos asumir con su educación y su futuro? ¿Y qué ocurriría si pudiéramos visionar cualquier episodio de nuestra vida tal como sucedió, sin el matiz afectivo y el sesgo interpretativo de lo que llamamos «recuerdos»?No importa cuál sea el tema que trate Ted Chiang en sus narraciones, siempre demuestra una formidable habilidad para indagar en los enigmas de la condición humana y abordar los conflictos éticos que la relación con la tecnología plantea en nuestra existencia. Lejos del enfoque distópico hoy predominante en las narraciones futuristas, las historias de Chiang muestran una perspectiva abiertamente positiva y vitalista, delineando preguntas filosóficas de un enorme calado humano.Ted Chiang es uno de los nombres insoslayables de la ciencia ficción, género en el que desde hace años goza del más sólido prestigio, como atestigua la infinidad de premios que su obra ha recibido; reveladores, elegantes y sorprendentes, los relatos de Exhalación lo sitúan, sencillamente, entre los autores indiscutibles de la literatura estadounidense actual.', 'Exhalación', 9.75, 5.75, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.6, 3.89, '9788417615086', '8417615083', 0, 23.29, 3.78, '1975-11-07', 'Ohio. Cada mañana, los empleados se encuentran destrozados los armarios Kjerring, tiradas por el suelo las lámparas Brooka, y extrañas manchas en los sofás Liripip. Para desvelar este misterio, cinco jóvenes empleados se ofrecen como voluntarios para un largo turno de noche, en el que afrontarán horrores que desafían la imaginación. Una tradicional historia de casas encantadas en un entorno contemporáneo (y repleto de horrores propios de nuestra época).Horrorstor es una novela que viene convenientemente presentada en forma de catálogo completo, con ilustraciones para montar los muebles y otros accesorios más siniestros. ¡Te prometemos que no has visto nada igual!¡Bienvenidos a Orsk!La tienda sueca de muebles más famosa del mundo esconde un secreto terrorífico.¿Sonidos en la oscuridad? ¿muebles que parecen potros de tortura? ¿laberínticos pasillos? ¿ofertas de morirse? ¡No hay mejor plan para un sábado por la noche que ir a Orsk!', 'Horrorstör', 3.24, 5.65, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.32, 1.58, '9788417700751', '8417700757', 184, 27.9, 1.95, '1956-02-04', 'En una aldea suiza de alta montaña, el nuevo alcalde decide que durante el verano se lleve el ganado a los pastos de ?arriba?, en las inmediaciones del glaciar, tras veinte años de no hacerlo a causa de ?algo? que los viejos del lugar recuerdan con temor pero no nombran.  Desde las primeras páginas, Ramuz consigue crear una atmósfera cerrada al aire libre, un clima opresivo en las cumbres y los abismos, que da lugar a una tragedia alpina en la que los indicios pánicos, signos de desolación y desgracias ?entre ellas la más temida, la epidemia? se acumulan progresivamente hasta la catástrofe final.  ''El Gran Miedo en la Montaña'' es una parábola del mal, situado simbólicamente en el seno del interminable combate entre la naturaleza y los hombres.  CHARLES-FERDINAND RAMUZ (Lausanne, 1878 - Pully, 1947) figura entre los escritores más representativos de la novela de la primera mitad del siglo XX. Como renovador del género, vivió las grandes revoluciones formales de las vanguardias, aspecto éste claramente advertible en el conjunto de su obra. Amigo de Gide, de Stravinski, de Emmanuel Mounier, Ramuz encarna el momento más relevan-te de la novela suiza contemporánea.  Además de ''El Gran Miedo en la Montaña'' (1925) ?su obra maestra?, en su producción destacan, entre otras, ''Vida de Samuel Belet'' (1913), ''La Belleza de l.', 'El gran miedo en la montaña', 7.45, 8.32, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.9, 6.02, '9788417834524', '8417834524', 512, 90.67, 1.86, '1968-05-20', 'Bienvenido a Black Spring, una población pintoresca con un macabro secreto: una mujer recorre las calles con la boca y los ojos cosidos, entra en los hogares y espía a la gente mientras duerme. La llaman la Bruja de Black Rock.Los vecinos se han acostumbrado tanto a su presencia que a veces se les olvida lo que ocurrirá si algún día abre los ojos. Para protegerse de curiosos, los fundadores de Black Spring han instalado equipos de vigilancia con los que mantienen la zona en cuarentena. Hasta que unos adolescentes, hartos de su aislamiento, deciden saltarse las normas y convertir la maldición en una experiencia viral.Nadie se imagina la siniestra pesadilla que entonces los aguarda.HEX es el gran éxito editorial de terror neerlandés que ha arrasado en ventas tanto en Europa como Estados Unidos. La Warner Bros. ha comprado sus derechos televisivos y cinematográficos.', 'Hex', 7.42, 9.83, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.17, 2.17, '9788418001024', '841800102X', 157, 55.06, 4.11, '1971-12-16', '" Bañaderos, año 1939, recién acabada la Guerra Civil española. En el seno de una familia modesta y cristiana, nace Pape, quien tiene la suerte de crecer en un ambiente de pueblo rodeado de amigos de todas las clases sociales. Dotado de gran inteligencia y habilidad, sus amigos lo aúpan a la jerarquía de jefe. Al estar su casa ubicada en las cercanías de una carpintería y de un taller mecánico, estas se convertirán en actores muy importantes en la formación del carácter del pequeño. La carpintería, sobre todo, será su segundo hogar. Más que una novela, se trata de una serie de relatos sucedidos a lo largo de su infancia, enriquecidos por los sentimientos de un amor juvenil. Personajes importantes en estas historias, además de sus padres, don Juan, el maestro, y don Hilario el cura, son Josefina, su novia, a la que en su intimidad llama Fefi, la niñera, Petra, a la que cariñosamente llama Pe, y su tío Pedro. Todas sus aventuras transcurren en los lugares típicos de su pueblo, rincones en los que es feliz en compañía de sus queridos amigos. De alguna forma, Pape es una parte de la historia de la vida del autor. Puede decirse que es una autobiografía algo manipulada, pero bastante real."', 'Pape, Fefi y la pandilla', 2.7, 5.53, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.35, 4.38, '8418037016', '9788418037016', 0, 66.27, 4.61, '2021-08-24', 'Finalista de los Hugo Awards 2022. Ganadora del Goodreads Choice Awards 2021 de Ciencia Ficción. Recomendada por Obama como lectura del verano 2021. La nueva novela del autor de El marciano, que se convertirá en una película protagonizada y producida por Ryan Gosling. UN ÚNICO ASTRONAUTA. UNA MISIÓN IMPOSIBLE. UN ALIADO QUE JAMÁS HABRÍA IMAGINADO. Ryland Grace es el único superviviente en una misión desesperada. Es la última oportunidad y, si fracasa, la humanidad y la Tierra misma perecerán. Claro que, de momento, él no lo sabe. Ni siquiera puede recordar su propio nombre, y mucho menos la naturaleza de su misión o cómo llevarla a cabo. Lo único que sabe es que ha estado en coma inducido durante mucho mucho tiempo. Acaba de despertar y se encuentra a millones de kilómetros de su hogar, sin más compañía que la de dos cadáveres. Muertos sus compañeros de tripulación, y a medida que va recuperando confusamente los recuerdos, Grace se da cuenta de que se enfrenta a una misión imposible. Recorriendo el espacio en una pequeña nave, depende de él acabar con una amenaza de extinción para nuestra especie. Sin apenas tiempo y con el ser humano más cercano a años luz de distancia, habrá de conseguirlo estando completamente solo. ¿O no? Proyecto Hail Mary, una aventura interestelar irresistible como solo Andy Weir podía imaginar, es una historia de descubrimiento, especulación y supervivencia a la altura de El marciano, que nos lleva a lugares que nunca soñamos alcanzar. ENGLISH DESCRIPTION Finalists for the 2022 Hugo Awards . Winner of the Goodreads Choice Awards 2021 on Science Fiction A lone astronaut must save the earth from disaster in this incredible new science-based thriller from the #1 New York Times bestselling author of The Martian. “A novel that would have delighted Robert A. Heinlein and Isaac Asimov.”—George R.R. Martin, author of A Game of Thrones “Weir’s finest work to date . . . the one book I read last year that I am certain I can recommend to anyone, no matter who, and know they’ll love it.”—Brandon Sanderson, author of the Stormlight Archive series Ryland Grace is the sole survivor on a desperate, last-chance mission—and if he fails, humanity and the earth itself will perish. Except that right now, he doesn’t know that. He can’t even remember his own name, let alone the nature of his assignment or how to complete it. All he knows is that he’s been asleep for a very, very long time. And he’s just been awakened to find himself millions of miles from home, with nothing but two corpses for company. His crewmates dead, his memories fuzzily returning, Ryland realizes that an impossible task now confronts him. Hurtling through space on this tiny ship, it’s up to him to puzzle out an impossible scientific mystery—and conquer an extinction-level threat to our species. And with the clock ticking down and the nearest human being light-years away, he’s got to do it all alone. Or does he? An irresistible interstellar adventure as only Andy Weir could deliver, Project Hail Mary is a tale of discovery, speculation, and survival to rival The Martian—while taking us to places it never dreamed of going.', 'Proyecto Hail Mary / Project Hail Mary', 5.91, 3.63, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.17, 3.85, '8418037105', '9788418037108', 0, 74.64, 1.53, '2021-07-20', 'La trilogía olvidada de la gran dama de la ciencia ficción. Treinta años después de su primera publicación en castellano, La estirpe de Lilith, título que reúne la Trilogía Xenogénesis en un solo volumen, vuelve a las librerías dispuesta a reivindicar a Octavia E. Butler como la gran pionera que deslumbró en ciencia ficción siendo una mujer negra. Hoy se la considera la primera escritora afroamericana de género en incorporarse al canon de la literatura norteamericana. Lilith Iyapo despierta en una nave espacial oankali, la raza alienígena que salvó a la humanidad de la extinción después de que la Tierra quedase devastada a causa de una guerra nuclear. Estos seres han mantenido a Lilith y a otros supervivientes dormidos en animación suspendida durante siglos. Ella será la elegida que guiará a los suyos de vuelta a su propio planeta, ahora dominado por la naturaleza salvaje, para que aprendan a vivir en él y se conviertan en la semilla de una nueva estirpe. Pero todo intercambio tiene una contrapartida: su descendencia no será humana. O no exactamente. Bienvenidos a la poderosa epopeya interplanetaria que ha convertido a Octavia E. Butler en un mito. «Hablé con unos treinta o cuarenta escritores negros de género que publicaban relatos cortos, novelas y demás, y todos lo hacían porque Octavia E. Butler les había abierto el camino.» -N. K. Jemisin. ENGLISH DESCRIPTION The acclaimed trilogy that comprises Lilith''s Brood is Hugo and Nebula award-winner Octavia E. Butler at her best. Presented for the first time in one volume with an introduction by Joan Slonczewski, Ph.D., Lilith''s Brood is a profoundly evocative, sensual -- and disturbing -- epic of human transformation. Lilith Iyapo is in the Andes, mourning the death of her family, when war destroys Earth. Centuries later, she is resurrected -- by miraculously powerful unearthly beings, the Oankali. Driven by an irresistible need to heal others, the Oankali are rescuing our dying planet by merging genetically with mankind. But Lilith and all humanity must now share the world with uncanny, unimaginably alien creatures: their own children. This is their story...', 'La estirpe de Lilith / Lilith''s Brood', 8.69, 4.14, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.31, 3.11, '9788418037214', '8418037210', 670, 16.92, 1.41, '1936-02-03', 'Nueva edición deEl Imperio Final. El primer volumen de  «Nacidos de la Bruma (Mistborn)», con 8 ilustraciones a color.Brandon Sanderson es el gran renovador de la fantasía del siglo XXI,  con veinte millones de lectores en todo el mundo.La saga Nacidos de la Bruma (Mistborn) es una obra imprescindible del  Cosmere, el universo destinado a dar forma a la serie más extensa y fascinante jamás escrita en el ámbito de la fantasía épica.Durante mil años han caído cenizas del cielo. Durante mil años nada ha  florecido. Durante mil años los skaa han sido esclavizados y viven en la  miseria, sumidos en un miedo inevitable. Durante mil años el Lord  Legislador ha reinado con poder absoluto, dominando gracias al terror, a  sus poderes y a su inmortalidad, ayudado por «obligadores» e «inquisidores», junto a la poderosa magia de la alomancia.Pero los nobles a menudo han tenido trato sexual con jóvenes skaa y,  aunque la ley lo prohíbe, algunos de sus bastardos han sobrevivido y  heredado los poderes alománticos: son los «Nacidos de la Bruma» (Mistborn).Ahora, Kelsier, el «superviviente», el único que ha logrado huir de los  Pozos de Hathsin, ha encontrado a Vin, una pobre chica skaa con mucha  suerte... Tal vez los dos, con el mejor equipo criminal jamás reunido,  unidos a la rebelión que los skaa intentan desde hace mil años, logren  cambiar el mundo y acabar con la atroz mano de hierro del Lord Legislador.', 'El imperio final', 8.55, 7.49, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.87, 6.6, '8418037237', '9788418037238', 0, 53.25, 1.55, '2021-11-02', 'Esquirla del Amanecer es una historia que forma parte de la decalogía El Archivo de las Tormentas y está ambientada entre Juramentada y El Ritmo de la Guerra. Sigue la estela de Danzante del Filo y permite que brillen unos personajes que suelen quedar eclipsados. Brandon Sanderson es el gran renovador de la fantasía del siglo XXI, con diecinueve millones de lectores en todo el mundo. Tras el descubrimiento de un barco fantasma, cuya tripulación al parecer murió intentando llegar a la isla de Akinah, rodeada por tormentas, Navani Kholin deberá enviar una expedición para asegurarse de que la isla no haya caído en manos enemigas. Los Caballeros Radiantes que vuelan demasiado cerca de Akinah se encuentran de pronto con su luz tormentosa drenada, por lo que la travesía debe realizarse por mar. La naviera Rysn Ftori perdió el uso de las piernas, pero ganó la compañía de Chiri-Chiri, una larkin alada que se alimenta de luz tormentosa y pertenece a una especie que se creía extinta. La mascota de Rysn ha enfermado y la única esperanza de que Chiri-Chiri se recupere podría encontrarse en el hogar ancestral de los larkin, Akinah. Con la ayuda de Lopen, el Corredor del Viento que antes era manco, Rysn tendrá que aceptar el encargo de Navani y navegar hacia el interior de la peligrosa tormenta, de la que nadie ha vuelto con vida. Si su tripulación no logra desvelar los secretos de la isla oculta antes de que caiga sobre ellos la ira de sus antiguos guardianes, el destino de Roshar y de todo el Cosmere penderá de un hilo. ENGLISH DESCRIPTION From Brandon Sanderson—author of the #1 New York Times bestselling Stormlight Archive and its fourth massive installment, Rhythm of War—comes a new hefty novella, Dawnshard. Taking place between Oathbringer and Rhythm of War, this tale (like Edgedancer before it) gives often-overshadowed characters their own chance to shine. When a ghost ship is discovered, its crew presumed dead after trying to reach the storm-shrouded island Akinah, Navani Kholin must send an expedition to make sure the island hasn''t fallen into enemy hands. Knights Radiant who fly too near find their Stormlight suddenly drained, so the voyage must be by sea. Shipowner Rysn Ftori lost the use of her legs but gained the companionship of Chiri-Chiri, a Stormlight-ingesting winged larkin, a species once thought extinct. Now Rysn''s pet is ill, and any hope for Chiri-Chiri’s recovery can be found only at the ancestral home of the larkin: Akinah. With the help of Lopen, the formerly one-armed Windrunner, Rysn must accept Navani''s quest and sail into the perilous storm from which no one has returned alive. If the crew cannot uncover the secrets of the hidden island city before the wrath of its ancient guardians falls upon them, the fate of Roshar and the entire Cosmere hangs in the balance.', 'Esquirla del amanecer / Dawnshard', 8.94, 3.17, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.64, 2.14, '9788418037276', '841803727X', 779, 72.86, 1.93, '1935-11-28', 'Nueva edición de El Pozo de la Ascensión. El segundo volumen de  Nacidos de la Bruma (Mistborn), con 8 ilustraciones a color.Brandon Sanderson es el gran renovador de la fantasía del siglo XXI,  con veinte millones de lectores en todo el mundo.La saga Nacidos de la Bruma (Mistborn) es una obra imprescindible del  Cosmere, el universo destinado a dar forma a la serie más extensa y fascinante jamás escrita en el ámbito de la fantasía épica.Durante mil años nada ha cambiado: han caído las cenizas, los skaa han  sido esclavizados y el Lord Legislador ha dominado el mundo. Pero lo  imposible ha sucedido. El Lord Legislador ha muerto. Sin embargo, vencer  y matarlo fue la parte sencilla. El verdadero desafío será sobrevivir a las consecuencias de su caída.Tomar el poder tal vez resultó fácil, pero ¿qué ocurre después?, ¿cómo  se utiliza? La tarea de reconstruir el mundo, ahora que Kelsier no está,  ha quedado en manos de Vin. Y las brumas, desde que el Lord Legislador cayó, se han vuelto cada vez más impredecibles.A medida que el asedio se intensifica, la antigua leyenda del Pozo de la Ascensión ofrece un único rayo de esperanza.En ese mundo de aventura épica, la estrategia política y religiosa debe  lidiar con los siempre misteriosos poderes de la alomancia.', 'El pozo de la ascensión', 7.37, 9.63, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.03, 3.44, '9788418037290', '8418037296', 760, 17.69, 3.15, '1993-07-23', 'Nueva edición deEl Héroe de las Eras. El tercer volumen de  «Nacidos de la Bruma (Mistborn)», con 8 ilustraciones a color.Brandon Sanderson es el gran renovador de la fantasía del siglo XXI,  con veinte millones de lectores en todo el mundo.La saga Nacidos de la Bruma (Mistborn) es una obra imprescindible del  Cosmere, el universo destinado a dar forma a la serie más extensa y fascinante jamás escrita en el ámbito de la fantasía épica.Durante mil años nada ha cambiado: han caído las cenizas, los skaa han  sido esclavizados y el Lord Legislador ha dominado el mundo. Kelsier, el  "superviviente", el único que ha logrado huir de los Pozos de Hathsin,  junto a Vin, una pobre chica skaa, se une a la rebelión. Y por fin lo  imposible sucede: por fin la revolución ha triunfado. Pero acabar con el  Lord Legislador es la parte sencilla. El verdadero desafío consistirá en  sobrevivir a las consecuencias de su caída... sin Kelsier.Vin y el Rey Elend buscan en los últimos escondites de recursos del Lord  Legislador y, engañado, el Rey libera del Pozo de la Ascensión algo que  debería haber quedado oculto para siempre. Un enorme peligro acecha a la  humanidad, y la verdadera pregunta es si conseguirán detenerlo a tiempo.EnEl héroe de las erasse comprende el porqué de la niebla y las  cenizas, las tenebrosas acciones del Lord Legislador y la naturaleza del  Pozo de la Ascensión. Esta aventura lleva a la trilogía a un clímax dramático y sorprendente.', 'El héroe de las eras', 4.02, 6.93, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.92, 8.68, '9788418037542', '8418037547', 0, 88.93, 2.67, '1951-11-21', 'La edición ilustrada de la obra cumbre de Isaac Asimov, con 11  ilustraciones del artista Gabriel Björk Stiernström y traducción de Manuel de los Reyes. Isaac Asimov empezó a escribir la saga de la Fundación a los veintiún  años, sin saber que un día esta obra se convertiría en la piedra angular  de la ciencia ficción del siglo XX, ni que con ella cautivaría a lectores de todas las edades durante más de siete decadas. ¿Por que surgen y caen los imperios? La Trilogía Fundación es una  historia con múltiples capas cuya lectura sigue siendo tan apasionante  hoy como cuando se publicó por vez primera en la decada de 1950.  Incorporando infinitos elementos de la política contemporánea, la  historia antigua y las matemáticas, la obra maestra de Asimov explora el  declive del Imperio Galáctico, una civilización que gobernó sobre casi veinticinco millones de planetas habitados. Esta edición única de la Trilogía Fundación, ilustrada y en un  solo volumen, es el mejor homenaje a la mayor saga de la ciencia ficción universal. Citas: "Las novelas de la Fundación de Asimov le dieron sentido a mi forma de entender la economía". Paul Krugman, premio Nobel de Economía', 'Trilogía Fundación (edición ilustrada)', 4.78, 3.66, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.18, 6.66, '9788418037757', '841803775X', 0, 34.77, 2.15, '1940-06-19', 'La colección de novelas cortas de la saga Escuadrón, con  ilustraciones exclusivas de los personajes y las escenas eliminadas deEscuadrón con comentarios de Brandon Sanderson.Incluye La defensa del Elíseo.Viajamos con el Escuadrón Cielo a Detritus, el último refugio de la  humanidad frente al gobierno hostil de la Supremacía Galáctica. EnEscuadrón, Spensa Nitghshade se convirtió en piloto de caza estelar y pasó a formar parte del Escuadrón Cielo de la Fuerza de Defensa Desafiante con el objetivo de combatir la amenaza de la  Supremacía. EnEstelar, se hizo pasar por la alienígena Alanik  para infiltrarse en una estación espacial de la Supremacía y robar sus hipermotores. Y enCitónica viajó a la extraña dimensión conocida  como la ninguna-parte para descubrir los secretos de los zapadores -unos seres capaces de destruir planetas enteros- y liberar sus propios  poderes citónicos.Mientras Spensa está atrapada en la ninguna-parte, sus compañeros de  escuadrón, FM y Jorgen permanecen en Detritus con nuevas órdenes:  averiguar cómo utilizar los hipermotores para que la humanidad pueda  huir del planeta y buscar aliados entre las otras especies oprimidas por  la Supremacía. Primeror reciben una llamada de emergencia de le ministre  Cuna y otres diones desde el puesto de avanzada abandonado de Alcance  Solar, pero el pueblo de Alanik en el planeta ReAlba y los kitsen del  planeta Orilla Perpetua necesitarán también la ayuda del Escuadrón Cielo en sus desesperadas batallas.', 'Escuadrón Cielo: La colección', 5.48, 8.19, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.2, 3.01, '9788418040016', '8418040017', 156, 95.53, 3.88, '1993-10-02', 'Nostalgia milenial: el Yo fui a EGB de los milenials.¿Echas de menos... los tamagotchis?... los Power Rangers?... el Messenger?... el Grand Prix?... la falta de responsabilidades?Si la respuesta a la mayoría de preguntas es sí, no hay duda, lo que tú tienes se llama nostalgia milenial. Pero tranqui, ¡no es nada malo!Con este libro podrás recordar los desayunos con Megatrix, las tardes en el ciber, las canciones del verano o la llegada del Tuenti. También los politonos, el fenómeno Harry Potter o el primer OT. Podrás recordar lo maravilloso que fue crecer en pleno cambio de milenio.¿Te apuntas a este viaje al pasado? Pues sumérgete entre sus páginas y, como diría Mufasa, ¡recuerda quién eres!.', 'Nostalgia milenial', 3.05, 9.0, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.68, 5.62, '8418051191', '9788418051197', 0, 15.54, 4.97, '2022-10-11', 'El libro de Arturo González-Campos que te autoayuda a fracasar estrepitosamente en la vida «Amo las cosas y, por lo tanto, amo a las personas que hacen cosas. Gente que dedica su vida a hacer libros, pelis, canciones, cómics..., cosas. Gracias a ellas soy un poco menos imbécil, lo cual, en mi caso, tampoco es mucho decir». Enhorabuena por tu fracaso es un desnudo integral de Arturo González-Campos, lo que no sabemos si dice mucho a su favor. Una oda a lo genuino y una invitación a que te atrevas a persistir en lo que te apasiona; a fracasar y fracasar y volver a intentarlo para, con toda probabilidad, seguir aprendiendo a fracasar. Este es un relato (¿o unas memorias?) sobre esos fracasos que, sólo a veces, se convierten en éxitos y que han permanecido en la mente de Arturo González-Campos durante toda su vida. Listas de canciones, de películas, de libros, pequeñas historias personales que se hacen universales y anécdotas amargamente tristes que te matarán de risa. Todo eso y mucho más podrás encontrar en esta «artubiografía de las cosas» que es una puta locura. «Este libro no te va a llevar ni a Ítaca ni a Mordor. Mira fijamente el trayecto de la Roomba de tu casa; eso va a ser este libro. Este libro son mis cajitas». ENGLISH DESCRIPTION The book by Arturo González-Campos that will self-help you to fail miserably. «I love things and therefore I love people who make things. People who dedicate their lives to making books, movies, songs, comics... things. Thanks to them I am a little less stupid— which, in my case, is not saying much either.» Congratulations on your failure is a full-frontal nude of sorts by Arturo González-Campos— and not much of a flattering one at that. It is an ode to unpretentious honesty, and an invitation to persist: to fail and fail and try again so you can keep on learning to fail. This is a story (or is it a memoir?) about those exceptional failures that end up becoming successes, and that Arturo González-Campos has treasured in his memory. These are all small personal (yet somehow universal) stories, and bitterly sad anecdotes that will make you laugh out loud. You can find all that and much more in this fucking crazy «artubiography of things.» «This book won’t take you to Ithaca or to Mordor. Just look at your Roomba’s course: that’s what this book is going to be like.»', 'Enhorabuena por tu fracaso / Congratulations On Your Failure', 9.73, 9.23, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.08, 1.12, '9788418141379', '8418141379', 245, 54.03, 4.82, '1954-12-26', 'Se cumplen en 2021 treinta años del fin de la Unión de Repúblicas Socialistas Sovieticas. En el verano 1991, Sara Gutierrez inició en Ucrania un viaje para cruzar el país del mar Báltico al mar Negro. Al no disponer de permiso oficial, lo hizo en trenes nocturnos, apenas controlados por las autoridades sovieticas. Desde Leningrado, que quince días antes había sido renombrada San Petersburgo por sus habitantes, se desplazó a Tallin, Riga, Vilna, Lvov, Kiev y Odesa. Siete ciudades de cinco repúblicas donde las estrellas rojas y los emblemas de la hoz y el martillo comenzaban a convivir con las hamburguesas de McDonalds. Acompañaba a la autora una nativa de Uzbekistán que nunca había viajado sola ni visto el mar. Junto a estampas de la vida cotidiana de los dos últimos años de la urss, flota en el recorrido la tensión de un verano que sería el último de un sueño ilusionante para millones de personas y una pesadilla insoportable para otros tantos. Y para todos, incluidas la autora y su amiga uzbeca, el principio de casi todo.', 'El último verano de la URSS', 8.42, 6.85, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.34, 5.93, '9788418187445', '8418187441', 666, 8.0, 2.06, '1938-11-04', '«El Gran Libro de Satán» es la antología de literatura diabólica más completa que existe en el mundo. Este volumen recoge cincuenta y seis piezas largas y más de cuatrocientos pasajes breves de índole perniciosa: poemas, cuentos, ensayos y extractos de novelas con Satán como figura central o secundario imprescindible. Cada texto seleccionado es de un autor o autora distinto (nadie repite), y de toda clase de perversidad literaria: de Iris Murdoch a Sara Mesa, pasando por Clive Barker, Nathaniel Hawthorne, Sharon Olds, Dante Alighieri, Joan Aiken, Kelly Link, Charles Baudelaire, Irene Solà, Ambrose Bierce, Ursula K. Le Guin, Ana María Matute, John Milton, Samanta Schweblin, Ray Bradbury, Neil Gaiman, Elisa Victoria, Michael Chabon, Belén Gopegui, Mark Twain, Karen Russell, Shirley Jackson, Mijaíl Bulgákov y muchísimos más.', 'El gran libro de Satán', 3.43, 9.17, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.66, 4.48, '9788418227158', '841822715X', 624, 33.82, 1.42, '2015-11-24', 'Partiendo de Alicante y desde Cabo Verde, Cocúa atraviesa el Atlántico hasta Tobago, Trinidad y Venezuela. Cruza el canal de Panamá, y desde Ecuador, recalando en las Galápagos, se interna en el Pacífico hacia las Marquesas, Tahití, Tonga, Fiyi y Nueva Zelanda. De allí, pone rumbo al norte hacia Nueva Guinea y después a Indonesia. Alcanza más tarde el mar de China ­Malasia, Singapur, y luego se dirige por el océano Índico hasta el Mar Rojo. En plena Guerra del Golfo surca aquellas aguas para alcanzar el canal de Suez, que cruza para salir al Mediterráneo y poner rumbo de vuelta a casa. En este libro Cocúa nos sube a bordo de su barco y nos lleva con él a vivir un viaje insólito y extraordinario. Y el amor por el mar.', 'Un paseo por el mundo', 6.95, 5.27, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.66, 9.84, '8418363282', '9788418363283', 0, 83.36, 3.32, '2021-12-07', 'Bestseller del New York Times Ganador del Women''s Prize for Fiction Finalista de World Fantasy Awards Vuelve la autora de Jonathan Strange y el señor Norrell con una novela hipnótica ambientada en una realidad onírica. La casa de Piranesi no es un edificio cualquiera: sus habitaciones son monumentales, con paredes llenas de miles de estatuas, y sus pasillos, interminables. Dentro del dédalo de corredores hay un océano aprisionado en el que las olas retumban y las mareas inundan los aposentos. Pero Piranesi no tiene miedo: comprende las embestidas del mar igual que el patrón del laberinto, mientras explora los límites de su mundo y avanza, con la ayuda de un hombre llamado El Otro, en una investigación científica para alcanzar El Gran Conocimiento Secreto. ENGLISH DESCRIPTION New York Times Bestseller Winner of the Women''s Prize for Fiction World Fantasy Awards Finalist Chosen as a book of the year by the the Times, Guardian, Observer, Daily Telegraph, Financial Times, I Paper, New Statesman, Spectator, Time Magazine, Times Literary Supplement, BBC Culture, Netgalley and the Church Times The spectacular new novel from the bestselling author of Jonathan Strange & Mr Norrell, ‘one of our greatest living authors.’ (New York Magazine) Piranesi lives in the House. Perhaps he always has. In his notebooks, day after day, he makes a clear and careful record of its wonders: the labyrinth of halls, the thousands upon thousands of statues, the tides that thunder up staircases, the clouds that move in slow procession through the upper halls. On Tuesdays and Fridays Piranesi sees his friend, the Other. At other times he brings tributes of food to the Dead. But mostly, he is alone. Messages begin to appear, scratched out in chalk on the pavements. There is someone new in the House. But who are they and what do they want? Are they a friend or do they bring destruction and madness as the Other claims? Lost texts must be found; secrets must be uncovered. The world that Piranesi thought he knew is becoming strange and dangerous. The Beauty of the House is immeasurable; its Kindness infinite.', 'Piranesi. (Spanish Edition)', 5.49, 7.5, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.96, 1.23, '9788418451812', '8418451815', 0, 15.38, 4.73, '1974-09-10', '«De modo que aquí la tienen. Una invitación a la sorpresa, a la admiración. Eso son, entre otras muchas cosas, los cuentos de doña Emilia Pardo Bazán. Si nunca la leyeron antes, les envidio. Están a punto de darse un auténtico festín de auténtica literatura.Damas, caballeros: pasen y lean».Así presenta Care Santos, en el prólogo de esta edición, el volumen que reúne diez cuentos de terror de Doña Emilia. Efectivamente, además de ensayos, libros de viajes, lírica, traducciones, su epistolario y, por supuesto, su más que famosa obra Los pazos de Ulloa, la escritora gallega fue también autora de una larga lista de historias cortas de terror que, como no podía ser de otra forma en alguien con el origen de Emilia Pardo Bazán, recopilan buena parte del imaginario fantástico gallego', 'La cita y otros cuentos de terror', 2.33, 4.84, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.36, 3.54, '9788418504433', '8418504439', 176, 80.64, 1.42, '2016-01-11', 'Entre los delirios suicidas de una madre obsesionada por las vidas de santos y el desinterés silencioso de un padre proctólogo, la protagonista de Sulfuro se obsesiona por conquistar una cierta normalidad: se casa pronto y se divorcia, se vuelve a casar y se muda a un barrio en apariencia tranquilo. Sin embargo, al otro lado de la calle hay un cementerio y cuando la vida de “los otros”, de los muertos, se mezcla con la suya, inicia un viaje sin retorno hacia lo que Lovecraft definió como las montañas de la locura.Relato de miedo y de fantasmas, Sulfuro es, a la vez, una lúcida exploración de la fragilidad mental y una mordaz crítica a los esquemas sociales convencionales y a la perversa hipocresía de las “buenas costumbres”, siempre con la intensidad poética y la imaginación desbordada que singularizan la literatura de Fernanda García Lao, una de las escritoras más originales e irreverentes de la nueva narrativa latinoamericana.«Una devastadora mirada a la familia, a la procreación o el sexo como territorios de los que siempre salimos abollados y confusos».Carlos Zanón, Babelia, El País. «Una puesta en escena delirante en donde campea el hiperrealismo, la paranoia, la subversión histórica, la belleza de lo macabro y, sobre todo, la resignificación de los miedos humanos».J.J. Maldonado, Caretas.', 'Sulfuro :.', 1.38, 3.46, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.05, 8.29, '9788418557682', '8418557680', 0, 16.58, 4.14, '1935-03-21', 'GANADORA A LA MEJOR NOVELA DEL AÑO DE LOS BRITISH FANTASY AWARDS.LA NOVELA DE FANTASÍA MÇS ESPERADA DE LOS ÚLTIMOS AÑOS.Una profunda historia sobre la resistencia, la sororidad y el derecho a voto ambientada en una versión alternativa de la Nueva Inglaterra del siglo XIX.En 1893 ya no hay brujas. En el pasado sí que las había, en esa epoca oscura e inhóspita antes de que empezasen a encenderse las hogueras. Ahora, la brujería es poco más que hechizos de amas de casa y canciones infantiles. Si la mujer moderna quiere algo de poder, las urnas son el único lugar donde puede llegar a conseguirlo.Pero James Juniper, Agnes Amaranth y Beatrice Belladonna, las hermanas Eastwood, se unen a las sufragistas de Nueva Salem y empiezan a buscar las palabras y los componentes olvidadas capaces de convertir la revolución de las mujeres en la revolución de las brujas. Las hermanas se verán acechadas por sombras y todo tipo de males, perseguidas por fuerzas que no tienen intención de permitir que las brujan voten, o que vivan siquiera, y tendrán que indagar en magia antigua, forjar nuevas alianzas y solucionar los problemas entre ellas si quieren sobrevivir.Ya no hay brujas. Pero las habrá."En un mundo en el que las mujer', 'Las brujas del ayer y del mañana', 7.9, 9.47, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.93, 3.15, '9788418668371', '8418668377', 0, 55.63, 2.57, '2022-11-22', 'In the future, the human race has ceased to progress. Granted endless leisure by widespread automation, the masses devote themselves solely to the pleasures of the here and now, to drugs that dull their senses and electronic bliss that disconnects them from reality. Theirs is a world that is without meaning or purpose, without art, children, or reading, and overseeing the bleak persistence of humanity is an intelligent machine whose only wish is to extinguish its own existence. But when two ordinary people begin to fight the system, hope for the human race glimmers in their journey as they attempt to realize the full potential of humanity.', 'Sinsonte', 8.82, 1.28, 132, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.62, 7.5, '9788418800191', '8418800194', 0, 93.08, 2.05, '1980-09-04', 'Un sugerente catálogo de pequeños placeres y momentos maravillosos.En Pasaporte sentimental Arturo San Agustín lleva al lector a las cuatro esquinas del mundo, en una suerte de colección de postales, recuerdos, sensaciones y momentos imperecederos donde lo vivido se confunde con lo leído, y lo leído con lo vivido. De una ciudad a otra, de un recuerdo a otro. Del silencio atronador de la noche africana a Torshaven, cuyo puerto rinde homenaje a Thor, dios del Trueno. O del sillón de Hemingway a la nota reverberante del erhu, instrumento de origen chino.', 'Pasaporte sentimental', 7.46, 9.26, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.26, 5.96, '9788418897528', '841889752X', 0, 32.7, 3.23, '1951-10-19', 'Una novela gráfica que toda madre debería regalar a su hija, ¡y toda hija a su pareja! El cómic feminista sobre la historia cultural de la vulva (dejaos de vaginas) que está cambiando el mundo.#VivaLaVulvaCierta parte de la anatomía femenina ha suscitado a lo largo de la  historia, y sigue suscitando, el interés digamos que «vivo» de ciertos  representantes del género masculino. Pero... los más ilustres próceres no han dado pie con bola en milenios.El fruto prohibido es una historia cultural de la vulva,  desde la Biblia hasta Freud y más allá, pasando por los más variopintos  padres de la Iglesia, pedagogos, sexólogos e incluso por famosos  anuncios de tampones que, tras siglos y siglos de represión sexual, han  seguido llenando nuestras cabezas de concepciones falsas sobre los genitales femeninos.En siete capítulos, de manera desenfadada y lúcida, Liv Strömquist  cuestiona la mirada del patriarcado al órgano sexual de las mujeres y denuncia los problemas que se siguen de ella.El fruto prohibido  sorprende por la justicia y la claridad de su análisis,  por el  interesante manejo de conceptos políticos, científicos y sociológicos,  por la gracia con la que confronta presente y pasado, por sus  paralelismos sorprendentes y, sobre todo, por su humor omnipresente y vitriólico.Críticas:«Liv Strömquist es esa dibujante de las costumbres humanas que jamás irá  con el freno de mano puesto. Con paso decidido y sin ningún tipo de  dilación, es capaz de transformar teorías sociales avanzadas en viñetas  diáfanas que además le dan a la indignación un contrapunto hilarante.»Aftonbladet«Un excelente cómic llegado de Suecia: feminista, cáustico, instructivo y terriblemente divertido.»Time Out Paris«Las partes íntimas de la mujer son un campo de batalla que ha sido  explicado o bien en términos místicos o bien estigmatizándolo y   reduciéndolo al tabú. Señoras y señores, Liv Strömquist ha llegado para cambiarlo.»tip Berlin«El cómic feminista que llama a la vulva por su nombre.»Verne (El País)', 'El fruto prohibido', 4.23, 3.75, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.38, 1.7, '9788418930478', '8418930470', 0, 36.01, 2.02, '2022-11-22', 'With deliberately vague and vivid descriptions, the narrator describes a mid-summer festival in the utopian town of Omelas, whose prosperity depends on one boy''s perpetual misery. Those Who Leave Omelas was nominated for the Locus Award for Best Short Story in 1974 and won the Hugo Award for Best Short Story in the same year.', 'Quienes Se Marchan de Omelas', 5.44, 8.47, 132, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.33, 2.79, '9788871936932', '8871936930', 123, 59.06, 2.96, '2024-07-05', 'Sin descripción disponible', 'Venecia', 8.26, 2.04, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.35, 6.86, '9788419172105', '8419172103', 0, 87.25, 2.85, '1966-10-27', 'Las islas esconden tesoros. Las islas son para desconectar del ruido y encontrarse. En las islas es donde sobrevive lo desconocido. El misterio, el miedo, la aventura, el placer. Debería alarmarnos que muchas estén desapareciendo. Día a día, islas antiguas que han presenciado mil milagros desaparecen por culpa del cambio climático. Sin embargo, el ser humano destruye, pero también crea. Para bien y para mal. Así que aparecen nuevas islas: por ambición territorial, para satisfacer el turismo, por capricho de millonarios y por necesidades científicas.Son muchas. La isla Runit, donde Estados Unidos almacena 73.000 m3 de residuos radiactivos bajo una cúpula amenazada por la subida de las aguas. Seasteading, la utopía financiada por el dueño de PayPal que busca construir viviendas en el mar independientes de cualquier jurisdicción nacional. Las fortalezas marinas en el Támesis, o las cárceles y manicomios cercanos a Venecia. O Funtasy Island, complejo hotelero cercano a Singapur destinado a turistas que buscan entretenimiento natural en un paraíso virgen.Nunca hemos necesitado tanto fantasear con viajar a una isla. Quizá deberíamos saber mucho más sobre su fascinante historia y sus alucinantes presente y futuro.', 'El mapa de las islas', 5.9, 3.84, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.15, 6.86, '9788419207470', '8419207470', 344, 13.77, 4.6, '2022-05-04', '«Un libro que estaba esperando a su autor. Esta Roma desordenada cumple con todas las promesas de felicidad que los viajeros del mundo hemos asociado a las palabras Italia o Roma». IGNACIO PEYRÓ Roma nos permite ser voyeurs de nuestra propia historia. De las tumbas de los etruscos a la mundana Via Veneto, de Nerón a Pasolini, pasando por Caravaggio, Bernini, Borromini y Winckelmann —con escala española en Alberti, Zambrano o Gaya—, este es un libro que se propone juntar de nuevo las piedras de una mampostería eterna para contarlo todo otra vez de la ciudad que lo sabe todo. Una misión enloquecedora, saltando de siglo en siglo, con un ojo puesto en la Roma urbi y otro en la Roma orbe, uno en las reliquias de los santos y otro en los torsos desnudos de las estatuas, uno en la confusión y otro en la calma, en un viaje por la ciudad donde, como en un arca de Noé, se han salvado todas las historias de la historia, y que es la culminante demostración de que el ser humano ha conocido la belleza. Desde una personalísima y poliédrica perspectiva, Juan Claudio de Ramón ofrece, con erudición y la emoción del extranjero que se descubre romano, un mosaico de hechos históricos, anécdotas, curiosidades, gastronomía y calas literarias y artísticas en distintas épocas. Roma desordenada es el apasionado relato del viajero que, felizmente cautivo, se torna habitante de una de las ciudades más conocidas y, sin embargo, por inabarcable, desconocidas del mundo. Y es que «decir que todos los caminos llevan a Roma es menos exacto que decir que de Roma salen todos los caminos».', 'Roma desordenada', 9.63, 7.26, 133, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.82, 1.55, '9788419343048', '8419343048', 0, 86.4, 1.25, '1985-01-05', 'En el seno de una de esas colosales ensenadas que se adentran en la orilla oriental del Hudson, en esa amplia extensión del río denominada por los antiguos navegantes holandeses el Tappan Zee, y donde siempre acortaban prudentemente las velas e imploraban la protección de San Nicolás cuando cruzaban, se encuentran un pequeño pueblo mercante y su puerto, que algunos llaman Greensburgh, pero que se conoce más comúnmente con el nombre de Tarry3 Town. Este nombre fue dado, según se cuenta, en tiempos pasados, por las buenas mujeres del pueblo vecina, por la muy establecida costumbre de sus maridos de frecuentar su taberna los días de mercado. Sea como fuere, no doy fe del hecho, sino que me limito a mencionarlo, en aras de la precisión y la autenticidad.', 'Sleepy Hollow. La leyenda del jinete sin cabeza', 5.3, 6.39, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.04, 9.44, '9788420682471', '8420682470', 0, 64.68, 1.7, '2022-08-15', 'Locke Lamora y Jean Tannen han huido de su hogar y del naufragio de sus vidas. Pero no pueden seguir huyendo para siempre y, cuando se detienen, se deciden por el blanco más rico y difícil en el horizonte: la ciudad de Tal Verrar y la Aguja del Pecado, la casa de juego mejor guardada del mundo. Nadie ha robado allí ni siquiera una moneda y vivido para contarlo. Es la clase de desafío a la que Locke simplemente no puede resistirse.', 'Mares de sangre bajo cielos rojos', 3.5, 6.57, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.69, 2.48, '9788420760087', '8420760080', 276, 76.16, 4.6, '1946-11-12', '', '¡Arrástrate, sombra, arrástrate!', 4.84, 1.75, 4, NOW(), NOW());
