INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.85, 1.58, '9788426116789', '8426116787', 382, 64.01, 2.79, '2002-03-28', '', 'Fatu-Hiva', 2.66, 1.73, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.97, 2.82, '9788426137227', '8426137229', 432, 88.48, 1.65, '2008-11-01', 'Desde Homero, el mar no ha dejado de ser fuente de inspiración. Escritores, poetas, navegantes solitarios, viajeros ocasionales, marinos de altura..., todos han mojado su pluma en tinta de mar. Porque los océanos propician viajes de los que uno nunca regre', 'Tinta de mar', 5.51, 4.66, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.65, 3.16, '9788426145963', '8426145965', 427, 5.04, 2.76, '2009-01-06', 'En 1968 el periódico The Sunday Times de Londres, propuso organizar una regata en solitario y sin escalas alrededor del mundo a un grupo de navegantes entre los que se encontraba Bernard Moitessier. Nunca se había hecho nada parecido. Aquí se inició la insólita historia que se narra en este libro: 37.000 millas marinas para llegar? al corazón de un hombre. Esta nueva edición incluye un inestimable prólogo de Julio Villar, quien compartió escala (y muchas cosas más) con Moitessier en este largo viaje.  El largo viaje es el relato de diez meses navegando en solitario. El periplo significó una vuelta y media al mundo a través del mar, que, «según el viento, según el cielo, según que el ocaso fuera rojo o gris, ruge, murmura o gime bajo el casco». En este libro descubrimos la audacia, calculada y prudente, de un marino fuera de serie que decidió llegar hasta el límite de la resistencia humana y de la de su barco, sobre un mar a veces en calma, y a veces rugiente como una fiera. Se trata de la travesía más larga en solitario: 37.455 millas sin tocar tierra.  Además de ser el relato de una pericia que pocos hombres han asumido en la historia, este libro contiene múltiples consejos, trucos y apreciaciones para aquellos apasionados de la navegación a vela más tradicional, con un apéndice de más de 100 páginas con pautas para la preparación de una navegación sin escalas de este tipo. Esta reedición revisada, contiene además materiales inéditos como múltiples fotos que realizó el autor durante su travesía y diseños realizados por el mismo. Un testimonio de la navegación de altura sin igual.', 'El largo viaje', 6.27, 3.27, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.27, 7.33, '9788427012080', '842701208X', 161, 45.93, 2.77, '1960-11-13', '', 'Software', 2.08, 8.49, 10, NOW(), NOW());
