INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.03, 1.99, '9788427016484', '8427016484', 430, 81.29, 4.54, '1951-02-03', 'Cheradenine Zakalwe, born outside of the Culture, was recruited into it by Special Circumstances and works as an operative secretly intervening in less advanced civilizations.', 'El uso de las armas', 6.88, 4.46, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.27, 6.67, '9788427018679', '8427018673', 191, 75.01, 4.2, '2018-10-24', '', 'El Retorno del Jedi', 4.4, 1.01, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.58, 3.41, '9788427019850', '8427019858', 174, 12.07, 3.29, '1980-01-19', '', 'Conan el Cimmerio', 1.88, 5.82, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.98, 9.96, '9788427049697', '8427049692', 197, 82.72, 1.35, '1971-01-16', 'Madre está harta de que las técnicas ancestrales de la maternidad se estén perdiendo. Pero eso se va a acabar. Ella va a poner orden: ha fundado la Academia de Madres, donde compartirá con otras madres ávidas de sabiduría todos sus conocimientos, desde el legendario lanzamiento de chancla hasta las frasecitas de madre. En su camino la apoyará toda la familia: el distraído Padre, el encauzado Hijo Mayor, el olvidado Hijo Mediano y el mimado Hijo Pequeño. ¡Acompaña a Madre mientras pone un poco de sentido en este mundo de caos!', 'Academia de Madres, el origen', 2.12, 5.86, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.11, 7.59, '9788427050457', '8427050453', 0, 95.19, 3.02, '1941-11-23', 'Perséfone es una de las jóvenes más bellas y populares de la élite de Olimpo. Su sueño y su plan es alejarse del nido de víboras que es la política de Olimpo y huir para siempre. Pero su plan fracasa cuando su madre la sorprende en una fiesta anunciando públicamente su compromiso con Zeus, el peligroso líder de la gran ciudad. Decidida a no conformarse con el destino que se cierne sobre ella, Perséfone se escapa de la fiesta y huye hasta la Infraciudad, donde busca la protección de Hades, con quien consigue hacer un pacto.  Hades ha pasado toda su vida en las sombras y no tiene intención de salir de ellas. Pero cuando Perséfone le ofrece participar en una jugosa y ansiada venganza contra Zeus será excusa suficiente para ayudarla, a cambio de una sola cosa: ella. Pero, tras noches sin aliento junto a Perséfone, Hades será capaz de organizar una guerra con Olimpo para mantenerla a su lado. ', 'Dioses de neón (Serie Dark Olympus 1)', 3.08, 8.96, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.87, 3.63, '9788433998248', '8433998242', 208, 3.53, 1.99, '1957-11-05', 'Una niña desentierra en el jardín unos huesos que resultan no ser de un animal; la bucólica escena veraniega de unas chicas que se bañan en un paraje natural acaba convertida en un infierno de celos de inquietantes consecuencias; un mendigo despreciado siembra la desgracia en un barrio pudiente; Barcelona se transforma en un escenario perturbador, marcado por la culpa y del que es imposible escapar; una presencia fantasmal busca un sacrificio en un balneario; una chica siente una atracción fetichista por los corazones enfermos; un rockero fallecido de un modo atroz recibe un homenaje de sus fans que va más allá de lo imaginable; un chico que filma clandestinamente a parejas haciendo el amor y a mujeres con tacones altos caminando por las calles recibe una propuesta que le cambiará la vida.En los doce soberbios cuentos que componen este volumen Mariana Enriquez despliega todo un repertorio de recursos del relato clásico de terror: apariciones espectrales, brujas, sesiones de espiritismo, grutas, visiones, muertos que vuelven a la vida... Pero, lejos de proponer una mera revisitación arqueológica del género, reelabora ese material con una voz propia y radicalmente moderna. Tirando del hilo de la mejor tradición, la lleva un paso más allá, con historias que indagan en lo siniestro que se agazapa en lo cotidiano.', 'Los peligros de fumar en la cama', 2.87, 8.55, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.16, 9.49, '9788433998859', '8433998854', 0, 58.09, 1.71, '1979-01-06', 'La herencia, el deseo de pervivir, la paternidad, el horror, lo íntimo y lo político. Una novela libre y osada, hechizante y genial. Un padre y un hijo atraviesan Argentina por carretera, desde Buenos Aires hacia las cataratas de Iguazú, en la frontera norte con Brasil. Son los años de la junta militar, hay controles de soldados armados y tensión en el ambiente. El hijo se llama Gaspar y el padre trata de protegerlo del destino que le ha sido asignado. La madre murió en circunstancias poco claras, en un accidente que acaso no lo fue. Como su padre, Gaspar está llamado a ser un médium en una sociedad secreta, la Orden, que contacta con la Oscuridad en busca de la vida eterna mediante atroces rituales. En ellos es vital disponer de un médium, pero el destino de estos seres dotados de poderes especiales es cruel, porque su desgaste físico y mental es rápido e implacable. Los orígenes de la Orden, regida por la poderosa familia de la madre de Gaspar, se remontan a siglos atrás, cuando el conocimiento de la Oscuridad llegó desde el corazón de Africa a Inglaterra y desde allí se extendió hasta Argentina --', 'Nuestra parte de noche', 6.08, 1.81, 134, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.04, 9.3, '9788435022071', '8435022072', 288, 98.34, 1.23, '1996-06-14', 'Al ascender a la estratosfera, Jack Hamilton miro hacia la Tierra, una enorme bola con una pequena masa de materia incasdescente que orbita a su alrededor... B!el Sol! Era acaso el antiguo universo geocentrico en que todos los cuerpos celestes giraban en torno a una Tierra estatica? Pero de pronto descubriria que lo que estaba viendo era un ojo, un ojo gigantesco en el cielo. Hamilton se encontraba atrapado en otro mundo, creado por una mente enferma. Y de este mundo no habia escapatoria posible.', 'Un Ojo en el Cielo', 8.77, 9.14, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.73, 8.77, '9788435024044', '8435024040', 62, 69.92, 2.7, '1942-02-14', '', 'Contra ellas', 6.22, 5.4, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.54, 7.67, '9788435031189', '8435031187', 384, 92.68, 4.5, '2005-01-01', 'George MacDonald Fraser (1925-2008) es autor de numerosos guiones cinematográficos y de varias novelas de tono humorístico, entre las que destaca la serie sobre Harry Flashman (Royal Flash, ¡Tres hurras por Flashman!, Flashman a la conquista de Abisinia...), publicada íntegra en Edhasa.', 'La búsqueda de Tarzán (XIX)', 1.59, 7.84, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.59, 5.41, '9788435095051', '8435095053', 896, 9.7, 1.18, '2008-03-01', 'Donald Dahlquist es un reputado hombre de teatro y cine de Nueva York. Como dramaturgo y director teatral ha participado en diversos festivales nacionales e internacionales, y ha obtenido entre otros premios el Bug & Bub y el premio de dramaturgia Garland en dos ocasiones (por Messalina y Delirium Palace). También sus películas han sido presentadas en importantes festivales de cine independiente (San Francisco, Seattle International, Norwest, etc). Los libros de cristal de los devoradores de sueños fue su estreno como novelista, pero le reportó ya un espectacular éxito de ventas y su obra no tardó en ser traducida a una treintena de lenguas.', 'Los libros de cristal de los devoradores de sueños', 5.95, 4.36, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.3, 3.22, '9788439717805', '8439717806', 73, 84.88, 1.35, '2012-12-04', '', 'Memorias del señor de Schnabelewopski', 9.48, 5.03, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.18, 4.65, '9788440614209', '8440614209', 534, 26.5, 1.46, '2008-11-25', '', 'Ciencia ficción', 7.9, 3.35, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.22, 1.51, '9788440617514', '8440617518', 426, 41.06, 4.74, '1961-07-20', '', 'El Mundo al final del tiempo', 4.33, 9.79, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.71, 2.57, '9788440622884', '8440622880', 253, 92.32, 1.54, '2006-10-09', '', 'El Dragón en el mar', 9.13, 6.83, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.62, 9.59, '9788440656858', '8440656858', 0, 2.44, 1.75, '1938-05-10', '', 'Apolo 13', 7.55, 7.83, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.12, 2.56, '9788445000250', '844500025X', 368, 71.04, 3.99, '2012-04-10', '2019. La humanidad es testigo del mayor descubrimiento científi co hasta la fecha: la cura para el envejecimiento. Tras un intenso debate político y moral, el gobierno decide poner la Cura al alcance de todo el mundo. La ansiada inmortalidad, sin embargo, también tiene sus pegas: el fin del matrimonio, programas gubernamentales de eutanasia, fanáticos pro-muerte, un nuevo e inquietante culto religioso y otras calamidades serán sólo el principio del fin.', 'Eterna juventud', 9.28, 3.08, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.5, 7.69, '9788445003107', '8445003100', 352, 55.94, 2.67, '2001-10-08', 'Continúa la serie que explica los orígenes de Warhammer 40000En esta serie se relatan hechos que suceden 10000 años antes que los referidos en las novelas de Warhammer 40000. Por este motivo se trata de una serie imprescindible para los aficionados que quieran conocer el origen de episodios y personajes de otras novelas.', 'La herejía de Horus 2. Falsos dioses : las raíces de la herejía', 6.74, 2.04, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.85, 4.11, '9788445005910', '844500591X', 288, 17.38, 4.71, '1964-03-24', 'El libro que inspiró la película de Netflix BIRD BOX.NO ABRAS LOS OJOS. Hay algo ahí fuera. Algo espantoso, que hace que la gente enloquezca y se suicide ante su sola visión. Nadie sabe qué es ni de dónde viene.Cinco años después de que diera comienzo la pesadilla, los pocos supervivientes que quedan viven refugiados en el interior de casas y edificios, protegidos por puertas cerradas y ventanas con las cortinas echadas. Malorie, que ha conseguido sobrevivir en una casa abandonada junto a sus dos hijos, decide abandonar la seguridad de su refugio para emprender un viaje por el río hacia un lugar mejor. En esta peligrosa odisea a ciegas, Malorie sólo podrá confiar en su instinto y en el entrenado oído de los niños, que no tardarán en descubrir que algo los sigue. Pero, ¿qué es? Inmersa en la oscuridad, rodeada de sonidos, familiares unos, estremecedores otros, Malorie se embarca en una tremenda odisea; un viaje que le llevará a un mundo sin visión y de vuelta a su pasado. En un mundo que ha enloquecido, ¿se puede confiar en alguien?Netflix se ha basado en esta historia para su nueva películaBird Box, protagonizada por Sarah Paulson y Sandra Bullock.(estreno 21/12/2018).', 'A ciegas', 4.22, 6.58, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.41, 4.85, '9788445006030', '8445006037', 688, 47.77, 3.6, '2023-09-27', 'La oscuridad ha proyectado sus sombras, ¿aprovechará otro Londres para resurgir? La respuesta en la tercera y última entrega de la trilogía Sombras de Magia.El conflicto está servido en los distintos Londres. Las fuerzas de Kell, quien creyó ser el último Antari vivo, comienzan a flaquear bajo la presión de sus rivales. Frente a la tragedia, ¿podrá sobrevivir Arnes? ¿Quién se alzará? Lila Bard, quien fue una ladrona común, ha sobrevivido y se ha vuelto cada vez más fuerte al atravesar una serie de combates mágicos.Pero ahora deberá aprender a controlar la magia, antes de que esta pueda consumirla. Mientras tanto, el desprestigiado capitán del Aguja Nocturna, Alucard Emery, reúne a su tripulación y juntos emprenden una carrera contra el tiempo para conseguir lo imposible. ¿Quién tomará el control? Además, un viejo enemigo regresa a reclamar la corona, mientras un héroe caído intenta salvar a un mundo de la descomposición.', 'Conjuro de luz', 5.59, 9.51, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.72, 9.16, '9788445006467', '8445006460', 64, 18.19, 2.59, '1964-04-16', 'Con esta novela, Lovecraft escribe en los años 20 del pasado siglo una de las historias más famosas de la literatura fantástica americana. Cthulhu, el Gran Antiguo que sueña y espera en el fondo de los negros abismos oceánicos, se convertirá por sí solo en el símbolo de todo el universo que crea el autor de Providence', 'La llamada de Cthulhu', 1.85, 6.84, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.42, 2.82, '9788445006498', '8445006495', 304, 77.67, 3.65, '1985-02-15', 'Nueva edición de Los Hijos de Húrin, con nueva cubierta siguiendo la estética de colección de las ediciones de Beren y Lúthien y La Caída de Gondolin, publicadas recientemente.Los hijos de Húrines uno de los grandes relatos que fundamentan la historia de la Tierra Media y se sitúa en la Primera Edad, cuando elfos, hombres y enanos llevaban unos pocos siglos sobre la tierra. Junto con las historia de Beren y Lúthien, es la historia más mencionada enEl Señor de los Anillos y enEl Silmarillioncomo referente del heroísmo y la tragedia en la lucha contra el Mal, en la Primera Edad encarnado en la figura de Morgoth. Una historia trágica de amores imposibles, pasiones incomprendidas y guerras sin cuartel entre el Bien y el Mal. Con hombres, elfos, enanos, orcos y dragones.', 'Narn i Chîn Húrin', 3.35, 7.32, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.16, 6.5, '9788445007020', '8445007025', 682, 43.0, 2.93, '1995-10-25', 'Rand, acosado por inquietantes sueños sobre una espada de cristal, decide abandonar a sus compañeros tras un ataque de Engendros de la Sombra y se encamina hacia Tear para descubrir quién es realmente. Mientras tanto, las tres jóvenes aspirantes a Aes Sedai viajan con Mat hacia Tar Valon para ingresar como novicias en la Torre Blanca, donde esperan que las hermanas sanen a Mat de la extraña enfermedad que padece. Poco después la Amyrlin les encomienda una peligrosa misión.Por su calidad literaria, su ambicioso planteamiento y su descomunal historia, La Rueda del Tiempo es la saga de fantasía más importante de los últimos treinta años. El lector que inicie el camino junto a Rand, Mat y Perrin no podrá abandonar el viaje hasta su incierto y sorprendente final..', 'La rueda del tiempo 3', 4.02, 8.14, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.03, 5.37, '9788445007051', '844500705X', 1084, 50.73, 4.8, '1962-07-14', 'Rand se esfuerza por unir a las naciones para combatir al Oscuro al tiempo que se ve obligado a sortear las trampas que los Renegados tienden a la desprevenida raza humana. Pero además tiene que enfrentarse a los Hijos de la Luz, cuyo capitán general se propone desprestigiarlo para dirigir él mismo la batalla contra la Sombra y sus huestes. Por su parte, las Aes Sedai, tanto las que siguen fieles a la Torre Blanca como las rebeldes, buscan a Rand para ofrecerle su apoyo, aunque éste sospecha que su verdadera intención es usarlo para sus propios fines. Por su calidad literaria, su ambicioso planteamiento y su descomunal historia, La Rueda del Tiempo es la saga de fantasía más importante de los últimos treinta años. El lector que inicie el camino junto a Rand, Mat y Perrin no podrá abandonar el viaje hasta su incierto y sorprendente final. Amazon prepara su adaptación como serie de TV.', 'El Señor del Caos', 6.32, 7.23, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.62, 1.17, '9788445007068', '8445007068', 761, 92.07, 1.03, '1991-10-16', 'Elayne, Nynaeve y Aviendha prosiguen con sus investigaciones en Ebou Dar para encontrar el ter''angreal con el que podrían frenar la espantosa ola de calor que azota el mundo. Para ello se reúnen con los Marinos, quienes dan el nombre de Cuenco de los Vientos al objeto. Egwene continúa con su lucha para ser la Sede Amyrlin escogida por las Aes Sedai rebeldes, y acabar con el control que sobre ella ejercen las Asentadas y otros grupos de hermanas.Entre tanto, en los distintos reinos, nobles y dirigentes continúan buscando su propio beneficio, sin tener presente que la mano del Oscuro está tocando el mundo y que la Última Batalla se acerca', 'La corona de espadas', 8.82, 2.61, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.41, 5.34, '9788445007075', '8445007076', 599, 5.64, 1.82, '1940-05-10', 'Sigue la saga de fantasía épica de Robert Jordan, LA RUEDA DEL TIEMPO.Mientras Elayne y Nynaeve, con la ayuda de Detectoras de Vientos y las Allegadas, ponen en funcionamiento el Cuenco de los Vientos, Perrin se encuentra en Ghealdran para conseguir que la reina Alliandre respalde públicamente al Dragón Renacido.Rand continúa en Illian, intentando pacificar el paós, cuando recibe la noticia de que los Shaido están esperando el caos provocado por los Juramentados del Dragón. El tan deseado cambio climático, propiciado por el Cuenco de los Vientos, provoca bruscos cambios de temperatura que dificultan el desplazamiento de tropas.Por ello Rand decide hacer frente a los seanchan en las costas de Illian, con el fin de frenar el avance del ejército invasor. Pero Rand no tendrá que luchar únicamente contra el enemigo.', 'El camino de dagas', 9.6, 4.21, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.35, 9.21, '9788445007082', '8445007084', 635, 35.03, 4.41, '2003-04-21', 'Tras el ataque en el Palacio del Sol, Rand viaja con Min dejando pistas falsas a sus enemigos. En Cairhien, Cadsuane continúa preparando la estrategia para la Última Batalla.Perrin organiza el rescate de Faile, que está prisionera del septiar de Sevanna, y en Tar Valon se suceden las intrigas de la Torre Blanca. Los seanchan han conquistado Ebou Dar y Mat se encuentra atrapado allí, junto a sus compañeros. Rand se dirige a Far Madding, la ciudad donde el Poder no surte efecto. Allí espera enfrentarse a los Asha''man renegados, condición que considera necesaria para limpiar el Saidin de la infección del Oscuro.', 'El corazón del invierno', 4.65, 5.88, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.55, 3.81, '9788445007099', '8445007092', 684, 5.25, 1.17, '1966-04-03', 'Décima entrega de la mítica saga de Fantasía, La Rueda del Tiempo de Robert Jordan.Mat Cauthon huye con la hija de las Nueve Lunas mientras la Sombra y el imperio seanchan emprenden una persecución implacable. La heredera del Trono de Andor, rodeada de enemigos que planean su destrucción, puede caer en manos de la Sombra y arrastrar consigo al Dragón Renacido, y Egwene al’Vere pone sitio al centro de poder Aes Sedai, pero ha de vencer con rapidez para evitar que los Asha’man sean los únicos capaces de defender el mundo del Oscuro.Tras limpiar la mitad masculina de la Fuente Verdadera, Rand Al’Thor se ve obligado a correr grandes riesgos sin saber con certeza quienes son sus aliados y quienes sus enemigos.', 'La rueda del tiempo', 6.03, 4.91, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.66, 1.63, '9788445007129', '8445007122', 942, 65.6, 2.82, '1959-05-13', 'Penúltima entrega de la saga fantástica.La Última Batalla ha comenzado. Los Capas Blancas, un asesino de lobos y las responsabilidades del liderazgo acosan a Perrin Aybara. Debe buscar respuestas en el Tel’aran’rhiod a fin de superar estos obstáculos, controlar al lobo que lleva dentro y no perder para siempre su condición humana.Entre tanto, Matrim Cauthon se dispone a afrontar el reto más difícil de su vida: los seres del otro lado de los marcos de piedra, los alfi nios y los elfi nios. La Torre de Ghenjei espera y sus secretos revelarán el destino de una persona amiga que lleva perdida mucho tiempo. Dovie’andi se tovya sagain. Es hora de lanzar los dados.', 'Torres de medianoche', 6.7, 9.83, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.88, 4.21, '9788445007839', '8445007831', 0, 87.53, 2.15, '1973-09-02', 'Una cinematográfica y animal aventura.En 1953, Ray Bradbury, entonces un escritor relativamente poco conocido, fue llamado a Irlanda para escribir el guión de Moby Dick, una película del ya famoso director John Huston. Bradbury permaneció siete meses en Irlanda y de esta experiencia nacieron algunos cuentos notables como «La carrera del himno» y «El mendigo del puente O''Connell».EnSombras verdes, ballena blanca Bradbury mezcla estos y otros episodios en un gran cuadro y cuenta vívidamente toda la historia: las aventuras del joven asombrado (en parte Bradbury mismo) que enfrenta al extraordinario director, lucha con la bestia mítica, y—con la ayuda entusiasta de los parroquianos de la taberna de Finn—llega a conocer los misteriosos secretos de los irlandeses.', 'Sombras verdes, ballena blanca', 2.32, 4.55, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.48, 3.68, '9788445008263', '8445008269', 398, 91.99, 1.6, '2000-05-12', 'La novela oficial de uno de los mejores videojuegos del mundo (Ubisoft).El Maestro Assassin Ezio Auditore se embarca en un viaje para encontrar la biblioteca perdida de Altaïr, que tal vez tenga la clave para acabar con los Templarios. Sin esperarlo, descubre que la biblioteca también contiene un secreto que pueda ayudar a los Templarios a hacerse con el control del destino de la humanidad.Para acceder a la biblioteca se precisan cinco llaves que Ezio deberá encontrar en Constantinopla, donde los Templarios suponen una gran amenaza para el imperio otomano. Ezio deberá seguir los pasos de su predecesor, Altaïr, y derrotar por fin a los Templarios.  ', 'Revelations', 9.77, 1.57, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.15, 4.84, '9788445008393', '8445008390', 0, 14.65, 3.51, '1982-01-08', 'Una fantástica novela Warhammer.Tras un largo y arduo conflicto, los traidores al fin se aproximan a Terra. Sin embargo, pronto perderán la oportunidad para atacar: tanto Guilliman como el León regresan a toda prisa, y sus ejércitos podrían girar las tornas de la batalla. Las tropas del Señor de la guerra deben reunirse, pues solo entonces podrán asaltar el mundo del Trono.Mientras Mortarion se adelanta para actuar como la vanguardia de la flota, recae sobre Lorgar y Perturabo la tarea de reunir a Fulgrim y a Angron, quienes ya han sido enaltecidos como demonios y tal vez se encuentren más allá del alcance de la voluntad del Señor de la guerra. No obstante, Horus está malherido, y, mientras la batalla más grande de la galaxia se cierne sobre Terra, es Maloghurst quien debe asegurarse de que su fracturada Legión se mantenga unida y de rescatar al propio Horus del borde del abismo.', 'The Horus Heresy no 51/54 Esclavos de la oscuridad', 8.27, 9.67, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.02, 6.5, '9788445009307', '8445009303', 462, 49.49, 3.21, '1951-05-03', 'Shevek, un físico brillante, originario de Antares, un planeta aislado y «anarquista», decide emprender un insólito viaje al planeta madre Urras, en el que impera un extraño sistema llamado el «propietariado». Shevek cree por encima de todo que los muros del odio, la desconfianza y las ideologías, que separan su planeta del resto del universo civilizado, deben ser derribados. En este contexto la autora explora algunos de los problemas de nuestro tiempo: la posición de la mujer en la estructura social, la complejidad de las relaciones humanas, los méritos y las promesas de las ideologías, y las perspectivas del idealismo político en el mundo actual.', 'Los desposeídos', 9.77, 2.36, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.24, 1.52, '9788445009772', '844500977X', 0, 29.52, 2.44, '1947-03-07', 'La terrícola Sutty vive de forma solitaria en Dovza, la capital del planeta Aka. El planeta vive bajo el férreo control de un gobierno capitalista, la Corporación, que insiste en convertir a todos los ciudadanos en puros productores-consumidores. Para ello procede a destruir sistemáticamente todo vestigio de cualquiera de las formas tradicionales de vida. Aunque el mundo ficticio de El relato y sus peculiares costumbres no tienen relación alguna con la China antigua o moderna, tanto esa sociedad como la «Tierra futura» de la que proviene su heroína, reflejan ciertas tendencias y pasiones políticas y religiosas de nuestra propia Tierra en el cambio de milenio. Los gobiernos totalitarios y las religiones fundamentalistas operan con el mismo objetivo, reemplazando la búsqueda de la verdad por una respuesta incuestionable y castigando a los que cuestionan. El Futuro, en la ficción, no suele ser más que un modo de mirar el Presente.', 'El relato', 1.34, 4.41, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.92, 5.58, '9788445009819', '8445009818', 349, 6.78, 2.97, '1977-11-08', 'After receiving a frantic letter from her newly-wed cousin begging for someone to save her from a mysterious doom, Noemi Taboada heads to High Place, a distant house in the Mexican countryside. She''s not sure what she will find--her cousin''s husband, a handsome Englishman, is a stranger, and Noemi knows little about the region. Noemi is also an unlikely rescuer: She''s a glamorous debutante, and her chic gowns and perfect red lipstick are more suited for cocktail parties than amateur sleuthing. But she''s also tough and smart, with an indomitable will, and she is not afraid: Not of her cousin''s new husband, who is both menacing and alluring; not of his father, the ancient patriarch who seems to be fascinated by Noemi; and not even of the house itself, which begins to invade Noemi''s dreams with visions of blood and doom. Her only ally in this inhospitable abode is the family''s youngest son. Shy and gentle, he seems to want to help Noemi, but might also be hiding dark knowledge of his family''s past. For there are many secrets behind the walls of High Place. The family''s once colossal wealth and faded mining empire kept them from prying eyes, but as Noemi digs deeper she unearths stories of violence and madness.', 'Gótico', 4.3, 8.32, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.6, 4.91, '9788445009833', '8445009834', 575, 25.18, 1.46, '1955-12-15', 'Una extraordinaria visión de cómo será el cambio climático.El Ministerio del Futuroes una obra maestra de la imaginación. Narra a través de testimonios ficticios cómo nos afectará a todos el cambio climático. Su visión no es la de un mundo desolado y apocalíptico, sino la de un futuro que ya se nos echa encima…y cuyos desafíos tal vez consigamos superar por los pelos.Es una novela actual e impactante, descorazonadora y esperanzadora a partes iguales, y es uno de los libros más poderosos y originales que jamás se hayan escrito sobre el cambio climático.Creado en el año 2025, el objetivo del nuevo organismo era sencillo: Defender a las futuras generaciones de la humanidad y proteger a todos los seres vivos, del presente y del futuro. Enseguida empezó a ser conocido como el Ministerio del Futuro, y esta es su historia.Narrada enteramente a través de los testimonios de testigos directos ficticios,El Ministerio del Futuro es una obra maestra de la imaginación, el relato de cómo el cambio climático nos afectará a todos a lo largo de las próximas décadas.Uno de los libros favoritos de Barack Obama.', 'El Ministerio del Futuro', 4.84, 5.92, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.22, 3.8, '9788445010020', '8445010026', 452, 4.72, 1.91, '1939-06-09', 'La novela más política de Ursula K. Le Guin.Shevek, un físico brillante, originario de Anarres, un planeta aislado y «anarquista», decide emprender un insólito viaje al planeta madre Urras, en el que impera un extraño sistema llamado el «propietariado». Shevek cree por encima de todo que los muros del odio, la desconfianza y las ideologías, que separan su planeta del resto del universo civilizado, deben ser derribados.En este contexto la autora explora algunos de los problemas de nuestro tiempo: la posición de la mujer en la estructura social, la complejidad de las relaciones humanas, los méritos y las promesas de las ideologías, las perspectivas del idealismo político en el mundo actual.', 'Los desposeídos', 8.38, 9.91, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.63, 5.71, '9788445011072', '8445011073', 0, 47.35, 1.23, '1994-01-10', 'La extraña y exótica Menzoberranzan, la gran ciudad de la Antípoda Oscura, fundada hace milenios por los elfos oscuros tras su marcha del mundo exterior, es la morada del héroe de "El valle del viento helado", Drizzt Do''Urden. Drizzt, el joven príncipe de una de las casas regentes, llega a la madurez en el mundo cruel y despiadado de su raza, donde el único rayo de esperanza es su maestro de armas, Zaknafein, quien le enseña cómo -y para qué- usar una espada. Dotado de un honor incomprensible para la sociedad sin principios que lo rodea, atenta únicamente a satisfacer los viles caprichos de la reina Araña, el joven Drizzt se enfrenta a un dilema inevitable: ¿podrá vivir en un mundo que rechaza la integridad?', 'Elfo Oscuro no 01/03 La morada', 9.06, 2.87, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.33, 2.13, '9788445011102', '8445011103', 0, 29.13, 1.62, '1967-08-27', 'Ahora todo el mundo sabe que los esbirros draconianos de Takhisis, la Reina de la Oscuridad, han vuelto. Todas las naciones se disponen a defender sus hogares, sus vidas y su libertad. Pero las razas llevan largo tiempo divididas por el odio y los prejuicios. Los guerreros elfos luchan contra los caballeros humanos. La guerra parece perdida antes de comenzar. Los compañeros se ven separados por el con?icto, viviendo distintas aventuras. Pasará una estación completa antes de que vuelvan a reunirse, si es que lo consiguen. Bajo el pálido sol invernal, un caballero caído en desgracia, una doncella elfa mimada y un kender algo chi?ado ven cómo se acercan las tinieblas. Nadie diría que son unos héroes. Y ellos, menos que nadie.', 'Crónicas de la Dragonlance no 02/03 La tumba de Huma', 3.67, 6.27, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.12, 6.75, '9788445011164', '8445011162', 0, 15.75, 3.97, '1949-06-12', 'La guerra contra los dragones siervos de la Reina de la Oscuridad sigue su curso. Armados con los misteriosos y mágicos Orbes de los Dragones y con la resplandeciente Dragonlance, los compañeros se convierten en la esperanza del mundo. Por ahora, cuando amanece un nuevo día, los oscuros secretos que han ensombrecido los corazones de este grupo de amigos salen a la luz. La traición, el engaño y la debilidad estarán a punto de destruir todo lo que ya han conseguido. Les queda por librar la más grande de las batallas: cada uno contra sí mismo. Y al final, serán héroes.', 'Crónicas de la Dragonlance no 03/03 La Reina de la Oscuridad', 6.66, 6.09, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.92, 5.4, '9788445011751', '8445011758', 0, 87.81, 3.57, '1970-01-15', 'Decidido a librarse de la runa de Matafuegos que lleva enterrada en el pecho, Gotrek Gurnisson, el más extraordinario matador que haya existido jamás, se adentra en el extraño y alquímico reino de Chamon. Los señores kharadron de Barak-Urbaz le ofrecen la oportunidad de poner fin a su búsqueda mediante su misteriosa aeterciencia. Pero cuando la Luna Mala sale y el letal Gloomspite Gitz amenaza con destruir el puerto aéreo, Gotrek se enfrenta con el enemigo más antiguo de su pueblo, los pieles verdes. Mientras su compañero de viaje, el elfo Maleneth Hojabruja, supera toda clase de dificultades para mantenerlo vivo, Gotrek se lanza de cabeza a una sangrienta batalla por la supervivencia que lo enviará al corazón húmedo, tenebroso y fungoso del manicomio de Skragrott.', 'Gitslayer', 7.22, 1.15, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.32, 4.98, '9788445012215', '8445012215', 350, 11.48, 1.37, '1955-12-19', 'Se dice que fue Briamor Candess quien, ayudado por otros cuatro hechiceros, construyó la altiva e impresionante torre ciudadela destinada a albergar a toda la comunidad de hechiceros que hasta entonces existían repartidos por el mundo, y que se llamó La Luz del Oeste. Durante muchísimo tiempo fue un lugar al que el mundo miraba con ojos admirados y asustados, pues era hipocentro de un poder desatado. Mas el poder está siempre en los ojos de aquellos que codician, y La Luz del Oeste no iba a ser una excepción. Hechicero cuenta la parábola de Ellör Litos Ceoril, uno de los Cinco Fundadores, desde los primeros días de gloria hasta que se vio obligado a vivir en el exilio, oculto y apartado, y... lo que pasó después. Hechicero rebosa magia y recoge el testimonio del auge y caída de la Luz del Oeste tal y como ocurrió.Como Nigromante, contará con cubierta e ilustraciones interiores a todo color del prestigioso ilustrador Tomás Hijo. ', 'Hechicero', 4.53, 2.27, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.36, 9.24, '9788445012222', '8445012223', 0, 61.7, 4.6, '1954-06-15', 'Han pasado más de diez años desde que Ged se enfrentara a su propia sombra en Un mago de Terramar. Capaz ahora de actuar en beneficio de otros, decide recobrar la runa de la unión, la mitad perdida del anillo de Erreth-Akbe, guardado, se cuenta, en las Tumbas de Atuan. La sacerdotisa de las Tumbas es Arha, que lleva el significativo apodo de la Devorada, y que no tiene identidad, pues la ha perdido para ponerse al servicio de los Sin Nombre, las potestades tenebrosas de Terramar.', 'Las tumbas de Atuan', 5.02, 8.35, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.17, 9.87, '9788445070178', '8445070177', 174, 59.07, 3.38, '2015-04-07', '', 'Las ciudades invisibles', 8.31, 2.95, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.28, 6.28, '9788445071113', '8445071114', 334, 99.66, 4.61, '1954-03-07', 'En el universo alucinatorio del ciberespacio, a la vez lírico y mecánico, erótico y violento, la vida de la joven Mona se cruza inevitablemente con la vida de la famosa Angie Mitchell, que ha sido capaz desde niña de entrar en el ciberespacio sin necesidad de una computadora. Dentro de la matriz, una entidad fantasmal que ha acumulado información para obtener lo que quiere, pretende utilizar a Angie en una trama que ella misma no puede controlar, ni siquiera entender. Mientras tanto, detrás de todo, se mueve la sombría Yakuza, la despiadada y poderosa mafia internacional japonesa que manipula gentes y acontecimientos. Encuadernación: Tapa dura con sobrecubierta.', 'Mona Lisa acelerada', 4.24, 3.91, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.07, 9.99, '9788445071465', '8445071467', 255, 32.88, 5.0, '1989-12-01', '', 'Cuentos Inconclusos', 6.02, 5.67, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.19, 2.19, '9788445072288', '8445072285', 96, 28.87, 2.82, '1994-10-01', 'Una selección de las cartas ilustradas que Tolkien escribía a sus hijos cada año como Papá Noel.Todos los niños saben lo ocupado que está papá Noel en diciembre pero,¿qué hace el resto del año?. Esta colección de cartas y dibujos para niños revela algunos de estos secretos: las aventuras del travieso oso Polar, los elfos que lo ayudan a preparar los regalos, y las batallas con los fastidiosos duendes son un ejemplo.Edición en miniatura con ilustraciones en color de J.R.R. Tolkien.', 'Cartas de Papa Noel', 7.47, 9.68, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.23, 8.94, '9788445073803', '844507380X', 288, 85.22, 4.39, '1962-02-03', 'Un gran clásico moderno y el preludio a las vastas y poderosas mitologías de El Señor de Los Anillos. Cuando alrededor de 1930, J.R.R. Tolkien comenzó a escribir El Hobbit, hacía ya diez años que trabajaba en el vasto panorama mitológico de El Libro de los Relatos, que más tarde se llamaría El Silmarillion. Así como esas crónicas tempranas narraban los mitos inmemoriales de la Primera y Segunda Edad, Tolkien pronto advirtió que El Hobbit iba ordenándose de algún modo como un relato de la Tercera Edad (Gandalf habla del Nigromante en las primeras páginas), aunque las inesperadas aventuras de un pacífico "hombre del campo" no parecieran tener mucha relación con las vastas y oscuras mitologías de la Tierra Media. El estilo directo y lineal, con alusiones (que el autor deploró más tarde) a un público infantil, no impide la poderosa irrupción --unas pocas veces en términos de comedia-- de los grandes temas tolkienianos (el poder, la codicia, la guerra, la muerte) que reaparecerían en una dimensión a menudo obviamente épica en El Señor de los Anillos.', 'El Hobbit', 2.17, 9.55, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.7, 8.85, '9788445073810', '8445073818', 416, 49.2, 4.75, '2002-06-27', 'El Silmarillion es el cuerpo central de los textos narrativos de J.R.R. Tolkien, una obra que no pudo publicar en vida porque creció unto con él. Tolkien comenzó a escribirlo mucho antes que El Hobbit, obra concebida como historia independiente, pero que fue parte de lo que él llamaba un "tema que copia y se ramifica", y del que emergió El Señor de los Anillos. El Silmarillion cuenta la historia de la Primera Edad, el antiguo drama del que hablan los personajes de El Señor de los Anillos, y en cuyos acontecimientos algunos de ellos tomaron parte, como Elrond y Galadriel. Los tres Silmarils eran gemas creadas por Fëanor, el más dotado de los Elfos, y contenían la Luz de los Dos Árboles de Valinor antes que los Árboles mismos fueran destruidos por Morgoth, el primer Señor Oscuro. Desde entonces la inmaculada Luz de Valinor vivió sólo en los Silmarils, pero Morgoth se apoderó de ellos, y los engarzó en su corona, guardada en la fortaleza impenetrable de Angband en el norte de la Tierra Media. En este volumen se incluyen otras obras cortas, como el Ainulindalë o la Música de los Ainur, la creación mítica del mundo, y el Valaquenta, sobre la naturaleza y poderes de los dioses. A El Silmarillion sigue el Akallabeth, que vuelve a narrar la caída del reino de Númenor al fin de la Segunda Edad, y por último la historia De los Anillos del Poder, en la que el tema de El Señor de los Anillos reaparece en la perspectiva más amplia de El Silmarillion. El Silmarillion no es una novela, ni un cuento de hadas, ni una historia ficticia. Podría definirse como una obra de imaginación inspirada, una visión sombría, legendaria o mítica, del interminable conflicto entre el deseo de poder y la capacidad de crear.', 'El Silmarillion', 7.87, 4.62, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.08, 5.73, '9788445073865', '8445073869', 349, 67.51, 2.05, '1968-04-13', 'Los temas más celebrados de Ray Bradbury reaparecen en esta colección con una renovada vitalidad: el tiempo ambiguo, ilusorio, intimidante; los automóviles, a veces destinados a complacer instintos destructivos; las máquinas, respuestas a las esperanzas y necesidades del hombre y también inesperadas y graves amenazas.', 'Fantasmas de lo nuevo', 6.25, 5.54, 135, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.9, 7.61, '9788445074220', '8445074229', 262, 91.16, 1.29, '2002-12-17', 'Lone, un retrasado mental que tiene poderes mentales conoce a Janie,una chica con poderes telekinéticos. Los vecinos de Lone mueren y él decide adoptar el bebé de éstos, que tiene mente de genio. Todos estos personajes junto a dos gemelas, con poderes para teletransportarse, formarán un peucliar grupo que uniendo sus poderes formarán nuevas conciencias colectivas llamadas Gestalt.', 'Más que humano', 5.16, 8.57, 135, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.19, 1.25, '9788445076859', '844507685X', 832, 24.08, 2.16, '1935-11-18', 'Ursula K. Le Guin es uno de los más notables exponentes de la llamada ciencia ficción especulativa o de ideas, en la que, mediante el vehículo tradicional de la utopía y el análisis de aspectos inusuales de sociedades alienígenas, reflexiona sobre nuestra propia cultura. En sus obras, que habitualmente se han calificado de antropología ficción y donde se da gran importancia a aspectos sociológicos, se desarrollan temas como el feminismo, la ecología o la anarquía. La mano izquierda de la oscuridad es un análisis acerca de nuestra identidad sexual y nuestros tabús, mediante la presentación de la raza nativa de Invierno, una sociedad alienígena que alterna su sexualidad de forma periódica. En El nombre del mundo es Bosque una colonia humana instalada en el planeta Nueva Tahití utiliza a los habitantes nativos para explotar los recursos naturales, hasta que éstos se rebelan. En Los desposeídos el científico Shevek, originario de Anarres, un planeta aislado y anarquista, emprende un insólito viaje al planeta madre Urras, con el objetivo de derribar los muros del odio, la desconfianza y las ideologías que separan ambas sociedades.', 'Los mundos de Ursula K. Le Guin', 2.51, 8.27, 135, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.48, 2.61, '9788445077139', '8445077139', 224, 25.59, 3.39, '1937-01-19', 'Mares, pantanos y lagunas cubren la mayor parte de la Tierra. El aumento de la temperatura ha propiciado un clima tropical, de manera que la flora y la fauna proliferan de forma extraordinaria y el mundo parece volver al Triásico. Los pocos humanos deben desplazarse en embarcaciones y sobrevivir con los escasos restos de la civilización que pueden encontrar en los pisos más altos de los rascacielos ahora sumergidos. Viven continuamente amenazados por animales, insectos y enfermedades, que ahora son difíciles de combatir. En este mundo, Kerans intenta sobrevivir, aunque en muchas veces parece más el aliado que el enemigo de una naturaleza que intenta eliminar al hombre. Sin embargo, más allá de la aventura, el desarrollo psicológico de los personajes encuentra su reflejo en imágenes maravillosas y sorprendentes, pues la lucha se plantea también dentro de cada persona y entre ellas porque el infortunio común no es obstáculo para seguir con envidias, rivalidades y egoísmos.', 'El mundo sumergido', 1.97, 1.28, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.03, 4.3, '9788445077603', '8445077600', 352, 49.55, 2.17, '2013-07-25', 'Diez años después de que el Rey y la Reina fueran asesinados y el trono fuera usurpado por Lucien y sus tropas rebeldes, Malonia ha quedado destrozada por la guerra. El pueblo cree que el príncipe se exilió a una tierra muy lejana y que una profecía lo mantiene a salvo de cualquiera que intente atentar contra su vida. Sin embargo, sus otros súbditos no pueden dejar de preguntarse si el príncipe sobrevive aún. Un país al borde de una revolución aguarda en silencio su regreso. Leo es un aprendiz de soldado con poderes ocultos. Una noche encuentra un misterioso libro abandonado sobre la nieve, del que emana un extraño aura. Pronto, las páginas comienzan a completarse con relatos sobre Anna y Ryan de Inglaterra - un país sacado de un cuento de hadas para las gentes de Malonia. Cuando la tragedia se desate, Leo intentará salvarse a si mismo de las páginas del libro.', 'Los ojos de un rey', 5.27, 6.34, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.94, 3.5, '9788445907474', '8445907476', 400, 42.45, 2.44, '2002-12-19', '', 'Drácula', 3.51, 7.49, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.45, 3.14, '844800048X', '9788448000486', 322, 56.63, 5.0, '2012-02-14', 'Mientras Nicci pone en funcionamiento la caja del Destino y designa a Richard como jugador, éste por fin encuentra a Kahlan. Pero la Confesora no tiene ni idea de quién es él y, además, ambos están cautivos de la Orden Imperial y tienen pocas posibilidades de escapar. Por si esto fuera poco, un descubrimiento inesperado llevado a cabo por Jagang podría dar al traste con todo y precipitar el fin de la guerra a su favor. Todo parece confabularse contra Richard y su lucha por liberar al mundo del yugo de la Orden.', 'El año de la purificación', 8.27, 3.02, 136, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.96, 3.37, '8448008421', '9788448008420', 497, 37.42, 2.16, '2001-07-15', 'Existe una historia secreta del mundo. Una historia que comienza en 1946 cuando un extraño virus alienígena es liberado sobre los cielos de Nueva York, proporcionando superpoderes a unos cuantos supervivientes. A aquellos que dedican sus talentos a servir a la humanidad los llaman Ases. A los otros, a los que usan sus poderes para ayudar al mal, los denominan Jokers. Wild Cards nos cuenta su historia. Aquí comienza todo. Este es la génesis de lo que acontecerá. En este volumen se presentan los Ases y Jokers que poblarán el universo de Wild Cards: Jetboy, Golden boy, Dr. Tachyon, Jack Braun, Croid Crenson, Hunter S. Thompson. Todos superhéreoes de una novela mosaico en la que los relatos se combinan con noticias y hechos de una historia alternativa que va desde justo después de la Segunda Guerra Mundial hasta la década de los ochenta', 'Wild cards', 4.87, 7.12, 136, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.94, 6.48, '9788448032319', '8448032314', 360, 71.34, 3.48, '1935-12-05', 'El emperador Jagang desata una terrible plaga de peste contra la Tierra Central. Para salvar miles de vidas inocentes, tanto Richard como Kahlan deberán tomar una difícil decisión y sacrificarse. Los espíritus, buenos y malos, están dispuestos a ayudarlos. Pero todo tiene un precio, y en el mundo de los espíritus mora el peor enemigo de Richard: Rahl el Oscuro, su propio padre. ¿Qué exigirá a cambio de ayudar a Richard en su búsqueda de un remedio para la plaga?', 'El templo de los vientos', 9.14, 7.43, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.05, 7.86, '9788448034160', '8448034163', 384, 34.13, 3.8, '2005-03-08', 'Una nueva oleada de esperanza se extiendo por todo el sistema de Sabbat, infestado por las tropas del Caos, cuando llega la noticia de que una joven proclama ser la reencarnación de Santa Sabbat. A pesar de las dudas mostradas por el alto mando, la muchacha demuestra ser la inspiración perfecta para las acosadas tropas imperiales. Sin embargo, las siniestras fuerzas del Caos no subestiman esta nueva amenaza, y cuando ordenan a sus asesinos más letales acabar con ella, el comisario Gaunt y sus hombres se convierten en su última línea de defensa.', 'Santa Sabbat Martir', 3.74, 1.86, 137, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.7, 9.78, '9788448036201', '8448036204', 192, 52.82, 2.08, '2008-02-12', 'Erróneamente acusado del rapto de una reina turania, Conan decide no exponerse al hacha del verdugo. Huye al oeste por el Camino de los Reyes, y persigue a los raptores de la reina Jamilah hasta los ensangrentados muros del siniestro templo de Zath. Para poder sobrevivir a las calles de la perversa Yezud, se verá obligado a matar a todo un ejército de asesinos y caza recompensas. Sin embargo, sólo con la ayuda de una bella y valerosa doncella del templo podrá acceder a las profundidades donde habita el mal y hacer frente al venenoso dios araña...', 'Conan y el dios araña', 7.54, 2.4, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.01, 2.45, '9788448036218', '8448036212', 224, 67.34, 4.39, '2008-04-04', 'Con la soga al cuello, Conan aguarda la muerte en el cadalso. Sin embargo, el fuerte cimmerio no morirá. Cuando el áspero roce de la cuerda ya le quema en la garganta aparecen los que han de rescatarlo.Los rebeldes de la Rosa Blanca acogerán en su círculo al bárbaro. Éste, una vez libre, matará a legiones enteras por ellos, sembrando la muerte con su acero entre las filas del ejército del déspota.¡Y sin embargo, conocerá la traición, y no habrá hora tan cruel como la de su venganza!', 'Conan y el Camino de los Reyes', 8.7, 5.77, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.79, 8.56, '9788448036799', '8448036794', 496, 22.84, 2.16, '1948-12-08', 'Mientras Kahlan se enfrenta a las inmensas huestes de Jagang, Richard descubre la verdad sobre el dominio de la Orden Imperial. Obligado a soportar su ordalía sin magia, sin la Espada de la Verdad y sin su amor, se enfrenta a la desesperación y al aturdidor régimen del Viejo Mundo, manteniendo con vida la esperanza sólo gracias a que sabe que su causa es justa.', 'La fe de los caídos', 6.66, 5.43, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.32, 3.95, '9788448036836', '8448036832', 480, 5.71, 3.71, '1982-11-04', '2000 años antes de la era de Sigmar, el Imperio de Nehekharan se abrió paso entre las áridas tierras del desierto al sur del Viejo Mundo. Sin el conocimiento de sus gentes, este poderoso Imperio está a punto de derrumbarse. Una lucha por el poder supremo condenará este territorio y a sus habitantes para siempre. Esta es la amarga historia del ascensión de Nagash, un rey sacerdote cuya búsqueda por la inmortalidad desatará una plaga de muerte y maldad en una época en la que los muertos volverán del Más Allá.', 'Nagash, el Hechicero', 7.4, 1.26, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.56, 7.57, '9788448036898', '8448036891', 288, 21.18, 1.05, '1974-12-22', 'Atormentada toda su vida por voces inhumanas, la joven Jennsen busca poner fin a su insoportable agonía. Pero cuando descubre cómo salvarse de sus demonios interiores y silenciar las voces de modo definitivo no sabe que, para todos los demás, el tormento está a punto de empezar.', 'La estirpe de Rahl el Oscuro', 1.98, 6.05, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.42, 3.2, '9788448036997', '8448036999', 128, 85.32, 4.99, '2009-09-04', 'Sumérgete en estas páginas fascinantes y eruditas y asómate a algunas de las representaciones más vívidas de esta bestia que nos pertenece a todos. Afortunadamente, encontrarás aquí las alucinaciones de los cartógrafos plasmadas más allá de sus sueños más locos. «Aquí es donde moran los dragones», ciertamente. Desde las leyendas antiguas a la ciencia ficción, desde los nueve mundos a la Tierra Media, descubre los apasionantes dragones de John Howe y crea también los tuyos propios.', 'Forjar dragones', 7.01, 1.15, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.97, 1.96, '9788448038212', '8448038215', 0, 92.13, 4.9, '2013-01-25', 'Extinción: La Reina de la Red de Pozos Demoníacos le ha dado la espalda incluso a sus sirvientes más leales. Para una sacerdotisa, la única posibilidad que le queda es descubrir la verdad, aunque tenga que volver a un lugar de donde pocos han regresado. Para otra sacerdotisa, la perspectiva de una vida después de la muerte sin la Reina Araña la conduce a los brazos de otra diosa. Aniquilación: Si la Ciudad de las Arañas acabase enterrada, los enemigos de los drows vivirían un gran triunfo. Pero el archimago Gomph Baenre no permitirá que ocurra. Cuando llegue el momento, lo arriesgará todo para salvar a la ciudad que ama más de lo que ningún drow se atrevería a admitir. Resurrección: Con este volumen finaliza la serie de Reinos dedicada a los avatares de los elfos oscuros y la Reina Araña. En esta ocasión, la Reina debe elegir a su sucesora. Las aventuras a las que deben enfrentarse las tres aspirantes culminarán en un final sorprendente que dará lugar al mayor horror que los Reinos hayan conocido.', 'Estuche La Guerra de la Reina Araña 2', 9.27, 4.86, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.8, 8.62, '9788448038229', '8448038223', 950, 9.12, 4.83, '2001-03-01', 'Los dioses se han desvanecido y la magia se ha debilitado hasta casi desaparecer de Krynn. Es la Era de los Mortales, pero también es la Era de los Dragones, que arrasan pueblos, esclavizan a sus gentes y se proclaman señores supremos de Ansalon. Han alterado la tierra por medios mágicos, esculpiendo sus dominios de acuerdo con sus viles inclinaciones, y ahora comienzan a reunir ejércitos de dragones, humanoides y criaturas. Incluso los antaños orgullosos Caballeros de Takhisis se han unido a sus filas y preparan el ataque contra los ciudadanos de Ansalon. Sin embargo, un puñado de humanos no quiere rendirse. Incitados por el famoso hechicero Palin Majere y armados con una antigua Dragonlance, osan desafiar a los dragones.', 'Quinta era', 6.29, 7.53, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.27, 2.75, '9788448039769', '8448039769', 390, 86.09, 5.0, '1960-01-14', 'HALO: La novelización de uno de los juegos para consola de más éxito de todos los tiempos.Mientras la sangrienta guerra entre los seres humanos y la Alianza lo arrasa todo en Halo, el destino de la humanidad podría descansar en un solo guerrero, el último spartan superviviente de otra legendaria batalla... la desesperada lucha sin prisioneros que ha conducido a la humanidad hasta Halo: la caída del planeta Reach. He aquí la historia completa de ese glorioso, malhadado conflicto.', 'La caída de Reach', 5.04, 4.96, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.31, 2.33, '9788448043933', '8448043936', 320, 13.1, 2.03, '1990-02-03', 'En esta serie se relatan hechos que suceden 10000 años antes que los referidos en las novelas de Warhammer 40000. Por este motivo se trata de una serie imprescindible para los aficionados que quieran conocer el origen de episodios y personajes de otras novelas.', 'Falsos dioses', 9.16, 4.43, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.91, 8.24, '9788448043964', '8448043960', 320, 89.76, 1.15, '2007-05-29', 'Los marines espaciales del capítulo de los Cuervos Sangrientos se aprestan a defender uno de sus planetas. Todo parece indicar que los culpables del ataque son los misteriosos eldars, pero al realizar una serie de descubrimientos bajo la superficie del planeta, sale a la luz un enemigo mucho más mortífero. El capitán Gabriel Angelos debe llegar hasta el fondo de ese misterio antes de que todo el sector quede envuelto en una guerra a escala galáctica.', 'Ascensión', 1.39, 9.31, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.38, 2.45, '9788448043988', '8448043987', 304, 58.9, 3.86, '1983-11-13', 'En esta serie se relatan hechos que suceden 10.000 años antes que los referidos en las novelas de Warhammer 40000. Por este motivo se trata de una serie imprescindible para los aficionados que quieran conocer el origen de episodios y personajes de otras novelas. El señor de la guerra Horus se ha recuperado de sus terribles heridas y encabeza a las triunfantes fuerzas imperiales contra el mundo rebelde de Isstvan III. Sin embargo, aunque los rebeldes son aplastados, la traición de Horus se hace patente cuando ordena que arrasen el planeta con bombas víricas y los marines espaciales se vuelven contra sus hermanos de batalla en el combate más feroz imaginable.', 'La galaxia en llamas', 7.79, 4.98, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.2, 4.12, '9788448044121', '8448044126', 288, 40.73, 1.82, '1972-12-25', 'El comisario Ciaphas Cain –héroe del Imperio y famoso en todo el sector por su coraje y valentía– es enviado para ayudar a mantener el orden en un mundo en los límites del espacio Tau. Pero cuando el embajador extranjero es asesinado, Cain y su regimiento de vahallanos se ven envueltos en una guerra. Mientras la Guardia Imperial lucha por contener una insurrección civil de ámbito mundial ¿podrá el astuto comisario identificar al verdadero villano antes de que el Imperio pierda para siempre el dominio de ese planeta?', 'Por el emperador', 1.04, 2.26, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.53, 2.98, '9788448044329', '8448044320', 280, 84.4, 3.64, '2009-06-23', 'Dirigidos por un recientemente ascendido sargento que está decidido a ponerse a prueba a sí mismo, los marines espaciales Cuervos Sangrientos llegan a un mundo desierto para reclutar a más soldados para su Capítulo. Pero una vez aterrizan, los encontrarán invadidos por orcos alienígenas. Los Cuervos sangrientos encabezan una serie de asaltos sobre el territorio enemigo para acabar descubriendo que en el origen de los ataques se esconde un horror aún más letal.', 'DAWN OF WAR II (DAWN OF WAR) WARHAMMER 40000', 8.41, 6.19, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.5, 8.34, '9788448044336', '8448044339', 320, 48.5, 1.2, '1939-06-28', 'La República se desmorona, incluso bajo el mandato del canciller supremo Palpatine, elegido diez años antes para intentar recomponer el fragmentado gobierno. Los Separatistas amenazan con la guerra, y el Senado ha perdido la esperanza, no sabe si armar un ejército o tratar de conservar la frágil paz. Pero incluso con la República tambaleándose a su alrededor, Anakin y Padmé conectan de forma tan intensa que todo lo demás empieza a perder importancia. Pero el joven jedi ha jurado lealtad a la Orden y ciertas emociones que le está prohibido tener acabarán provocando su propia perdición...', 'Episodio II: El ataque de los clones', 3.85, 9.0, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.75, 9.46, '9788448044497', '8448044495', 400, 73.23, 4.54, '1940-10-11', 'En el universo de Warhammer 40.000 los nobles Ultramarines, guerreros genéticamente mejorados para proteger al Imperio de sus enemigos, son los Marines Espaciales por excelencia. El capitán Uriel Ventris, recién llegado del Ojo del Terror, debe redimirse a ojos de sus hermanos de batalla, que temen que haya sido tentado por el Caos. La invasión del planeta Pavonis por parte de los Tau será la oportunidad perfecta para que Uriel se una a su capítulo y demuestre que su honor está fuera de toda duda.', 'Coraje y honor', 8.11, 6.21, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.81, 4.62, '9788448044510', '8448044517', 224, 79.1, 3.91, '1994-05-28', 'Cuando la barcaza prisión imperial Purga, hogar temporal de quinientos de los criminales más peligrosos de la galaxia, se avería en una zona alejada y deshabitada del espacio, su única esperanza parece residir en un destructor estelar a la deriva y aparentemente abandonado. Sin embargo, sólo la mitad del equipo de búsqueda que entra en él regresa, y trae consigo una terrible enfermedad, tan letal que en cuestión de horas la Purga al completo muere de las formas más horribles imaginables. La media docena de supervivientes de la Purga harán lo que sea para sobrevivir. Pero los muertos -desalmados, imparables e inexplicablemente hambrientos- se están levantando.', 'Las tropas de la muerte', 9.48, 5.53, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.5, 1.08, '9788448044527', '8448044525', 504, 36.53, 2.9, '2010-09-21', 'La Gran Cruzada vive un momento decisivo y los Mil Hijos luchan con entrega y lealtad. Sin embargo, el Imperio recela de la Legión de Magnus el Rojo a causa de sus métodos arcanos. Temido por aquellos a quienes ha jurado proteger, Magnus es llamado al planeta Nikaea para defenderse de las acusaciones de brujería. No obstante, cuando el desventurado primarca tiene visiones que predicen la traición de Horus, decide avisar al Emperador mediante poderes prohibidos, y el Señor de la Humanidad envía a Leman Russ, primarca de los Lobos Espaciales, a atacar Próspero, el planeta de los Mil Hijos. Pero Magnus ha visto más allá de la traición del Señor de la Guerra y estas revelaciones decidirán el destino de su Legión para siempre.', 'Los Mil Hijos', 6.31, 4.49, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (10.0, 3.83, '9788448044534', '8448044533', 400, 56.97, 2.17, '2010-10-19', 'Los Marines Espaciales del capítulo Salamandra se dirigen, guiados por una antigua profecía, a un planeta plagado de misterios. Aunque parece un puesto avanzado de los Guerreros de Hierro, las apariencias engañan, ya que en su interior les esperan enemigos mucho más peligrosos. ¿Sobrevivirán lo suficiente como para descubrir la verdad sobre este mundo y conocer las revelaciones que sacudirán los cimientos del capítulo para siempre?', 'Salamandra', 3.3, 8.87, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.29, 1.81, '9788448044626', '8448044622', 320, 10.67, 4.32, '2013-12-13', 'Estamos en el 31o milenio y la raza humana se ha diseminado por toda la Galaxia. Cuando Horus, señor de la guerra se rebela contra el Emperador, la subsiguiente guerra civil está a punto de destrozar el Imperio. La guerra desgarra los mundos, enfrentado a los Astartes contra sus hermanos de batalla en una lucha donde la muerte es la única que sale victoriosa.', 'Cuentos de la Herejía', 6.1, 4.46, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.06, 9.85, '9788448044640', '8448044649', 400, 4.03, 4.71, '1972-11-26', 'Esta vez, los Ángeles Sangrientos se enfrentan a los feroces Demonios de la Sangre, tras haberles impedido arrasar su planeta de origen, Baal. Al mismo tiempo, salen en búsqueda de quien casi destruye a su Capítulo: Fabius Bilis. Pero cuando localizan al traidor Marine del Caos en su base secreta de Dynikas IV, un planeta asediado por tiránidos, descubren un horror aún más terrible que sus peores pesadillas. Tendrán que recuperar la muestra de sangre que ha sido robada a su primarca antes de que Fabius Bilis lleve a cabo sus siniestros planes. ¿Podrán conseguirlo?', 'Marea negra', 5.36, 6.95, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.56, 1.87, '9788448049072', '8448049071', 420, 91.56, 3.81, '1974-12-20', 'Fue un momento trágico de la historia del Imperio. Las semillas de la traición y de la deslealtad sembradas por las fuerzas del Caos hicieron que el antaño leal señor de la guerra, Horus, se volviera contra el Emperador de la Humanidad. El enfrentamiento entre estos dos titanes provocó que se estremecieran hasta los cimientos del Imperio e hizo que el hermano se enfrentara al hermano en una brutal guerra civil que acabó siendo conocida como la Herejía de Horus.', 'La Herejía de Horus. La gran guía ilustrada.', 1.52, 4.31, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.08, 4.71, '9788461386789', '8461386787', 256, 61.3, 3.65, '2010-04-15', 'Primero pensaron que podrían dar la vuelta al mundo con su furgoneta 4x4 en 4 años. Luego se convencieron que la terminarían en 7. Cuando llegaron al sexto año de viaje, creyeron que diez era buen número, un número redondo. El próximo mes de junio cumplen 10 años viviendo en la ruta. Y todavía les queda medio planeta. "Jamás olvidaré el lunes que apoyé el cañón de una pistola en mi cabeza y disparé hasta quedarme sin balas, sin detenerme a pensar en lo que hacía para no darle otra oportunidad al arrepentimiento. Era la despedida a un trabajo fijo, la renuncia a un futuro previsible, la jubilación anticipada de la seguridad. Pasaban diez minutos de las diez de la mañana y mis últimas palabras decían, más o menos, ''quédense ustedes con el muerto que yo me largo''. Mi cuerpo se desplomó y yo salí por la puerta."', 'La vuelta al mundo en 10 años', 5.02, 5.52, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.22, 4.14, '9788466347921', '8466347925', 1502, 48.01, 3.01, '1944-04-26', '¿Quien o que mutila y mata a los niños de un pequeño pueblo norteamericano?¿Por que llega cíclicamente el horror a Derry en forma de un payaso  siniestro que va sembrando la destrucción a su paso? Esto es lo que se proponen averiguar los protagonistas de esta novela.  Tras veintisiete años de tranquilidad y lejanía, una antigua promesa  infantil les hace volver al lugar en el que vivieron su infancia y  juventud como una terrible pesadilla. Regresan a Derry para enfrentarse  con su pasado y enterrar definitivamente la amenaza que los amargó durante su niñez. Saben que pueden morir, pero son conscientes de que no conocerán la paz hasta que aquella cosa sea destruida para siempre. It es una de las novelas más ambiciosas de Stephen King, con la  que ha logrado perfeccionar de un modo muy personal las claves del genero de terror. La crítica ha dicho."Insuperable."La Vanguardia', 'Eso', 9.86, 7.7, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.62, 4.98, '9788466601870', '8466601872', 240, 63.38, 4.34, '2001-05-01', 'La magia de las mujeres celtas. Poderosas, salvajes, sabias, magas, las mujeres del antiguo mundo celta son protagonistas de historias maravillosas cargadas de heroismo y fantasia.Jennifer Heath ha recopilado los cuentos que su madre y su abuela -irlandesas- le contaran en la infancia, y los ha enriquecido con sus propias investigaciones sobre los textos epicos y la tradicion oral de la isla, de los que las mujeres celtas han sido importantes creadoras y guardianas. Leer Dioses y Hadas es una forma de revivir la magica atmosfera de la antigua y misteriosa Irlanda para revelar su secreta clave femenina.', 'Diosas y Hadas', 3.25, 4.55, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.1, 9.73, '9788466639590', '8466639594', 384, 32.35, 1.36, '1941-04-25', 'La Tierra se ve amenazada por los insectores, una raza extraterrestre completamente ajena a los humanos, a los que pretende destruir. Para vencer a los insectores es necesario un nuevo tipo de genio militar, y por ello se ha permitido el nacimiento de Ender, quien en cierta forma constituye una anomalía viviente: es el tercer hijo de una pareja en un mundo que ha limitado estrictamente a dos el número de descendientes. El niño Ender deberá aprender todo lo relativo a la guerra en los videojuegos y en los peligrosos ensayos de batallas que realiza con sus compañeros. A la habilidad en el tratamiento de las emociones, ya característica de Orson Scott Card, se une en este libro el interés por el empleo de las simulaciones de ordenador y juegos de fantasía en la formación militar, estratégica y psicológica del protagonista.', 'El juego de Ender', 9.37, 7.92, 138, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.57, 1.32, '9788466646239', '846664623X', 0, 55.94, 3.68, '2011-01-19', 'En WARBREAKER, el sistema de magia única se basa en el aliento (breath), que los de Idrian también llaman el alma. Cada ser humano nace con un aliento. Uno se puede desprender de su aliento y aún así seguir viviendo, aunque parecerá a los demás co', 'EL ALIENTO DE LOS DIOSES', 9.15, 1.16, 138, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.96, 7.78, '9788466656238', '8466656235', 320, 8.55, 2.18, '1957-05-06', 'Una travesía durante la cual el autor recorrió 36 países a lo largo  de 40.000 kilómetros pedaleando durante más de 400 días. Xavi Narro tiene todo lo que necesita para ser feliz. Sin embargo,  no se puede quitar de la cabeza la estúpida promesa que, de pequeño, se hizo a sí mismo: "Cuando cumpla los treinta, dare la vuelta al mundo en bicicleta." Inevitablemente, ese día llega, y Xavi se ve obligado a abandonar lo que  hasta el momento ha sido su vida para ponerse a pedalear por todo el planeta durante quince meses. A lo largo de cuarenta mil kilómetros topará con personajes tan  pintorescos como su propio fantasma, un pingüino en un lavabo y la duquesa de Alba de luna de miel. Al mismo tiempo, nos hará reír, llorar y reflexionar sobre la importancia de seguir nuestro propio camino, aunque este desemboque en un precipicio.', 'Vagabundo: Una vuelta al mundo en bici', 7.1, 9.21, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.96, 9.11, '8466657541', '9788466657549', 0, 33.43, 1.59, '2015-11-30', 'Hace seis años, un asesino mató al rey Alethi, y ahora está asesinando a los gobernantes de todo Roshar; entre sus principales objetivos es Dalinar. Kaladin está al mando de los guardaespaldas reales, un puesto controvertido por su baja condición, y debe proteger al rey y a Dalinar, mientras que en secreto domina nuevos poderes extraordinarios vinculados a Syl. Shallan tiene la carga de impedir el regreso de Voidbringers y el fin de la desolada civilización que queda. Los Parshendi están convencidos por su líder a arriesgarlo todo en una apuesta desesperada con las fuerzas sobrenaturales que una vez desaparecieron. ENGLISH DESCRIPTION Six years ago, the Assassin in White killed the Alethi king, and now he''s murdering rulers all over Roshar; among his prime targets is Highprince Dalinar. Kaladin is in command of the royal bodyguards, a controversial post for his low status, and must protect the king and Dalinar, while secretly mastering remarkable new powers linked to his honorspren, Syl.', 'Palabras radiantes / Words of Radiance', 5.08, 3.36, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.68, 7.22, '8466658858', '9788466658850', 0, 92.35, 2.18, '2017-01-31', 'En Sombras de identidad el autor muestra cómo ha ido evolucionando el mundo a medida que la tecnología se mezcla con la magia, la economía crece, la democracia se sostiene con la corrupción, y la religión se convierte en una fuerza cultural en crecimiento, con cuatro de ellas que compiten por la conversión. Esta sociedad optimista pero todavía inestable, se enfrenta a su primer caso de terrorismo, delitos que avivan el odio y el conflicto laboral con el conflicto religioso. Wax y Wayne, con la ayuda de su estimado y brillante Marasi, deben desentrañar una conspiración antes de que la lucha civil encuentre las pistas. ENGLISH DESCRIPTION Shadows of Self shows Mistborn''s society evolving as technology and magic mix, the economy grows, democracy contends with corruption, and religion becomes a growing cultural force, with four competing faiths. This bustling, optimistic, but still shaky society now faces its first instance of terrorism.', 'Sombras de identidad / Shadows of Self', 4.14, 4.05, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.02, 8.84, '8466658904', '9788466658904', 0, 47.0, 2.85, '2016-11-30', 'Durante los últimos mil años, han caído las cenizas y nada florece; los skaa han sido esclavizados y viven sumidos en un miedo inevitable; el Lord Legislador reina con un poder absoluto gracias al terror y a su divina invencibilidad. Le ayudan los "obligadores" y los "inquisidores" junto a la poderosa magia de la "alomancia" que reside en los nobles. Sólo algunos son capaces de "quemar" los metales que han tragado y que les otorgan poderes sobrenaturales. Pero los nobles, demasiado a menudo, han tenido trato sexual con jóvenes skaa y, aunque la ley lo prohibe, algunos de sus bastardos han sobrevivido. ENGLISH DESCRIPTION They did the impossible, deposing the godlike being whose brutal reign had lasted a thousand years. Now Vin, the street urchin who has grown into the most powerful Mistborn in the land, and Elend Venture, the idealistic young nobleman who loves her, must build a healthy new society.', 'El pozo de la ascension / The Well of Ascension', 8.43, 9.9, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.77, 4.46, '8466658912', '9788466658911', 0, 77.65, 1.86, '2017-01-31', 'Durante los últimos mil años, han caído las cenizas y nada florece. Durante mil años, los skaa han sido esclavizados y han vivido sumidos en un miedo inevitable. Durante mil años, el Lord Legislador ha reinado con un poder absoluto gracias al terror y a la omnipresente magia de la "alomancia". Kelsier, el "Superviviente", el único que logró huir de los Pozos de Hathsin, encontró a Vin, una pobre chica skaa con mucha suerte. Los dos unidos a la rebelión que los skaa intentaban desde hace mil años vencieron al Lord Legislador. Pero matar a éste fue la parte sencilla. El verdadero desafío será sobrevivir a las consecuencias de su caída. En El héroe de las Eras se comprende el porqué de la niebla y las cenizas, la justificación de las tenebrosas acciones del Lord Legislador y la naturaleza del Pozo de la Ascensión. Todo resulta atado -y bien atado- cuando Vin y el Rey Elend buscan los últimos escondites de recursos del Lord Legislador y descubren el peligro que acecha a la humanidad. Podrán detenerlo a tiempo? Tras el gran éxito mundial de Elantris, Sanderson logra repetir la hazaña. La trilogía Nacidos de la bruma es una excepcional muestra de una nueva fantasía épica con magia, leyenda y todo tipo de misterios. ENGLISH DESCRIPTION Having escaped death at the climax of "The Well of Ascension" by becoming a Mistborn himself, Emperor Elend Venture hopes to find clues left behind by the Lord Ruler that will allow him to save the world. Vin is consumed with guilt at having been tricked into releasing the force known as Ruin from the Well.', 'El héroe de las eras / The Hero of Ages', 8.61, 2.37, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.56, 6.06, '8466660151', '9788466660150', 0, 86.23, 2.35, '2017-01-12', 'En el siglo XXIII la humanidad ha conseguido colonizar la mayor parte del sistema solar. Las relaciones entre la Tierra y Marte son algo tensas, pero conviven y consiguen la mayor parte de sus recursos y mano de obra gracias a los habitantes del cinturón de asteroides, que se han conformado como una gran civilización viviendo en estaciones espaciales. Más allá del cinturón de asteroides también hay humanos, pero algunos de ellos se han unido en lo que se llama la OPA (Asociación de Planetas Exteriores) y están empezando a luchar por sus derechos y a enfrentarse a la hegemonía de los planetas interiores (Tierra y Marte). En este futuro, Julie Mao, hija de una importante corporación de la Luna desaparece y Joe Miller, detective privado del cinturón de asteroides, recibe la misión de encontrarla. Por otra parte, James Holden, antiguo militar de la Tierra que ahora se dedica a comandar un carguero de hielo en el cinturón de asteroides, carguero que unas naves muy sospechosas destruyen justo cuando Holden había salido en una lanzadera para investigar una extraña llamada de auxilio. ENGLISH DESCRIPTION Two hundred years after migrating into space, mankind is in turmoil. When a reluctant ship''s captain and washed-up detective find themselves involved in the case of a missing girl, what they discover brings our solar system to the brink of civil war, and exposes the greatest conspiracy in human history.', 'El despertar de Leviatan / Leviathan Wakes', 3.28, 5.92, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.14, 9.2, '9788466660952', '846666095X', 0, 6.91, 3.98, '2017-12-31', 'Tras interminables guerras, amargas luchas internas y sangrientas confrontaciones, incluso las tropas imperiales necesitan un descanso. Pero la obsesión expansionista de la emperatriz Lassen no tiene límites, y cuenta con el apoyo de sus sanguinarios agentes de la Garra. Tras el último asedio, el sargento Whiskeyjack y su pelotón de Abrasapuentes necesitan tiempo para descansar y enterrar a sus muertos, pero Darujhistan, la última de las Ciudades Libres de Genabackis, los espera. Es el objetivo último de la insaciable emperatriz... Y parece que el Imperio no es el único que codicia esa plaza: fuerzas siniestras conspiran dentro y fuera de las sendas mágicas, y todo indica que los propios dioses se preparan para la batalla. ENGLISH DESCRIPTION Set in a brilliantly realized world ravaged by dark, uncontrollable magic, this thrilling novel of war, intrigue and betrayal confirms Steven Eirkson as a storyteller of breathtaking skill, imagination and originality--a new master of epic fantasy.', 'Malaz / Deadhouse Gates', 2.77, 8.2, 139, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.69, 7.51, '8466662669', '9788466662666', 0, 89.41, 3.65, '2018-04-24', 'Memorias del hielo es la tercera entrega de la saga «Malaz: El Libro de los Caídos», la decalogía originalmente publicada entre 1999 y 2011 que ha convertido al escritor canadiense Steven Erikson en una de las mayores voces de la fantasía épica contemporánea. Desde entonces, esta obra maestra de la imaginación está considerada una de las series más ambiciosas del género de los últimos años. Una fuerza aterradora ha surgido en el continente asolado de Genabackis. Como una marea de sangre corrompida, el Dominio Painita cruza el continente como lava hirviente que consume a todos los que no escuchan la palabra de su profeta, el Vidente Painita. En su camino se interpone una alianza incómoda: la hueste de Dujek Unbrazo y los veteranos Abrasapuentes de Whiskeyjack, junto con antiguos adversarios: el caudillo Caladan Brood, Anomander Rake y sus tiste andii. Superados en número y desconfiando de todo y de todos, deben hacer llegar el mensaje a cualquier posible aliado, incluyendo las Espadas Grises, una hermandad mercenaria que ha jurado defender a toda costa la ciudad sitiada de Capustan. Pero son más los clanes antiguos que se están reuniendo. Los t#lan imass se alzan para responder a una antigua llamada primitiva. Algo maligno amenaza este mundo: las sendas están envenenadas y abundan los rumores sobre un dios que se ha deshecho de sus cadenas y está empeñado en vengarse... ENGLISH DESCRIPTION The ravaged continent of Genabackis has given birth to a terrifying new empire: the Pannion Domin. Like a tide of corrupted blood, it seethes across the land, devouring all. In its path stands an uneasy alliance: Onearm''s army and Whiskeyjack''s Bridgeburners alongside their enemies of old--the forces of the Warlord Caladan Brood, Anomander Rake and his Tiste Andii mages, and the Rhivi people of the plains. But ancient undead clans are also gathering; the T''lan Imass have risen. For it would seem something altogether darker and more malign threatens this world. Rumors abound that the Crippled God is now unchained and intent on a terrible revenge. Marking the return of many characters from Gardens of the Moon and introducing a host of remarkable new players, Memories of Ice is both a momentous new chapter in Steven Erikson''s magnificent epic fantasy and a triumph of storytelling.', 'Memorias del hielo / Memories of Ice', 3.12, 7.6, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.77, 2.38, '9788466664738', '8466664734', 633, 31.65, 3.97, '2012-04-12', 'Verano de 1960. En el pueblecito de Elm Haven, Illinois, cinco pre-adolescentes de doce años pasan sus días bajo atardeceres en bicicleta, juegos y descubrimientos propios de una pacífica infancia en un lugar idílico. Sin embargo, tras la desaparición de un compañero de clase, su afán de aventura los llevará a averiguar mucho más de lo que esperaban: un mundo paralelo en el que la realidad y la fantasía apenas se distinguen. El inesperado repique de una extraña campana europea en medio de la noche marcará el fin de los días tranquilos. Ahora, desde las profundidades de Old Central School, el mal acecha. Acontecimientos insólitos y escalofriantes comienzan a apropiarse del día a día, propagando el miedo por el pueblo.', 'Un verano tenebroso', 8.53, 6.86, 10, NOW(), NOW());
