INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.5, 2.39, '9788473866026', '8473866029', 509, 97.02, 3.8, '1949-01-22', '', 'Rama II', 8.42, 9.75, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.37, 7.98, '9788474232967', '8474232961', 714, 26.39, 5.0, '1950-12-17', 'Esta coleccion nacio como una hermana mayor de la « Serie general con el fin de acoger los « grandes temas y los « grandes libros (que muchas veces han sido tambien libros grandes). Se inicio en 1986 con Los descubridores, de Daniel J. Boorstin (primer titulo de una trilogia que se completaria con Los creadores y Los pensadores, y uno de los libros mas vendidos de la editorial) y ha seguido publicandose hasta hoy con titulos como Carlos V y sus banqueros (edicion completa) de Ramon Carande; El conde duque de Olivares, de John Elliott; Diarios completos, de Manuel Azana; Federico Garcia Lorca, de lan Gibson; Historia de Espana, de Joseph Perez; Historia de Espana (3 vols.), de Ferran Soldevila; Historia de Espana (14 vols.), dirigida por John Lynch; Historia de America Latina (16 vols.), dirigida por Leslie Bethell; Historia del siglo XX, de Eric J. Hobsbawm; Los Origenes de la Inquisicion espanola, de B. Netanyahu; La riqueza y la pobreza de las naciones, de David S. Landes, etcetera. La historia del hombre como descubridor; pero no solo del descubridor de tierras, cielos y mares, sino descubridor del tiempo, de la naturaleza y de la sociedad.', 'Los descubridores', 8.4, 2.04, 140, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.56, 7.87, '9788474770919', '8474770912', 227, 14.11, 1.48, '1996-04-07', '', 'Charles Richard Vaughan', 5.16, 1.54, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.25, 4.61, '9788474902266', '8474902266', 240, 85.52, 2.49, '1989-05-01', 'Causa una cierta sorpresa el desarrollo e interés que despiertan los estudios sobre el arte románico en nuestro tiempo. Pero esta sorpresa se desvanece cuando se analiza el románico desde un punto de vista cultural y se establece su paralelismo con el contexto de nuestro tiempo. En los siglos XI y XII, es decir, en la etapa de la génesis y floración del arte románico, las diversas naciones y regiones de la Europa occidental,  sea, de la Cristiandad, se sintieron partícipes de una empresa común. Una misma esprirtualidad las unía y tras la anarquía y fragmentación del período prorrománico, unos mismos ideales cimientan la cultura europea. Este estudio pictórico refleja y analiza la herencia románica de las tierras de Aragón.', 'Itinerarios románicos por el Alto Aragón', 2.64, 7.5, 141, NOW(), NOW());
