INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.55, 6.37, '9788477222880', '8477222886', 260, 61.49, 1.22, '1986-07-14', '', 'Niebla Amarilla', 3.53, 9.49, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.92, 5.16, '9788477224112', '8477224110', 608, 78.38, 4.04, '1955-12-11', 'The legends of King Arthur come alive with a Christian world-view in these masterfully told adventures. These new editions contain new maps and other new material.', 'Merlin', 4.91, 1.49, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.92, 3.04, '9788477224136', '8477224137', 326, 3.93, 2.13, '1995-03-01', 'David Day ha escrito un completo bestiario que incluye los nombres de las criaturas y monstruos imaginados por Tolkien, así como una exhaustiva relación de razas, ciudades, reinos, deidades, flora, batallas y los infinitos sucesos que tuvieron lugar en la Tierra Media.', 'Bestiario de Tolkien', 3.94, 4.19, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.58, 3.97, '9788477350972', '8477350973', 304, 54.84, 2.4, '1958-07-18', '', 'El Libro de los cráneos', 5.0, 6.79, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.46, 6.02, '9788477823865', '8477823863', 162, 57.57, 3.08, '1996-01-01', '', 'Navegantes y náufragos', 5.9, 9.75, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.87, 5.36, '9788478442621', '8478442626', 364, 74.18, 1.44, '1995-02-01', 'En otono de 1973 el escritor Peter Matthiessen y el zoologo George Schaller emprendieron una expedicion a la Montana de Cristal, en la meseta del Tibet, para estudiar los habitos de un animal no muy conocido: el bharal o cordero azul himalayo. Pero su autentica esperanza era poder ver al mas hermoso y raro de los grandes felinos: el leopardo de las nieves.Para Matthiessen, adentrarse en la tierra de Dolpo, ultimo enclave de la cultura tibetana en estado puro, significara mucho mas que una expedicion naturalista o una aventura: despojarse de las ventajas y las ataduras de la civilizacion, convivir con hombres y paisajes en su mas elemental belleza, penetrar en si mismo por las vias que le proporciona el budismo o el zen: ahi estan, abiertas y sugerentes, las huellas del leopardo de las nieves. B+Un hombre sale de viaje y es otro quien regresa.B; Ese es el sentido del viaje de Matthiessen, como lo es de todo autentico viaje.', 'El leopardo de las nieves', 5.59, 4.46, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.56, 1.83, '9788478463206', '8478463208', 398, 31.66, 2.87, '1994-01-01', '', 'Por los caminos de la trashumancia', 9.43, 3.07, 142, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.45, 8.84, '9788479530464', '8479530464', 279, 11.29, 4.57, '1963-12-08', '', 'Hotel Mamá', 7.55, 4.85, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.95, 8.86, '9788481090840', '8481090840', 155, 33.24, 2.96, '1976-07-08', '', 'Yo he vivido en la Antártida', 5.88, 9.16, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.74, 2.56, '9788482646954', '8482646958', 448, 47.11, 4.99, '1999-03-28', 'Possedor d’un dels talents mes visionaris del segle XX, Ray Bradbury ens va deixar alguns contes que són obres mestres del genere. En aquest volum trobarem trenta-dos relats cabdals que revelen el Bradbury mes imaginatiu, pero sobretot hi retrobarem un escriptor tendre, capaç d’explicar, amb la historia d’un individu o d’un fet mínim, tota una visió dramàtica sobre l’home i allo que l’espera. Un autor que ens ha dotat de figures i símbols que ens ajuden a entendre l’univers que habitem, com ara el celebre "efecte papallona", expressat amb gran encert en el conte "El so d’un tro". Gràcies a Bradbury retrobem allo meravellós, el mes terrible i el mes sublim, l’inesperat i el malson que es transforma en una visió obsessionant i lúcida sobre la nostra condició.', 'Les pomes daurades del sol', 5.53, 9.14, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.36, 5.04, '9788483670118', '8483670119', 118, 92.78, 2.09, '1940-01-20', 'Hace algunos años, en el diario barcelonés La Vanguardia, el novelista y crítico literario Sebastián Juan Arbó decía que la novela de Víctor Alperi, El rostro del escándalo, figuraba entre las cinco novelas españolas que se podían com', 'España, un corazón desnudo', 2.02, 5.88, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.49, 9.02, '9788484605584', '8484605582', 240, 94.55, 3.92, '2007-11-02', 'Tras el éxito alcanzado con el primer volumen, podemos disfrutar de nuevas y magníficas "perlas" que se reúnen en este amplio y disparatado repertorio para provocar la carcajada de sus lectores. Ni la LOGSE ni eso de la ESO han acabado con los disparates estudiantiles. Si alguna vez has pasado el mal trago de un examen, seguro que te divertirás con esta completa colección de respuestas absurdas.', 'Gran enciclopedia del disparate 2', 1.65, 3.05, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.88, 5.58, '9788485411511', '848541151X', 360, 16.8, 5.0, '2018-09-18', '', 'Lope de Aguirre', 2.02, 8.13, 143, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.32, 2.2, '9788485639298', '8485639294', 103, 66.44, 4.85, '2021-06-14', '', 'Cartas del descubrimiento del Gran Catayo', 1.92, 7.52, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.4, 8.81, '9788485639366', '8485639367', 259, 56.02, 3.26, '1997-11-01', 'Descripción del viaje (1403-1406) que por encargo del Rey Enrique III de Castilla realizó el autor a la mítica Samarcanda de Tamerlan, siendo éste el primer libro de viajes de la literatura castellana. La minuciosidad de las noticias y descripciones...', 'Embajada a Tamerlán', 6.63, 3.01, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.83, 4.14, '9788487698071', '8487698077', 241, 73.2, 2.42, '1973-03-20', '', 'Barrera siniestra', 9.85, 2.32, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.53, 6.52, '9788487733598', '848773359X', 82, 84.69, 2.7, '1943-08-10', '', 'Suave roce de piel', 9.73, 7.75, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.89, 5.87, '9788489890183', '8489890188', 144, 60.43, 3.73, '1954-01-21', 'En aquest llibre l''autor explica les seves experiències en diverses expedicions a l''Himàlaia i intenta que el seu fill i tots aquells que llegeixin l''obra hi trobin relatades unes vivències completes i entenguin fins a quin punt de la mà de la il•lusió es pot intentar tot.', 'Pare, muntanya, regal', 3.11, 7.11, 144, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.6, 9.66, '9788490066621', '8490066620', 416, 10.91, 1.94, '1982-06-20', 'Chicago, 1992. Dicen que lo que no te mata te hace más fuerte. Que se lo digan a Kirby Mazrachi, cuya vida se ha trastocado tras un brutal intento de asesinarla. Mientras lucha por encontrar a su atacante, su único aliado es Dan, un antiguo periodista de homicidios que se ocupó del caso  y que trata de protegerla de su obsesión. A medida que Kirby avanza en la investigación descubre a otras chicas, las que no lo lograron. Las pruebas de los crímenes son& imposibles. Pero para una chica que debería estar muerta, imposible no quiere decir que no haya pasado&', 'Las luminosas', 2.43, 1.31, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.17, 2.67, '9788490563786', '8490563780', 144, 30.36, 2.55, '1942-10-15', 'Ciertos conocimientos son perfectamente innecesarios. Se puede vivir muy feliz sin saber con que truculencia surgió la cúpula del rascacielos Chrysler, por que los Yankees son el equipo supremo en Nueva York, cuál es la relación entre Arabia Saudí y la cerveza de Brooklyn, por que la grasa de los filetes es más amarillenta que en Europa, en que bar bebió Dylan Thomas su último whisky o dónde sirven las mejores hamburguesas de Manhattan. Historias de Nueva York habla de esas cosas. Tambien habla de una ciudad rugiente y fabulosa, de una jornada negra de septiembre, de un grupo de personas y de tres amigos inolvidables.', 'Historias de Nueva York', 5.55, 5.7, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.95, 2.11, '9788490564103', '8490564108', 128, 34.02, 2.12, '2013-09-04', 'Roma es una ciudad de ciudades. Irresistiblemente caótica, en sus calles impregnadas de la pausada melancolía de un pasado de piedras milenarias abundan los lugares y los instantes mágicos. Historias de Roma no es una guía turística ni un compendio de tópicos, sino un recorrido personal por una Roma fascinante, en ocasiones secreta. En sus páginas encontrará el lector una sucesión de historias, personajes, momentos y escenarios romanos: los gatos, las pinturas del Caravaggio, la casa y la tumba de Keats, la rica cocina de casquería romana, la burocracia, la calle en la que apareció el cadáver de Aldo Moro, los papas, Berlusconi y sus emisarios, una iglesia en la que nadie quiere casarse, el fútbol, las conspiraciones masónicas, los palazos, la cúpula de San Pedro entre la neblina…', 'Historias de Roma', 4.35, 6.63, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.61, 7.24, '9788491046875', '8491046879', 544, 37.6, 1.94, '1992-06-22', 'Quince relatos y novelas cortas de uno de los mejores escritores de ficcion breve de la ciencia-ficcion." El zoo de papel" es la primera obra que ha obtenido los tres grandes premios del genero en el mismo año." La obra breve de Ken Liu ha ganado todos los premios internacionales de prestigio y, lo que es mas importante, ha conquistado tambien y para siempre el corazon de los lectores de todo el mundo." Mariano Villarreal, Literatura Fantastica" A traves de todos estos cuentos, Liu utiliza tropos de la fantasia y la ciencia ficcion para explorar de forma profunda, inteligente y, en muchas ocasiones, tremendamente emotiva una gran diversidad de temas con la intencion final de arrojar un poco de luz sobre la gran pregunta de que significa ser humano Es una coleccion de relatos impresionante y no podeis perderosla." Elias Combarro, Sense of Wonder" Las historias incluidas en esta coleccion tratan una amplia variedad de temas, pero siempre estan relatadas con una voz clara y segura. Una coleccion imprescindible."" SF Signal"" Algunas de estas historias tienen un lado sombrio y a veces inquietante, casi todas son provocadoras y hay varias brillantes."" The Chicago Tribune"" Los maravillosos relatos de Liu exploran de forma elocuente el lu... (Fuente: La Casa del Libro).', 'El zoo de papel y otros relatos', 2.45, 6.59, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.03, 7.19, '8491296336', '9788491296331', 0, 88.04, 1.13, '2022-11-22', 'Stephen King y Richard Chizmar se unen una vez más para traernos el increíble desenlace de la historia que comenzaron con La caja de botones de Gwendy. Cuando tenía doce años, Gwendy Peterson conoció a Richard Farris, un tipo misterioso que le pidió que cuidara de una extraña caja de botones. Ahora, Gwendy es una afamada novelista y su carrera política está empezando a despegar. Parece que lo tiene todo a su alcance, pero entonces el insólito objeto vuelve a su vida. Las fuerzas del mal se han apoderado por completo de la caja de botones y ahora recae sobre Gwendy la responsabilidad de alejarlas de ella. ¿Su última misión? Salvar al mundo. Y puede que a todos los mundos. ENGLISH DESCRIPTION The final book in the New York Times bestselling Gwendy’s Button Box trilogy from Stephen King and Richard Chizmar. When Gwendy Peterson was twelve, a mysterious stranger named Richard Farris gave her a mysterious box for safekeeping. It offered treats and vintage coins, but it was dangerous. Pushing any of its eight colored buttons promised death and destruction. Years later, the button box reentered Gwendy’s life. A successful novelist and a rising political star, she was once again forced to deal with the temptation the box represented. Now, malignant forces seek to possess the button box, and it is up to Senator Gwendy Peterson to keep it from them at all costs. But where can one hide something from such powerful entities? In Gwendy’s Final Task, master storytellers Stephen King and Richard Chizmar take us on a journey from Castle Rock to another famous cursed Maine city to the MF-1 space station, where Gwendy must execute a secret mission to save the world. And, maybe, all worlds.', 'La última misión de Gwendy / Gwendy''s Final Task', 5.23, 7.95, 38, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.35, 1.18, '9788491730095', '8491730095', 274, 61.21, 1.39, '1970-02-06', '¡Por fin llega la novela de Ahsoka! ¡Descubre qué le ocurrió después de abandonar la Orden Jedi!Los fans llevan tiempo preguntándose qué le ocurrió a Ahsoka después de abandonar La Orden Jedi durante el fin de Las Guerras Clon y antes de reaparecer como el misterioso operativo Fulcrum en Rebels. Al fin, su historia será contada. Siguiendo sus vivencias con los Jedi y la devastación provocada por la Orden 66, Ahsoka siente que no podrá formar parte de otra alianza nunca más. Pero su deseo de combatir el mal del Imperio y proteger aquellos que lo necesitan la llevará hasta Bail Organa y la Alianza rebelde.', 'Ahsoka', 4.51, 8.61, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.79, 1.49, '9788491739050', '849173905X', 384, 58.04, 4.32, '1976-04-19', 'Inicio de la trilogía de Darth Bane (Camino de destrucción, Regla de dos y Dinastía del mal).Huyendo de las vengativas fuerzas republicanas, Dessel, un minero de cortosis, se enrola en las filas del ejército Sith, uniéndose a la sangrienta guerra contra la República y sus héroes Jedi. Allí, su brutalidad, astucia y excepcional dominio de la Fuerza le convierten rápidamente en un guerrero de renombre. Pero sus jefes, siempre vigilantes, creen que le aguarda un futuro mucho más brillante. Como acólito de la academia Sith, donde estudia los secretos y poderes del lado oscuro, Dessel adopta su nueva identidad: Bane. Pero la verdadera prueba aún está por llegar. Para poder ser aceptado en la Hermandad de la Oscuridad, deberá desafiar las tradiciones más secretas y rechazar todo lo que le han enseñado. Esta será una auténtica prueba de fuego en la que deberá entregarse por completo al lado oscuro–y hacer renacer de sus cenizas una nueva era de poder absolutoEl autor es guionista habitual de videojuegos, como Star Wars: Knights of the Old Republic o Mass Effect.', 'Camino de destrucción', 2.01, 1.95, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.23, 9.51, '9788491817345', '8491817344', 205, 85.28, 2.24, '1944-02-12', 'BENDITA SEA LA NORMA.EN LA PUREZA ESTÁ NUESTRA SALVACIÓN.¡CUIDADO CON LOS MUTANTES!Después de la Tribulación, una catástrofe apocalíptica que da lugar a mutaciones genéticas, las desviaciones de la norma son consideradas Blasfemias. Los animales y plantas que no tengan un aspecto normal son eliminados, y los humanos son expulsados a los Márgenes.Nadie sospecha en su aldea que David y Rosalind también son mutantes, pero a medida que se hacen mayores cada vez les resulta más difícil ocultar su propia aberración y se ven obligados a huir a las Malas Tierras para no ser descubiertos.', 'Las crisálidas', 8.27, 8.78, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.7, 4.24, '9788491876939', '8491876936', 0, 52.81, 3.7, '2007-03-14', 'Durante más de una década, un solo hombre aterrorizó a la ciudad de Nueva York colocando más de una treintena de bombas en lugares públicos, generalmente muy concurridos. A pesar de los indicios que dejaba en los escenarios del crimen y de los numerosos mensajes que firmaba como F. P., la policía siempre se mostró incapaz de averiguar su identidad. Como los métodos tradicionales fracasaban uno tras otro, al final se optó por probar algo atípico que la mayoría de los agentes consideraban absurdo: recurrir a un psiquiatra.Incendiario narra la increíble historia de un terrorista que la prensa de la época calificó como «la mayor amenaza individual a la que se haya enfrentado Nueva York». Pero también es el relato de la introducción del perfil criminal como herramienta de incalculable valor en las investigaciones policiales.A FINALES DE 1956, LA POLICÍA NEOYORQUINA IBA A CAMBIAR SU METODOLOGÍA PARA SIEMPRE', 'Amanecer rojo 1', 1.02, 2.6, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.66, 6.11, '9788491878346', '8491878343', 0, 53.55, 2.12, '2024-02-01', 'Chicago, 1931. Harper Curtis, un vagabundo violento, se topa con una casa que oculta un sorprendente secreto: es la puerta que lo traslada a otros momentos del tiempo para acechar a mujeres jóvenes que se le aparecen como "luminosas", rodeadas de una aureola especial que las convierte en el preciado objeto de sus instintos asesinos. Chicago, 1992. La vida de Kirby Mazrachi se ha trastocado tras el brutal intento de asesinarla. Mientras lucha por encontrar a su atacante, su único aliado es Dan, un antiguo periodista de homicidios que se ocupó del caso y que trata de protegerla de su obsesión. A medida que Kirby avanza en la investigación descubre a otras chicas, las que no lo lograron. Las pruebas de los crímenes son imposibles y la respuesta parece ocultarse en una casa abandonada en medio de la ciudad.', 'Las luminosas', 4.33, 8.17, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.25, 3.58, '9788492492251', '8492492252', 176, 59.85, 1.28, '1995-04-16', 'De David H. Keller nunca se había publicado ninguna antología en nuestro país. Esta primera incursión por nuestra parte repcopila una novela y ocho relatos de temas muy diversos, todos ellos fruto de las colaboraciones que nuestro autor realizó en las más importantes revistas de lo fantástico en la primera mitad del siglo pasado. Desde la novela Cazadoras solitarias, publicada en Weird Tales, que empieza siendo una novela policíaca que acaba convertida en un magnífico relato de terror (con todos los ingredientes del mejor género: amenazas sin fin, damiselas en apuros enemigos terribles y mortales, científico loco.), hasta el relato que cierra el volumen, recorremos muchos de los temas más queridos por nuestro autor y por todos los aficionados al terror, a la ciencia ficción y a lo fantástico más clasico.', 'Cazador solitario y otros cuentos de terror', 3.73, 8.42, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.71, 6.09, '9788492492701', '8492492708', 224, 10.05, 1.89, '1993-10-05', 'Hace ahora cien años que Edgar Rice Burroughs, un hombre apenas sin futuro en aquellos días, decidió volcarse en una nueva carrera: la de escritor profesional. Su primera obra le llevo´ a la fama. A partir de ese momento, todo para él fue un maravilloso viaje por la vida. Esta primera novela de su Serie Marciana once volúmenes llenos de aventura, intriga y, quizá, ciencia ficción nos lleva a recorrer un planeta Marte donde conviven multitud de razas de muy diversa índole, condición y colores, todas ellas enfrentadas en una serie continua de guerras y enfrentamientos. Allí´ es donde llega, huyendo de los apaches, nuestro héroe, John Carter, un soldado de la Confederación que decide hacerse buscador de oro (como su padre literario) cuando acaba la guerra entre los Estados y que se ve misteriosamente trasladado a un planeta Marte que no es otro que el Marte soñado por el astrónomo Percival Lowell, con sus canales y todo; un mundo lleno de vida. Las aventuras de John Carter le hacen encontrarse con la hermosa Dejah Thoris, princesa de Hélium, a quien, en una serie ininterrumpida de hechos trepidantes que le llevarán a recorrer todo el planeta, acabara´ encontrando y perdiendo en numerosas ocasiones. Su amor, capaz de romper la barrera que separa los mundos, nos hará descubrir todo el exotismo y variedad de ambientes de uno de los mundos alienígenas más coloridos que se han dado en la literatura. Una obra, esta Una princesa de Marte, que ha influenciado a toda una pléyade de escritores (desde Jack Vance a Leigh Brackett) y a una legión de narradores cinematográficos, desde La guerra de las galaxias hasta Avatar.', 'Bajo las lunas de Marte 1. Una princesa de Marte', 8.66, 3.09, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.13, 5.32, '9788492628902', '8492628901', 149, 72.95, 1.08, '1980-07-06', 'El año 2008 la Comunidad Autónoma de Canarias, con motivo del Día de las Letras Canarias, celebró al escritor grancanario Benito Pérez Galdós, y entre las distintas actividades y premios, organizó una visita al Madrid galdosiano guiada por el Catedrático de Literatura de la Universidad de LPGC, el Dr. Cabrera Perera.Compartí, con él y con los premiados, una jornada en la que recorrimos los distin-tos lugares que d. Benito frecuentara desde su llegada a la capital de España, el 30 de septiembre de 1862, hasta su muerte el día 4 de enero de 1920. La Puerta del Sol, los cafés, las célebres reboticas, el Ateneo, el Teatro Real, Lhardy, distintas ig-lesias, la Plaza Mayor, la calle Mayor, las tiendas de paños, la Cava de San Miguel. Disfrutamos leyendo los textos galdosianos, seleccionados por d. Antonio Cabrera, alusivos a todos y cada uno de los lugares y monumentos que visitamos. Fue como volver a la época en la que el novelista vivió Madrid.Fruto de aquel inolvidable viaje es este libro, una ruta galdosiana, escrita por el profesor Cabrera Perera, un entusiasta investigador del novelista, un experto y ena-morado de la literatura del Siglo de Oro español. Podemos decir que es el primer canario que nos invita, con este trabajo, a viajar al Madrid literario del escritor de las Islas más universal, d. Benito Pérez Galdós. Tenemos pues una nueva excusa para un viaje cultural y turístico, a través de las mejores páginas que el novelista escribiera sobre la historia de la ciudad de Madrid y de sus gentes. Pérez Galdós a su llegada a la capital va a participar vivamente de la vida madri-leña, conocerá los distintos ambientes sociales, políticos y literarios. En silencio, las más de las veces, d. Benito observará y escuchará a su alrededor. Madrid será el centro de su novela, la realidad de una sociedad que estrenaba una nueva clase social: la clase media española.Releer a Galdós, siguiendo sus pasos, es conocer el Madrid de su tiempo, el sentir de los vecinos, lo que se hablaba en las tertulias y salones, pero también lo que se conspiraba en los cafés, la moda de la capital de España, el ascenso de una clase so-cial que gasta lo que no tiene, el problema religioso y la educación de la mujer. Y siempre Pérez Galdós en su idea de “alumbrar la conciencia nacional, influir en el modo social de ser de los españoles y mejorar su índole política”, el llamado con acierto, por Armas Ayala, el “redentorismo galdosiano”. Todo ello fue y sigue siendo un atractivo para los lectores de su tiempo y para los de nuestros días. Con esta publicación sumamos un atractivo más, si aún cabe, a su reconocido legado literario y social.', 'Veinticuatro horas en el Madrid de Galdós', 3.35, 1.3, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.58, 8.57, '9788493603045', '849360304X', 351, 40.82, 3.61, '1979-09-23', '', 'Drácula', 4.49, 1.51, 145, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.44, 3.92, '8493700762', '9788493700768', 163, 90.29, 1.09, '1982-01-18', 'Es un libro para entender que hay viajes que nunca terminan, y otros que aún no han empezado. Para comprender que ninguna distancia es demasiado larga ni ninguna quimera demasiado imposible. Y que, como demostró Guevara, ninguna batalla está perdida.', 'Dónde estás Guevara?', 3.26, 7.52, 146, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.87, 8.66, '9788493739676', '8493739677', 288, 45.04, 3.74, '1942-10-27', 'Una noche, Sarah, una adolescente de carácter fantasioso, se ve obligada a quedarse en casa cuidando a Toby, su hermano pequeño. Cuando sus padres se marchan a una fiesta, harta de oír llorar al niño, Sarah recita unos versos de su libro favorito, Dentro del laberinto, y ordena a los goblins que se lleven a su hermano. Al momento, unas extrañas criaturas aparecen y se esfuman con Toby. Poco después, un hombre misterioso y atractivo surge de la nada y se presenta como Jareth, el rey de los goblins, para a continuación sugerirle a Sarah que se olvide del niño. Arrepentida de lo que ha hecho, Sarah le pide que le devuelva a Toby, pero el rey se niega. Entonces él le propone un trato: «Tienes trece horas para atravesar el laberinto y encontrar a tu hermano. De lo contrario, se convertirá en uno de nosotros». Y el tiempo apremia... Una novela con tintes de Alicia en el país de las maravillas y El mago de Oz, por la que desfilan extrañas criaturas, bailes de máscaras y, por encima de todo, interminables laberintos.', 'Dentro del laberinto', 2.8, 6.65, 147, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.9, 3.36, '9788493746636', '8493746630', 0, 87.9, 1.59, '2010-03-08', 'Professor Persikov, un irascible experto del Instituto Zoológico de Moscú, realiza un increíble descubrimiento: un rayo rojo de luz que posee el increíble poder de acelerar el crecimiento de cualquier célula viva. Al mismo tiempo, una misteriosa plaga destruye la población entera de pollos de la Unión Soviética. Cuando el rayo rojo de Persikov es incautado por el gobierno para recuperar la población de aves, el profesor se siente ultrajado, pero su enfado pronto muta a terror... En parte un relato satírico sobre la avaricia y la falta de escrúpulos del gobierno soviético, en parte un aviso terrorífico sobre los peligros de permitir que la tecnología caiga en manos poco científicas, la novela corta de Bulgákov Los huevos fatídicos (1925) es una obra maestra en miniatura del autor de El maestro y Margarita. Junto con Corazón de perro (1925), es una de las dos magníficas historias de ciencia ficción del autor, una recreación asalvajada sobre cómo, en un futuro cercano, el progreso puede caer en manos descontroladas, abocándonos al desastre. Escrita con la mezcla inimitable de Bulgákov de humor e indignación, esta breve obra merece su lugar junto a Nosotros de Yevgüeni Zamiatin o 1984 de George Orwell en su ataque a los abusos de cualquier estado totalitario, pero con una inesperada dosis de humor.', 'Estrella roja', 6.01, 9.2, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.31, 1.63, '9788493868925', '8493868922', 0, 14.62, 4.18, '1992-09-06', 'Procedentes de Alejandría, Flaubert y su amigo Maxime Du Camp emprenden en Beirut, ciudad de partida de esta segunda parte del Viaje a Oriente, un largo periplo que, del 19 de julio al 19 de diciembre de 1850, les llevará desde Líbano hasta El Pireo, pasando por Palestina, Siria, Asia Menor y Constantinopla. Como en las páginas consagradas a Egipto, el texto de esta segunda etapa sigue siendo lacónico, telegráfico a veces, cercano al prontuario y deslumbrante por momentos. Paisajes, creencias, gentes, ritos y costumbres cosechados por un escritor que, entre entusiasmado y contenido, trata de captar imágenes susceptibles de acrisolar la experiencia de su viaje por Oriente. Ilustrado con fotografías de Maxime Du Camp', 'Líbano-Palestina', 8.0, 5.19, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.01, 1.59, '9788493904401', '8493904406', 305, 14.85, 1.86, '2021-03-05', 'El Diente de la Ballena fue publicado por primera vez en 1999. Se trataba de un texto que seguía la senda de los dos grandes maestros de la literatura de viajes contemporánea en España: Manu Leguineche y Javier Reverte. Un relato, o mejor dicho, tres relatos cargados de empatía y sentido del humor, un recorrido por tres continentes, América, África y Asia, en los que el viajero nos conduce hasta algunos de los lugares más remotos de la Tierra al encuentro de sí mismo, a la búsqueda de un paraíso que no existe. Chema Rodríguez (Sevilla, 1967) es escritor y director de cine. Ha publicado los libros El Diente de la Ballena, El País-Aguilar (1999) y Anochece en la India, RBA (2003)', 'El diente de la ballena', 4.83, 8.82, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.21, 8.88, '8494234536', '9788494234538', 60, 92.65, 3.01, '2014-10-12', 'Sé Tao, sé feliz es un resumen de las principales ideas del Tao aplicadas a nuestra forma de vida actual para conseguir plenitud y adaptación a nuestro entorno. Conciso, preciso y práctico es una guía, sin pretensiones filosóficas, con herramientas para asumir nuestra realidad y a nosotros mismos.', 'Sé TAO, Sé Feliz', 7.98, 2.75, 148, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.15, 4.28, '8494426346', '9788494426346', 249, 89.49, 1.73, '2015-11-16', 'Cuando Simonetta Agnello Hornby llegó por primera vez a Londres, en septiembre de 1963, tenía dieciocho años. Y desde entonces no ha abandonado la ciudad, salvo para pasar los veranos en su Sicilia natal. Este libro es un homenaje a su ciudad: es el Londres de Simonetta Agnello Hornby, el Londres tolerante y democrático que recibe a la gente de todas las etnias y le da la posibilidad de trabajar, el Londres que no para de crecer y está en constante movimiento, el Londres que palpita y sorprende, y siempre está dispuesto a ofrecer algo nuevo al visitante. La autora acompaña al lector a los pequeños museos, a pasear por los parques, a sus librerías preferidas, a visitar determinados barrios de la ciudad como Brixton, donde ejerció de abogada durante unos años. Y no sólo eso, también describe cómo son los ingleses, cómo viven, qué comen y qué piensan, un retrato muy particular de la vida de los londinenses.', 'Mi Londres', 7.93, 8.19, 149, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.78, 2.94, '9788494445552', '8494445553', 312, 81.09, 3.13, '1986-04-17', 'La ciudad de Ávila y  su provincia tienen uno de sus mejores relatos en esta obra.Dioniso Ridruejo (1912-1975), acometió con el may or entusiasmo su guía personalde Castilla la Vieja. De Ávila nos dice Ridruejo que «el tremendo legado de sucantera histórica es tan solo belleza». Publicada originalmente a principios de losaños 70 y  hoy considerada un clásico insustituible, esta nueva edición del tomocorrespondiente a Ávila, con prólogo del Premio Cervantes José JiménezLozano, quiere dar a conocer la obra a los lectores de hoy  e invitarles a conocermejor Ávila y  su provincia de l a mano de su autor.Para Jiménez Lozano, este libro es «sin duda, la mejor compañía para visitar yconocer este territorio» cuy a capital  « parece contener entre sus murallas el mundo»[ INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.91, 9.02, '9788494474262', '849447426X', 168, 6.54, 1.33, '1984-08-12', 'Estos ocho relatos de terror tienen en común la angustiaque sufren los protagonistas de los mismos.', 'La transformación y tros Relatos de Terror', 7.74, 7.51, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.03, 3.32, '9788494486418', '8494486411', 390, 74.92, 3.12, '1987-02-26', 'Un apasionante relato de revelaciones sorprendentes', 'Proyecto Thule', 4.47, 7.99, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.34, 6.51, '9788494795848', '8494795848', 190, 16.26, 1.24, '1962-11-22', '"Binti: Hogar es la segunda parte de esta emocionante trilogía. Binti y Okwu llevan un año en la Universidad Oomza. Un año desde que Binti consiguiera la unión entre civilizaciones en guerra y desde que encontrara amistad en el lugar más inesperado.En esta ocasión, Binti tendrá que volver a casa con Okwu y enfrentarse a su familia y comunidad, además de hacer posible que, por primera vez en más de cien años, una medusa ponga pie en la Tierra para un fin que no sea la guerra."', 'Hogar', 9.16, 6.87, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.64, 8.18, '9788494836695', '8494836692', 265, 35.69, 3.01, '2006-09-27', 'Cuatro personajes llegan a un viejo y laberíntico caserón conocido como Hill House. Son el doctor Montague, un estudioso de lo oculto que busca pruebas de fenómenos psíquicos en casas encantadas, y tres personas a quienes el doctor ha reclutado para llevar a cabo un experimento. A pesar de las reticencias de su familia, Eleanor, una joven algo atormentada y de pasado infeliz, acabará formando parte de la singular comitiva. Los otros son Theodora, con quien Eleanor establece un fuerte vínculo inicial, y Luke, el heredero de la casa. Pronto todos deberán enfrentarse a situaciones que están más allá de su comprensión. Hill House parece estar preparándose para escoger a uno de ellos y hacerlo suyo para siempre. Llevada dos veces al cine e inspiración de una reciente serie televisiva, "La maldición de Hill House" es una de las novelas más famosas de Shirley Jackson y una de las principales obras de terror del siglo XX.', 'La maldición de Hill House', 3.66, 5.95, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.6, 3.93, '9788494976001', '8494976001', 421, 88.05, 1.88, '1992-04-28', 'YA EN 3ª EDICIÓN. El libro definitivo de uno de los mayores especialistas en la Raya, donde se describe el primer recorrido completo por la frontera hispano-portuguesa, población a población, desde Ayamonte hasta Caminha. Con un extenso y profundo epílogo del acreditado historiador César Rina y amplio reportaje gráfico de Esperanza Rubio.YA EN 3ª EDICIÓN. El libro definitivo de uno de los mayores especialistas en la Raya, donde se describe el primer recorrido completo por la frontera hispano-portuguesa, población a población, desde Ayamonte hasta Caminha. Con un extenso y profundo epílogo del acreditado historiador César Rina y amplio reportaje gráfico de Esperanza Rubio.Este itinerario completo por las dos caras de un mismo límite, el que separa España y Portugal, ofrece una nueva visión sobre la cicatriz de la Península Ibérica, un continuo gozne territorial tan inactual como profundamente rico. Entre lo cotidiano y lo histórico, lo paisajístico y lo atemporal, entre lo singular y lo turístico, su autor nos ofrece un retrato a pie de tierra de un mundo humano y espacial donde, precisamente por la omnipresencia de lo limítrofe, también se borra cualquier frontera y se asientan peculiares formas de vida en común. ~El libro definitivo de uno de los mayores especialistas en la Raya, donde se describe el primer recorrido completo por la frontera hispano-portuguesa, población a población, desde Ayamonte hasta Caminha. Con un extenso y profundo epílogo del acreditado historiador César Rina y amplio reportaje gráfico de Esperanza Rubio.«El mejor embajador de la raia…y quien mejor la conoce es quien mejor nos la hace sentir.»  ~Xosé Luis Vilela, director de La Voz de Galicia«Nadie puede quitarle el mérito de ser el primero en recorrer la Rayaen toda su extensión.»  ~Ángel Ortiz, director de El Norte de Castilla«Asomarse a la Raya, cruzarla y descruzarla…nos ha separado históricamente, pero nos une y nos define. Con José Ramón descubrimos un mundo que merece la pena.»  ~Manuela Martín, directora de Hoy de Extremadura«Un recorrido apasionante por la frontera que recorre la España vaciada…Una sorpresa continua.»  ~Álvaro Ybarra, director de ABC de Sevilla', 'Un viaje por la raya', 5.89, 3.47, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.24, 1.16, '9788494991349', '8494991345', 420, 18.09, 4.01, '1950-12-07', 'En efecto, la Biblia es el libro más leído de todos los tiempos, pero ninguna de las numerosas versiones que conocéis es la buena. ¿Por qué? Porque todas fueron escritas por hombres. Y como toda obra humana, está repleta de fallos, imperfecciones. La Biblia contiene numerosos errores históricos, científicos, geográficos, lingüísticos... y contradicciones.Ahora me dispongo a ofreceros la versión definitiva, la buena, la mía, la divina, la del protagonista: La Biblia contada por Dios, por @diostuitero. Tomad y leed.Si, seas creyente o no, desde pequeño te dijeron que todo era pecado. Quizás no todo lo que te contaron fuera cierto.¡Nunca pensaste que te reirías tanto con la biblia!', 'La Biblia Según Dios', 3.08, 2.94, 131, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.18, 2.68, '9788495572554', '8495572559', 55, 18.94, 3.86, '1966-09-22', '', 'La luz en el diván', 3.74, 8.29, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.68, 1.54, '9788496173729', '8496173720', 288, 3.19, 2.55, '1951-04-28', '"Como un elaborado hechizo mágico, cada novela de Sapkowski es una mezcla de fantasía, agudeza intelectual y humor lacónico."TIME MagazineEl esperado regreso de Geralt de Rivia con nuevas aventuras.La vida de un brujo cazador de monstruos no es fácil. Tan pronto puede uno tener que meterse hasta el cuello en un estercolero para eliminar a la bestia carroñera que amenaza la ciudad, intentado no atrapar una infección incurable, como se puede encontrar unido a la cacería de uno de los últimos dragones, en la que la cuestión no es si los cazadores conseguirán matar a la pobre bestia, sino qué pasará cuando tengan que repartirse el botín. Magos, príncipes, estarostas, voievodas, druidas, vexlings, dríadas, juglares y criaturas de todo pelaje pueblan esta tierra, enzarzados en conflictos de supervivencia, codicia y amor, y entre ellos avanza, solitario, el brujo Geralt de Rivia.La obra de Sapkowski ha sido uno de los mayores éxitos de ventas en Europa Central, con una versión en cómic, una superproducción cinematográfica polaca, Wiedzmin (Marek Brodzki, 2001), y una serie de televisión de la TVP."Uno de los personajes más ricos de la literatura de los últimos años... Destaca la perfección con la que Sapkowski cuenta estas historias... Estilo rápido y fácil de leer, y a la vez rico en detalles... Diálogos ingeniosos, finales sorprendentes y personajes tan bien caracterizados... Bienvenido, Geralt de Rivia."Solaris"Un soplo de aire fresco llega a la literatura fantástica de la mano de Sapkowski. Frente a los modelos heredados de la caballeresca europea y de la fantasía anglosajona, el autor nos acerca a la cultura eslava de la mano de Geralt de Rivia, el brujo mutante de cabellos blancos que se convierte en inquietante hilo conductor de relatos llenos de ironía y buen hacer. Verdaderamente, todo un descubrimiento para nosotros."Fnac.es"Una obra de altísima calidad literaria que brinda una nueva perspectiva y que se sitúa a la altura de las grandes creaciones del género con un delicioso y agudo sentido del humor, con un estilo narrativo ágil y absorbente que hace desear que la novela no termine nunca."Pasadizo.com', 'La espada del destino', 4.55, 1.07, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.79, 1.45, '9788496173811', '849617381X', 496, 3.45, 4.61, '2020-08-18', 'Entre las novelas de Robots y la serie de la Fundación se encuentra la Trilogía del Imperio: tres clásicas obras de Isaac Asimov donde se trazan los inicios de la expansión humana por la Galaxia hasta llegar al auge del Imperio Galáctico con capital en Trantor.En Polvo de estrellas, un ranchero de un mundo agrícola y la princesa de un sofisticado reino nebular deben unir sus fuerzas para tratar de encontrar el mundo rebelde que supone la última esperanza contra el tiránico imperio que los oprime.En Las corrientes del espacio, el descubrimiento de un espacioanalista pone en peligro la relación de dependencia entre Florina, el único planeta donde se cultiva el preciado kyrt, y sus amos de Sark, en un conflicto que afecta a la expansión del Imperio de Trantor.En Un guijarro en el cielo, un hombre de nuestros días se ve catapultado al futuro lejano, cuando el Imperio abarca la Galaxia y la Tierra no es más que una mota perdida entre millones de mundos habitados, que se mofan de sus pretensiones de ser el origen de la humanidad. Pero la Tierra prepara su venganza.', 'Trilogía del Imperio', 5.89, 2.23, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.89, 8.5, '9788496201460', '8496201465', 159, 28.61, 1.26, '2005-01-01', 'Teniu a les mans una petita joia; per primera vegada, a Cap de setmana a ciutat, Teresa Pàmies ens descobreix la Barcelona més catalana i universal alhora, i ho fa tan sols caminant-hi i mirant-la amb ulls ignorants però amorosos. El Museu d’Instruments Musicals a l’edifici modernista de Puig i Cadafalch a la Diagonal; el Palau Macaya, al passeig de Sant Joan; l’edifici de la Pia Almoina convertit en Museu Diocesà al Pla de la Catedral; el fastuós Museu Marés... Centenars de racons que amaguen la prodigiosa bellesa i la riquesa cultural que ofereix el cap i casal de Catalunya. No us ho perdeu!', 'Cap de setmana a ciutat', 1.65, 1.83, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.0, 6.49, '9788496509931', '8496509931', 68, 44.23, 4.1, '2008-01-01', 'Veintidós criaturas nos conducen al mundo perturbador del gran maestro de la narrativa fantástica. Las imágenes de Enrique Alcatena nos revelan las bestias más inquietantes del universo de H. P. Lovecraft en un descenso magistral hacia los abismos del terror.', 'Bestiario', 2.86, 2.33, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.38, 2.95, '9788496689251', '8496689255', 411, 8.5, 3.48, '2002-01-23', '', 'Mundo Anillo', 2.47, 6.39, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.16, 3.54, '9788496806924', '8496806928', 390, 64.57, 4.25, '2009-06-30', '', 'La huella de Babur / Babur''s trace', 8.59, 1.36, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.72, 1.71, '9788496822979', '8496822974', 0, 91.45, 3.49, '2010-04-26', 'Anthology of stories and paintings about pilgrimage to Santiago de Compostela.', 'Libro del Camino de Santiago', 2.21, 4.94, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.65, 5.57, '9788496964006', '8496964000', 248, 44.53, 1.22, '1974-03-17', 'Zane Grey compra en 1924 en Nueva Escocia una goleta de tres palos a la que bautiza con el nombre de Fisherman. Tras importantes trabajos de adaptación a la pesca deportiva, el navío desciende por la costa atlántica vía Cuba y Jamaica hasta Panamá, donde cruza el canal. Ya en el Pacífico, el 17 de enero de 1925, el famoso escritor se embarca junto a su hermano R.C., su quinceañero hijo Romer y unos cuantos amigos. Desde Balboa se dirigen a la isla del Coco, y desde allí a las desérticas Islas Galápagos, para regresar al continente por el Archipiélago de las Perlas.', 'Relatos de pesca en mares vírgenes', 4.98, 9.96, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.03, 2.25, '9788496964143', '8496964140', 236, 80.69, 4.07, '2008-02-13', 'Cuando el general británico Lionel C. Dunsterville (1865-1946) era un muchacho que residía en el colegio para hijos de oficiales de Westward Ho! conoció a Rudyard Kipling, el cual lo bautizaría con el nombre de Stalky en su famoso libro de aventuras juveniles Stalky & Cía (1899). Tras el colegio, Dunsterville inició en la academia de Sandhurst la que sería una larga y muy brillante carrera militar, que lo llevó a China, a la India y posteriormente (en la primera guerra mundial) a mandar en Persia una fuerza compuesta por tropas australianas, británicas, canadienses y neozelandesas que se bautizó popularmente como la “Dunsterforce”. Éste es el apasionante relato de su vida. ', 'Las aventuras de stalky', 2.66, 2.85, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.23, 2.07, '9788496964907', '8496964906', 336, 61.8, 3.32, '2016-06-02', 'Cuando el que fuera presidente de los Estados Unidos durante nueve años pierde la nominación a las elecciones presidenciales, decide emprender un viaje largamente aplazado a Sudamérica. Aprovechando la invitación de los gobiernos de Brasil y Argentina para dar unas conferencias, emprende rumbo Sur, y tras cumplir sus obligaciones se interna en las profundidades del continente y se une a un explorador y cartógrafo brasileño, Candido da Silva Rondón. Su objetivo es recorrer y cartografiar el río de la Duda (llamado en la actualidad río Roosevelt), cuyas fuentes habían sido descubiertas por el brasileño. Esta expedición, que se planteaba como un viaje de aventuras y caza (a la que era gran aficionado el norteamericano como había quedado patente en su viaje a África donde había cobrado más de 3000 piezas), se convierte en un viaje científico en condiciones muy penosas y que casi le cuesta la vida. Ediciones del Viento publica por primera vez en español este apasionante relato.', 'El Río de la Duda', 5.06, 8.78, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.1, 3.8, '9788498003031', '8498003032', 0, 89.1, 4.87, '1976-03-09', 'A William Kennedy no le van bien las cosas. La familia lo persigue, los fantasmas lo atormentan y vive obsesionado por esas canciones pop que uno no puede quitarse de la cabeza. Tiene 32 años, sigue enamorado de su ex mujer y acaba de perder su trabajo. Sueña con calles fantasmales, su aire acondicionado no funciona y en la radio ya no ponen buena música. Cuando su primo lo llama para hablarle de una chica muerta que ronda por su garaje, ayudarlo a salir del paso le parece una buena forma de ganar mil dólares... Pero las cosas no son tan sencillas, sobre todo con la familia de por medio, porque sus parientes muertos lo están buscando para pedirle explicaciones...', 'Círculo perfecto', 4.98, 3.68, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.05, 5.53, '9788498003185', '8498003180', 0, 70.47, 2.91, '1953-10-19', 'Glen Runciter ha muerto. ¿O lo han hecho todos los demás? Esta cáustica comedia metafísica de muerte y salvación (servida en cómodo aerosol) es un tour de force de amenaza paranoica y diversión sin trabas, en la que los fallecidos dan consejos comerciales, compran su siguiente encarnación y corren continuamente el riesgo de morir de nuevo. Philip K. Dick no alcanzó la cúspide de su fama hasta después de su muerte. Antes de ella, nos había ofrecido ya obras tan famosas como El hombre en el castillo, ¿Sueñan los androides con ovejas eléctricas? y Ubik, considerada la mejor de todas ellas. Además de haber inspirado multitud de «homenajes» cinematográficos no reconocidos por sus autores, películas como Blade Runner, Minority Report, Desafío total y Paycheck están basadas en su creación literaria.', 'Ubik', 8.89, 5.25, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.78, 9.11, '9788498003611', '849800361X', 0, 30.64, 5.0, '1946-03-15', 'Andrew Harlan ha cometido un crimen, pero su acto no es un simple delito. La ley que ha quebrantado es la más importante de todas para un Ejecutor: la ley que impide que miles de años de historia sean borrados y reescritos de forma irreversible por la guerra, la muerte y la decadencia. Ni siquiera la Eternidad, la organización a la que pertenece, puede detenerle.', 'El fin de la eternidad', 2.3, 7.07, 150, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.64, 2.58, '9788498004687', '8498004683', 0, 6.87, 2.02, '1998-05-11', 'Nicholas, tercer hijo del príncipe Arutha de Krondor, es un joven brillante y dotado, pero vive protegido en la corte de su padre. Para adquirir conocimientos sobre el mundo más allá de las murallas de palacio, Nicholas y su escudero se hacen a la mar en dirección a la bucólica Crydee. Y así comienza una aventura que colocará el destino de su patria encima de sus inseguros hombros.Nicholas emprende un largo y peligroso viaje durante el cual empieza a comprender lo que está en juego, y esta vez es mucho más que unas vidas o el destino del reino: detrás de un atajo de piratas asesinos se esconde una fuerza que pone en peligro todo el mundo de Midkemia. Y él está destinado a enfrentarse a esta terrible ame-naza.', 'El bucanero del rey', 6.5, 3.48, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.18, 4.92, '9788498005035', '8498005035', 0, 78.03, 1.71, '2004-06-19', 'Aunque sus abuelos fueron recluidos en su día en la colonia, Mannie nació libre y eso supone una gran diferencia. Como contratista privado, hace negocios con la Autoridad pero no figura en su nómina. El régimen de Luna es severo e injusto, la revolución se masca en el ambiente y se habla incluso de derrocar a la odiada Autoridad. Cuando Mannie ayuda a la preciosa Wyoming Knott a escapar de los guardaespaldas del Guardián, se encuentra de alguna manera en el centro de una rebelión sin esperanza. Aunque Mannie tiene un arma secreta: Mike es el ordenador más inteligente de la colonia, está conectado a toda clase de equipos útiles... Y Mannie es el mejor amigo de Mike.', 'La luna es una cruel amante 2o ed.', 9.61, 9.95, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.5, 6.94, '9788498005752', '8498005752', 320, 93.37, 1.95, '1961-10-05', 'Ronnie, de trece años, tiene un montón de problemas: mamá y papá se separan, su hermano Tim es un pelma, Melanie Ward o lo ama o lo odia, y le resulta cada vez más difícil seguir a Jesús. Además tiene que pasar todos los días por delante de la iglesia roja, donde se esconde el monstruo del campanario. El sheriff Littlefield también odia la iglesia; su hermano pequeño murió allí años atrás en un extraño accidente, y ahora él empieza a ver su fantasma. Archer McFall, el nuevo sacerdote, ha comprado la iglesia roja para albergar su Templo de los Dos Hijos. Los tres comparten un secreto de culpa y traición, un pecado que McFall y sus feligreses creen que solo hay una forma de lavar: con sangre.', 'La iglesia roja', 5.02, 6.92, 151, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.97, 4.24, '9788498006247', '8498006244', 0, 88.83, 1.04, '1935-02-21', '2016: Otro verano pasado por agua. Pero esta vez, la barrera de contención del Támesis cede y el centro de Londres se convierte en una marisma. Las aguas se retiran y la economía empieza a recuperarse, pero en cuestión de dos años, Londres y Nueva York se verán sumergidas bajo el mar. El papa se dirigirá por última vez a los fieles desde el Vaticano; la Meca también desaparecerá bajo las olas. El mundo se ahoga. Comienza una desesperada carrera por averiguar qué ocurre. El nivel de las aguas no deja de subir y la humanidad se retira a los puntos más altos del planeta. Comenzarán las guerras por ver quién domina las montañas.', 'Inundación', 2.52, 8.81, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.57, 4.19, '9788498007237', '8498007232', 0, 76.32, 1.0, '2011-10-07', 'Smoky Barnable es un joven anodino que viaja a pie desde la ciudad hasta un lugar de nombre Edgewood, que no figura en ningún mapa, con la intención de casarse con Daily Alice Drinkwater, tal y como le han profetizado. Es una historia épica de cuatro generaciones de una peculiar familia que vive en una casa que es muchas casas. Pero también es la historia de un amor fantástico, de una pérdida desgarradora, de cosas imposibles y destinos inamovibles, y de la visión de un futuro distópico en el que Estados Unidos es gobernado por un déspota siniestro.', 'Pequeño, grande', 1.57, 4.78, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.93, 8.61, '9788498026085', '8498026083', 544, 41.49, 3.91, '1959-11-20', '', 'Los Caballeros del Cielo', 7.94, 6.65, 152, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.64, 1.59, '9788498092547', '849809254X', 384, 8.74, 3.74, '2018-04-14', 'La col·lecció “Geografia literària” vol posar a l’abast d’un públic lector ampli una vasta antologia de paisatges i textos vinculats al territori. S’hi recullen poemes, narracions, cartes, notes de dietari, scenes teatrals, cançons i breus croniques periodístiques o de genere assagístic. La fesomia del país, la historia, les tradicions i els monuments hi apareixen interpretats pels nostres grans ecriptors amb el contrapunt atent de l’ull fotogràfic. Els textos ajuden a copsar el país, pero tambe el territori pot ajudar a entendre l’obra d’alguns escriptors. Amb els volums de la “Geografia literària” descobrirem, per tant, literatura i paisatge, trenats en una vasta antologia que Llorenç Soldevila ha elaborat amb rigor i ambició. Aquest volum que teniu a les mans està dedicat a la Barcelona vella, la de l’interior de les antigues muralles, i es complementarà amb un altre, Barcelona nova i el Barcelones, que abraçarà la ciutat i el seu entorn metropolità mes modern i cosmopolita.', 'La Barcelona Vella', 8.0, 6.63, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.51, 8.86, '9788498167825', '8498167825', 48, 70.6, 4.41, '2010-08-31', 'Basilio Villarino (1741-1785). España. Nació en La Coruña en 1741 y llegó al Río de la Plata en 1773 en la fragata Perpetua, al mando del capitán Bustillos. Su largo viaje por la Patagonia argentina comenzó en 1778, con la exploración de los ríos Colorado, Negro, Deseado y Limay, entre otros. En 1779 formó parte de la expedición de Francisco de Viedma, quien fundó Carmen de Patagones, y en 1782 recorrió las márgenes de los ríos Collón Curá y Negro, hasta la confluencia de éste con el Limay y el Neuquén. Tras el descubrimiento de la isla Choele Choel, en 1783, renunció a seguir su viaje de exploración ante la hostilidad de los indígenas. Murió en enero de 1785 a manos de los indios del Cacique Negro, en la expedición a la sierra de la Ventana. Este diario recoge las observaciones de Villarino en el curso de sus viajes.', 'Diario De La Navegacion Emprendida En 1781/ Journal of the Voyage Undertaken in 1781', 3.93, 6.66, 153, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.1, 4.29, '9788498215182', '8498215188', 293, 91.86, 3.68, '1958-07-22', 'AMBROSÍA Diecinueve años después... La coronación de Nathan Nekhbet estuvo envuelta de un gran ambiente festivo. Su padre, Halmir, había estado gobernando como regente de su hijo por ser éste menor de edad. Ahora, le entrega el testigo porque considera que su hijo está preparado para gobernar solo. La ceremonía siguió las costumbres ancestrales y sus rituales transcurrieron con toda su magnificiencia. Lucien, como madre de Nathan y sacerdotisa de la Orden de los Iniciados, hizo entrega a su hijo de los tributos reales: La Túnica Sagrada y la Espada Ceremonial. Unos de los momentos más esperados por todos era el pronunciamiento del heraldo, éste leyó los títulos que le correspondían: rey de reyes, rey de Jhodam, Sumo Sacerdote de Jhodam entre otros títulos. Al finalizar la ceremonia, Exius como custodio del Tributo Real, colocó la corona de oro sobre la cabeza de Nathan. A partir de ese momento, toda la ciudad estalló en un gran jubilo y las festividades duraron varios días. Comenzaba así, una nueva dinastía. Los Falcon se extinguieron con la muerte de Nathan Falcon. Ahora, era el momento de los Inmortales, el reino de Jhodam pasaba a ser propiedad de la legendaria e inmortal Dinastía Nekhbet. Fue Halmir quién trasmitió el Legado Inmortal Nekhbet a su segundo hijo: Nathan Nekhbet, rey de Jhodam.', 'El último dios', 9.29, 8.64, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.39, 9.67, '9788498381269', '8498381266', 256, 39.87, 1.65, '2012-09-24', 'Joven estudiante de Bellas Artes en la Universidad de Toulouse, Fabienne Verdier emprendió en 1983 un viaje a China, donde quedó fascinada por un arte milenario: la caligrafía. No sólo era el primer occidental que entraba en la provincia de Sichuan desde 1949, sino que no hablaba chino y el partido comunista había prohibido a los estudiantes relacionarse con extranjeros. Además, la caligrafía había sido condenada por la Revolución Cultural en nombre del «progreso y la modernidad». Sin embargo, Verdier se enfrentó a todos los obstáculos y, tras una ardua lucha burocrática, consiguió que le permitieran estudiar con el profesor Huang Yuan, uno de los más insignes maestros de caligrafía, que trabajaba marginado en la clandestinidad. En compañía de Yuan, Verdier viajó a zonas del país prohibidas a los extranjeros y conoció a ancianos artistas que la iniciaron en los secretos y códigos de la caligrafía. Así, lo que había comenzado como una simple y breve aventura se transformó en un largo periodo de aprendizaje que duraría diez años, los diez años más apasionantes de su vida.Relato de iniciación que se lee como una novela de aventuras, Pasajera del silencio es al mismo tiempo un emocionado homenaje a los últimos maestros de la caligrafía y un testimonio único sobre una China desconocida para los occidentales.', 'Pasajera del silencio', 5.72, 5.16, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.48, 9.4, '9788498387360', '8498387361', 0, 43.73, 2.98, '1951-02-23', '"Neil Gaiman nos presenta una coleccion de veinticinco relatos y poemas que puede entenderse como una suma de esencias o festin creativo de uno de los escritores de imaginacion mas fertil e inquietante de la actualidad. Un menu degustacion que concentra todo el potencial fantasioso y onirico de Gaiman: historias de terror y de fantasmas, ficcion especulativa y cuentos de hadas, fabulas perversas y versos sorprendentes."--provided by Amazon.com.', 'Material sensible', 2.17, 4.43, 154, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.67, 8.0, '9788498677928', '8498677920', 144, 24.97, 3.95, '1936-08-03', 'Dicen que Roma es la Ciudad Eterna, tal vez porque el tiempo la atraviesa con lentitud. Es caótica y, sin embargo, pausadamente melancólica. Acumula un escepticismo de siglos pero mantiene la luminosa viveza del Mediterráneo. Es una ciudad en la que abundan los lugares y los instantes mágicos. En sus páginas encontrará el lector un montón de estupendas historias, personajes, momentos y escenarios romanos: los gatos, las pinturas de Caravaggio, la casa y la tumba del poeta Keats, la cocina de casquería, la mejor pizzería, el lugar en el que se bebe el café más sublime del mundo, la burocracia, Alberto Sordi, el cadáver de Aldo Moro, la historia de un marqués perverso, mirón, asesino y suicida, el periplo de un paquete que recorre medio mundo y vuelve a Roma gracias al disparatado servicio de correos, los papas, Berlusconi y sus emisarios, una iglesia en la que nadie quiere casarse, las fórmulas de cortesía, el fútbol, la mamma, las conspiraciones, el sastre de los papas, las barberías, los palacios, las vírgenes, los santos y los milagros, la cúpula de San Pedro entre la niebla... Roma, la ciudad que se añora a sí misma, la ciudad en la que todavía se vislumbran escenas que deberían ser en blanco y negro, retratada por un autor que ya nos regaló sus estupendas visiones de Londres y Nueva York.', 'Historias de Roma', 6.53, 1.23, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.58, 4.6, '8498832500', '9788498832501', 198, 46.11, 3.44, '1956-07-24', 'Aquest dietari del P. Bonaventura Ubach (1897-1960) conté el relat del viatge realitzat a Mesopotàmia els anys vint, redactat a partir de les notes de la seva agenda, ampliades quan, a partir de 1951, era ja a Montserrat. La relació va acompanyada d''una abundant documentació fotogràfica, reproduïda aquí integrament. Hi trobem presents molts costums arcaics de l''antic Orient, conservats encara aleshores, i també diverses mostres del folklore oriental. En el relat d''aquest viatge, el lector trobarà el P. Ubach estudiant sisíac entre Damasc i Palmira, abans de seguir-lo a Bagdad on s''establí durant set mesos. Des d''allí realitzà expedicions a Babilònia, Ur dels Caldeus, Bàssora, Pèrsia, Mossul, Nínive i part del Kurdistan, tot resseguint sovint les voreres dels rius Tigris i Eufrates, ajudat de vegades pels beduins del desert. Moltes anècdotes sorprenents en fan la lectura amena i agradable.', 'Dietari d''un viatge per les regions de l''Iraq (1922-1923)', 8.99, 7.51, 155, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.27, 9.71, '9788498890372', '8498890373', 256, 40.33, 3.47, '1937-09-03', 'Geralt de Rivia, brujo y mutante sobrehumano, se gana la vida como cazador de monstruos en una tierra de magia y maravilla: con sus dos espadas al hombro -la de acero para hombres, y la de plata para bestias- da cuenta de estriges, manticoras, grifos, vampiros, quimeras y lobisomes, pero sólo cuando amenazan la paz. Irónico, cínico, descreído y siempre errante, sus pasos lo llevan de pueblo en pueblo ofreciendo sus servicios, hallando las más de las veces que los auténticos monstruos se esconden bajo rostros humanos. En su camino sorteará intrigas, elegirá el mal menor, debatirá cuestiones de precio, hollará el confín del mundo y realizará su último deseo: así comienzan las aventuras del brujo Geralt de Rivia.Andrzej Sapkowski es el gran renovador de la literatura fantástica de nuestros tiempos, un genio del lenguaje y la caracterización cuya prosa ya ha hechizado a millones de lectores en todo el mundo.', 'El último deseo', 2.58, 1.65, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.11, 7.87, '9788498890433', '8498890438', 288, 46.91, 2.31, '1948-08-19', 'La vida de un brujo cazador de monstruos no es fácil. Tan pronto puede uno tener que meterse hasta el cuello en un estercolero para eliminar a la bestia carroñera que amenaza la ciudad, intentado no atrapar una infección incurable, como se puede encontrar unido a la cacería de uno de los últimos dragones, en la que la cuestión no es si los cazadores conseguirán matar a la pobre bestia, sino qué pasará cuando tengan que repartirse el botín. Magos, príncipes, estarostas, voievodas, druidas, vexlings, dríadas, juglares y criaturas de todo pelaje pueblan esta tierra, enzarzados en conflictos de supervivencia, codicia y amor, y entre ellos avanza, solitario, el brujo Geralt de Rivia.Andrzej Sapkowski es el gran renovador de la literatura fantástica de nuestros tiempos, un genio del lenguaje y la caracterización cuya prosa ya ha hechizado a millones de lectores en todo el mundo.', 'La espada del destino', 5.12, 6.37, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.37, 4.06, '9788498890457', '8498890454', 256, 86.31, 3.52, '2013-11-13', '"En verdad os digo que se acerca el tiempo de la espada y el hacha, la época de la tormenta salvaje. Se acerca el Tiempo del Invierno Blanco y de la Luz Blanca. El Tiempo de la Locura y el Tiempo del Odio, el Tiempo del Fin. El mundo morirá entre la escarcha y resucitará de nuevo junto con el nuevo sol. Resucitará de entre la Antigua Sangre, de Hen Ichaer, de la semilla sembrada. De la semilla que no germina sino que estalla en llamas. ¡Así será! ¡Contemplad las señales! Qué señales sean, yo os diré: primero se derramará sobre la tierra la sangre de los Aen Seidhe, la Sangre de los Elfos."Aen Ithlinnespeath, profecía de Ithlinne Aegli aep AevenienAndrzej Sapkowski es el gran renovador de la literatura fantástica de nuestros tiempos, un genio del lenguaje y la caracterización cuya prosa ya ha hechizado a millones de lectores en todo el mundo.', 'La sangre de los elfos', 4.81, 6.5, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.07, 4.76, '9788498890495', '8498890497', 496, 35.22, 1.11, '1956-02-24', 'Entre las novelas de Robots y la serie de la Fundación se encuentra la Trilogía del Imperio: tres clásicas obras de Isaac Asimov donde se trazan los inicios de la expansión humana por la Galaxia hasta llegar al auge del Imperio Galáctico con capital en Trantor.En Polvo de estrellas, un ranchero de un mundo agrícola y la princesa de un sofisticado reino nebular deben unir sus fuerzas para tratar de encontrar el mundo rebelde que supone la última esperanza contra el tiránico imperio que los oprime.En Las corrientes del espacio, el descubrimiento de un espacioanalista pone en peligro la relación de dependencia entre Florina, el único planeta donde se cultiva el preciado kyrt, y sus amos de Sark, en un conflicto que afecta a la expansión del Imperio de Trantor.En Un guijarro en el cielo, un hombre de nuestros días se ve catapultado al futuro lejano, cuando el Imperio abarca la Galaxia y la Tierra no es más que una mota perdida entre millones de mundos habitados, que se mofan de sus pretensiones de ser el origen dela humanidad. Pero la Tierra prepara su venganza.', 'Trilogía del imperio', 9.21, 4.95, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.24, 7.61, '9788498890532', '8498890535', 272, 62.5, 4.78, '2010-11-02', '"Decir que la conocí sería una exageración. Pienso que, excepto el brujo y la hechicera, nadie la conoció de verdad jamás. Cuando la vi por vez primera no me causó especial impresión, incluso pese a las extraordinarias circunstancias que lo acompañaron. Sé de algunos que han afirmado que al instante, a primera vista, percibieron el hálito de la muerte que seguía a esta muchacha. A mí sin embargo me pareció completamente normal, y ya por entonces sabía yo que no era normal, por eso me esforcé en mirar, descubrir, percibir lo extraordinario en ella. Pero nada vi y nada percibí. Nada que pudiera haber sido señal, presentimiento ni profecía de los trágicos acontecimientos posteriores. Aquéllos de los que fue causa. Y aquéllos que ella misma provocó."Jaskier, Medio siglo de poesíaAndrzej Sapkowski es el gran renovador de la literatura fantástica de nuestros tiempos, un genio del lenguaje y la caracterización cuya prosa ya ha hechizado a millones de lectores en todo el mundo.', 'Tiempo de odio', 7.56, 3.06, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.14, 6.67, '9788498890549', '8498890543', 256, 29.17, 3.56, '2010-11-02', 'Entonces le dijo la profetisa al brujo: "Este consejo te doy: ponte botas de yerro, toma en la mano un bastón de yerro. Ve con tus botas de yerro hasta el fin del mundo y por el camino agita el bastón y riega todo con lágrimas. Ve a través de la agua y el fuego, no te detengas ni mires a tu alredor. Y cuando las almadreñas se te desgasten, cuando el bastón de yerro se deshaga, cuando el viento y el calor te sequen los ojos de tal forma que de ellos ni una lágrima acierte a escapar, entonces, en el fin del mundo, hallarás lo que buscas y lo que amas. Pudiera ser".Y el brujo cruzó la agua y el fuego, sin mirar a su alrededor. Pero no se puso botas de yerro ni tomó bastón. Sólo llevó su espada de brujo. No escuchó las palabras de la profetisa. Y bien que hizo, porque era una mala profetisa.', 'Bautismo de fuego', 7.27, 6.21, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.99, 3.23, '9788498890570', '8498890578', 336, 93.94, 1.73, '2011-03-08', '"-Puedo darte todo lo que desees -dijo el hada-. Riqueza, poder y cetro, fama, una vida larga y feliz. Elige.-No quiero riqueza ni fama, poder ni cetros -respondió la bruja-. Quiero un caballo que sea negro y tan imposible de alcanzar como el viento de la noche. Quiero una espada que sea luminosa y afilada como los rayos de la luna. Quiero atravesar el mundo en la oscura noche con mi caballo negro, quiero quebrar las fuerzas del Mal y de la Oscuridad con mi espada de luz. Eso es lo que quiero.-Te daré un caballo que será más negro que la noche y más ligero que el viento de la noche -le prometió el hada-. Te daré una espada que será más luminosa y afilada que los rayos de la luna. Pero no es poco lo que pides, bruja, habrás de pagármelo muy caro.-¿Con qué? En verdad nada tengo.-Con tu sangre."Flourens Delannoy, Cuentos y leyendas', 'La torre de la golondrina', 1.59, 6.19, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.53, 2.01, '9788498890624', '8498890624', 464, 42.61, 1.81, '1981-11-28', '"De las llamitas, algunas altas y poderosas eran, vivamente brillaban y con claridad, otras por su parte eran pequeñas, vacilantes y temblorosas, y oscurecíase su luz y amortiguábase a trechos. En el mismo final había una llamita pequeña y tan débil que apenas ardía, apenas se removía, ora brillando con gran esfuerzo, ora casi, casi apagándose del todo. -¿De quién es ese fueguecillo moribundo? -preguntó el brujo.-Tuyo -respondió la Muerte." Flourens Delannoy, Cuentos y leyendasAndrzej Sapkowski es el gran renovador de la literatura fantástica de nuestros tiempos, un genio del lenguaje y la caracterización cuya prosa ya ha hechizado a millones de lectores en todo el mundo.', 'La dama del lago', 2.51, 1.29, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.43, 8.95, '9788498890969', '8498890969', 299, 63.9, 2.58, '2020-06-14', 'Poco sabía el brujo Geralt de Rivia lo que le esperaba al acudir a la villa costera de Kerack. Primero fue acusado injustamente de desfalco, luego fue misteriosamente liberado bajo fianza, y finalmente descubrió que sus preciadas espadas, dejadas en depósito al entrar en la ciudad, habían desaparecido. Demasiadas casualidades, en efecto, y máxime cuando tras ellas está la atractiva hechicera Lytta Neyd, llamada Coral.De esta manera, Geralt de Rivia se encuentra de nuevo implicado en los escabrosos asuntos de los magos, y ni la fiel (aunque ocasionalmente engorrosa) compañía del trovador Jaskier, ni el recuerdo de su amada Yennefer, ni toda su fama como implacable cazador de monstruos podrán evitar que se vea cada vez más envuelto en una oscura trama. Más bien al contrario.', 'Estación de tormentas', 1.07, 8.83, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.92, 6.7, '9788498891096', '8498891094', 0, 50.46, 1.74, '1988-01-01', '?Puedo darte todo lo que desees ?dijo el hada?. Riqueza, poder y cetro, fama, una vida larga y feliz. Elige. ?No quiero riqueza ni fama, poder ni cetros ?respondió la bruja?. Quiero un caballo que sea negro y tan imposible de alcanzar como el viento de la noche. Quiero una espada que sea luminosa y afilada como los rayos de la luna. Quiero atravesar el mundo en la oscura noche con mi caballo negro, quiero quebrar las fuerzas del Mal y de la Oscuridad con mi espada de luz. Eso es lo que quiero. ?Te daré un caballo que será más negro que la noche y más ligero que el viento de la noche ?le prometió el hada?. Te daré una espada que será más luminosa y afilada que los rayos de la luna. Pero no es poco lo que pides, bruja, habrás de pagármelo muy caro. ?¿Con qué? En verdad nada tengo. ?Con tu sangre. Flourens Delannoy, Cuentos y leyendas Andrzej Sapkowski es el gran renovador de la literatura fantástica de nuestros tiempos, un genio del lenguaje y la caracterización cuya prosa ya ha hechizado a millones de lectores en todo el mundo.', 'La Torre de la Golondrina', 6.92, 2.55, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.02, 6.19, '9788498891157', '8498891159', 264, 68.01, 4.12, '1950-03-26', '"Charlie Gordon está a punto de iniciar un viaje sin precedentes. Nacido con un cociente intelectual anormalmente bajo, lo han elegido como perfecto sujeto de pruebas para una cirugía experimental que, de funcionar, aumentará su inteligencia. El método ya ha dado un resultado espectacular al ser aplicado a un ratón de laboratorio llamado Algernon. Según hace efecto el tratamiento, la inteligencia de Charlie se expande hasta sobrepasar la de los propios doctores que produjeron su metamorfosis. El experimento parece ser un logro científico de primer orden, hasta que Algernon comienza a sufrir inesperadas consecuencias. ¿Le pasará lo mismo a Charlie? Daniel Keyes obtuvo el prestigioso premio Nebula con esta novela, que en su versión corta recibió también el popular premio Hugo, y que fue llevada al cine como Charly. Flores para Algernon es un clásico de la ciencia-ficción, y uno de los libros más vendidos de la historia del género. "', 'Flores para Algernon', 2.78, 4.16, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.57, 1.09, '9788498891355', '8498891353', 336, 50.84, 2.5, '1948-01-23', 'Una torre que se alza sobre la llanura mesopotámica hasta tocar la bóveda del cielo. Dos hombres que alcanzan un grado de inteligencia tan alto que se asemejan a dioses. La prueba de que las matemáticas carecen de sentido. Un lenguaje alienígena que permite a quienes lo leen expandir su consciencia a lo largo del tiempo. La cábala y la teoría de la preformación se combinan en una Inglaterra victoriana salida de nuestros sueños, o de nuestras pesadillas. Ante la llegada de los metahumanos, la ciencia humana se ve reducida a una nota a pie de página. En un universo donde Dios existe sin que quepa ninguna duda, ¿es posible no amarle? Y si pudieras programarte para ignorar las apariencias, ¿te arriesgarías a perder toda percepción de la belleza humana?Ted Chiang, galardonado con el premio John W. Campbell Jr., brilla como una nova en el firmamento de la ciencia-ficción. Con un premio Hugo, tres Nebula, un Sturgeon, un Kurd Lasswitz, dos Seiun, un Sidewise y dos Locus, La historia de tu vida es un libro imprescindible.En 2016, el relato que da nombre a esta antología ha sido llevado al cine bajo el título La llegada (por Denis Villeneuve, con Amy Adams y Jeremy Renner), cosechando un enorme éxito mundial y lanzando a Ted Chiang al estrellato de los autores de ciencia-ficción mejor', 'LA HISTORIA DE TU VIDA/ STORIES OF YOUR LIFE AND OTHERS.', 9.48, 5.98, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.41, 7.56, '9788498975161', '8498975166', 74, 14.41, 2.16, '2010-08-31', 'Felix de Azara, 18 de mayo de 1742 (Barbunales, Huesca)-1821. (Espana.) Fue militar, ingeniero, explorador, cartografo, antropologo y naturalista. Estudio en la universidad de Huesca y en la Academia militar de Barcelona donde se graduo en 1764. Sirvio en el regimiento de infanteria de Galicia y obtuvo el grado de lugarteniente en 1775. Siendo herido en la guerra de Argel, sobrevivio de milagro. Asimismo rechazo en 1815 la Orden de Isabel la Catolica en protesta por los ideales absolutistas imperantes en Espana. Mediante el tratado de San Ildefonso (1777), Espana y Portugal fijaron las fronteras de sus dominios en America del Sur y Azara fue elegido como uno de los cartografos encargados de delimitar con precision las fronteras. Marcho a Sudamerica en 1781 para una mision de algunos meses y vivio alli veinte anos. Al principio se establecio en Asuncion, Paraguay, para realizar los preparativos necesarios y esperar al comisario portugues. Sin embargo, pronto se intereso por la fauna local y comenzo a estudiarla acumulando el extenso archivo que mas tarde conformo los cimientos de su obra cientifica. Cabe anadir, ademas, que colaboro con Jose Artigas en el establecimiento de pueblos en las fronteras entre la Banda Oriental (actual Uruguay) y el Imperio del Brasil. Azara murio en Espana en octubre de 1821, victima de una pulmonia; fue tambien conocida su amistad con Goya, quien pinto un retrato suyo.', 'Correspondencia Oficial', 4.24, 1.13, 156, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.84, 5.83, '9788499232836', '8499232833', 336, 20.32, 3.9, '2010-05-10', '', 'Gotzon Mantuliz. Diario de un conquistador.', 6.34, 1.72, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.5, 2.0, '8499420087', '9788499420080', 288, 25.36, 4.4, '1970-10-08', 'Pilar de la narrativa francesa de la primera mitad del siglo XX, Gide es toda una literatura. Su talento y su agudeza para la observación han hecho de sus obras una referencia obligada para lectores de varias generaciones. Habitante actual del purgatorio de los escritores, su prosa, sin embargo, merece salir del olvido y encabezar la lista de escritores que han aportado una visión radical (moral) del mundo. Este Viaje al Congo que ahora proponemos, es una excelente oportunidad para (re)descubrir a Gide. Un escritor que comprendió, viajando, viviendo, sufriendo y amando, la importancia del punto de vista. Miremos a través de Gide. Un autor, imprescindible, que nunca decepciona.Los editores', 'Viaje al Congo', 9.6, 1.19, 157, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (6.46, 4.59, '9789176372951', '9176372952', 618, 3.61, 1.26, '2017-09-15', 'The Iliad is an ancient Greek epic poem in dactylic hexameter, traditionally attributed to Homer. Set during the Trojan War, the ten-year siege of the city of Troy (Ilium) by a coalition of Greek states, it tells of the battles and events during the weeks of a quarrel between King Agamemnon and the warrior Achilles.', 'The Iliad (Wisehouse Classics Edition)', 2.3, 2.49, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.26, 7.31, '9789290929536', '9290929537', 81, 77.01, 2.64, '2023-02-23', '"Publication stock no. BKK125168"--Verso of title page.', 'Developing Indicators and Monitoring Systems for Environmentally Livable Cities in the People''s Republic of China', 9.53, 4.47, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.54, 2.42, '9789292574550', '9292574558', 80, 58.62, 1.81, '2014-05-10', 'Better transport is essential to Myanmar''s development. After decades of underinvestment, Myanmar''s transport infrastructure lags behind other regional countries. Sixty percent of trunk highways and most of the railways need maintenance or rehabilitation. River infrastructure does not exist, while 20 million people lack basic road access. Can the transport sector deliver the master plan''s objectives? What is needed to improve the quality of the infrastructure and services for the industry? How can basic transport services be provided to all? How can Myanmar reduce the economic and social cost of transport? The MyanmarTransport Sector Policy Note is composed of a series of 9 reports.', 'Myanmar Transport Sector Policy Note', 8.37, 8.74, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.76, 1.11, '9789292574635', '9292574639', 70, 82.56, 1.75, '1973-04-11', 'Better transport is essential to Myanmar''s development. After decades of underinvestment, Myanmar''s transport infrastructure lags behind other regional countries. Sixty percent of trunk highways and most of the railways need maintenance or rehabilitation. River infrastructure does not exist, while 20 million people lack basic road access. Can the transport sector deliver the master plan''s objectives? What is needed to improve the quality of the infrastructure and services for the industry? How can basic transport services be provided to all? How can Myanmar reduce the economic and social cost of transport? The MyanmarTransport Sector Policy Note is composed of a series of 9 reports.', 'Myanmar Transport Sector Policy Note', 2.47, 8.99, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.77, 8.5, '9789292574697', '9292574698', 90, 46.7, 1.45, '1987-09-28', 'The Asian Development Bank (ADB) recorded $2.47 billion in clean energy investments in 2015, making this the fifth year in a row where investments in this sector have been above the $2 billion annual target. This report summarizes the investments in clean energy made by ADB in 2015, condensing information from project databases and formal reports into an easy-to-reference format. This report was prepared by ADB''s Clean Energy Program which provides the cohesive agenda that encompasses and guides ADB''s lending and nonlending assistance, initiatives, and plan of action for sustainable growth in Asia and the Pacific.', '2015 Clean Energy Investments', 9.36, 7.9, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.62, 5.22, '9789292574772', '9292574779', 42, 3.52, 4.53, '1979-04-21', 'The rapid growth of urban areas in Asia has often resulted in poorly designed infrastructure in hazard-prone areas. This has increased the risk of disasters resulting from natural hazards. The intensity and frequency of climate-related hazards are increasing, further exacerbating the risk. Better understanding of disaster risk by urban stakeholders and the use of this information by governments to develop policies, regulations, and fi nancing is needed. This publication summarizes the experiences of three areas that have provided incentives for disaster risk reduction. Case studies are presented from Da Nang in Viet Nam, Kathmandu Valley in Nepal, and Naga City in the Philippines.', 'Incentives for Reducing Disaster Risk in Urban Areas', 7.58, 7.78, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.2, 8.83, '9789292574833', '9292574833', 108, 50.01, 4.27, '1941-11-09', 'Better transport is essential to Myanmar''s development. After decades of underinvestment, Myanmar''s transport infrastructure lags behind other regional countries. Sixty percent of trunk highways and most of the railways need maintenance or rehabilitation. River infrastructure does not exist, while 20 million people lack basic road access. Can the transport sector deliver the master plan''s objectives? What is needed to improve the quality of the infrastructure and services for the industry? How can basic transport services be provided to all? How can Myanmar reduce the economic and social cost of transport? The Myanmar Transport Sector Policy Note is composed of a series of 9 reports.', 'Myanmar Transport Sector Policy Note', 4.88, 4.97, 5, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.03, 4.56, '9789292576691', '9292576690', 118, 45.66, 2.83, '2003-05-26', 'The provision of water supply and sanitation services is vulnerable to projected changes in climate conditions, in the frequency and intensity of extreme weather events, and in the projected rise in sea-level and intensification of storm surges. Accounting for climate change at the outset of the project cycle implies that decisions about project design and climate-proofing measures are informed of the possible impacts of climate change in the initial phases of the project so that costly decisions are avoided. This publication presents a step-by-step methodological approach to managing climate change risk in the context of water supply and sanitation investment projects.', 'Guidelines for Climate Proofing Investment in the Water Sector', 4.6, 8.07, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.69, 9.87, '9789292576998', '9292576992', 51, 99.51, 2.77, '1991-01-22', '"Publication Stock No. RPT168579-2"--Verso of title page.', 'Open Windows, Closed Doors', 9.08, 4.02, 10, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (2.85, 6.54, '9789292577018', '9292577018', 0, 45.35, 2.14, '2016-12-30', 'The People''s Republic of China (PRC) is undergoing several structural and cyclical changes, which have wide-ranging implications for economic activity in the PRC, the rest of developing Asia, and the world. This report assesses the effects of these changes by looking closely at various channels of transmission including commodity prices, trade, and production. The PRC''s continued growth moderation could knock off a third of a percentage point a year in growth for the rest of developing Asia over the next 2 years. Thisreport discusses how developing Asia''s policy -makers can respond to the challenges and opportunities presented by these changes.', 'Structural Change and Moderating Growth in the People''s Republic of China', 8.37, 3.86, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.99, 5.65, '9789292577216', '9292577212', 0, 43.89, 3.31, '2017-08-30', 'Catastrophic floods, droughts, and cyclones have plagued Pakistan in recent years. The 2010 flood killed 1,600 people and caused around $10 billion in damage. The 2015 Karachi heat wave led to the death of more than 1,200 people. Climate change-related natural hazards may increase in frequency and severity in the coming decades. Climatic changes are expected to have wide-ranging impacts on Pakistan, affecting agricultural productivity, water availability, and increased frequency of extreme climatic events. Addressing these risks requires climate change to be mainstreamed into national strategy and policy. This publication provides a comprehensive overview of climate change science and policy in Pakistan.', 'Climate Change Profile of Pakistan', 5.48, 1.0, 158, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.46, 3.31, '9789292579111', '9292579118', 394, 17.76, 4.15, '1990-12-14', 'Asia and the Pacific accounted for 40.9% of global GDP in 2016, up from 29.4% in 2000. The People''s Republic of China, India, and Japan accounted for about 70% of the region''s total output in 2016.', 'Key Indicators for Asia and the Pacific 2017', 6.01, 2.11, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.36, 5.05, '9789292579135', '9292579134', 52, 26.31, 2.99, '1987-01-27', 'The 5-volume publication, ADB through the Decades, provides a historical account of how ADB has evolved to respond to the dynamic changes across the Asia and Pacific region over the past 5 decades. This first volume from the series explains how the idea of a regional development bank for Asia emerged and gained support, and how ADB established itself as a sound and credible institution. When ADB was established in 1966, the Asia and Pacific region was undergoing a process of deep change. Several countries gained independence and a sense of regional identity was emerging. The region was defined by poverty and feeding people remained a primary concern, even while the Green Revolution was under way. The first oil crisis in 1973 tested many Asian economies. This volume explains the beginnings of a regional development bank for Asia. During its formative years, ADB dealt with administrative, organizational, and funding issues to establish itself as a sound and credible institution. ADB''s first President, Takeshi Watanabe, envisioned ADB''s role as Asia''s "family doctor." The Bank conducted several studies to have a fuller understanding of the region before lending on energy, transport, agriculture, and finance gained momentum during the latter half of the first decade.', 'ADB Through the Decades', 5.53, 3.35, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.14, 1.06, '9789292579210', '9292579215', 74, 19.02, 4.31, '1943-08-24', 'The 5-volume publication, ADB through the Decades, provides a historical account of how ADB has evolved to respond to the dynamic changes across the Asia and Pacific region over the past 5 decades. This third volume from the series presents ADB''s response to expert recommendations for a new role for ADB in the 1990s, and greater emphasis on effectiveness in the delivery of development assistance. The growth momentum within the region continued. Intraregional trade and investment grew rapidly as Asian economies drew increasing strength from within the region. Interest was growing both within and outside Asia to understand and assess policy recipes for rapid and sustained "miracle growth." The decade opened with recommendations from a panel of eminent development experts for a new role for ADB in the 1990s. Donor expectations evolved and placed greater emphasis on aid effectiveness of development assistance. In response, ADB strengthened internal procedures and gave greater attention to project quality. ADB moved to a new headquarters to centralize its operations. New members joined from Central Asia and some existing but nonactive members renewed their regular links with ADB. Lending picked up considerably while regional activities began to grow.', 'ADB Through the Decades', 9.56, 3.75, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.76, 5.49, '9789292579234', '9292579231', 112, 33.72, 2.33, '1970-04-01', 'The 5-volume publication, ADB through the Decades, provides a historical account of how ADB has evolved to respond to the dynamic changes across the Asia and Pacific region over the past 5 decades. This fourth volume from the series presents how ADB responded to rapid changes in the region following the Asian financial crisis and the changes in international development thinking. The 1997 Asian financial crisis hit the region and became a defining moment for Asia and ADB. As ADB participated in coordinated crisis responses, Asian policy-makers reassessed their economic policies in a fundamental way. This volume presents how ADB met the challenges of designing strategies to respond to rapid changes in the region following the Asian financial crisis and changes in international development thinking. Several important policies and strategies were approved, including ADB''s Poverty Reduction Strategy as well as ADB''s first Long-Term Strategic Framework to 2015. ADB embarked on two major reorganizations (in 2002 and 2006) and committed to an internal reform agenda to be a more responsive, relevant, and results-oriented organization.', 'ADB Through the Decades', 8.07, 9.11, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (4.37, 3.07, '9789292579272', '9292579274', 0, 76.92, 4.51, '2017-09-30', 'Insights and lessons are provided in this publication from a technical assistance project on building livable cities across Asia and the Pacific through the future cities approach. Inefficient and uncompetitive cities inhibit economic growth and inclusive development. Integrated urban planning will help stem the decline of Asian and Pacific cities, spelling the difference between a future of gloom or glory in the region. The technical assistance Establishing the Future Cities Program in the Asia and Pacific Region identifies new approaches, particularly the Future Cities approach, to address the challenges of urbanization. The program reviewed the entire ecosystem of how to develop livable cities and served as a testing ground for new or improved solutions. This publication captures insights from work in six pilot cases in Tbilisi, Mandalay, Greater Suva Area, Ulaanbaatar, Makassar, and Bandung.', 'Engaging with Cities of the Future', 7.15, 5.45, 158, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.21, 5.58, '9789292579296', '9292579290', 120, 82.65, 4.16, '1944-04-16', 'Good corporate governance practices reduce vulnerability to financial crises, reinforce property rights, reduce the cost of capital, and lead to greater capital market development. In this fourth edition of the Association of Southeast Asian Nations (ASEAN) Corporate Governance initiative of the Asian Development Bank and the ASEAN Capital Markets Forum, over 500 top publicly listed companies from six ASEAN countries were assessed. In depth analysis of each country including rights of shareholders, equitable treatment of shareholders, role of stakeholders, disclosure and transparency, and responsibilities of the board are discussed. The ASEAN Corporate Governance Scorecard Country Reports and Assessments 2015 is a joint initiative of the ASEAN Capital Markets Forum and the Asian Development Bank.', 'ASEAN Corporate Governance Scorecard Country Reports and Assessments 2015', 8.01, 4.15, 2, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.58, 8.4, '9789292579319', '9292579312', 40, 33.78, 3.35, '2017-05-11', 'Despite significant economic growth in Asia in recent decades, millions of people in rural Asia still lack access to electricity. A project has been implemented to develop small hybrid renewable energy systems in these areas. This publication highlights the experiences of these pilot projects in five developing member countries. It provides technical guidance and recommendations for the deployment of similar systems in minigrids in remote rural locations and small isolated islands to achieve access to electricity and energy efficiency.', 'Improving Lives of Rural Communities Through Developing Small Hybrid Renewable Energy Systems', 9.27, 2.97, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.41, 3.99, '9789292579753', '9292579754', 42, 72.33, 3.63, '1977-01-12', 'This Microsoft Excel-based tool kit and user guide intends to support planning hybrid renewable energy systems based on experiences of pilot projects in ADB''s South Asian developing member countries. ADB has implemented a regional technical assistance to develop small hybrid renewable energy systems that will provide reliable, adequate, and affordable energy for inclusive growth in Asian rural areas, and enable access to electricity and energy efficiency in remote rural locations and small isolated islands. A Microsoft Excel-based Tool Kit, prepared as part of knowledge development activities of the technical assistance, is intended to support planning hybrid renewable energy systems based on experiences of pilot projects in South Asian developing member countries. It will help find the most cost-effective configuration for a hybrid renewable energy stand-alone system through simulation of operation for each possible configuration of the system.', 'Microsoft Excel-Based Tool Kit for Planning Hybrid Energy Systems', 7.37, 3.66, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.26, 7.97, '9789292579838', '9292579835', 112, 61.78, 1.93, '1961-08-08', 'India needs to spend close to Rs43 trillion (about $646 billion) on infrastructure through to 2022. Such a staggering requirement cannot be met though traditional sources such as public sector bank loans. India must immediately explore and quickly ramp up financing from alternative investment sources. This paper explores the securitization of existing infrastructure assets by public sector banks in India, as a means to (i) strengthen their capital position to meet Basel III requirements, (ii) free up capital to help fund new credit growth opportunities, and (iii) ultimately improve fund flow to the infrastructure sector by enhancing its access to institutional investors.', 'Securitization in India', 2.46, 5.43, 3, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.62, 9.45, '9789292579913', '9292579916', 74, 96.19, 2.58, '1957-08-17', 'This study looks at the rapidly changing rural landscape in the People''s Republic of China and how the private and public sectors can improve and promote logistics development. Logistics plays an important role in agricultural production and supply-chain management, ultimately enhancing food safety and quality. Improvements in rural logistics help farmers to harvest and market crops more efficiently; and by facilitating communication, they serve to expand the markets for agricultural products. While recognizing the rapidly changing rural landscape in the People''s Republic of China, the distribution of goods is still impeded, and the quality of services poor. This study is part of the Asian Development Bank''s initiative to support and promote the development of the agriculture sector and establish efficient rural-urban synergies. Read how the private and public sectors can improve and promote logistics development in rural areas.', 'Promoting Logistics Development in Rural Areas', 6.76, 2.79, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.6, 6.22, '9789292610142', '9292610147', 74, 99.06, 3.13, '1967-04-01', 'This practical guide provides technical advice on disaster risk assessment to facilitate the consideration of disaster risks in the design of development projects. Disasters pose a significant threat to the sustainability of development investments. From 2007 to 2016, disasters triggered by natural hazards caused average daily physical losses of $133 million in ADB''s developing member countries. This practical guide provides technical advice on disaster risk assessment to facilitate the consideration of disaster risks in the design of development projects, seeking to ensure that disaster risks are properly identified and measures taken to reduce them where necessary. Disaster risk assessments can also help steer development investments to increase the disaster resilience of exposed and vulnerable communities more broadly.', 'Disaster Risk Assessment for Project Preparation', 5.76, 4.2, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.64, 2.23, '9789292610227', '9292610228', 58, 65.03, 2.59, '1974-03-04', 'This publication covers the progress of ADB in implementing its Operational Plan for Regional Cooperation and Integration, 2016-2020, focusing on 2016, by reviewing progress made and identifying areas for improvement. Regional cooperation and integration (RCI) has become a valuable means for attaining national development goals. This corporate report takes stock of ADB''s RCI operations, focusing on 2016, by reviewing progress made and identifying areas for improvement. It complements ADB''s existing RCI reports by focusing on RCI progress aligned with the three operational directions (connectivity, competitiveness, and regional public goods and collective action) and the three approaches (nascent RCI, nonsovereign RCI, and intersubregional RCI) to RCI operational quality. This corporate report pools together and offers a one-stop source of information on RCI operations for both internal and external stakeholders.', 'Regional Cooperation and Integration in Asia and the Pacific', 9.45, 2.67, 8, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.6, 3.74, '9789292610241', '9292610244', 68, 14.64, 1.86, '1976-07-15', 'This publication features an ADB project that turned around an urban water utility in Dhaka, Bangladesh, and offers a good example for other similar utilities in South Asia. ADB''s investment program in the Dhaka Water Supply and Sewerage Authority (DWASA) provided a breakthrough in approaching urban development, particularly the delivery of clean, reliable, affordable water and to the poor, no less. And not just a breakthrough for Dhaka or the rest of Bangladesh, but for the region of South Asia. This publication looks at the key success factors that other utilities are taking note of: The zonal approach to rehabilitating and managing urban water services, trenchless technology for expeditiously laying pipes, and how to connect the urban poor-and keeping them connected-through community-managed approaches.', 'The Dhaka Water Services Turnaround', 2.62, 4.56, 6, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (8.53, 6.66, '9789353290672', '9353290678', 64, 93.39, 4.17, '2018-10-31', 'This book has been considered by academicians and scholars of great significance and value to literature. This forms a part of the knowledge base for future generations. We havent used any OCR or photocopy to produce this book. The whole book has been typeset again to produce it without any errors or poor pictures and errant marks.', 'Hammersmith, Fulham and Putney', 8.33, 4.79, 159, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.34, 9.63, '9789353290719', '9353290716', 72, 42.39, 3.38, '2018-10-31', 'This book has been considered by academicians and scholars of great significance and value to literature. This forms a part of the knowledge base for future generations. We havent used any OCR or photocopy to produce this book. The whole book has been typeset again to produce it without any errors or poor pictures and errant marks.', 'The Strand District', 1.88, 1.57, 159, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (5.46, 9.37, '9789491386008', '949138600X', 134, 79.58, 2.28, '2009-09-25', '"What an absolutely cool guy!" --- Dennis Shasha, NYU "Fascinating... very worthwhile" --- Robert Harper, CMU What mathematical rigor has and has not to offer to software engineers. Peter Naur wrote his first research paper at the age of 16. Soon an internationally acclaimed astronomer, Naur''s expertise in numerical analysis gave him access to computers from 1950. He helped design and implement the influential ALGOL programming language. During the 1960s, Naur was in sync with the research agendas of McCarthy, Dijkstra, and others. By 1970, however, he had distanced himself from them. Instead of joining Dijkstra''s structured programming movement, he made abundantly clear why he disapproved of it. Underlying Naur''s criticism is his plea for pluralism: a computer professional should not dogmatically advocate a method and require others to use it in their own work. Instead, he should respect the multitude of personal styles in solving problems. What philosophy has to do with software engineering. Though Peter Naur definitely does not want to be called a philosopher, he acknowledges having been influenced by Popper, Quine, Russell, and others. Naur''s writings of the 1970s and 1980s show how he borrowed concepts from philosophy to further his understanding of software engineering. In later years, he mainly scrutinized the work in philosophy and mathematical logic & rules in particular. By penetrating deeply into the 1890 research of William James, Naur gradually developed his own theory of how mental life is like at the neural level of the nervous system. This development, in turn, helps explain why he always opposed the Turing Test and Artificial Intelligence, why he had strong misgivings about the Formal Methods movement and Dijkstra''s research in particular.', 'Pluralism in Software Engineering', 1.75, 1.37, 1, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.45, 1.73, '9789491386015', '9491386018', 48, 47.01, 4.84, '2011-11-01', 'Top researchers debate whether any real progress has been made during the past decades and how to distinguish between good and bad software. This booklet allows the reader to compare and contrast dominant voices in software engineering. It may serve as an aid for lecturers in explaining to engineering students how to see the wood for the trees in the complicated field of software engineering. The researchers address concurrency, program verification, and the contradistinction between software today versus how it should be in the future. Is it possible to increase the level of abstraction without paying a price in program performance? What is the difference between engineering verification and real verification? What is the role of program specifications in today''s development practice? Panelists: Barry Boehm, Manfred Broy, Erich Gamma, Michael A. Jackson, David L. Parnas, Niklaus Wirth, Pamela Zave, Yuri Gurevich, Rustan Leino, Bertrand Meyer, and Andreas Zeller.', 'The Future of Software Engineering', 3.04, 8.69, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.88, 4.33, '9789500702775', '9500702770', 467, 77.43, 1.66, '1980-01-25', '', 'Yo el Supremo', 6.74, 1.95, 9, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (7.83, 7.09, '9789684096691', '9684096690', 0, 12.81, 1.24, '1974-05-19', '', 'La receta del tiranosauro', 2.09, 7.37, 7, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (9.55, 6.06, '9789700767581', '9700767582', 231, 98.32, 1.11, '1967-05-09', 'Libro con encuadernación rústica pegada', 'Un mundo feliz', 7.06, 2.47, 4, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (1.93, 3.64, '9987160239', '9789987160235', 176, 33.19, 2.89, '1940-05-08', 'The author looks at The Gambia and its people and how this African country has been able to achieve cultural integration on a national level. He also provides a comprehensive picture of the country''s nation identity which is a fusion of the multiple identities of the various ethno-cultural groups which collectively constitute the Gambian nation. The work is a study of ethnic cultures and identities in the Gambian context whose relevance is continental in scope. Ethnicity is the primary identity in most African countries. It transcends national identity. Understanding its role in the lives of most Africans also helps us to understand African countries with all their complexities which collectively define the continent. In spite of its ethnic and cultural diversity, The Gambia is one of the most united countries in Africa. It''s also one of the most peaceful, enjoying harmonious relations among its various ethnic groups unlike many African countries where instability and civil strife caused by ethnic rivalries - fuelled by unscrupulous politicians - is the defining feature of national life. The ability of the various ethnic groups in The Gambia to interact harmoniously has led to cultural integration on a scale unheard of in most African countries. While it''s true that different tribal cultures do exist in The Gambia, it''s equally true that there also exists a national culture which unites the country''s various ethnic groups into a cohesive whole transcending ethno-regional loyalties. As an ethnically diverse nation, The Gambia is a microcosm of Africa: a continent whose countries are characterised by ethnic and cultural diversity where rivalries along tribal and regional lines are the norm rather than the exception. But The Gambia also is a good example of what many African countries have yet to be: united, with a solid national identity that has not been fractured or fragmented by ethnic conflicts. Cultural integration on a national scale remains an elusive goal in most African countries. But if there are a few countries on the continent which have achieved cultural integration, The Gambia is one them. It has, in fact, even achieved cultural fusion in some respects as we learn from this work which focuses on Africa''s smallest country and its people. The work is intended to be a general introduction and may help members of the general public learn some basic facts about The Gambia which, because of its strategic location and other attributes, has earned distinction as a gateway to West Africa. People going to The Gambia may find this work to be useful. Students in various academic fields may also benefit from the interdisciplinary approach taken by the author in his study of this African country. It''s comprehensive enough as an introductory work on the people of The Gambia and their ethnic identities and cultures.', 'The Gambia and Its People', 5.84, 6.23, 160, NOW(), NOW());
INSERT INTO public.book (depth, height, isbn_10, isbn_13, pages, price, rating, release_date, synopsis, title, weight, width, id_publisher, created_at, updated_at) VALUES (3.65, 6.36, '9987160387', '9789987160389', 180, 56.48, 3.47, '1941-02-28', 'This work looks at Sierra Leone, its people and history. Other subjects are also covered to provide a general introduction to the country. It is not intended for academic specialists, and it is not an in-depth study of the country. It is written from the perspective of a layman or general reader who simply wants to know some important things about this West African country. Sierra Leone is one of the oldest countries in Africa. And before it won independence in 1961, it was also one of the oldest colonies on the continent. Only two African countries won independence in 1961, both from the same colonial power, Great Britain. They were Sierra Leone, on 27 April, and Tanganyika on 9 December. The history of Sierra Leone is also one of the most tragic. But Sierra Leone still is one of the most fascinating countries on the continent in spite of the horrendous tragedy it went through during the civil war in the 1990s. The fact that it emerged intact from that brutal conflict is strong testimony to the resilience of the Sierra Leonean people against overwhelming odds which could have broken weaker souls.', 'Sierra Leone', 6.23, 2.36, 161, NOW(), NOW());
